(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["ya4"] = [{"id":"ya4-105-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"下列有關死腔（dead space）的敘述，何者錯誤？","options":["(A) 主要是因為有組織的喪失或是切除所留下的空間","(B) 適當的縫合可以減少死腔的形成","(C) 置放加壓敷料（pressure dressing）12到18小時，有助於fibrin之形成，以減少死腔","(D) 對於減少死腔的效果，非吸引式引流管（non-suction drain）較吸引式引流管（suction drain）佳"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"下列何者無法在傷口處理時，減少死腔（dead space）的產生，下列何者不宜？","options":["(A) 縫合tissue planes","(B) pressure dressing","(C) 硬組織的空腔可以紗布加壓，止血後取出","(D) 宜以尼龍線縫合肌肉層"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-1-3","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"下列何種病人不適合使用笑氣？","options":["(A) 氣喘病人","(B) 懷孕第一期婦女","(C) 有心絞痛病史的病人","(D) 慢性阻塞性肺臟疾病"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-1-4","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"下列有關神經解剖之敘述，何者錯誤？","options":["(A) 三叉神經之眼分枝由上眶裂穿出","(B) 三叉神經之上顎分枝，穿出圓孔，走出顱底，為純粹的感覺神經","(C) 三叉神經之下顎分枝，穿出卵圓孔，走出顱底，為三叉神經中最大之分枝，為純粹的感覺 神經","(D) 下齒槽神經，其最終分枝為門齒神經（incisive）及頦神經（mental nerve）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-1-5","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"良好的視野（visibility），是口腔外科手術基本的要件，下列那一項並非構成良好視野的條 件？","options":["(A) 無菌操作技術","(B) 適當的途徑","(C) 適當的燈光","(D) 無過多的血液或液體積聚於手術區"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"口內注射 lidocaine 在 160 mg 以內時，血中的麻醉劑濃度約為多少 µg/mL？","options":["(A) 0.5～2","(B) 3.5～5","(C) 6～7.5","(D) 8.5～9"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"麻醉劑分子的何部分，會結合神經膜感受部位（receptor site）而阻礙去極化 （depolarization） ？","options":["(A) 鈣離子（calcium ion）","(B) 游離鹽基（free base）","(C) 陰離子（anion）","(D) 陽離子（cation）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-8","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"一位病人在接受下顎第三大臼齒阻生牙拔除手術，3天後回到診所抱怨半邊舌頭知覺麻木，可 能為第幾對腦神經受損？","options":["(A) 第 4 對","(B) 第 5 對","(C) 第 6 對","(D) 第 7 對"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-9","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"有關麻醉劑中的血管收縮劑 norepinephrine 之敘述，下列何者正確？","options":["(A) 主要作用在 β2 接受器上","(B) 會增加心跳速度","(C) 提高血壓的效果比 epinephrine 明顯","(D) 有明顯氣管擴張的效果"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-1-10","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"一般言之，關於小孩（3～9歲）的Inferior alveolar nerve阻斷麻醉方法，下列敘述何者正 確？","options":["(A) 與大人注射劑量一樣","(B) 小孩mandibular foramen的位置與咬合面關係，相對於成人是比較低位","(C) 小孩的麻醉成功率比成人低","(D) 麻醉使用2% Lidocaine without epinephrine，小孩的最高劑量為300 mg"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"有關拔除上顎後牙之根尖三分之一之殘根，下列敘述何者錯誤？","options":["(A) 使用 closed technique 拔除殘根是指不須以翻瓣手術及移除骨頭方式去拔除殘根","(B) 欲拔除殘根時，必須在有充足的燈光及吸唾設備下進行，及適當的沖洗血塊，方便辨認根 尖牙周韌帶位置","(C) 應施以較大的力量，以便讓牙根較易頂鬆脫出","(D) 在殘根小於 4 到 5 mm 且沒有根尖病灶的情形下，因臨近重要解剖器官有造成傷害的疑 慮，可考慮留置不取出"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"手術拔除下顎第三大臼齒，牙齒拔出後傷口出血。下列何者為最優先使用止血方法？","options":["(A) 重新縫合","(B) 壓迫傷口","(C) 電燒止血","(D) 結紮出血點"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-13","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"手術拔除下顎第三大臼齒阻生齒，術後的張口受限症狀若是因為注射麻藥後肌肉穿刺受傷導 致，則最常發生在那一塊肌肉？","options":["(A) 顳肌","(B) 外翼肌","(C) 咬肌","(D) 內翼肌"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-14","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"下列有關拔牙挺（elevator）的使用，何者錯誤？","options":["(A) 常先用拔牙挺弄鬆牙齒，再用拔牙鉗拔出牙齒","(B) 窄刃而直的拔牙挺如no. 301適合用來先弄鬆牙齒","(C) 寬刃而直的拔牙挺如no. 34S可用於牙間距較寬時","(D) 彎曲的拔牙挺適用於下顎前牙"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-15","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"下列那一個型號的刀片比較適合在上顎骨tuberosity處施行牙齦切開手術？","options":["(A) No. 11","(B) No. 12","(C) No. 15","(D) No. 10"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-16","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"病人罹患下列那一種疾病，在接受牙科侵入性治療前可以不需要先服用抗生素？","options":["(A) Severe atherosclerotic vascular disease","(B) Prosthetic heart valves","(C) Cyanotic congenital heart defects","(D) Heart transplantation"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-17","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"有關影響宿主免疫力導致齒源性感染的敘述，下列何者正確？","options":["(A) 癌症的病人免疫力較低，主要是癌細胞抑制淋巴球的功能","(B) 類固醇能影響免疫細胞的細胞膜功能，導致降低免疫反應","(C) 有HIV感染的病人因為T細胞功能被抑制，導致容易引起齒源性感染","(D) 糖尿病病人因為血糖較高，導致造血能力不足，白血球的數目比正常人低"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"牙科治療時，有關抗生素預防感染的敘述，下列何者正確？","options":["(A) 如果糖尿病患者飯前血糖值高過300 mg/dL，若抗生素給到兩倍劑量，即可隨時手術","(B) 術後必須再給抗生素1週","(C) 為了不影響口腔內菌叢的平衡，手術前如果需要服用抗生素，最好是給予制菌類 （bacteriostatic type）抗生素","(D) 手術前如果需要口服抗生素，最好時間是手術前1小時"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-1-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"下顎牙齒中，何者之感染最易侵犯顎下間隙（submandibular space）？","options":["(A) 第一大臼齒","(B) 第二大臼齒","(C) 第三大臼齒","(D) 第二小臼齒"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-20","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"下列那一種微生物（microorganism）比較不常引起齒源性感染（odontogenic infection）？","options":["(A) Aerobic gram-positive cocci","(B) Aerobic gram-positive rods","(C) Anaerobic gram-positive cocci","(D) Anaerobic gram-negative rods"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-21","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"下列有關前庭成形術（vestibuloplasty）的敘述，何者錯誤?","options":["(A) 將裸露的骨膜表面以游離軟組織移植覆蓋，可減少前庭再次變淺","(B) 若使用自體移植，會增加病人術後疼痛及腫脹的程度","(C) 腭黏膜移植術後收縮比皮膚移植來得明顯","(D) 皮膚移植可取得較大量的軟組織"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-1-22","subject":"ya4","topic":"植牙外科","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"下列關於植牙的敘述何者正確？","options":["(A) 上顎前牙區植體應儘量種在顏面正中線以達到美觀","(B) 若其他條件相同，植體達到骨整合的時間以下顎前牙區最慢","(C) 植牙前欲以活動臨時假牙贗復缺牙區，ovate design 優於 ridge lap design","(D) 術前抗生素的給予是必要的"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-23","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"當一個病人要做上顎complete denture時，下列何種狀況最不需要做贋復前手術？","options":["(A) inflammatory papillary hyperplasia of the palate","(B) palatine tori","(C) epulis fissuratum","(D) lateral palatal exostosis"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-24","subject":"ya4","topic":"植牙外科","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"一般建議要符合下列何要件，才可於拔牙後立即進行牙科植體之種植？①牙齒並無嚴重感染 ②齒槽內壁與植體表面縫隙要小於5 mm ③植體植入後要能維持穩定","options":["(A) 只有①","(B) 只有②","(C) ①③","(D) 只有③"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"有關口腔惡性腫瘤的化學治療敘述，下列何者錯誤？","options":["(A) 對於腫瘤或正常細胞的傷害，不具有完全的選擇性","(B) 大部分經由靜脈方式給與","(C) 也可以由動脈方式給藥","(D) 有效的單一藥物效果比有效的多種藥物合用的效果更好"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-1-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"有關顎骨惡性腫瘤手術後的骨缺損重建敘述，下列何者錯誤？","options":["(A) 顎骨骨頭重建好後，才能進行牙齒咬合重建","(B) 感染機會高，應採延遲重建","(C) 術後需做放射線治療時，宜採立即重建","(D) 腫瘤復發機會高者，應採延遲重建"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-27","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"關於冷凍切片（frozen-section）病理檢查的敘述，下列何者錯誤？","options":["(A) 通常於手術過程中，用來確認切除邊緣是否仍有殘留病變組織","(B) 通常於手術過程中，用來確認切除組織的最終病理診斷","(C) 切片前，可利用液態氮（liquid nitrogen）將送檢的組織急速冷凍","(D) 切片前，可利用液態二氧化碳（liquid carbon dioxide）將送檢的組織急速冷凍"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-1-28","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"關於口腔癌患者接受放射線治療後發生口乾症（xerostomia）的敘述，下列何者錯誤？","options":["(A) 吞嚥困難（dysphagia）與發音困難（dysphonia）與口乾症無關","(B) 治療口乾症可以用人工唾液，但人工唾液的成分仍無法與天然唾液的成分完全一致","(C) 用副交感神經促進劑（parasympathomimetic agent）可以刺激唾液分泌，改善口乾症","(D) 原有之牙周病會因口乾症而加劇病情"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-29","subject":"ya4","topic":"口腔病理基礎","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"有關齒源性角化囊腫的病理特徵，下列何者錯誤？","options":["(A) 囊腫外壁薄","(B) 上皮有6～8 層","(C) 上皮為不全角化（parakeratinization）者比正角化（orthokeratinization）者多","(D) 基底層的細胞核屬於嗜酸性"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-1-30","subject":"ya4","topic":"口腔病理基礎","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"基底細胞痣症候群（basal cell nevus syndrome）不會有下列那一個症狀？","options":["(A) 肋骨分叉","(B) 基底細胞癌","(C) 眼距過短","(D) 齒源性角化囊腫（odotogenic keratocyst）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-1-31","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"對於口腔內的囊腫病灶（cystic lesion），下列那一項治療是不適當的？","options":["(A) 造袋術（marsupialization）","(B) 減壓術（decompression）","(C) 剜出術（enucleation）","(D) 截骨術（block resection）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"Maxillary osteotomy 後採用V-Y closure 的目的，下列何者正確？","options":["(A) 可以使上唇變薄一些，以露出牙齒","(B) 對於唇紅緣（vermilion）的高低變化沒有幫助","(C) 使上顎前移時，軟組織的移動量接近骨的移動量","(D) 可以減少鼻翼變寬"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"施行矢向劈裂骨切開術（sagittal split osteotomy）後，下齒槽神經應位在下列何種狀況？","options":["(A) 骨切開後之近心端骨片","(B) 骨切開後之遠心端骨片","(C) 下齒槽神經應與近心及遠心端骨片連結一起","(D) 下齒槽神經應與所有骨骼分離"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-1-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"有關上顎發育不足或是下顎發育過度病患的敘述，下列何者正確？","options":["(A) 上下門牙常向外傾","(B) 上下門牙常向舌側倒","(C) 上門牙常向外傾，下門牙常向舌側倒","(D) 上門牙常向舌側倒，下門牙常向外傾"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-35","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"施行下列何種手術較易造成下唇麻木?①BSSO ②Mandibular anterior osteotomy ③Genioplasty ④Maxillary anterior osteotomy ⑤LeFort I osteotomy","options":["(A) ①④","(B) ③④","(C) ④⑤","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"下列何種頭痛最常見？","options":["(A) 壓力型頭痛（tension－type headache）","(B) 偏頭痛（migraine）","(C) 叢發型頭痛（cluster headache）","(D) 顳部動脈炎（temporal arteritis）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"有關非典型顏面痛（atypical facial pain）的敘述，下列何者錯誤？","options":["(A) 好發率：女性＞男性","(B) 深、鈍之持續性疼痛","(C) X光影像無異常發現","(D) 有引發區（trigger zone）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-38","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"神經纖維如依直徑分類，下列何者傳導痛覺速度較快？","options":["(A) Aα神經纖維（nerve fiber）","(B) Aβ神經纖維（nerve fiber）","(C) Aδ神經纖維（nerve fiber）","(D) C神經纖維（nerve fiber）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-39","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"當上呼吸道阻塞發生時，下列何種方式可以最快建立通道進入氣管？","options":["(A) oral airway tube","(B) cricothyrotomy","(C) tracheostomy","(D) nasal airway tube"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-40","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"Towne's view用來檢查何處骨折？","options":["(A) mandibular condyle","(B) maxillary sinus","(C) zygomatic complex","(D) zygomatic arch"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-41","subject":"ya4","topic":"口腔外科基礎","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"撕裂性傷口的處理有四個基本步驟，其先後順序應為何？①傷口的清洗（cleansing） ②傷 口的止血 ③傷口的清創（débridement） ④傷口的縫合","options":["(A) ①②③④","(B) ②①③④","(C) ②③①④","(D) ①③②④"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"下列有關治療下顎髁突骨折（fracture of mandibular condyle）的敘述，下列何者錯誤？","options":["(A) 必須手術將斷裂骨骼復位至原先的解剖位置","(B) 開放式復位手術可選擇由口內或口外途徑進入關節區域","(C) 施行上下顎間鋼絲固定術（intermaxillary fixation）於成人，最多固定2至3週","(D) 施行上下顎間鋼絲固定術（intermaxillary fixation）於孩童，最多固定10至14天"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-43","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"裂腭處的多生牙何時拔除最佳？","options":["(A) 進行唇裂修補手術時","(B) 進行腭裂修補手術時","(C) 進行腭裂修補手術前2～3個月","(D) 進行齒槽裂補骨手術前2～3個月"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-44","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"處理唇腭裂病人鼻部畸形的最早時機，常與下列何者手術合併實施？","options":["(A) 施行唇裂手術時","(B) 施行腭裂手術時","(C) 施行齒槽骨缺損的補骨手術時","(D) 施行正顎手術時"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-45","subject":"ya4","topic":"植牙外科","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"有關移植骨的骨生成（osteogenesis）的兩相（two phases）敘述，下列何者正確？","options":["(A) 第一相是植入骨之骨細胞所產生的新生骨","(B) 第一相的營養供應來自植入骨的組織液浸潤","(C) 第二相的骨生成，大約在植入後第六週才開始","(D) 第二相的骨生成，以新生骨的形成為主，與骨重塑無關"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-46","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"患有冠狀動脈狹窄做過冠狀動脈繞道手術之病患，有每天服用 aspirin，若是該病患要拔牙， 則術前最好須停藥幾天？","options":["(A) 5","(B) 4","(C) 3","(D) 2"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-47","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"以牙科所使用的局部麻醉藥物 2% lidocaine with 1：100,000 epinephrine，做口腔局部浸潤 （infiltration）麻醉，對於上顎牙齒約略可麻醉幾小時？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-1-48","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"下列那些患者不適宜使用morphine作手術後止痛？①慢性阻塞性肺疾（chronic obstructive pulmonary disease）病患 ②有心肌梗塞（myocardiac infarction）病史之病患 ③孕婦","options":["(A) 只有①②","(B) 只有②③","(C) 只有①③","(D) ①②③"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-1-49","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"一位遭受車禍嚴重受創之病人，已被醫師宣告腦死，家人同意捐出眼角膜，此病人屬於ASA 的那個分類？","options":["(A) ASA III","(B) ASA IV","(C) ASA V","(D) ASA VI"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-50","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"有關顳顎關節之敘述，下列何者錯誤？","options":["(A) gliding 或 translatory movement 主要發生於上關節腔","(B) 關節盤之四周均與關節囊連接","(C) 關節盤中心主要由纖維組織構成，缺乏神經血管","(D) 兩側髁軸（condyle axis）交會處約位於枕骨大孔"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-1-51","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"臨床上myofascial pain and dysfunction（MPD）在下列敘述中那一項非患者之抱怨？","options":["(A) 患者通常有耳前局部性的疼痛，有時咀嚼肌群也有疼痛","(B) 有夜間磨牙症的患者，其早上起床時疼痛更明顯","(C) 患者會咀嚼時漸漸張口困難","(D) 關節X光片檢查會發現關節有退化性的改變"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-1-52","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"有關顳顎關節疾病之敘述，下列何者錯誤？","options":["(A) 可復位性關節盤前移（anterior disc displacement with reduction）通常會在下顎運動時有 關節彈響","(B) 不可復位性關節盤前移（anterior disc displacement without reduction）表示關節頭在進行 translation movement 時，關節盤的位置並不隨之改變，又稱之為 closed lock","(C) 骨性軟骨病變（osteochondromatosis）發生在關節髁頭表面","(D) 關節半脫臼（subluxation）所產生之關節彈響乃發自於髁頭經過關節隆凸所導致，與關節 內紛亂所產生之關節彈響不同"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-1-53","subject":"ya4","topic":"口腔病理基礎","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"對於將手術取得的切片組織不當地應用在研究上，有關醫院倫理委員會的任務之敘述，下列 何者錯誤？","options":["(A) 這是有關人體試驗的課題","(B) 應視為倫理教育任務的課題","(C) 應做為重擬醫療作業準則任務的參考","(D) 這是屬於協助醫師輔導病人就醫的任務"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-54","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"患者因右側顎下區（submaxillary region）腫大，尤其在飯後特別腫脹，理學檢查發現右顎 下區摸到一軟性壓痛腫塊，口腔內檢查發現口底唾液腺開口有紅腫，開口處有一黃白色硬 塊。（請依此回答下列3題） 1.下列X光影像何者較能診斷出問題？①skull film（P-A view） ②panoramic film ③occlusal film ④sialogram","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) 只有①④"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-55","subject":"ya4","topic":"唾液腺疾病","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"2.依下圖口內彩色照片，及X光咬合片影像，下列何種診斷正確？","options":["(A) 口底腫瘤","(B) 唾液結石堵塞於Stensen’s duct","(C) 唾液結石堵塞於Wharton’s duct","(D) 此問題是由舌下腺引起的"],"answer":2,"image":"ya4-105-1-55.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-56","subject":"ya4","topic":"唾液腺疾病","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"3.該患者應如何處置？①將口底紅腫塊切除 ②將堵塞之黃白硬塊，以牙科檢查用之forceps 反夾後，在其表面黏膜切開擠出硬塊即可 ③給予抗生素 ④鼓勵術後多喝水","options":["(A) ①③④","(B) 只有②③","(C) 只有③④","(D) ②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"下列敘述，何者錯誤？","options":["(A) Bremsstrahlung屬於characteristic spectrum","(B) Bremsstrahlung又稱braking radiation","(C) Filtration係指移除低能量的光子","(D) X光束是由許多帶有不同能量的光子所組成的"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"依照國際放射防護委員會（International Commission on Radiological Protection）規定， non-classified workers每年輻射曝露量最高可為classified workers劑量的：","options":["(A) 1/10","(B) 3/10","(C) 6/10","(D) 8/10"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"牙科X光機在70 kVp以上，鋁濾片厚度為多少mm？","options":["(A) 0.1","(B) 0.5","(C) 1","(D) 2.5"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-60","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"下列那些是根尖片凸點的作用？①照射時凸點朝向放射源 ②照射時凸點背對放射源 ③照 射時凸點朝向咬合面 ④照射時凸點遠離咬合面","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-61","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"有關評估正顎手術前後，下顎骨對稱與否之X光攝影法，下列何者最適當？","options":["(A) Water's projection","(B) PA cephalometric projection","(C) Reverse Towne projection","(D) Lateral cephalometric projection"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"有關垂直咬翼片照射（vertical bitewing radiography）時機之敘述，下列何者正確？","options":["(A) 當患者有中等程度到嚴重的齒槽骨喪失","(B) 常配合分角線法照射","(C) 乳牙根管治療時常喜歡使用","(D) 以5°～8°向上的垂直角ล照射"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"下列何者可降低影像放大（image magnification）之效應？","options":["(A) 使用長錐（long cone）","(B) 使用短錐（short cone）","(C) 減少焦點與皮膚之距離（focal spot to skin distance）","(D) 增加感應器與被照物之距離（receptor to object distance）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-64","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"下列何種放射線影像能最清晰的顯示genial tubercle之解剖影像？","options":["(A) periapical film","(B) panoramic film","(C) mandibular occlusal film","(D) bitewing film"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-1-65","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"於根尖放射線影像（periapical radiograph）上，上顎顴骨突（zygomatic process of the maxilla）之影像，最常出現於下列何處？","options":["(A) 上顎粗隆（maxillary tuberosity）","(B) 上顎第一及第二大臼齒處","(C) 上顎第一及第二小臼齒處","(D) 上顎犬齒處"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-1-66","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"下圖咬翼片中，白色箭頭所指之放射線不透過性帶（radiopaque band）最可能為下列何 者？","options":["(A) Resin filling material","(B) Artifact image","(C) Calculus","(D) Cervical abrasion"],"answer":2,"image":"ya4-105-1-66.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-67","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"下圖X光影像中，左上正中門齒最可能的診斷為何？","options":["(A) Caries","(B) Periodontal disease","(C) Dens evaginatus","(D) Extrusion"],"answer":3,"image":"ya4-105-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-68","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"一位12歲女孩，顏面無痛腫脹已有3年，其電腦斷層影像如圖，她的皮膚上還有咖啡牛奶 斑。其最可能的診斷是：","options":["(A) Florid-osseous dysplasia","(B) McCune-Albright's syndrome","(C) Paget's disease","(D) von Recklinghausen disease of skin"],"answer":1,"image":"ya4-105-1-68.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-69","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"下列何種疾病，較常會大量破壞齒槽骨，造成被侵犯區域牙齒之X光表現，呈現牙齒浮於空 中之影像（teeth floating in air）？","options":["(A) 牙骨質-骨質發育不良（cemento-osseous dysplasia）","(B) 骨之柏哲德氏病（Paget's disease of bone）","(C) 纖維性發育不良（fibrous dysplasia）","(D) 蘭格罕氏細胞疾病（Langerhans cell disease）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-1-70","subject":"ya4","topic":"口腔病理基礎","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"一位18歲男性患者主訴右下顎後牙痛及下顎骨慢慢膨大，下圖X光片顯示右下顎第一大臼齒 根尖處有一混合放射阻性及放射透性之病灶、外圍一明顯的放射透性帶，並有根部吸收情 形，根據上述資料其臨床診斷最不可能為下列何者？","options":["(A) Osteoblastoma","(B) Cementoblastoma","(C) Osteoid osteoma","(D) Chondroma"],"answer":3,"image":"ya4-105-1-70.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-71","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"下列何種疾病，其頭顱（skull）X光影像較常呈現多發性孔狀病變（multiple punched-out lesions），且較好犯於年老男性患者？","options":["(A) 牙骨質-骨質發育不良（cemento-osseous dysplasia）","(B) 多發性骨髓瘤（multiple myeloma）","(C) 痣樣基底細胞癌症候群（nevoid basal cell carcinoma syndrome）","(D) 蘭格罕氏細胞疾病（Langerhans cell disease）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-1-72","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"下圖Ｘ光片中，右下第三大臼齒處和下顎上升枝所呈現之骨破壞，下列何種診斷最有可能？","options":["(A) Ameloblastoma","(B) Paget's disease","(C) Fibrous dysplasia","(D) Squamous cell carcinoma"],"answer":3,"image":"ya4-105-1-72.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-73","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"對下列顎骨腫瘤切除後標本之放射線影像，最適切之描述為何？","options":["(A) 洋蔥皮狀影像（onion-skin appearance）","(B) 毛玻璃狀影像（ground-glass appearance）","(C) 羊毛棉花狀影像（cotton-wool appearance）","(D) 陽光線狀影像（sun-ray appearance）"],"answer":3,"image":"ya4-105-1-73.jpeg","clinical_level":"重點"},{"id":"ya4-105-1-74","subject":"ya4","topic":"口腔病理基礎","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"下列那一種囊腫之X光影像，最常呈現心臟型放射線透過性（radiolucent）病變？","options":["(A) 鼻腭管囊腫（nasopalatine duct cyst）","(B) 鼻唇囊腫（nasolabial cyst）","(C) 鼻齒槽囊腫（nasoalveolar cyst）","(D) 球突上顎囊腫（globulomaxillary cyst）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-75","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"下列全身性疾病中，何者可於放射線影像上呈現牙骨質增生？","options":["(A) 腦下垂體功能亢進（hyperpituitarism）","(B) 甲狀腺功能過低（hypothyroidism）","(C) 腦下垂體功能過低（hypopituitarism）","(D) 副甲狀腺功能過高（hyperparathyroidism）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-76","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"此種放射線影像檢查的結果，其最可能的診斷為何？","options":["(A) Mandibular fracture","(B) Maxillary palatine cyst","(C) Maxillary sinusitis","(D) Fibrous dysplasia"],"answer":2,"image":"ya4-105-1-76.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-77","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"有關直接՝位放射線影像（direct digital radiography），下列敘述何者錯誤？","options":["(A) 感應片（receptor）較易折損","(B) CMOS system屬之","(C) CCD system屬之","(D) 一樣大的感應片，照出來的影像範圍比實際的PSP感應片小"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-1-78","subject":"ya4","topic":"放射線原理與技術","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"放射線曝露的急性效應屬下列何者？","options":["(A) 確定效應（deterministic effects）","(B) 機率效應（stochastic effects）","(C) 遺傳效應（hereditary effects）","(D) 非確定效應（uncertain effects）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-1-79","subject":"ya4","topic":"口腔病理基礎","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"一位70歲老先生因慢性骨髓炎而反覆住院治療，最近一次住院時顎骨X光檢查如下圖所示， 黑色箭頭所指為何？","options":["(A) 骨膜反應（periosteal bone reaction）","(B) 腐骨（sequestra）","(C) 腫瘤團塊（tumor mass）","(D) 軟組織鈣化（soft tissue calcification）"],"answer":1,"image":"ya4-105-1-79.jpeg","clinical_level":"一般"},{"id":"ya4-105-1-80","subject":"ya4","topic":"放射影像診斷","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"承上題，白色箭頭所指為何？","options":["(A) 人為影像重疊（double image artefact）","(B) 骨膜反應（periosteal bone reaction）","(C) 鈣化血管（calcified vessel）","(D) 腐骨（sequestra）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-1","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"有關感染控制的觀念，下列何者錯誤？","options":["(A) 要達到一樣的滅菌效果，溼熱滅菌法較乾熱滅菌法所需溫度較低，需時較短","(B) 100℃沸騰的水可有效殺死孢子及病毒","(C) 嗜熱桿菌芽孢（Bacillus stearothermophilus spores）為常用的高溫滅菌有效指標","(D) Ethylene oxide gas適用於多孔性物質及塑膠器械的滅菌"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"關於傷口止血，下列敘述何者正確？ ①對於較小的血管可以直接加壓20～30秒 ②血腫可能增加傷口感染的機會 ③電燒止血時可以先用電燒器尖端碰觸血管，再 將傷口血液吸乾 ④腎上腺素也可以用來直接加壓在傷口上至少7分鐘","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"治療下圖根尖病變合併廔管形成，下列何種手術皮瓣設計較不恰當？","options":["(A) intrasulcular incision with triangular flap","(B) intrasulcular incision with rectangular flap","(C) submarginal incision with triangular flap","(D) vestibular incision with fistulectomy"],"answer":3,"image":"ya4-105-2-3.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-4","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"下列各種局部麻醉製劑中，那一種對罹患變形性血紅素（methemoglobinemia）的病患是有使用上的禁忌？","options":["(A) lidocaine","(B) articaine","(C) mepivacaine","(D) prilocaine"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-5","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"有關創傷癒合的理論，下列那一種狀況屬於第一級癒合（primary intention）？","options":["(A) 神經斷裂後，重新接通吻合（reanastomoses）的神經","(B) 拔牙後的齒槽","(C) 復位不佳的骨折","(D) 深度的潰瘍"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"局部麻醉藥物過量，最常發生在下列何者？","options":["(A) 老年人","(B) 幼童","(C) 中年婦女","(D) 壯年男丁"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-7","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"心臟病或高血壓病人其可接受的最高血管收縮劑 epinephrine 劑量為多少 mg？","options":["(A) 0.04","(B) 0.2","(C) 2","(D) 0.4"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"下列何種針頭最常使用在牙科麻醉？","options":["(A) 25號長針","(B) 27號長針","(C) 28號長針","(D) 30號長針"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-9","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"麻醉劑分子的何部分，決定其分類為酯類（ester）或醯氨類（amide）？","options":["(A) 親脂部分（lipophilic portion）","(B) 親水部分（hydrophilic portion）","(C) 中間鏈（intermediate chain）","(D) caine 連結（caine linkage）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-10","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"施打局部麻醉藥時，下列那些病人須嚴格限制 epinephrine 的使用量？ ①缺血性心臟病 ②腦血管疾病（如中風），但血壓正 常 ③心律不整 ④高血壓 ⑤甲狀腺亢進 ⑥氣喘","options":["(A) ①③④⑤","(B) ①②③④","(C) ②③⑤⑥","(D) ②④⑤⑥"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"阻生之下顎第三大臼齒，下列何種情況最難拔除？","options":["(A) 垂直阻生","(B) 近心傾斜阻生","(C) 水平阻生","(D) 遠心傾斜阻生"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"阻生齒發生率下列何者正確？","options":["(A) 第三大臼齒 > 犬齒 > 門齒 > 小臼齒","(B) 犬齒 > 第三大臼齒 > 小臼齒 > 門齒","(C) 第三大臼齒 > 犬齒 > 小臼齒 > 門齒","(D) 犬齒 > 第三大臼齒 > 門齒 > 小臼齒"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-13","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"關於第三大臼齒牙冠周圍炎之敘述，下列何者錯誤？","options":["(A) 發作時常引起嚴重疼痛，開口困難","(B) 有可能是因食物卡陷，造成無法清潔所致","(C) 主要是大腸桿菌感染","(D) 雙氧水有殺菌、治療的清潔功效"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-14","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"下圖為A、B、C三位病患之X光片，他們在接受右側上顎第一大臼齒之拔除時，發生牙根斷裂，此時若用拔牙挺挖取齒槽中斷 裂之牙根，那位病患之斷根被推擠入上顎竇之風險最高？","options":["(A) A","(B) B","(C) C","(D) 三位病患之風險相同"],"answer":1,"image":"ya4-105-2-14.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-15","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"下列何者是拔牙的禁忌症？","options":["(A) 骨折線經過的牙齒合併牙根斷裂","(B) 下顎阻生齒合併有急性嚴重牙冠周圍炎","(C) 因矯正需要","(D) 多生齒（supernumerary tooth）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"下列何者，是造成齒源性感染病人死亡的最常見原因？","options":["(A) 菌血症","(B) 腎臟衰竭","(C) 呼吸道阻塞","(D) 廣泛性血管栓塞"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"有關顎骨骨髓炎之敘述，下列何者正確？","options":["(A) 因為接近上顎竇，上顎骨後牙區發生率最高","(B) 拔牙或者根管感染之後，可能造成顎骨骨髓炎","(C) 通常是細菌隨著血流進入顎骨骨髓之後，導致骨髓炎的發生","(D) 骨髓炎發生時通常沒有症狀，直到死骨形成時候才會感覺到痛"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-18","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"服用下列何種藥品的患者不必視為潛在性容易感染？","options":["(A) Anticoagulants","(B) Cortricosteroids","(C) Cyclosporin","(D) Azathioprine"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"有關齒源性感染導致身體遠端擴散發炎的敘述，下列何者錯誤？","options":["(A) 病人身體有一個抵抗力較弱的區域存在，才會發生此現象","(B) 可經由淋巴結或是血液擴散","(C) 人工關節是一個容易發生此現象的地方","(D) 口腔內草綠色鏈球菌（viridans-group streptococci）較會造成心內膜炎"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-20","subject":"ya4","topic":"齒源性感染與藥物","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"急診病患主訴4天前拔除右下第二大臼齒後，第2天臼齒區後方隱隱作痛，至昨天更形嚴重且張口困難，口腔檢查發現拔牙傷口 正常，但上下顎間最後方明顯壓痛，臉部外觀正常無腫脹，推斷為阻斷麻醉路徑感染，其感染部位應在何處？","options":["(A) 翼顎間隙","(B) 顳下間隙","(C) 頰肌間隙","(D) 咬肌間隙"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-21","subject":"ya4","topic":"植牙外科","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"骨內植體（intra osseous implant）尖端與下顎管之間的距離至少需多少mm最適當？","options":["(A) 0.5","(B) 1.0","(C) 1.5","(D) 2.0"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-22","subject":"ya4","topic":"植牙外科","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"有關人工植牙手術的敘述，下列何者正確？","options":["(A) 在沒有特殊因素影響之下，尚在發育中的青少年最好是滿13歲以後才植牙","(B) TMI（transmandibular implant）適用於下顎前牙區的無牙嵴，而且無牙嵴的高度不得少於0.6公分","(C) 曾經暴露於放射線治療範圍內的下顎骨，一律不建議做植牙手術","(D) 在上顎前牙美觀區（esthetic zone）植牙時必須考慮到軟組織厚度的問題，所以植體頂端通常會與鄰牙齒頸部一樣高"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-23","subject":"ya4","topic":"植牙外科","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"關於立即植牙（immediate implant）手術，下列敘述何者錯誤？","options":["(A) 每個拔牙後的狀況均可立即植牙","(B) 採用立即植牙時，最好植深入並穿過齒槽窩底部3～4 mm","(C) 採用立即植牙時，植體與齒槽窩壁之間的間隙小於1 mm時，可以不必補骨粉","(D) 採用立即植牙時，植體與齒槽窩壁之間的間隙大於1 mm時，要補骨粉"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-24","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"下列何者不屬於上顎隆突降低術（maxillary tuberosity reduction）的適應範圍？","options":["(A) 上顎隆突骨頭過度生長","(B) 覆蓋在上顎隆突骨頭上軟組織過度生長增厚","(C) 上顎隆突骨頭和覆蓋在其上的軟組織都有過度生長增厚現象","(D) 上顎竇底部過低"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-2-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"口腔鱗狀細胞癌T1N1M0 的分期是：","options":["(A) Stage I","(B) Stage II","(C) Stage III","(D) Stage IV"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-2-26","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"下列何者是最危險的口腔黏膜病變？","options":["(A) 黏膜下纖維化","(B) 扁平苔癬","(C) 紅斑症","(D) 白斑症"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"下列何者不是顎骨黏液瘤（myxoma）之特性？","options":["(A) 放射線影像顯示其會將牙齒推開","(B) 有時放射線影像會像含牙囊腫","(C) 有時放射線影像呈現網球拍狀（tennis racket）","(D) 不具有侵犯性毋須做較廣泛切除"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"當牙醫師做抽吸式切片檢查（aspiration biopsy）時，發現針管內吸出的是血液，可能是下列那一種病變？","options":["(A) multiple myeloma","(B) osteosarcoma","(C) central giant cell granulomas","(D) ameloblastic fibroma"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"下列何種囊腫較不適合採用保守性的手術？","options":["(A) 齒源性角化囊腫（odontogenic keratocyst）","(B) 含牙囊腫（dentigerous cyst）","(C) 殘留囊腫（residual cyst）","(D) 根尖囊腫（radicular cyst）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-30","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"下列何者不屬於發炎性囊腫（inflammatory cyst）？","options":["(A) 根尖囊腫（apical radicular cyst）","(B) 殘餘囊腫（residual cyst）","(C) 含牙囊腫（dentigerous cyst）","(D) 根側囊腫（lateral radicular cyst）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-105-2-31","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"以手術治療齒源性角化囊腫（odontogenic keratocyst）時，下列何者較不易復發？","options":["(A) 減壓術（decompression）","(B) 造袋術（marsupialization）","(C) 剜出術（enucleation）","(D) 剜出術（enucleation）加刮除術（curettage）"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya4-105-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"下列何者不是 LeFort I osteotomy，造成術後延遲出血（delayed hemorrhage）的主要血管？","options":["(A) greater palatine artery","(B) facial artery","(C) internal maxillary artery","(D) pterygoid venous plexus"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"關於垂直下顎枝截開術（vertical ramus osteotomy）的敘述，下列何者錯誤？","options":["(A) 下顎枝部連著髁狀突的部分重疊在遠心端下顎骨之上","(B) 由口內進入時，可使用angulated oscillating saw以方便操作","(C) 可由口內進入，以減少對顏面神經下顎分枝的傷害","(D) 用於矯正嚴重下顎突出和後縮"],"answer":3,"clinical_level":"重點"},{"id":"ya4-105-2-34","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"有關正顎手術之傷口癒合，下列敘述何者錯誤？","options":["(A) 骨重塑期（remodeling phase）在組織受傷時即開始","(B) 巨噬細胞（macrophage）是發炎期（inflammatory phase）最重要的調節細胞","(C) 增殖期（proliferative phase）的主要目標為強化傷口強度，重建血液循環及再上皮化（reepithelialization）","(D) 傷口組織抗張強度（tensile strength）在第三周時約可達原本組織之50%"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-35","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"施行勒福一型（LeFort I）正顎手術，若做大幅度移動，有關術後穩定性，下列何者最差？","options":["(A) 前置（anterior reposition）","(B) 後置（posterior reposition）","(C) 上置（superior reposition）","(D) 下置（inferior repostion）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-36","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"有關帶狀疱疹感染後神經痛之敘述，下列何者正確？","options":["(A) 侵犯三叉神經時，以下顎支最常見","(B) 以年輕人居多","(C) 侵犯顏面神經時稱為侖謝亨特症候群（Ramsay Hunt Syndrome）","(D) 約有20～30%會出現神經痛，且2～5週自然痊癒"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-37","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"神經失用症（neurapraxia）一般在多少時間以內會復原？","options":["(A) 4週","(B) 8週","(C) 12週","(D) 16週"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-38","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"一名病患經檢查發現瞳孔對光照無法收縮及眼瞼下垂（ptosis），則該患者是那一條神經受損？","options":["(A) 第三對腦神經（cranial nerve III）","(B) 第四對腦神經（cranial nerve IV）","(C) 第六對腦神經（cranial nerve VI）","(D) 第七對腦神經（cranial nerve VII）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"那一個大唾液腺體分泌的唾液，是以黏液為主？","options":["(A) 腮腺","(B) 舌下腺","(C) 顎下腺","(D) 腭腺"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-40","subject":"ya4","topic":"唾液腺疾病","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"有關 sialolithiasis 之敘述，下列何者錯誤？","options":["(A) 好發於男性","(B) 舌下腺的發生率最高","(C) 主要的症狀是在用餐時，會感覺到腫脹及疼痛","(D) transcutaneous electromagnetic waves可用來治療腺體內較小的Sialolithiasis"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-2-41","subject":"ya4","topic":"唾液腺疾病","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"下列那種情況最不宜做唾液腺照影（sialography）？","options":["(A) 懷疑有唾液腺腫瘤","(B) 口乾症","(C) 唾液腺腫大","(D) 急性唾液腺感染"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"下列何種下顎骨折，不會出現下嘴唇麻木感？","options":["(A) 下顎骨角（angle）","(B) 下顎上升枝（ramus）","(C) 下顎骨體（body）","(D) 下顎聯合處（symphysis）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"當牙醫師急診檢查齒顎外傷的患者時，下列那一項檢查很少使用？","options":["(A) 受傷牙齒的牙髓活性檢查","(B) 受傷牙齒的X光片檢查","(C) 受傷牙齒區域的觸診檢查","(D) 受傷牙齒區域的軟組織檢查"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"臨床上處理下顎骨骨折時，下列敘述何者正確？","options":["(A) 為避免影響骨頭發育，兒童下顎骨骨折不要施行close reduction","(B) 如髁頭處有骨折，一定要將其完全復位以避免未來張口困難發生","(C) 粉碎性骨折需避免使用開放性復位手術","(D) 如利用close reduction治療下顎骨骨折的年老病患，IMF的時間不能超過4週以免發生TMJ ankylosis"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"有關中臉部勒福（LeFort）I型骨折的敘述，下列何者錯誤？","options":["(A) 通常是由上顎骨受到水平力量撞擊所致","(B) 骨折區域經過上顎竇及鼻腔底部","(C) 造成上顎和翼突板、鼻骨、顴骨構造之間的分離","(D) 此種類型骨折又稱為顱顏面分離性（craniofacial separation）骨折"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-46","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"有唇腭裂的病人，出現上顎發育不良，如需要活動式矯正裝置，可開始矯正的時機為何？","options":["(A) 上顎第一大臼齒萌發後","(B) 上顎犬齒萌發後","(C) 所有恆牙萌發後","(D) 齒槽裂補骨手術後"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"電視影像螢光透視法（videofluoroscopy）可用來檢查腭裂患者之發音功能，關於此法的運用，下列敘述何者錯誤？","options":["(A) 病患於檢查時需注射顯影劑（contrast medium）","(B) 可檢測咽腭帆肌肉群（velopharyngeal musculatures）之動作","(C) 可顯示上呼吸道解剖型態及殘留腭瘻管（residual palatal fistula）","(D) 檢查時必須有語言病理學家（speech pathologist）做發音測試"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-48","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"繼生腭（secondary palate）是由上顎腫（maxillary swelling）隆起之何種構造形成？此構造於何時出現？","options":["(A) 腭架（palatine shelf），6週","(B) 腭架（palatine shelf），10週","(C) 顎間段（intermaxillary segment），4週","(D) 顎間段（intermaxillary segment），8週"],"answer":[0,1],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-105-2-49","subject":"ya4","topic":"拔牙學與併發症","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"為孕婦拔除牙齒，最好在懷孕的那一時期施行？","options":["(A) 前三月期","(B) 中三月期","(C) 後三月期","(D) 任何時期皆不宜"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-50","subject":"ya4","topic":"局部與全身麻醉","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"牙科所使用的局部麻醉藥物 2% lidocaine with 1：100,000 epinephrine，對一個健康的 20 公斤兒童，在同一次的治療中最多 可以注射幾管 （1.8 mL / 管）？","options":["(A) 2","(B) 3","(C) 4","(D) 5"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-2-51","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"腦中風發作後，至少多久時間內最好不要拔牙？","options":["(A) 6個星期","(B) 3個月","(C) 6個月","(D) 1年"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-52","subject":"ya4","topic":"全身性疾病與急症","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"在牙科門診中，病患若發生持續或反覆癲癇（status epilepticus），除應立刻召喚醫療急救人員外，可考慮先給予下列那種藥 物？","options":["(A) Hydrocortisone","(B) Midazolam","(C) Morphine","(D) Succinylcholine"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"下列何種病變最容易引起顳顎關節疼痛?","options":["(A) 類風濕性關節炎（rheumatoid arthritis）","(B) 骨關節炎（osteoarthritis）","(C) 軟骨瘤（chondroma）","(D) 關節盤前方移位（disc anterior displacement）"],"answer":[0,1],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-105-2-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"下列有關「不可復性關節盤前移（anterior disc displacement without reduction）」之敘述，何者錯誤？","options":["(A) 患者在張口時，會有關節彈響聲音（clicking sound）出現","(B) 患者無法達到正常的張口程度，張口時下顎骨會往患側偏移","(C) 下顎骨減少往對側方向做側移（lateral excursion）的運動","(D) 核磁共振檢查可發現關節盤有前側位移現象"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"發生於顳顎關節之類風濕性關節炎（rheumatoid arthritis），有下列那些特徵？①滑液組織（synovial tissue）不正常增生，形 成所謂血管翳（pannus） ②骨骼之侵蝕大多侷限在關節隆凸（articular eminence），而不會影響髁頭（condylar head）","options":["(A) 只有①正確","(B) 只有②正確","(C) ①②均正確","(D) ①②均不正確"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-56","subject":"ya4","topic":"口腔外科基礎","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"當醫療糾紛產生時，病人或是家屬已經採取法律訴訟時，下列那一項敘述錯誤？","options":["(A) 醫師必須熟悉病患所有病歷記載以及相關醫療資料","(B) 醫師有義務回答病人或是家屬甚至是病人律師任何問題","(C) 醫師應該聽從醫療糾紛小組成員或是律師的建議","(D) 醫師在回答家屬或是病人律師的疑問時，必須使用已知的知識以及相關紀錄為基礎"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"現行使用輻射之劑量當中，用於人員之劑量單位為等效劑量（equivalent dose），下列何者正確？","options":["(A) 1 Sv=100 rem","(B) 1 Sv=1000 rem","(C) 1 Gy=10 Sv","(D) 1 rad=1 Sv"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"下列有關口內放射線攝影的敘述，何者錯誤？","options":["(A) X光機電壓不應低於50 kV","(B) X光管直徑不可超過60 mm","(C) 使用正方形的瞄準儀（collimator）有最佳的防護效果","(D) X光機電壓在70 kV以下應使用1.5 mm的鋁濾片"],"answer":[1,2],"clinical_level":"重點","explanation_pending":false},{"id":"ya4-105-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"下列何者非放射線對DNA分子破壞後的結果？","options":["(A) DNA單鍵或雙鍵的斷裂","(B) 斷裂後的DNA發生鍵內或鍵外重組","(C) 鹼基缺失或改變","(D) DNA和RNA的重組"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"下列何者非超音波優於X-ray的優點？","options":["(A) 非游離輻射","(B) 沒有傷害性的生物效應","(C) 適合於軟組織之鑑別診斷","(D) 解析度較高"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-61","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"下列敘述，何者最為正確？","options":["(A) Submentovertex film可以同時觀察上下顎、牙齒與condyle","(B) MRI可以很清楚觀察到disc perforation","(C) TMJ arthrography可以觀察disc動態活動，但具侵入性","(D) CT scan無侵入性的觀察disc displacement"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"關於X光操作時之敘述，下࠻何者正確？","options":["(A) 最安全的角ล是與主射線夾0度至90度的範圍","(B) 在沒有ໝ射防護屏蔽下，X光操作者須ੋ病人至少5 feet","(C) 操作者應幫病人壓片","(D) 操作者最好要使用X光片固定器（film-holding device）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-105-2-63","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"下圖之上顎根尖片模糊影像，最可能之原因為：","options":["(A) mA過低","(B) kVp過低","(C) X光片彎曲","(D) 病人移動"],"answer":3,"image":"ya4-105-2-63.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-64","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"下圖所示之X光影像與何種拍攝方式所產生的影像最為接近？","options":["(A) Water's view","(B) Submental vertex view","(C) Posterior-anterior view","(D) Anterior-posterior view"],"answer":0,"image":"ya4-105-2-64.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-65","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"下圖箭頭所指之帶狀黑色的放射線透過性（radiolucent）區域是：","options":["(A) fracture line","(B) fistulae","(C) neurovascular canal","(D) suture"],"answer":2,"image":"ya4-105-2-65.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-66","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"下圖根尖X光片中，黑色箭頭所指為何種構造？","options":["(A) Anterior nasal spine","(B) Intermaxillary suture","(C) Anterior floor of the nasal aperture","(D) Incisive foramen"],"answer":0,"image":"ya4-105-2-66.jpeg","clinical_level":"重點"},{"id":"ya4-105-2-67","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"門齒孔（incisive foramen）之寬度至少要大於多少公分，才會被認定為一門齒管囊腫（incisive canal cyst）？","options":["(A) 0.4","(B) 0.6","(C) 0.8","(D) 1.0"],"answer":1,"clinical_level":"一般"},{"id":"ya4-105-2-68","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"下圖X光影像中，下顎骨病變最可能的診斷為何？","options":["(A) Chondroma","(B) Osteoradionecrosis","(C) Fibrous dysplasia","(D) Ameloblastoma"],"answer":2,"image":"ya4-105-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-69","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"下圖中左側門牙的變異為何？","options":["(A) Dens evaginatus","(B) Dens invaginatus","(C) Peg lateral","(D) Talon cusp"],"answer":1,"image":"ya4-105-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-70","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"一名20歲男性因美觀問題求診，他全口的牙齒都有嚴重磨耗的情形，其後牙的根尖片如圖。他可能罹患何種疾病？","options":["(A) Amelogenesis imperfecta","(B) Dentinogenesis imperfecta","(C) Dentin dysplasia","(D) Odontogenesis imperfecta"],"answer":0,"image":"ya4-105-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-71","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"一位中年男性因鼻咽癌接受頭頸部放射線治療，左圖為治療前X光片，右圖為放射線治療半年後的X光片影像呈現牙齒及齒槽 嵴周邊有骨硬化和大量骨破壞情形，在鑑別診斷後，下列何種病變最有可能?","options":["(A) Recurrence of the malignant neoplasm","(B) Actue osteomyelitis","(C) Radiation therapy-induced osteoradionecrosis","(D) Bisphosphonate-induced osteonecrosis"],"answer":2,"image":"ya4-105-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-72","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"下圖之X光影像箭頭所示處，最可能之X光診斷為：","options":["(A) 多生牙","(B) 唾液腺結石","(C) 淋巴結鈣化","(D) 靜脈結石"],"answer":3,"image":"ya4-105-2-72.jpeg","clinical_level":"重點"},{"id":"ya4-105-2-73","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"下列何種疾病患者顎骨之放射線影像，有時可見牙齒旁之齒槽骨板（lamina dura）喪失之情形？","options":["(A) 副甲狀腺功能過旺（hyperparathyroidism）","(B) 副甲狀腺功能不足（hypoparathyroidism）","(C) 腦下垂體功能過旺（hyperpituitarism）","(D) 腦下垂體功能不足（hypopituitarism）"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-74","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"下圖是何種檢查所呈現之影像？","options":["(A) MRI","(B) ultrasonography","(C) computed tomography","(D) PET whole body scan"],"answer":3,"image":"ya4-105-2-74.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-75","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"下列何者的放射線影像，會呈現扇形（scalloped shape）的病灶？","options":["(A) 齒源性角化囊腫（odontogenic keratocyst）","(B) 根尖囊腫（radicular cyst）","(C) 鼻腭管囊腫（nasopalatine duct cyst）","(D) 濾泡性囊腫（follicular cyst）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-105-2-76","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"顎骨內神經鞘瘤（neurilemoma）之最常見放射線影像表徵為何？","options":["(A) 單房放射線透性病變（unilocular radiolucent lesion）","(B) 多房放射線透性病變（multilocular radiolucent lesion）","(C) 混合放射線透性和不透性病變（mixed radiolucent and radiopaque lesion）","(D) 放射線不透性病變（radiopaque lesion）"],"answer":0,"clinical_level":"重點"},{"id":"ya4-105-2-77","subject":"ya4","topic":"口腔病理基礎","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"常見造釉細胞瘤（ameloblastoma）的放射線影像特徵，下列敘述何者錯誤？","options":["(A) 下顎最常發生的部位在臼齒-上升枝區","(B) 下顎最常發生的部位在前牙區","(C) 單房或多房的放射線透性影像","(D) X光片上可見牙根被推開或吸收情形"],"answer":1,"clinical_level":"重點"},{"id":"ya4-105-2-78","subject":"ya4","topic":"放射線原理與技術","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"目前的數位攝影檢出器（detector）可獲得的密度範圍為多少bit depth？","options":["(A) 1～2 bit","(B) 4～6 bit","(C) 8～16 bit","(D) 32～64 bit"],"answer":2,"clinical_level":"一般"},{"id":"ya4-105-2-79","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"下圖之X光影像最主要觀察那一解剖構造？","options":["(A) Zygomatic arch","(B) Maxillary sinus","(C) Body of mandible","(D) Ramus of the mandible"],"answer":1,"image":"ya4-105-2-79.jpeg","clinical_level":"一般"},{"id":"ya4-105-2-80","subject":"ya4","topic":"放射影像診斷","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"承上題，該X光影像最可能之X光診斷為：","options":["(A) 骨硬化症（osteopetrosis）","(B) 骨疏鬆症（osteoporosis）","(C) 下顎骨骨折（mandibular fracture）","(D) 鼻竇炎（sinusitis）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"影響傷口癒合的情況，下列何者錯誤？","options":["(A) 有異物","(B) 有壞死組織","(C) 傷口張力過大","(D) 傷口切線長"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"傷口癒合的順序為何？ ①fibroplastic stage ②inflammatory stage ③remodeling stage","options":["(A) ②①③","(B) ①②③","(C) ③①②","(D) ①③②"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"有關翻瓣手術，下列敘述何者錯誤？ ①皮瓣寬度設計，游離緣可大於基底部 ②垂直鬆弛性（vertical release）切線應於預計要移除骨頭區的邊緣 ③皮瓣裂開會 增加疤痕形成 ④適當處理之較長切線的傷口癒合時間與較短切線傷口沒有差異","options":["(A) ①②","(B) ①③","(C) ①④","(D) ③④"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-4","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"下列有關大臼齒拔除後齒槽骨癒合（healing of extraction sockets）的敘述，何者正確？","options":["(A) 齒槽癒合第1週的特徵，為齒槽內充滿了肉芽組織，並且類骨質（osteoid）沈積其內","(B) 齒槽癒合第2週為發炎期，纖維組織開始增生","(C) 上皮覆蓋（epithelialization）完成於第3至第4週","(D) 拔牙8週後，由X光影像上，可看到原來清晰易辨的齒槽骨板（lamina dura）消失"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-5","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"下列有關神經失用症（neurapraxia）的敘述，何者錯誤？","options":["(A) 為周邊神經受損時，神經鞘膜及軸突皆斷裂之病症","(B) 局部缺血或神經周圍發炎時可能發生","(C) 通常數天或數週後，神經功能將自發性復原","(D) 當植入植體輕微觸壓到下齒槽神經時，可能發生神經失用症"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"要拔除上顎智齒，需要麻醉那些神經？","options":["(A) 後上齒槽神經","(B) 後上齒槽神經與中上齒槽神經","(C) 後上齒槽神經與大腭神經","(D) 後上齒槽神經，中上齒槽神經與大腭神經"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-7","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"有關局部麻醉劑之最大建議劑量（Maximum Recommended Dose, MRD），下列何者錯誤？","options":["(A) Lidocaine = 200 mg （2.8mg/kg）","(B) Articaine = 500 mg （7mg/kg）","(C) Bupivacaine = 90 mg （1.3mg/kg）","(D) Mepivacaine = 300 mg （4.4mg/kg）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"有關下列圖示的敘述，何者正確？","options":["(A) 上圖與下圖都是骨內局部麻醉注射器","(B) 上圖是骨內局部麻醉注射器，下圖是牙周韌帶注射器","(C) 上圖與下圖都是牙周韌帶注射器","(D) 上圖是牙周韌帶注射器，下圖是骨內局部麻醉注射器"],"answer":2,"image":"ya4-106-1-8.jpeg","clinical_level":"重點"},{"id":"ya4-106-1-9","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"病患至牙科診所治療時，自述於大約20小時前吸食甲基安非他命（methamphetamine），其治療需使用局部麻醉劑，則應如何 處置？","options":["(A) 已超過12小時，可進行注射局部麻醉劑","(B) 限制血管收縮劑為標準劑量之20％","(C) 延遲治療至吸食甲基安非他命24小時之後","(D) 只能使用 bupivacaine"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-10","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"1管的1.8 ml 2% xylocaine所含麻藥量為多少？","options":["(A) 18 gm","(B) 18 mg","(C) 36 gm","(D) 36 mg"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"下列何一牙齒適合以拔牙鉗旋轉施力帶出？","options":["(A) 上顎門牙","(B) 上顎大臼齒","(C) 上顎第一小臼齒","(D) 上顎第二小臼齒"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"當拔除上顎臼齒發生口竇相通，直徑為5 mm時，應如何處置？","options":["(A) 先以手術刮匙（curette）探測相通孔洞深度及位置","(B) 不需任何處置，請病人遵循sinus precautions即可","(C) 在拔牙窩洞置入Gelfoam並以八字結（figure-of-eight）縫合，請病人遵循sinus precautions","(D) 以皮瓣修補口竇相通"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-13","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"有關拔除阻生下顎第三大臼齒後，預防發生感染的問題，下列敘述何者錯誤？","options":["(A) 一般來說，口腔內的手術傷口是屬於清潔傷口（clean wound）","(B) 一般術後發生感染的機會大約是1～5%","(C) 可不需給予術前預防性抗生素","(D) 可不需給予術後抗生素"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-14","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"下列何者不適合以骨鑿（chisel）劈開牙齒拔出？","options":["(A) 下顎第二大臼齒","(B) 上顎第三大臼齒","(C) 下顎第二小臼齒","(D) 下顎第三大臼齒"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-15","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"有關口腔手術後之照護，下列敘述何者錯誤？","options":["(A) 手術後的腫脹通常於術後的24到48小時達到最腫脹程度","(B) 手術後瘀斑（ecchymosis）多出現於手術後2到4天","(C) 對健康的病人施行阻生齒拔除手術，並不需要於術後常規給予抗生素","(D) 手術後第5天腫脹大於手術後第3天是正常現象，尤其常見於女性患者"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-16","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"成年病人在接受化學治療之後，抱怨口腔內有疼痛性燒灼感與白色斑塊，如圖所示，在給予適當性藥物治療後，白色斑點消 失，症狀也緩解。請問這是何種感染？","options":["(A) 蜂窩性組織炎","(B) 廣泛性黏膜發炎","(C) 黴菌引起發炎","(D) 原發性病毒性感染"],"answer":2,"image":"ya4-106-1-16.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-17","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"下列有關顏面顎骨區放射線骨壞死（osteoradionecrosis）的敘述，那一個正確？","options":["(A) 由於上顎骨比較薄，容易遭受放射線破壞，發生放射線骨壞死","(B) 如果放射線劑量 5000 cGy 時就會發生","(C) 通常是拔牙後因細菌感染造成放射線骨壞死","(D) 可能會在完成放射線治療多年後，在沒有特殊原因之下就突然發生"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"為了預防牙科治療的感染，有關抗生素使用的敘述，下列何者正確？","options":["(A) 如果手術前需要給予抗生素，則抗生素的劑量是平常用法的兩倍","(B) 手術後只需要給予抗生素兩天，超過兩天則抗生素的效用是沒有意義","(C) 如果手術超過四小時，則手術中需要給予抗生素的劑量是平常用法的兩倍","(D) 只能採用廣效性（broad-spectrum）抗生素"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"54歲有糖尿病的病人，在拔除右下第一大臼齒一星期之後，就感覺到下巴與口底有疼痛性腫大，如圖，你初步臆測是什麼樣的 感染？","options":["(A) 急性骨髓炎","(B) 化膿性骨髓炎","(C) 盧德威氏口峽炎（Ludwig's angina）","(D) 顎下唾液腺炎合併舌下唾液腺炎"],"answer":2,"image":"ya4-106-1-19.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-20","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"你正在檢視下週牙科手術病患之過去史，發現有幾個心臟病史需要投予預防性抗生素，但下列何者除外？","options":["(A) 發紺充血性心臟病且缺損尚未修補者","(B) 人工瓣膜裝置術後","(C) 冠狀動脈繞道術後","(D) 心室中隔嚴重缺損"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-21","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"齒槽骨成形術時，將齒槽中隔（septum）移除之術式名稱為何？","options":["(A) Dean's technique","(B) Gillies' operation","(C) Kole's procedure","(D) Millard's operation"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-22","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"下列有關補綴前手術之敘述，何者錯誤？","options":["(A) 進行腭隆凸（torus palatinus）骨去除術時，須注意避免鼻黏膜穿孔","(B) 無牙病人欲改善其下顎骨唇側倒凹，若範圍不大應先考慮骨切除手術而非骨再生手術","(C) Mylohyoid ridge reduction與口底下降手術合併進行效果較好","(D) 若上顎頰側外生骨贅（exostosis）的倒凹很大，切除時以H形切線翻瓣較不受到倒凹的影響"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-1-23","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"移除torus palatinus時，須注意那一條血管的走向？","options":["(A) Greater palatine artery","(B) Descending palatine artery","(C) Nasopalatine artery","(D) Ascending palatine artery"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-24","subject":"ya4","topic":"植牙外科","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"下列何者最不適合植牙？","options":["(A) 牙周病患者","(B) 骨質疏鬆使用靜脈注射雙磷酸鹽類藥物","(C) 糖化血色素控制在 7% 以下的糖尿病患者","(D) 夜間磨牙"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-25","subject":"ya4","topic":"口腔外科基礎","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"肩胛舌骨上頸部淋巴廓清術（supraomohyoid neck dissection）所要清除的頸部淋巴包括：","options":["(A) 第一、二階層 （Level I,II）","(B) 第一、二、三階層（Level I,II,III）","(C) 第一、二、三、四階層（Level I,II,III,IV）","(D) 第一、二、三、四、五階層（Level I,II,III,IV,V）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-1-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"當懷疑患者有multiple myeloma時，可由X光片檢查發現顱骨的影像有下列何種特徵？","options":["(A) Sun-ray appearance","(B) Onion appearance","(C) Digital appearance","(D) Multiple radiolucent round shadow"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-27","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"有關造袋術治療囊腫，與剜出手術比較，下列何者錯誤？","options":["(A) 傷口照顧較困難","(B) 治療期間較久","(C) 不知整體病灶的病理變化","(D) 感染機會較高"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-28","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"有關含牙囊腫（dentigenous cyst）的特徵，下列何者錯誤？","options":["(A) 囊腫包覆在埋伏齒的齒頸部","(B) 以犬齒最常見","(C) 組織學上，囊腫外壁很厚","(D) 囊腫接近下顎管，以造袋術治療為宜"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-1-29","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"下列那一項囊腫不屬於發育性齒源性囊腫（developmental odontogenic cyst）？","options":["(A) 含牙囊腫（dentigerous cyst）","(B) 鈣化齒源性囊腫（calcifying odontogenic cyst）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 根尖囊腫（radicular cyst）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-1-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"患有下顎骨過長（mandibular excess）之病人，常會有下述那些特徵？①下唇及頦部（chin）過度前突 ②嚴重時會使嘴唇閉 合困難 ③第一大臼齒及犬齒均為第三級咬合關係（Class III relationship）","options":["(A) 只有①②","(B) 只有①③","(C) 只有②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-31","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"各種全上顎骨切開術（total maxillary osteotomies）合併不同部位的片段骨切開術（segmental osteotomy），可用來治療上 顎何種方向之畸形（deformity）？①前後向 ②垂直向 ③橫向","options":["(A) 只有①","(B) 只有①②","(C) 只有②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"下列關於下顎發育異常的敘述，何者錯誤？","options":["(A) 過深的唇頦皺裂，下唇外翻，上唇位置異常，及不良的喉型均是下顎發育過度的特徵","(B) 若頦部前後位置適當，但為第二類異常咬合時，可採用全部牙根尖下的骨切開術（total subapical osteotomy），使下顎前移","(C) 當咬合關係正常時，可使用頦成形術（genioplasty），來使頦部前突","(D) 頦成形術（genioplasty）可以矯正顏面的不對稱"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-33","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"有關 hemimandibular hypertrophy 與 hemimandibular elongation 之敘述，下列何者錯誤？","options":["(A) 前者發生於青春期，後者則發生於青春期前","(B) 前者是從下顎骨髁頭至下顎骨體增大，後者只有下顎骨體增大","(C) 前者通常會影響上顎之生長，後者不會","(D) 前者通常不合併咬合錯咬"],"answer":[0,1],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-106-1-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"除三叉神經痛外最常見的顱神經痛是：","options":["(A) 顏面神經痛","(B) 舌咽神經痛","(C) 迷走神經痛","(D) 副神經痛"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"叢發型頭痛（cluster headache）在發作時，其疼痛部位常包括下列那個區域？","options":["(A) 上顎後齒區","(B) 上顎前齒區","(C) 下顎後齒區","(D) 下顎前齒區"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"下列何者最常被用來治療三叉神經痛？","options":["(A) Acetaminophen","(B) Carbamazepine","(C) Diazepam","(D) Chloroxazone"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-37","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"有關黏液囊腫的敘述，下列何者正確？","options":["(A) 可發生在頰黏膜","(B) 黏液囊腫手術不需移除其底下的小唾液腺，以避免較大的疤痕收縮","(C) 最常發生於口底","(D) simple ranula 和 plunging ranula 之區分是以頦舌骨肌為界線"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-38","subject":"ya4","topic":"唾液腺疾病","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"診斷位於口底前方之顎下腺結石時，下列那一種X光片是最佳之診斷工具？","options":["(A) 環口X光片","(B) 根尖片","(C) 測顱X光片","(D) 咬合片"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-39","subject":"ya4","topic":"唾液腺疾病","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"有關三大唾液腺之最，下列何者錯誤？","options":["(A) 分泌液中鈣離子濃度最高－腮腺","(B) 每日唾液製造分泌量最多－顎下腺","(C) 最易有結石－顎下腺","(D) 分泌液中黏性最高－舌下腺"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-40","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"處理頭頸部外傷病人時，必須詢問下列問題，其中最不重要的是：","options":["(A) 病人的姓名","(B) 發生的時間","(C) 病人的住址","(D) 發生的地點"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"脫落的牙齒用下列那一種液體保存，則再植入時成功的機率最高？","options":["(A) patient's saliva","(B) tap water","(C) milk","(D) Hanks balanced salt solution"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-42","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"根據這張電腦斷層顯示是何種骨折？","options":["(A) 左側上顎骨 comminuted fractrure及下顎骨左側 fracture","(B) LeFort Ι fracture","(C) 左側顴骨及下顎骨左側 comminuted fractrure","(D) LeFort ΙΙ fracture"],"answer":0,"image":"ya4-106-1-42.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"上下顎間固定術（intermaxillary fixation）的方法有好幾種，下圖所示的方法，是那一種？","options":["(A) Splinting wiring technique","(B) Ivy loop wiring technique","(C) Arch bar intermaxillary fixation technique","(D) Continuous loop wiring technique"],"answer":1,"image":"ya4-106-1-43.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-44","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"下列何者不是唇腭裂病人最常見的耳朵問題？","options":["(A) 中耳感染","(B) 歐氏管功能失調","(C) 中耳分泌物無法引流出來","(D) 先天性聽覺神經受損"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-1-45","subject":"ya4","topic":"植牙外科","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"有關應用於人體之allografts，下列敘述何者錯誤？","options":["(A) 等同於homografts","(B) 指的是其他人的骨頭","(C) 可提供phase I osteogenesis 所需","(D) 目前最常用的是冷凍乾燥處理過的骨頭"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-46","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"張小弟為一唇腭裂患者，接受手術修補後仍有鼻音過重的言語，下列何種原因最有可能？","options":["(A) 前牙錯咬（anterior crossbite）","(B) 咽腭帆閉合不全（velopharyngeal incompetency）","(C) 聲帶異常（vocal cord anomaly）","(D) 鼻中隔彎曲（nasal septum deviation）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-47","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"糖尿病病人接受口腔手術，術中血糖應控制在多少mg/dL範圍為適當？","options":["(A) 50～100","(B) 120～200","(C) 250～350","(D) 400～500"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-48","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"下列有關系統性疾病之敘述，何者正確？","options":["(A) 患有chronic obstructive pulmonary disease（COPD），可使用sedatives、hypnotics及narcotics來減緩病人的焦慮","(B) 洗腎患者約診宜約洗腎當天看診，並避免開立NSAID","(C) 酒精性肝病變患者在接受牙科治療前應檢驗PT、PTT、platelet count、bleeding time","(D) Ketoacidosis常見於non-insulin-dependent DM患者"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-49","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"根據 Wilkes 對顳顎關節內部紛亂（internal derangement）之分類，中/晚期（intermediate/late stage）之解剖病理敘述何者 正確？","options":["(A) 關節盤前位移，些微關節盤變形，中央區域良好","(B) 明顯關節盤變形及向前位移，硬組織無病變","(C) 硬組織受力面退化性重塑（degenerative remodeling），前後隱窩（recess）多處黏連（adhesion），關節盤或附著組織無 穿孔","(D) 關節盤及硬組織顯著退化，後附著部（posterior attachment）穿孔，多處黏連（adhesion），贅骨形成（osteophytosis）， 髁頭及隆凸扁平化"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-1-50","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"下列何種病變，較常做顳顎關節手術治療？","options":["(A) 退化性關節病變","(B) 類風濕性關節炎","(C) 黏連","(D) 關節盤移位"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-51","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"下列關於造成myofascial pain and dysfunction（MPD）原因之敘述，何者錯誤？","options":["(A) 造成MPD的原因一般認為是多因素的","(B) MPD主要是來自於不正常的肌肉功能與過度活動","(C) MPD也可以繼發顳顎關節內部問題（internal joint problems）","(D) 由於壓力或焦慮所導致的磨牙症（bruxism）不會造成MPD"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-1-52","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"有關傷害（harm）與益處（benefit）間的敘述，下列何者較符合牙科倫理學的原則？","options":["(A) 避免傷害和追求益處同等優先地位","(B) 避免傷害較追求益處優先","(C) 追求益處較避免傷害優先","(D) 避免傷害和追求益處何者優先，須視實際情況而定"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-53","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"如下圖所示，一位22歲男性罹患左側下顎骨病變，經切片檢查證實為齒源性腫瘤。（請依序回答下列2題） 1.下列那一項鑑別診斷最合理？","options":["(A) Ameloblastoma","(B) Pingborg’s tumor","(C) Cementoma","(D) Ameloblastic odontoma"],"answer":0,"image":"ya4-106-1-53.jpeg","clinical_level":"重點"},{"id":"ya4-106-1-54","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"2.依據您的鑑別診斷，則下列那一種手術治療方式中最易復發？","options":["(A) Enucleation","(B) Marginal resection","(C) Partial resection","(D) Composite resection"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-1-55","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"一位35歲女性病患，過去無心肺疾病之病史，在牙科治療椅上等候接受拔牙手術時，突然感覺焦慮不安、頭暈、呼吸困難、心 悸、胸痛，且症狀持續10分鐘未見改善，此時最可能之診斷為何？","options":["(A) 心絞痛","(B) 心律不整","(C) 換氣過度","(D) 氣喘"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-56","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"承上題，此時除持續監測病患之生命徵象外，最適當之處置方式為何？","options":["(A) 病患平躺，呼吸氧氣含量較高之空氣","(B) 病患半坐臥，呼吸二氧化碳含量較高之空氣","(C) 病患坐直，並給予氣管擴張劑","(D) 此為暫時性現象，不必作任何處置"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"目前放射線之劑量單位均以國際標準單位系統（SI System）為主，下列敘述，何者正確？","options":["(A) 曝露劑量（Exposure dose）與吸收劑量（Absorbed dose）之單位相同","(B) 有效劑量（Effective dose）與等效劑量（Equivalent dose）之單位相同","(C) 1 Sv＝100 rad","(D) 1 Gy＝100 rem"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"牙醫師為病人做X光檢查時，下列何者不是其主要的考慮因素？","options":["(A) 正當性（justification）","(B) 適當性（optimization）","(C) 親切性（hospitalization）","(D) 劑量限制性（dose limitation）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"如圖所示，照射病人左側下顎臼齒區時，如果A、B、C、D四點都距離病人180公分，那一點測得之輻射劑量最低？","options":["(A) A","(B) B","(C) C","(D) D"],"answer":3,"image":"ya4-106-1-59.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-60","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"下圖中所示之感應片（sensor plate）上的英文小寫字母“a”的意義為何？","options":["(A) 製造廠商之商標代號","(B) 產品的序列號","(C) 雷同傳統口內X光片之突點（dot）","(D) 發明者之英文姓氏縮寫"],"answer":2,"image":"ya4-106-1-60.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"欲清楚的觀察顎下腺管路完整的樹枝狀分布，可用下列何種extraoral projection，來做顎下腺造影術（submandibular gland sialography）？","options":["(A) Oblique lateral projection","(B) Puff-cheek projection","(C) Water's projection","(D) Submental vertical projection"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"將一硬幣置於暗房中未曝射之X光片上五分鐘後，洗片後發現硬幣圓框影像清晰可ྏ，最合਺的推測是：","options":["(A) 定影Ә完全","(B) 暗房á光","(C) 顯影Ә完全","(D) 顯影液與定影液溫ล過低"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-63","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"若X光片中牙齒的長度為a，X光片中伸入根管之器械（instrument）長度為b，實際的伸入根管之器械長度為c，下列何者最接 近實際牙齒長度？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011118-3ykh.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011123-qniq.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011133-l91k.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011137-dpz5.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-64","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"上顎咬合片中，黑色箭頭所指之橢圓形放射線透過性（radiolucent）影像為下列何種構造？","options":["(A) The nasopalatine canal","(B) The nasolacrimal canal","(C) The opening of the maxillary sinus","(D) The nutrient canal"],"answer":1,"image":"ya4-106-1-64.jpeg","clinical_level":"重點"},{"id":"ya4-106-1-65","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"下圖中白色箭頭所指為何種構造？","options":["(A) The superior border of the mandibular canal","(B) The external oblique ridge","(C) The mylohyoid ridge","(D) The internal oblique ridge"],"answer":2,"image":"ya4-106-1-65.jpeg","clinical_level":"重點"},{"id":"ya4-106-1-66","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"若要檢查顴骨弓應用以下何種攝影方法？","options":["(A) Submentovertex projection","(B) Reverse Towne's projection","(C) Waters' projection","(D) Panoramic radiography"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-67","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"下圖中第三大臼齒處之牙齒異常為何？","options":["(A) Dens evaginatus","(B) Dens invaginatus","(C) Gemination","(D) Microdontia"],"answer":3,"image":"ya4-106-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-68","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"下圖箭頭指示之處，其最可能之診斷為何？","options":["(A) Enamel pearl","(B) Calculus","(C) Overhanged resin filling","(D) Coronoid process"],"answer":1,"image":"ya4-106-1-68.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-69","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"有關牙瘤（odontoma）之敘述，下列何者錯誤？","options":["(A) 可分為complex odontoma和compound odontoma","(B) 是最常見的齒源性腫瘤","(C) 放射線影像看起來，由許多類似牙齒的構造組成","(D) 放射線影像看起來，病灶周邊有一圈窄而放射線不透過性（radiopaque）的邊緣"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-1-70","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"下列有關各病史的描述，何者最不符合此X光片？","options":["(A) 一位80歲骨質疏鬆症女性，服用 alendronate 3年，因牙周疾病拔除下顎兩側後牙後，傷口持續不癒合","(B) 一位70歲男性，意外發現下顎雙側 complex odontoma","(C) 一位55歲舌癌曾接受放射線治療的男性，左下顎齒槽骨裸露突出於口腔","(D) 一位50歲女性疑似患有 florid cemento-osseous dysplasia，曾接受病理切片檢查確診"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-71","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"下列何種牙根尖病變（periapical lesion），其疾病早期之X光影像，呈現放射線透過性病變（radiolucent lesion），好犯於30 至50歲女性患者下顎前牙區，且被侵犯牙常為活性牙（vital teeth）？","options":["(A) 牙根尖膿腫（periapical abscess）","(B) 牙根尖牙骨質-骨質發育不良（periapical cemento-osseous dysplasia）","(C) 牙根尖肉芽腫（periapical granuloma）","(D) 根尖囊腫（radicular cyst）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-1-72","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"下列何種病變之X光影像，最不可能為牙根尖、單房、放射線透過性病變（periapical unilocular radiolucent lesion）？","options":["(A) 根尖囊腫（radicular cyst）","(B) 晚期之牙根尖牙骨質-骨質發育不良（late-stage periapical cemento-osseous dysplasia）","(C) 牙根尖肉芽腫（periapical granuloma）","(D) 牙根尖膿腫（periapical abscess）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-73","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"下圖咬翼片中，三個黑色箭頭所指之放射線透過性（radiolucent）影像為：","options":["(A) Artifact","(B) Recurrent caries","(C) Cervical burnout","(D) Resin filling material"],"answer":1,"image":"ya4-106-1-73.jpeg","clinical_level":"重點"},{"id":"ya4-106-1-74","subject":"ya4","topic":"放射影像診斷","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"早期的根尖牙骨質發育不良（periapical cemental dysplasia）之放射線影像，和下列何者之影像，最為相似？","options":["(A) 根尖囊腫（radicular cyst）","(B) 中期之造牙骨質細胞瘤（cementoblastoma）","(C) 中期之牙骨質化纖維瘤（cementifying fibroma）","(D) 中期之骨化纖維瘤（ossifying fibroma）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-1-75","subject":"ya4","topic":"口腔病理基礎","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"有關含齒囊腫（dentigerous cyst）的敘述，下列何者正確？","options":["(A) 少見完整的邊界","(B) 若產生繼發性的感染後，其邊界會因鈣化而明顯","(C) X光影像除了牙齒外，幾乎呈放射線透性","(D) 很少造成鄰近牙根的吸收"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya4-106-1-76","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"顎骨中柏奇特氏淋巴瘤（Burkitt’s lymphoma）之放射線影像，最常呈現為下列何者？","options":["(A) 界線清楚之放射線透過性病變（radiolucent lesion）","(B) 界線不清楚之放射線透過性病變（radiolucent lesion）","(C) 混合放射線透過性和不透過性病變（mixed radiolucent and radiopaque lesion）","(D) 放射線不透過性病變（radiopaque lesion）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-1-77","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"源自下列那二種器官之顎骨轉移性癌（metastatic carcinoma），最常刺激其周圍正常骨，在放射線影像中可發現新骨形成 （new bone formation）？","options":["(A) 肝和腎","(B) 前列腺和乳房","(C) 大腸和直腸","(D) 食道和胃"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-78","subject":"ya4","topic":"唾液腺疾病","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"一位50歲中年男性，主訴右側口底部疼痛腫大已有多時，進食時疼痛及腫大更嚴重，飯後數小時則慢慢消失，牙醫師臨床檢測 發現右側華頓氏管（Wharton's duct）流量降低、左側正常，經顎全景（圖A）及下顎咬合片（圖B）X光攝影發現一如圖中箭 頭所示之放射線不透性團塊，下列何者為最適當之診斷？","options":["(A) 涎石（sialolith）","(B) 靜脈結石（phlebolith）","(C) 鈣化淋巴結（calcified lymph nodes）","(D) 異物（foreign body）"],"answer":0,"image":"ya4-106-1-78.jpeg","clinical_level":"一般"},{"id":"ya4-106-1-79","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"對於數位影像的敘述下列何者錯誤？","options":["(A) 數位影像無需洗片，可以降低洗片藥劑所造成的污染","(B) 數位影像所需之放射線劑量比傳統影像高","(C) 數位影像之傳輸較不會影響影像品質","(D) 數位影像機組之設立較傳統影像昂貴"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"下列何種因子與輻射生物效應較無關聯性？","options":["(A) Dose","(B) Oxygen","(C) Half-value layer（HVL）","(D) Linear energy transfer（LET）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"手術時能看清楚手術區的因素有那些？ ①適當的操作途徑 ②適當的光源 ③沒有過多的血液或體液","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-2","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"拔牙傷口裡填滿了大量的肉芽組織是從什麼時候出現？","options":["(A) 第一週","(B) 第二週","(C) 第三週","(D) 第四週"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-3","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"一個心血管疾病患者，要安排門診手術下拔牙，下列注意事項中，何者錯誤？","options":["(A) 若病人使用Coumadin，拔牙前應停用2～3天並測量PT值","(B) 手術當天若沒有流血傾向，可以重新開始繼續使用Coumadin","(C) 若病人服用aspirin，又需要緊急手術，可使用凝血劑反轉其功效","(D) 使用heparin的病人要延後至血液中的heparin無活性，至少需要六小時"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-4","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"拔牙後齒槽骨的癒合，其噬骨細胞（osteoclast）聚積於拔牙後的第幾週？","options":["(A) 第一週","(B) 第二週","(C) 第三週","(D) 第四週"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-5","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"以下縫線請依最易引發發炎反應順序排列：①絲線（silk） ②聚酯縫線（polyester） ③聚丙烯 （polypropylene）","options":["(A) ①②③","(B) ③②①","(C) ①③②","(D) ③①②"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"病人接受一般拔牙使用牙科局部麻醉後，在注射部位同一邊產生局部知覺麻痺超過 8 星期之久，最可能發生的 部位為何？","options":["(A) 牙齦","(B) 上唇","(C) 舌部","(D) 腭部"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"下列何項情況是牙周韌帶內注射的禁忌症：","options":["(A) 血友病病人","(B) 注射部位急性發炎","(C) 對兒童及青少年施打","(D) 對上顎臼齒部位施打"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"酯類（ester）局部麻醉劑主要由何種途徑代謝？","options":["(A) 肝臟","(B) 血液","(C) 脾臟","(D) 腦"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-9","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"下列何者不是上顎神經（maxillary nerve）阻斷式麻醉的方法？","options":["(A) 由口外經乙狀切迹（sigmoid notch）進針","(B) 由大腭孔（greater palatine foramen）進針","(C) 由粗隆高位（high tuberosity）進針","(D) 由口外經喙狀突前緣（in front of coronoid process）進針"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-10","subject":"ya4","topic":"局部與全身麻醉","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"下列何者是局部麻醉針最容易斷針的型號？","options":["(A) 30號短針","(B) 27號短針","(C) 25號短針","(D) 23號短針"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"拔除下列那一牙齒時常會應用到旋轉力（rotational pressure）？","options":["(A) 上顎正中門牙","(B) 上顎第一小臼齒","(C) 下顎第一大臼齒","(D) 下顎第二大臼齒"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"基於牙周恢復能力的考量，當病人年齡至少大於幾歲時，其無症狀之阻生齒應可考慮留置在顎骨內而不予以 立即拔除？","options":["(A) 20","(B) 30","(C) 40","(D) 50"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"下列何者不是拔牙的局部禁忌症？","options":["(A) 放射線治療照射區之牙齒","(B) 位於惡性腫瘤範圍內之牙齒","(C) 嚴重牙冠周圍炎之阻生第三大臼齒","(D) 急性牙齒齒槽膿腫 （acute dentoalveolar abscess）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-14","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"拔除下顎第三大臼齒時，做切線翻瓣時，最容易傷害到下列那一條神經，且很難恢復其功能？","options":["(A) 長頰神經","(B) 舌神經","(C) 頦神經","(D) 下顎舌骨神經"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-15","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"使用牙根尖挺（root tip pick或apex elevator）將齒槽內殘餘的牙根尖拔除時，所採用的力學原理為何？","options":["(A) lever","(B) wheel and axle","(C) wedge","(D) axle"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-16","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"有關頭頸部放射線治療後所產生的併發症，下列敘述何者正確？","options":["(A) 造成張嘴困難，主要是因為黏膜下纖維化症（oral submucous fibrosis）的緣故","(B) 造成唾液變少，主要是因為唾液腺導管上皮細胞直接被放射線破壞","(C) 口腔黏膜容易有不易癒合的潰瘍，臨床上常被誤認為是口腔癌復發","(D) 顎骨可能發生壞死，主要造成壞死的細菌是來自於正常口腔細菌叢"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"有關齒源性感染的特性，下列敘述何者正確？","options":["(A) 大部分的齒源性感染平均可以檢驗出約五種細菌","(B) 由培養齒源性感染細菌源中可以發現嗜氧性（aerobic）細菌佔大部分","(C) 由培養齒源性感染細菌源中可以發現厭氧性（anaerobic）細菌佔約30%","(D) 嗜氧性（aerobic）細菌中又以staphylococci族群佔大多數"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-2-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"對於接受頭頸部放射治療之病患，下列措施何者錯誤？","options":["(A) 使用含氟潄口水或局部使用氟膠","(B) 該拔除之牙齒宜於放射治療前拔之","(C) 治療期間每天使用chlorhexidine藥水含潄，並每天用doxycycline 2次口服預防感染","(D) 必要時用nystatine口內含片治療念珠菌感染"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-19","subject":"ya4","topic":"植牙外科","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"有關齒槽骨嵴牽引術 (distraction) 的敘述，下列何者錯誤？","options":["(A) 分為latency、distraction、consolidation三個過程","(B) 可同時增加軟組織及硬組織的量","(C) 一天牽引的量可達 3 mm","(D) 缺點為昂貴，且須二次手術將牽引器取出"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-20","subject":"ya4","topic":"拔牙學與併發症","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"緊鄰的幾顆牙齒一起拔除時，下列關於是否需要做齒槽骨成形術（alveoloplasty）的敘述，何者最正確？","options":["(A) Intraseptal alveoloplasty和simple alveoloplasty兩個名詞完全同義","(B) 如果將來的贋復計畫是人工植牙，最好不做intraseptal alveoloplasty","(C) 如果將來的贋復計畫是人工植牙，最好不做simple alveoloplasty","(D) 如果將來的贋復計畫是人工植牙，應該做intraseptal alveoloplasty"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-21","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"關於唇繫帶切開術的敘述，下列何者錯誤？","options":["(A) 當義齒與唇繫帶附著區產生不舒服或潰瘍時，可能需要唇繫帶切開術，來改善其症狀","(B) 唇繫帶切開術並不能增加全口假牙周圍的封密度，但可增加全口假牙的穩定度","(C) Z-plasty技術可應用在唇繫帶切開術","(D) 唇繫帶切開術併用局部前庭成形術，其傷口以次級上皮癒合方式"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-22","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"有關上顎無牙嵴嚴重萎縮，而必須做齒槽嵴增高術（alveolar ridge augmentation）的敘述，下列何者錯誤？","options":["(A) 上顎竇增高術（sinus lift）也可以算是一種上顎齒槽嵴增高術","(B) 當病人的腭穹窿（palatal vault）深度不足、形狀尚可時，通常會選擇「onlay bone grafting」的術式","(C) 「interpositional bone grafting」的術式，必需配合做「LeFort II」的手術","(D) 統計數據顯示「術後骨吸收量」：「interpositional bone grafting」比「onlay bone grafting」來得少"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"有關TNM系統中，T4的定義，下列何者錯誤？","options":["(A) 唇黏膜癌超過紅唇區","(B) 2公分大小之舌癌侵入至 intrinsic muscle","(C) 頰黏膜癌侵入鄰近骨頭","(D) 上顎牙齦癌侵入鼻竇中"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-2-24","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"有關廣泛性頸部淋巴廓清術（RND），下列何者解剖構造是一定要切除的？","options":["(A) 外頸動脈","(B) 迷走神經","(C) 內頸靜脈","(D) 上甲狀腺動脈"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"下列何者最不是口腔黏膜鱗狀細胞癌之臨床表現？","options":["(A) 容易流血","(B) 觸診時周圍有硬結","(C) 觸診時柔軟可移動","(D) 表面有潰瘍"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-26","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"下列何者非癌前期病變？","options":["(A) leukoplakia","(B) erythroplakia","(C) proliferative verrucous leukoplakia","(D) linea alba"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-27","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"下列有關根尖囊腫（radicular cyst）手術時所做的半月形切線，何者正確？","options":["(A) 剛好沿著囊腫的邊緣，基底部較寬","(B) 剛好沿著囊腫的邊緣，基底部較窄","(C) 寬度超過囊腫的邊緣半公分以上，基底部較寬","(D) 寬度超過囊腫的邊緣半公分以上，基底部較窄"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"基底細胞痣症候群（basal cell nevus syndrome）最常合併出現的囊腫是：","options":["(A) 齒源性角化囊腫 （odontogenic keratocyst）","(B) 殘餘囊腫（residual cyst）","(C) 根尖囊腫（radicular cyst）","(D) 含牙囊腫（dentigerous cyst）"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-2-29","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"施行剜出術（enucleation）時，下列敘述何者正確？","options":["(A) 使用刮匙（curette）時，刮匙凹面向骨頭","(B) 處理根尖囊腫時，如病源牙齒要拔除，最好將牙嵴處頰側齒槽骨板移除，以利清除","(C) 選擇刮匙（curette）時，刮匙面越小越容易清乾淨","(D) 處理囊腫時，刮匙（curette）是從內襯上皮與纖維囊壁之間，來刮除囊腫病灶"],"answer":0,"clinical_level":"重點"},{"id":"ya4-106-2-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"有關posterior maxillary osteotomy手術之敘述，下列何者錯誤？","options":["(A) 必須做顎間固定，以維持良好咬合及有利於骨癒合","(B) 水平骨切線離牙根 5 mm 以上","(C) 可採兩階段完成，一般須間隔4～6週","(D) 頰側垂直骨切線（vertical osteotomy）一般要比水平切線（horizontal osteotomy）先做"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-31","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"有關接受矯正分析病人的敘述，下列何者錯誤？","options":["(A) 測顱分析（cephlometric analysis）是矯正及正顎手術治療的參考標準","(B) 矯正治療的主要目標是讓異常的測顱分析值回歸正常","(C) 在照測顱X光片時病人需咬在中心咬合位置，並將嘴唇放鬆","(D) 測顱X光片可用來評估顏面骨骼不對稱及軟組織輪廓"],"answer":1,"clinical_level":"重點"},{"id":"ya4-106-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"下列何術式可用來治療下顎前突症（mandibular prognathism）？①口內兩側垂直下顎枝骨切開術（intraoral bilateral vertical ramus osteotomy） ②兩側矢向劈裂骨切開術（bilateral sagittal split osteotomy）","options":["(A) 只有①","(B) 只有②","(C) ①②","(D) ①②均不正確"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"如果正常人由左耳外緣到右耳外緣將臉部分成幾等分，那麼從左鼻翼到右鼻翼之間的距離約占臉部的幾分之 幾？","options":["(A) 1/3","(B) 1/5","(C) 1/4","(D) 1/6"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"關於感覺不良（dysesthesia）的敘述，下列何者正確？","options":["(A) 是一種疼痛降低的狀態（hypoalgesia）","(B) 是一種血管炎引起的疼痛","(C) 是一種不愉快的感覺，包含感覺異常（paresthesia）","(D) 對於疼痛沒有感覺（anesthesia）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"有關疱疹後（postherpetic）神經痛的敘述，下列何者錯誤？","options":["(A) 可以發生在任何年齡層","(B) 早年罹患水痘，病毒經一段潛伏期後，再度爆發","(C) 急性期大約可以持續八到十二週","(D) 慢性期的疼痛比急性期較輕微"],"answer":[2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-106-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"患有口腔灼感症候群（burning mouth syndrome）之病患，最常出現疼痛之部位是：","options":["(A) 頰黏膜","(B) 下顎牙齦","(C) 硬腭","(D) 舌"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-2-37","subject":"ya4","topic":"唾液腺疾病","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"腮腺被下列那一條腦神經將腺體分成上下兩葉？","options":["(A) 三叉神經","(B) 顏面神經","(C) 舌咽神經","(D) 舌下神經"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"有關唾液腺惡性腫瘤的敘述，下列何者錯誤？","options":["(A) Mucoepidermoid carcinoma 發生在大唾液腺時，最常發生在腮腺","(B) 若是發生在腮腺，可能會影響顏面神經功能","(C) 發生率最高的是 adenoid cystic carcinoma","(D) Adenoid cystic carcinoma 之預後以 solid type 最差"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-39","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"Sjögren's syndrome是多器官的疾病，下列何者並非其特有之表徵？","options":["(A) 男性較多","(B) 伴隨有類風濕性關節炎","(C) 以唇側小唾液腺切片檢查為精準之診斷方法","(D) 也侵犯淚腺"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-40","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"下列那一種外傷後胸部併發症，對生命的威脅性比較小？","options":["(A) chest ecchymosis","(B) tension pneumothorax","(C) flail chest","(D) hemothorax"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"有關腦脊髓液（CSF）和血清（serum）之間成分的差異，下列敘述何者正確？","options":["(A) chloride在CSF裡面濃度較serum為高","(B) osmolarity在CSF裡面濃度較serum為高","(C) sodium在CSF裡面濃度較 serum為低","(D) β2-transferrin在CSF裡面濃度較serum為低"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"顴骨骨折塌陷移位時造成張口困難，下列何者為最主要原因？","options":["(A) 外傷後組織腫脹","(B) 骨折時引起顳顎關節挫傷","(C) 下顎喙狀突被骨折片擋住","(D) 咬合肌肉受傷"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"下列有關顎骨骨折的治療原則，何者為最重要?","options":["(A) 固定下顎骨","(B) 軟組織縫合","(C) 對回原咬合","(D) 固定上顎骨"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-44","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"有關唇腭裂病人語言障礙問題的因素，何者錯誤？","options":["(A) 發音障礙，造成無法清晰發出詞彙的發音","(B) 唇裂的問題是造成鼻音過重的主因","(C) 咬合與舌頭位置異常造成構音問題","(D) 聽力不良造成語言學習障礙"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-45","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"唇腭裂病人手術條件中，下列何者合乎\"rule of 10\"？","options":["(A) 出生10個月以上","(B) 血紅素10g/dL以上","(C) 體重10公斤以上","(D) 足部長度10公分以上"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-46","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"下列何種情況經常最需要複合性移植（composite graft）手術？","options":["(A) 下顎造釉細胞瘤","(B) 下顎牙齦鱗狀細胞癌","(C) 舌尖之鱗狀細胞癌","(D) 骨髓炎造成之病理性骨折"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-47","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"有關狹心症之敘述，下列何者錯誤？","options":["(A) 會產生左肩、左臂甚至到下顎左側的轉移痛","(B) 可給予硝化甘油舌下含片 0.4 mg治療","(C) 10分鐘後若症狀沒改善且收縮壓低於 90 mmHg，可重複給予 0.4 mg硝化甘油","(D) 20分鐘後若症狀仍沒改善應立即送醫院急診"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-48","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"美國食品暨藥物管理局（FDA）將藥物依據其導致人體胎兒畸型的影響或風險，分成五大類。請問那一個類 別的藥品絕對不可以使用於懷孕婦女身上？","options":["(A) Category A","(B) Category C","(C) Category E","(D) Category X"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"如果一位糖尿病患者要預約拔牙，下列那一時段為他拔牙比較好？","options":["(A) 上午9點","(B) 上午11點","(C) 下午3點30分","(D) 不需考慮特殊時段"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-50","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"骨質疏鬆病患若長期服用類固醇（steroids）及bisphosphonate類藥物，在接受拔牙手術後，發生下列那種狀 況之風險會比一般病患為高？①產生顎骨壞死 ②傷口易出血","options":["(A) 只有①","(B) 只有②","(C) ①②","(D) ①②發生之風險均與一般病患相同"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-51","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"下列何種症狀或診斷不建議使用關節鏡治療?","options":["(A) Internal derangement","(B) Condylar hyperplasia","(C) Degenerative joint disease","(D) Hypermobility"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-52","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"下列何者不是顳顎關節手術常用之切入法？","options":["(A) 耳前","(B) Risdon approach","(C) 耳內","(D) 耳後"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"下列何者不是供應顳顎關節的血流？①咬肌動脈（masseteric artery） ②上顎動脈（maxillary artery） ③ 淺顳動脈（superficial temporal artery） ④深顳動脈（deep temporal artery）","options":["(A) ①④","(B) ②③","(C) 只有④","(D) ②④"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-54","subject":"ya4","topic":"全身性疾病與急症","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"病人有權中止接受治療，下列何者例外？","options":["(A) 家屬要求繼續給予治療","(B) 不接受治療將導致病情惡化","(C) 參與臨床實驗者","(D) 不接受治療可能會威脅其他人的健康"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-55","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"一個沒有藥物過敏史但是低免疫力的病人，需要在牙科手術前給予預防性抗生素治療，以降低齒源性感染的 機會。（請依序回答下列2題） 1.下列那一種抗生素是首選？","options":["(A) Amoxicillin","(B) Clindamycin","(C) Tetracycline","(D) Azithromycin"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-56","subject":"ya4","topic":"齒源性感染與藥物","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"2.優先選擇這種抗生素的主要理由是？","options":["(A) 它屬於廣效性的(broad-spectrum)抗生素","(B) 它對宿主造成過敏反應的機率極低","(C) 它屬於第一線抗生素","(D) 它屬於殺菌劑類(bactericidal)的抗生素"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"下列對X光性質的敘述，何者錯誤？","options":["(A) 是電磁波","(B) 不需介質傳導","(C) 波長比自然光長","(D) 以直線前進"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"下列何者是最能有效減少病患之X光放射線劑量的方法？","options":["(A) 高速底片","(B) 適當之瞄準儀（collimator）","(C) 較高的伏特數","(D) 數位化攝影"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"有關牙科傳統根尖片之敘述，下列何者錯誤？","options":["(A) Radiographic speed是指產生標準牙科影像所需的輻射劑量","(B) Fast film需要相對較低輻射劑量來產生X光影像","(C) Radiographic noise是指操作攝影時會產生的聲音","(D) Film speed之中F片比D片快速"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-60","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"如果主要目的是在於觀察牙齒鄰接面，最理想的放射線檢查為何？","options":["(A) 根尖片","(B) 環口片","(C) 咬翼片","(D) 咬合片"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-61","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"最適用於診斷高位區下顎髁骨頸部（condylar neck）骨折的放射線檢查法是：","options":["(A) Water's projection","(B) PA projection","(C) Reverse Towne projection","(D) Cephalometric projection"],"answer":2,"clinical_level":"一般"},{"id":"ya4-106-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"若不考量被照物及底片的距離（object-film distance），不正確的X-ray水平照射角度（horizontal angulation）會造成下列那個現象？","options":["(A) 影像的延長（elongation）","(B) 影像的縮短（foreshortening）","(C) 沒有明顯的影響","(D) 牙齒影像的重疊（overlapping）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-63","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"下列有關唾液腺攝影術（sialography）的敘述，何者錯誤？","options":["(A) 腺體慢性發炎與腺管疾病是唾液腺攝影的適應症","(B) 打入的顯影藥劑約需15 c.c.左右","(C) 在沒有刺激腺體的情形下，顯影藥劑的排空時間約為5分鐘","(D) 腺體急性感染是禁忌症"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-64","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"下圖根尖片中白色箭頭所指位於右下顎第二小臼齒根尖部位之橢圓形放射線透過性（radiolucent）影像，最可 能為下列何者？","options":["(A) Radicular cyst","(B) Lingual foramen","(C) Mental foramen","(D) Apical scar"],"answer":2,"image":"ya4-106-2-64.jpeg","clinical_level":"重點"},{"id":"ya4-106-2-65","subject":"ya4","topic":"口腔外科基礎","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"鉤狀突（hamular process）為由下列那一構造，往下延伸之一放射線不透過性（radiopaque）突出物？","options":["(A) 上顎粗隆（maxillary tuberosity）","(B) 內翼板（medial pterygoid plate）","(C) 外翼板（lateral pterygoid plate）","(D) 後翼板（posterior pterygoid plate）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-66","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"在正常情況下，內斜嵴在第二臼齒的咬翼片可以看到其radiopaque之程度比外斜嵴：","options":["(A) 強","(B) 弱","(C) 相似","(D) 無法辨識"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-67","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"下列選項中，在根尖片所呈現之影像，何者最不明顯？","options":["(A) Root caries","(B) Periapical inflammatory lesions","(C) Cervical burnout","(D) Periodontitis"],"answer":2,"image":"ya4-106-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-106-2-68","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"下列何者需以放射線影像來確定診斷？","options":["(A) Taurodontism","(B) Talon cusp","(C) Turner's tooth","(D) Dens evaginatus"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-69","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"一名15歲女孩，因右上顎牙齦腫大多時而求診，電腦斷層檢查如圖。最可能的診斷為何？","options":["(A) Ameloblastoma","(B) Adenomatoid odontogenic tumor","(C) Gorlin syndrome","(D) Dentigerous cyst"],"answer":1,"image":"ya4-106-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-106-2-70","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"如圖所示，箭頭處有何種牙齒相關病變？","options":["(A) 小牙症（microdontia）","(B) 牙中牙（dens invaginatus）","(C) 先天缺牙（congenital missing）","(D) 卡拉貝利牙阜（cusp of Carabelli）"],"answer":2,"image":"ya4-106-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-106-2-71","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"下圖中，有何種牙齒相關的病變？","options":["(A) Twinning","(B) Fusion","(C) Gemination","(D) Concrescence"],"answer":1,"image":"ya4-106-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-106-2-72","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"下圖十歲孩童之X光影像，最有可能之X光診斷為：","options":["(A) 加勒氏骨髓炎（Garre's osteomyelitis）","(B) 多發性骨髓瘤（multiple myeloma）","(C) 纖纖性發育不良（fibrous dysplasia）","(D) 骨硬化症（osteopetrosis）"],"answer":0,"image":"ya4-106-2-72.jpeg","clinical_level":"一般"},{"id":"ya4-106-2-73","subject":"ya4","topic":"口腔病理基礎","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"下列何種齒源性病變，其X光影像，較常呈現單房性放射線透過性病變（unilocular radiolucent lesion），包 圍未萌出牙之牙冠，可能含有少量鈣化物質，且較好犯於10至19歲女孩或年輕女性患者之上顎或下顎前齒 區？","options":["(A) 造釉細胞纖維齒瘤（ameloblastic fibro-odontoma）","(B) 造釉細胞瘤（ameloblastoma）","(C) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(D) 造釉細胞纖維瘤（ameloblastic fibroma）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-106-2-74","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"下列何種病變，其發生位置和X光影像，與硬化性骨炎（condensing osteitis）最為相似？","options":["(A) 骨之柏哲德氏病（Paget's disease of bone）","(B) 晚期牙根尖牙骨質-骨質發育不良（late-stage periapical cemento-osseous dysplasia）","(C) 纖維發育不良（fibrous dysplasia）","(D) 牙根尖肉芽腫（periapical granuloma）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-106-2-75","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"要檢查華頓氏管（Wharton’s duct）之遠心端（distal portion），是否有涎石（sialolith），最好採用下列何種 放射線檢查法？","options":["(A) 環口放射線攝影術（panoramic radiography）","(B) 唾液腺攝影術（sialography）","(C) 咬翼放射線攝影術（bitewing radiography）","(D) 咬合放射線攝影術（occlusal radiography）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-76","subject":"ya4","topic":"放射影像診斷","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"以下放射線影像都很相似，但何者例外？","options":["(A) Traumatic bone cyst","(B) Radicular cyst","(C) Eosinophilic granuloma","(D) Gorlin cyst"],"answer":3,"clinical_level":"一般"},{"id":"ya4-106-2-77","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"下圖影像箭頭所指最接近的診斷為下列何者？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 放射線骨壞死（osteoradionecrosis）","(C) 鱗狀細胞癌（squamous cell carcinoma）","(D) 纖維性發育不良（fibrous dysplasia）"],"answer":3,"image":"ya4-106-2-77.jpeg","clinical_level":"一般"},{"id":"ya4-106-2-78","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"頭顱放射線影像顯示似多發性骨髓瘤（multiple myeloma）之punched-out lesion，而屬於齒槽骨型病灶之放 射線影像又看似牙周病時，最有可能是下列何種疾病？","options":["(A) leukemia","(B) Burkitt’s lymphoma","(C) osteogenic sarcoma","(D) Langerhans cell histiocytosis"],"answer":3,"clinical_level":"重點"},{"id":"ya4-106-2-79","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"照射牙科數位影像時，需要雷射掃瞄器的是那一種感應片（sensor）？","options":["(A) Photostimulable phosphor plates（PSP）","(B) Charge-coupled device（CCD）","(C) Complementary metal oxide semiconductor（CMOS）","(D) 均不需要雷射掃瞄器"],"answer":0,"clinical_level":"一般"},{"id":"ya4-106-2-80","subject":"ya4","topic":"放射線原理與技術","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"引起somatic stochastic effect一般在下列何種劑量較易發生？","options":["(A) High dose of radiation","(B) Low dose of radiation","(C) Median dose of radiation","(D) High dose rate irradiation"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-1","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"下列何種病人需要及早考慮手術去除感染原因及大量給予抗生素以避免產生感染擴散？","options":["(A) 缺血性心臟病（ischemic heart disease）合併短暫疼痛病史","(B) 有心律不整且使用心律調節器（pacemaker）","(C) 腎臟移植並服用免疫抑制劑","(D) 非胰島素依賴型（Non-insulin dependent）糖尿病"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"關於「缺血」（ischemia）不利於傷口癒合的原理，下列敘述何者錯誤？","options":["(A) 傷口內血腫（hematoma）所形成的內在壓迫（internal pressure），不至於引起「缺血」","(B) 「缺血」的區域容易進一步導致組織壞死","(C) 「缺血」的區域也會缺氧","(D) 比較容易傷口感染"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-3","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"下列有關全身麻醉手術前之準備工作項目，其最合理的順序為何？①調整病人身體及頭頸部的位置以利手術進 行 ②插氣管內管（endotracheal intubation）並予以固定 ③調整手術燈的位置與角度 ④消毒手術部位與 舖手術單","options":["(A) ①→②→④→③","(B) ②→①→③→④","(C) ②→③→④→①","(D) ②→④→③→①"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-4","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"經由大腭孔進針的上顎神經阻斷式麻醉，下列何者錯誤？","options":["(A) 大腭孔位於上顎第二大臼齒遠心腭側","(B) 注射速度一般為半分鐘打 1 管","(C) 平均進針深度為 30 mm","(D) 有注入眼窩與鼻腔的可能"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-5","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"下列何者較少使用在牙齒麻醉？","options":["(A) 下齒槽神經阻斷麻醉","(B) 後上齒槽神經阻斷麻醉","(C) 眼眶下神經阻斷麻醉","(D) 頦神經阻斷麻醉"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"體重65公斤之女性病患於下顎神經阻斷注射第二管 2 % lidocaine後感覺不適並顯得焦慮，病患漸漸感覺疲 勞，言語含混不清，並感覺嘴巴麻麻的，此情況最可能是？","options":["(A) 因病人有吸食其他毒品","(B) 因過量給藥而造成藥物過量","(C) 因麻醉劑注入血管","(D) 病患對 lidocaine 過敏"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"下列有關局部麻醉藥物之敘述，何者正確？","options":["(A) 肝臟是局部麻醉藥物及其分解物的主要排出器官，故針對肝臟功能不佳病患使用時應注意其總量","(B) 腎臟是局部麻醉藥物及其分解物的主要排出器官，故針對腎臟功能不佳病患使用時應注意其總量","(C) 肝臟及腎臟是局部麻醉藥物及其分解物的兩個器官，故針對肝腎功能不佳病患使用時應注意其總量","(D) 脾臟是局部麻醉藥物及其分解物的主要排出器官，故針對脾臟功能不佳病患使用時應注意其總量"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"有關27 gauge麻醉針頭若打到血管，倒抽有血之機率，下列何者正確？","options":["(A) 2 %","(B) 27 %","(C) 87 %","(D) 100 %"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-9","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"上顎正中贅生齒阻生，阻礙恆牙萌出。下列何階段最適合拔除此贅生齒？","options":["(A) 恆門齒牙根發育1/4～1/3","(B) 恆門齒牙根發育 1/2～2/3","(C) 恆門齒牙根發育完成，但根尖尚未閉合","(D) 恆門齒牙根發育完成，根尖已閉合"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"拔除下顎第三大臼齒或口腔手術，須於臼齒後墊（retromolar pad）區域做切線時，應採取下列何原則？","options":["(A) 切線應偏舌側，以免損傷頰神經（buccal nerve）","(B) 切線應位於正中央，以免損傷頦神經（mental nerve）","(C) 切線應偏頰側，以免損傷舌神經（lingual nerve）","(D) 切線位置與神經損傷無關"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"有關乾性齒槽（dry socket），下列處理何者正確？","options":["(A) 給予口服類固醇3天","(B) 手術清創及縫合","(C) 給予口服抗生素2週","(D) 給予局部敷料或口服止痛藥物"],"answer":3,"clinical_level":"重點"},{"id":"ya4-107-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"拔牙所運用的機械原理不外乎是：①槓桿（lever） ②楔型（wedge） ③輪軸（wheel and axle），拔牙 鉗的喙（beaks）在用力夾住牙齒時所運用的原理為何？","options":["(A) 只有①","(B) 只有②","(C) 只有③","(D) ②③"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-13","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"欲拔除下顎第二小臼齒，除了麻醉下齒槽神經（inferior alveolar nerve）外，尚需外加下列何神經之麻醉？","options":["(A) 舌神經","(B) 長頰神經","(C) 舌神經及長頰神經","(D) 不需要另加任何麻醉"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-1-14","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"病人主訴右下顎骨智齒區域腫痛已有三天，如圖所示，下列診斷何者最適當？","options":["(A) 牙冠周圍炎（pericoronitis）","(B) 鱗狀細胞癌（squamous cell carcinoma）","(C) 化膿性肉芽腫（pyogenic granuloma）","(D) 含牙性囊腫（odontogenic cyst）"],"answer":0,"image":"ya4-107-1-14.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"70歲的女性病人抱怨其左下顎骨在拔牙之後就開始疼痛，如下圖，則何者臆斷比較接近臨床與環口X光片發 現？","options":["(A) 骨瘤（osteoma）","(B) 牙骨質化纖維瘤（cementifying fibroma）","(C) 骨髓炎（osteomyelitis）","(D) 骨肉瘤（osteosarcoma）"],"answer":2,"image":"ya4-107-1-15.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"下列那一種菌種在齒源性感染中屬於伺機性感染菌種（opportunistic organisms）？","options":["(A) Anaerobic Gram-negative cocci","(B) Anaerobic Gram-positive cocci","(C) Anaerobic Gram-negative rods","(D) Aerobic Gram-positive cocci"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-17","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"根據2007年美國心臟學會建議，要預防成年人牙科手術後心臟內膜炎的發生，如果術前給予Clindamycin， 下列劑量何者正確？","options":["(A) 300mg","(B) 600mg","(C) 900mg","(D) 1200mg"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"如下圖所示，下列那一個診斷比較正確？","options":["(A) Necrotizing fasciitis","(B) Abscess","(C) Osteomyelitis","(D) Ludwig’s angina"],"answer":1,"image":"ya4-107-1-18.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-19","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"舌繫帶不包含下列何者？","options":["(A) 黏膜（mucosa）","(B) 緻密的結締組織（dense fibrous tissue）","(C) 頦舌肌（genioglossus muscle）","(D) 頦舌骨肌（geniohyoid muscle）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-20","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"有關唇繫帶切除術（labial frenectomy）之敘述，下列何者錯誤？","options":["(A) Z-plasty適用於寬的繫帶","(B) Z-plasty可以減少術後前庭變淺的問題","(C) 須將骨膜保留，在骨膜上方剝離（supraperiosteal dissection）","(D) 雷射切除可減少術後疼痛及腫脹"],"answer":0,"clinical_level":"重點"},{"id":"ya4-107-1-21","subject":"ya4","topic":"植牙外科","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"植牙過程中，以下那一步驟不合適？","options":["(A) 手術鑽頭鈍了就丟棄","(B) 植牙時大量沖水","(C) 無菌操作","(D) 應使用無菌手套拿取植體"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-22","subject":"ya4","topic":"植牙外科","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"牽引骨生成術（distraction osteogenesis）可用來增加齒槽骨量以利牙科植體之種植，下列那項是此一技術 之缺點？","options":["(A) 需由別處取用自體骨（autogenous bone）","(B) 無法同時增加軟組織","(C) 牽引裝置維持在口內時會造成病患不方便","(D) 一天要轉動好幾次"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-23","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"有關齒源性角化囊腫（odontogenic keratocyst）的敘述，下列何者正確？","options":["(A) 上顎骨發生的機會比下顎骨多","(B) 手術後比其他囊腫的復發率低","(C) 發生在後牙區的機會比前牙區多","(D) 發生在老年人比較多"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya4-107-1-24","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"下列那種囊腫經剜出術（enucleation）治療後之復發率最高？","options":["(A) 根尖囊腫（radicular cyst）","(B) 含齒囊腫（dentigerous cyst）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 孤立性骨囊腫（solitary bone cyst）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-1-25","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"施行剜出術（enucleation）治療顎骨中囊腫時，下列那些作法正確？①盡量用最小的刮匙以縮小骨開窗之範 圍 ②先將囊腔內容物抽出以減低腔內壓力 ③以刮匙（curette）之凹面向骨將囊膜（cystic membrane） 剝離 ④將囊膜分開數片以利剜出","options":["(A) ①②","(B) ②③","(C) ③","(D) ④"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-26","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"在maxillary LeFort I osteotomy手術中那一個方向之上顎移動最容易導致alar base變寬的情形？","options":["(A) anterior and superior reposition","(B) posterior reposition","(C) inferior reposition","(D) lateral reposition"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-27","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"有數種術式曾被用來治療下顎後縮症，目前最常被使用的是下列那一種？","options":["(A) 下顎枝C形骨截開術（C-shape ramus osteotomy）","(B) 下顎枝倒L形骨截開術（inverted L osteotomy）","(C) 兩側矢向劈裂骨截開術（bilateral sagittal split osteotomy）","(D) 口內垂直下顎枝骨截開術（intraoral vertical ramus osteotomy）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-28","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"施行下顎兩側矢狀分裂骨切開術（bilateral sagittal split osteotomy）後，髁狀突是位於下列何部分？①下顎 枝部（ramus） ②下顎後體部（posterior body of the mandible） ③近心部 ④遠心部","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-29","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"當一位病人經齒列矯正後，咬合正常，但仍嫌下巴太長，可使用下列何種手術處理?","options":["(A) bilateral sagittal split osteotomy","(B) bilateral vertical ramus osteotomy","(C) anterior osteotomy","(D) genioplasty"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-30","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"下列何種顏面神經痛會合併心跳過緩（bradycardia）、血壓低下（hypotension）、休克（syncope）之發 生？","options":["(A) 三叉神經痛（trigeminal neuralgia）","(B) 迷走舌咽神經痛（vagoglossopharyngeal neuralgia）","(C) 非典型顏面痛（atypical facial pain）","(D) 侖謝亨特症候群（Ramsay Hunt syndrome）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-31","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"下列那一種感覺神經傳導最快？","options":["(A) Aα","(B) Aβ","(C) Aγ","(D) Aδ"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-32","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"一名病患經檢查發現當舌頭前伸時偏向左側，則該患者是那一條神經受損？","options":["(A) 右側舌下神經","(B) 左側舌下神經","(C) 右側舌神經","(D) 左側舌神經"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-33","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"sialodochitis是因為反覆發炎所造成之唾液腺管道上皮萎縮及反覆纖維化的疾病，其在唾液腺攝影上的表徵為 何？","options":["(A) sausage-link pattern","(B) ball-in-hand appearance","(C) blossom of apple tree","(D) interspersed radiolucency and radiopaque appearance"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-34","subject":"ya4","topic":"唾液腺疾病","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"為診斷Sjögren's syndrome做下唇的切片檢查，下列何者正確？","options":["(A) 應選擇下唇正中位置","(B) 應找出至少5顆以上的小唾液腺體","(C) 應包含下唇黏膜","(D) 檢體不能泡福馬林"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-35","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"在下列3張唾液攝影中，何者呈現發炎現象？","options":["(A) 只有①②","(B) 只有②③","(C) 只有①③","(D) ①②③"],"answer":2,"image":"ya4-107-1-35.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-36","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"顏面外傷時，如懷疑有顴骨弓骨折（zygomatic arch fracture），下列那一種影像檢查最適當？","options":["(A) 華特氏攝影法（Waters' view）","(B) 陶恩氏攝影法（Towne's view）","(C) 環口攝影法（Panoramic view）","(D) 頦下顱頂攝影法（Submental vertex view）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-37","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"急診處理頭頸部外傷的病人時，必須詢問下列問題，其中最不重要的是：","options":["(A) 發生的原因","(B) 外傷後有無噁心、嘔吐","(C) 有無尋獲脫落的牙齒","(D) 肇事者有無報警"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-38","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"下列關於顏面軟組織挫傷（contusion）之處置，何者錯誤？","options":["(A) 須查看有無骨折發生","(B) 若挫傷持續腫大，可能須外科手術結紥血管","(C) 傷口有破裂出血，須服用抗生素","(D) 挫傷所形成之血塊最後會由人體自行吸收"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-39","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"12歲男孩因跌倒，導致已萌出之右上顎正中門牙脫落（avulsion）。經醫師緊急處理後，將該牙植回原齒槽 窩（replantation）並固定，其固定之適當時間為多久？","options":["(A) 3～5天","(B) 1～2星期","(C) 3～4星期","(D) 2～4月"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-40","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"胚胎期間，有關鼻、唇與腭的形成敘述，下列何者正確？","options":["(A) 此三部位的形成在胚胎期的第3～9週","(B) 鼻部的形成最晚","(C) 上腭區的發育比鼻部發育約晚2週","(D) 上腭棚（palatal shelves）與原發上腭（primary palate）融合期約在胚胎期第 9～12週"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-41","subject":"ya4","topic":"植牙外科","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"有關xenografts之敘述，下列何者錯誤？","options":["(A) 等同於heterografts","(B) 免疫反應比homografts更大","(C) 以牛骨或豬骨為主","(D) 主要用於大型顎骨缺損"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-42","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"唇腭裂在牙科領域中，最常發現的問題中不包括下列何者？","options":["(A) 天生缺牙（congenital missing of teeth）","(B) 多生牙（supernumerary teeth）","(C) 咬合不正（malocclusion）","(D) 呈現第二類咬合"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-43","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"一般建議血中血小板數目應至少在多少以上，才適合接受一般拔牙手術？","options":["(A) 10000/dL","(B) 20000/dL","(C) 50000/dL","(D) 100000/ dL"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-44","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"哺乳產婦應避免使用那些藥物？①tetracycline ②acetaminophen ③metronidazole ④corticosteroid","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-45","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"下列之敘述，何者錯誤？","options":["(A) 若病人出現中風症狀如手腳發麻、視力模糊，應讓病人維持腳高頭低的姿勢且給予氧氣治療","(B) 一位健康的72公斤病人，拔牙前施打每管1.8ml的2% Lidocaine（1:100,000 epinephrine），一次最多不可 超過10管","(C) 因施打過量麻藥而產生心律不整或癲癇發作時，可靜脈緩慢注射5-10mg diazepam，之後送醫院急診","(D) 當病人發生低血糖急症時，若意識不清無法口服，應立即建立IV line並給予D50W或昇糖素"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-46","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"有一位懷孕八週的婦女因右側上唇、鼻翼附近及犬齒、門齒區域的前庭軟組織腫脹、疼痛，為期已經三天， 腫脹處還有波動感（fluctuation）。請問下列處置中，那一項最不合理？","options":["(A) 告訴該孕婦：因屬懷孕初期，不可做任何口腔X光檢查","(B) 不必告知她的婦產科醫師就給予任何抗生素抑制感染","(C) 檢查及治療時，可讓該孕婦仰臥，但不可太久","(D) 告訴該孕婦此時不可接受任何手術"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-47","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"下列何種處置，最難在顳顎關節鏡手術中完成？","options":["(A) condylar shaving","(B) fibrous band lysis","(C) plication","(D) lavage"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-48","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"下列何者疾病不適合以顳顎關節攝影（arthrography）作為診斷方法？","options":["(A) 顳顎關節盤破裂（disc perforation）","(B) 可復位性關節盤前移（anterior disc displacement with reduction）","(C) 不可復位性關節盤前移（anterior disc displacement without reduction）","(D) 骨性黏連（bony ankylosis）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-49","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"下列何者最不需要顳顎關節穿刺術（arthrocentesis）？","options":["(A) 不可復性關節盤前移（disc anterior disc displacement without reducion）","(B) 筋膜炎（myofascitis）","(C) 骨關節炎（osteoarthritis）","(D) 類風濕性關節炎（rheumatoid arthritis）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-1-50","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"有關臨床試驗研究，下列何者是紐倫堡規範（Nuremberg code）所抱持的精神？","options":["(A) 在進行臨床研究時，受試者須出於自願且知情同意為絕對必要條件","(B) 從事人體實驗只能進行對病人有益處的治療，禁止一般性知識的研究","(C) 以病人為中心的倫理原則為基礎","(D) 臨床研究設計必須精確，論證需紮實"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-51","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"採用高溫高壓蒸氣鍋（autoclave）消毒時，若條件設定為121℃、15psi時，一般消毒時間需時多久？（請依 序回答下列2題）","options":["(A) 60分鐘","(B) 24分鐘","(C) 4分鐘","(D) 1.5分鐘"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-52","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"承上題，在同樣的溫度條件下，採用乾熱（dry heat）消毒法時，需時多久？","options":["(A) 18～24小時","(B) 6～12小時","(C) 3～4小時","(D) 1～2小時"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-53","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"如下圖所示，一位9歲男童因左臉頰無痛性腫脹而來求診，依據此影像檢查的鑑別診斷，下列那一項最合 理？（請依序回答下列2題）","options":["(A) Cherubism","(B) Fibrous dysplasia","(C) Adenomatoid odontogenic tumor","(D) Odontogenic myxoma"],"answer":3,"image":"ya4-107-1-53.jpeg","clinical_level":"重點"},{"id":"ya4-107-1-54","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"承上題，依據您的鑑別診斷，則下列治療的方式，何者最不正確？","options":["(A) Curettage","(B) Partial resection","(C) Surgery with radiotherapy","(D) Enucleation"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-1-55","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"一位15歲女學生，其環口放射線影像（panorex）顯示左側下顎小臼齒與大臼齒區域有一個單室性囊狀病灶 （unicystic radiolucency），最大徑約4公分而且明顯將同側mandibular canal向下推擠至下顎骨下緣（lower border），電腦斷層掃描影像顯示病灶周圍皮質骨膨脹但仍完整無破損。經切片檢查後證實為齒源性囊腫， 但其中也有部分囊腫的上皮發生造釉細胞瘤的變化（如下圖所示）。（請依序回答下列2題） 1.下列敘述那一項正確？","options":["(A) Mural unicystic ameloblastoma","(B) Intramural ameloblastoma","(C) Intraluminal ameloblastoma","(D) Transmural ameloblastoma"],"answer":0,"image":"ya4-107-1-55.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-56","subject":"ya4","topic":"口腔外科基礎","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"2.下列手術治療方式那一項最不合理？","options":["(A) Partial resection of mandible","(B) Enucleation","(C) Marsupialization","(D) Curettage"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"有關牙科診斷用放射線的敘述，下列何者錯誤？","options":["(A) X光光束是由數百萬個具相同能量的X光子所組成","(B) X光可經由改變X光中光子的數量來改變X光強度（intensity）","(C) X光可經由改變X光中光子的能量來改變X光品質（quality）","(D) X光是一種游離輻射（ionizing radiation）"],"answer":0,"clinical_level":"重點"},{"id":"ya4-107-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"我國原子能委員會將牙科醫師視同為一般民眾，根據ICRR之新規範，其每年曝露劑量不得超過：","options":["(A) 1 Sv","(B) 1 cSv","(C) 1 mSv","(D) 1 µSv"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"使用增感屏（intensifying screen）可將敏感度（sensitivity）最高提升幾倍？","options":["(A) 1","(B) 10","(C) 60","(D) 100"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-60","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"檢視後牙牙根尖片時，X光片要如何放置？","options":["(A) 直放","(B) 橫放","(C) 斜放","(D) 無規定"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"為了要避開顴骨（zygomatic bone）觀察上顎大臼齒根尖病變，最理想的口內放射線檢查法為何？","options":["(A) 分角線法","(B) 平行法","(C) 咬翼片攝影","(D) 咬合片攝影"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-1-62","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"附圖之兩張根尖X光片上分別有白圈與白點，下列何者不是造成此顯影不足現象之原因？","options":["(A) 因氣泡而引起","(B) 灰塵附在片子上","(C) X光片先接觸到清水","(D) X光片先接觸到定影液"],"answer":2,"image":"ya4-107-1-62.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-63","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"口內X光片於洗片後發現有車輪狀痕跡（如附圖所示），其最可能之原因為何？","options":["(A) 氣泡引起的投影","(B) 灰塵附著在X光片上的投影","(C) X光片於洗片時，先接觸到定影液","(D) X光片反面之鉛片的投影"],"answer":3,"image":"ya4-107-1-63.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-64","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"附圖根尖X光片中，黑色箭頭所指之放射線透過性（radiolucent）影像為何種構造？","options":["(A) neurovascular canal","(B) extension of periapical lesion","(C) artifact of x-ray image","(D) fracture line of bone"],"answer":0,"image":"ya4-107-1-64.jpeg","clinical_level":"重點"},{"id":"ya4-107-1-65","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"附圖根尖X光片中白色箭頭所指最可能為下列何者？","options":["(A) floor of the maxillary sinus","(B) hamulus process","(C) zygomatic process of the maxilla","(D) pterygoid plate"],"answer":2,"image":"ya4-107-1-65.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-66","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"下列何者在正常情況下，其放射線影像呈現放射線不透過性（radiopaque）？","options":["(A) maxillary sinus","(B) incisive foramen","(C) genial tubercle","(D) mandibular canal"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-1-67","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"32歲女性患者之根尖片影像如圖所示，其中箭頭所指影像之敘述，下列何種組合正確？","options":["(A) 1為zygomatic process of maxilla，2為maxillary sinus floor","(B) 1為zygomatic process of maxilla，2為radicular cyst","(C) 1為artificial defect，2為maxillary sinus floor","(D) 1為artificial defect，2為 radicular cyst"],"answer":0,"image":"ya4-107-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-68","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"圖中所示，左下第一大臼齒根尖處的病變最可能為下列何者？","options":["(A) 根尖囊腫（radicular cyst）","(B) 齒源性角化囊腫（odontogenic keratocyst）","(C) 造牙骨質細胞瘤（cementoblastoma）","(D) 根尖肉芽腫（pericapical granuloma）"],"answer":2,"image":"ya4-107-1-68.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-69","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"下列何種齒源性病變，其X光影像，較常呈現多房性放射線透過性病變（multilocular radiolucent lesion）， 且較好犯於20至40歲患者之下顎臼齒區及上升枝（ascending ramus）？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 造釉細胞瘤（ameloblastoma）","(C) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(D) 造釉細胞纖維瘤（ameloblastic fibroma）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-1-70","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"如圖所示顎骨病變中黑色箭頭及白色箭頭所指之放射線不透過性（radiopaque）影像，最有可能分別為下列 何者？","options":["(A) fractured alveolar crest and fractured cortical bone","(B) sequestra and periosteal reaction","(C) tumor mass and cortical invasion","(D) fractured alveolar crest and hyoid bone"],"answer":1,"image":"ya4-107-1-70.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-71","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"下列那一病變，其放射線影像最不可能出現內部鈣化（internal calcification）的情形？","options":["(A) 造釉細胞纖維齒瘤（ameloblastic fibro-odontoma）","(B) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(C) 平伯氏腫瘤（Pindborg tumor）","(D) 鼻腭管囊腫（nasopalatine duct cyst）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-72","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"利用一張牙根尖片（periapical film）檢查史坦生氏管（Stensen’s duct）之涎石（sialolith），其X光之曝光 時間與正常照射臼齒之牙根尖放射線攝影時間相較，應如何調整較好？","options":["(A) 增加一半","(B) 增加三分之一","(C) 維持不變","(D) 減少一半"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-73","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"含齒囊腫（dentigerous cyst）和該相關牙相連之部位，最常為下列何處？","options":["(A) 牙冠中1/3和下1/3交界","(B) 牙骨質牙釉質交界（cementoenamel junction）","(C) 牙根上1/3和中1/3交界","(D) 牙根中1/3和下1/3交界"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-1-74","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"放射線影像若呈現下列根尖病變，何者之牙髓仍具活性反應？","options":["(A) 根尖肉芽腫（periapical granuloma）","(B) 根尖囊腫（radicular cyst）","(C) 根尖牙骨質發育不良（periapical cemental dysplasia）","(D) 急性根尖膿腫（acute periapical abscess）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-1-75","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"20歲女性患者，右臉腫脹疼痛已有6個月，放射線影像（如附圖）呈現骨破壞，並有sun-ray appearance， 其最可能的診斷為何？","options":["(A) 骨性肉瘤（osteogenic sarcoma）","(B) 骨髓炎（osteomyelitis）","(C) 血管瘤（hemangioma）","(D) 造釉細胞瘤（ameloblastoma）"],"answer":0,"image":"ya4-107-1-75.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-76","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"頰側雙叉囊腫（buccal bifurcation cyst），最常發生於下列那顆牙齒處？","options":["(A) 下顎第一大臼齒","(B) 下顎第二大臼齒","(C) 下顎第三大臼齒","(D) 上顎第一大臼齒"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-1-77","subject":"ya4","topic":"口腔病理基礎","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"8歲女孩主訴右下顎骨膨大、右下顎第一乳臼齒鬆動、牙齦滲血，將該牙往下壓，不久又慢慢浮起來，牙齦 仍然滲血，從環口X光影像（如附圖）發現兩側下顎骨體處有一大的放射線透性影像，右下顎第一、二小臼 齒與左側小臼齒比較有提早萌出之傾向，右下顎第一恆臼齒下方有一呈蜂窩狀之放射線透性影像，下列何者 是最佳之臨床診斷？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 造釉細胞瘤（ameloblastoma）","(C) 天使病（cherubism）","(D) 骨內血管瘤（central hemangioma）"],"answer":3,"image":"ya4-107-1-77.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-78","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"細胞之輻射效應不包括下列何者？","options":["(A) mitotic delay","(B) chromosome aberrations","(C) cell death","(D) most effects are instant"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-1-79","subject":"ya4","topic":"放射影像診斷","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"36歲男性來追蹤檢查其下顎右側後方假牙區，經X光檢查如附圖所示，箭頭所示之處最可能的診斷為何？","options":["(A) 牙瘤（odontoma）","(B) 骨肉瘤（osteosarcoma）","(C) 橋體下方骨增生（subpontic osseous hyperplasia）","(D) 下顎隆突（torus mandibularis）"],"answer":2,"image":"ya4-107-1-79.jpeg","clinical_level":"一般"},{"id":"ya4-107-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"有關數位charge-coupled device（CCD）的X光感應器的敘述，下列何者錯誤？","options":["(A) 不可以用高溫高壓滅菌","(B) 是密封式且防水的","(C) 必須有一個保護罩包住","(D) 可以微摺以適合口腔內拍攝"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"下列何者不是施行造袋術考量的重點？","options":["(A) 傷害鄰近重要結構","(B) 幫助牙齒萌發","(C) 囊腫大小","(D) 病人年紀"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-2","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"有關AIDS病人，下列敘述何者正確？","options":["(A) 當皮膚有傷口時，接觸病人的體液是造成感染的原因之一","(B) HIV離開宿主體內後，約可在體外生存一星期","(C) 與病人接吻，會感染HIV","(D) 病人血中病毒數最少為103"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"組織切除後，若不易縫合，通常要 undermine 傷口寬度之多少倍為宜？","options":["(A) 一半","(B) 一倍","(C) 一倍半","(D) 二倍"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-4","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"下列關於牙齦翻瓣的原則，何者錯誤？","options":["(A) 翻瓣游離端（free margin）不可比基底（base）寬","(B) 翻瓣的底部尺寸不可少於高度尺寸，最好底部尺寸是高度尺寸的兩倍","(C) 長的傷口癒合期較短的傷口癒合期長，所以一開始翻瓣不要翻的太大","(D) 常用手術的皮瓣（flap）是袋狀瓣（envelope flap）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-5","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"下列何藥物對正在哺乳之嬰兒，可能產生潛在之危害？","options":["(A) Erythromycin","(B) Acetaminophen","(C) Ampicillin","(D) Lidocaine"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"阻斷式麻醉較易引起血腫（hematoma）的三個部位，依序為何？","options":["(A) 後上齒槽神經、頦神經、下齒槽神經","(B) 下齒槽神經、後上齒槽神經、頦神經","(C) 後上齒槽神經、下齒槽神經、頦神經","(D) 下齒槽神經、頦神經、後上齒槽神經"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-7","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"治療缺血性心臟病（ischemic heart disease）患者，最多可使用 4% articaine, 1:200,000 epinephrine 之 cartridge(s) (1.8 ml/cartridge)？","options":["(A) 6","(B) 8","(C) 10","(D) 4"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"目前牙科使用之麻醉藥物中，不含下列何種成分？","options":["(A) 甲基亞苯（methylparaben）","(B) 重硫酸鹽鈉（sodium bisulphite）","(C) 鹽（sodium chloride）","(D) 蒸餾水（distilled water）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"使用cowhorn拔牙鉗，拔除結構大致完整的下顎第一大臼齒。下列何方式正確？","options":["(A) 其尖端置於該齒前齒頸部","(B) 其尖端置於該齒後齒頸部","(C) 其尖端均勻夾在該齒齒頸部","(D) 其尖端置於該齒牙根分叉處"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"拔牙後流血，下列處理方式何者最不適當？","options":["(A) 移除肉芽組織並置入absorbable gelatin sponge","(B) 紗布再加壓至少30分鐘","(C) 施以局部麻藥於患處","(D) 使用吸唾管將血塊吸走即可"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"拔除阻生第三大臼齒最佳的時機，是在牙根形成的何一時期？","options":["(A) 未形成時","(B) 形成1/3至2/3間","(C) 形成2/3至完全形成間","(D) 完全形成以後"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-12","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"下列那種器械比較不適合用來移除堅硬的骨頭？","options":["(A) Rongeur forceps","(B) Curette","(C) Bone file","(D) Mallet and chisel"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"當你拔除一個上顎臼齒後，懷疑有口竇相通，你會建議患者一些注意事項，下列那一個建議不包括在內？","options":["(A) 拔牙後的前2天少唱歌","(B) 拔牙後的前2天少打噴嚏","(C) 拔牙後的前2天少擤鼻涕","(D) 拔牙後的前2天少用吸管吸飲料"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-14","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"在接受放射線治療的病人，下列那一種口腔微生物比較容易增多（overgrowth）？","options":["(A) Candida albicans","(B) Actinomyces","(C) Aerobic Gram-positive cocci","(D) Aerobic Gram-negative rods"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-15","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"糖尿病病人之免疫力較低，容易罹患牙周感染，最主要的原因是？","options":["(A) 因為血糖較高，口腔內細菌比較容易獲得養分而增長導致牙周感染","(B) 因為血糖較高導致造血能力不足，白血球的數目比正常人低","(C) 因為血糖濃度不穩定導致白血球吞噬細菌的能力忽強忽弱","(D) 糖尿病病人白血球的趨化能力（chemotaxis）較差"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"根據齒源性感染在臨床上的變化，可以大略分為四個變化時期，有關這四個時期的敘述何者正確？","options":["(A) Inoculation stage的初期臨床上顏面組織呈現出柔軟性腫大","(B) 蜂窩性組織炎時期臨床上主要是嗜氧菌（aerobic），造成顏面組織呈現出明顯腫痛現象","(C) 膿瘍期（abscess stage）臨床上主要的破壞細菌是厭氧菌（anaerobic）","(D) 從發炎初期到恢復期（resolution stage）大約要花10～14天才能緩解"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"有關抗生素治療齒源性感染的敘述，下列何者正確？","options":["(A) 治療齒源性感染時，不一定要使用抗生素","(B) 在沒有先使用抗生素之下就拔除已感染的牙齒必會造成感染加重","(C) 先使用抗生素之後，再做切開引流手術才正確","(D) 當乾性齒槽（dry socket）出現時，使用抗生素之後才能加速癒合"],"answer":0,"clinical_level":"重點"},{"id":"ya4-107-2-18","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"病患潛在有心內膜炎之風險，你正在進行一些簡單的牙科處置，事先不認為有必要投予預防性抗生素，但事 後才發現犯下一個錯誤，緊急用靜脈注射補救，下列何者是該項牙科處置？","options":["(A) 根管清創（intracanal endodontic therapy）","(B) 牙周韌帶麻醉","(C) 全口印模","(D) 活動假牙試戴"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-19","subject":"ya4","topic":"植牙外科","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"植牙時植體植入的敘述，下列何者最為適當？","options":["(A) 植體和植體之間至少距離1mm","(B) 植體和植體之間至少距離3mm","(C) 植體和游離牙齦邊緣至少距離4~5mm","(D) 植體和自然牙之間至少距離0.75mm"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-20","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"有關上顎粗隆降低術（tuberosity reduction） 之敘述，下列何者錯誤？","options":["(A) 可在局部麻醉下，以牙周探針測得軟硬組織的厚度","(B) 移除多餘軟組織後，為了達到無張力關閉傷口（tension-free closure），不一定要將軟組織初級縫合 （primary closure）","(C) 可能會造成上顎竇穿孔","(D) 為了避免術後出血及疼痛，次級癒合（secondary wound healing）較初級縫合（primary closure）適當"],"answer":3,"clinical_level":"重點"},{"id":"ya4-107-2-21","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"在下顎，前庭整形術（vestibuloplasty）合併皮膚移植（skin graft）是效果相當好的一種補綴前手術 （preprosthetic surgery），但若要有穩定的術後結果，一定要：","options":["(A) 施行前庭整形術時骨面上保留一層骨膜","(B) 施行前庭整形術時不可傷及附連之肌肉","(C) 使用全層厚度之皮膚移植（full-thickness skin graft）","(D) 移植之皮膚以手術用固定板（surgical stent）固定於骨嵴上6週"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-22","subject":"ya4","topic":"植牙外科","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"當溫度超過攝氏幾度時，會造成骨細胞壞死？","options":["(A) 39度","(B) 41度","(C) 44度","(D) 47度"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"有關淋巴轉移情況，下列敘述何者符合N2？","options":["(A) 同側，單獨一個淋巴轉移，大小在6公分以上","(B) 雙側，大小在6公分以上","(C) 同側，單獨一個淋巴轉移，大小在3公分以下","(D) 雙側，大小在6公分以下"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-24","subject":"ya4","topic":"口腔病理基礎","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"一個病人被確診為齒源性角化囊腫前，應與下列何者做鑑別診斷？","options":["(A) Eagle's syndrome","(B) Stevens-Johnson syndrome","(C) Plummer-Vinson syndrome","(D) Basal cell nevus syndrome"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-25","subject":"ya4","topic":"口腔病理基礎","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"下列何者不屬於發育性囊腫（developmental cyst）？","options":["(A) 鼻腭管囊腫（nasopalatine duct cyst）","(B) 球突上顎囊腫（globulomaxillary cyst）","(C) 甲狀舌管囊腫（thyroglossal duct cyst）","(D) 根尖牙周囊腫（periapical periodontal cyst）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-107-2-26","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"下列囊腔性病灶中，那兩種之放射線影像最易呈多房性（multilocularity）？①齒源性角化囊腫 （odontogenic keratocyst） ②鈣化齒源性囊腫（calcifying odontogenic cyst） ③囊性造釉細胞瘤 （cystic ameloblastoma） ④側位牙周囊腫（lateral periodontal cyst）","options":["(A) ①②","(B) ①③","(C) ①④","(D) ②③"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-27","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"施行矢向劈裂骨切開術（sagittal split osteotomy），在劈裂下顎枝（mandibular ramus）前，所作之骨切開 位置一般是在：","options":["(A) 下顎枝之後緣及下緣","(B) 下顎枝之下緣及下顎骨體（mandibular body）後方之內側","(C) 下顎枝外側作一水平切開至前方，再順下顎枝前緣往下前切開，延到下顎骨體臼齒外側再轉向下緣作一垂 直切開","(D) 下顎枝內側作一水平切開至前方，再順下顎枝前緣往下前切開，延到下顎骨體臼齒外側再轉向下緣作一垂 直切開"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-28","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"下列何者並非上顎骨垂直性過度生長（vertical maxillary excess）患者的特徵？","options":["(A) 下臉部過長","(B) 下顎平面角度（mandibular plane angle）過小","(C) 上下嘴唇之間在休息狀態時閉不起來","(D) 上顎牙齦暴露出來較多"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-2-29","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"下列有關環境影響顏面生長的敘述，何者錯誤？","options":["(A) 影響子宮內正發育中之胎兒頭部時，可能產生嚴重的顏面發育異常","(B) 幼兒呼吸困難對顏面發育沒有影響","(C) 舌頭及唇位置異常對顏面發育有不利的影響","(D) 顏面骨的外傷可能引起顏面骨及咬合異常"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"下列何者不是雙側矢向劈裂截骨術（bilateral sagittal split ostetomy）術後產生髁頭吸收（condyle resorption）的危險因子？","options":["(A) anterior facial height比 posterior facial height 長","(B) 術前有顳顎關節障礙（temporomandibular disorder）之患者","(C) 較大之下顎平面角度（mandibular plane angle）","(D) 截骨後近心端骨塊產生順時針旋轉（clockwise rotation）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-31","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"下列何種感覺神經纖維的傳導速度最快？","options":["(A) Aα fiber","(B) Aβ fiber","(C) Aγ fiber","(D) Aδ fiber"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-32","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"口腔灼感症候群（burning mouth syndrome）會在口腔內產生灼熱疼痛的症狀，它最常出現的部位是下列何 者？","options":["(A) 牙齦","(B) 舌頭","(C) 喉嚨","(D) 頰部"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-2-33","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"有關口腔灼感症候群（burning mouth syndrome）敘述，下列何者錯誤？","options":["(A) 好發於中年停經後婦女","(B) 約有五成的患者，兩年後會自然痊癒","(C) 荷爾蒙治療效果良好","(D) 口腔內任何部位都有可能發生"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-2-34","subject":"ya4","topic":"唾液腺疾病","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"有關唾液腺結石之敘述，下列何者正確？","options":["(A) 在顎下腺導管出現的機率比腮腺導管高","(B) 小唾液腺出現結石的機率比大唾液腺高","(C) 唾液腺結石可以用電腦斷層及唾液腺攝影檢查，無法用超音波檢查","(D) 最容易出現在舌下腺導管"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-35","subject":"ya4","topic":"唾液腺疾病","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"有關唾液腺感染的敘述，下列何者正確？","options":["(A) 最常見致病菌是 Streptococcus viridans","(B) 第一線抗生素不包括 cephalosporin","(C) 對病毒性的唾液腺感染應使用全身性的抗生素治療","(D) 病毒性的唾液腺感染可能造成年輕男性罹患不孕症"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-36","subject":"ya4","topic":"唾液腺疾病","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"Pleomorphic adenoma出現在小唾液腺時，下列那一部位最常見？","options":["(A) 嘴唇","(B) 頰部","(C) 上腭","(D) 口底"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-37","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"造成連枷胸（flail chest）的原因是？","options":["(A) subcutaneous emphysema","(B) tension pneumothorax","(C) hemothorax","(D) multiple rib fractures"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-38","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"這張 panoramic film顯示何處骨折？","options":["(A) 右側下顎骨枝和右側下顎骨體","(B) 左側下顎骨角和下顎骨聯合","(C) 右側髁突下區和下顎骨聯合","(D) 左側上顎骨和右側下顎骨體"],"answer":2,"image":"ya4-107-2-38.jpeg","clinical_level":"一般"},{"id":"ya4-107-2-39","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"下列那些頭部放射線檢查的影像最適合用來診斷「zygomatic complex fracture」與「zygomatic arch fracture」？","options":["(A) skull PA view + skull lateral view","(B) skull PA view + Waters’ view","(C) Waters’ view + submental vertex view","(D) basal view + submental vertex view"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-40","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"牙齒合併齒槽骨斷裂至少應齒間固定多久，方使骨塊癒合？","options":["(A) 1週","(B) 2週","(C) 3週","(D) 4週"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-41","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"腭裂（cleft palate）可分為原發性（primary）與繼發性（secondary），下列何者正確？","options":["(A) 齒槽骨前為繼發性","(B) 門齒孔前為原發性","(C) 齒槽骨後為原發性","(D) 門齒孔後為原發性"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-42","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"有關唇腭裂病人餵食問題之敘述，下列何者錯誤？","options":["(A) 口咽封閉不良所致","(B) 口腔肌肉無力所致","(C) 吞嚥反射正常","(D) 需用短小洞細之奶嘴"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-43","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"鼻咽鏡（nasopharyngoscopy）可用來檢查腭裂患者之發音功能，關於此法的運用，下列敘述何者錯誤？","options":["(A) 檢查時不需任何麻醉劑","(B) 可直接檢視上呼吸道型態及咽腭帆肌肉群（velopharyngeal musculatures）之動作","(C) 需熟練之操作技術","(D) 需語言病理學家（speech pathologist）之協助"],"answer":0,"clinical_level":"重點"},{"id":"ya4-107-2-44","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"對於缺血性心臟病的患者注射含有 1：100,000 epinephrine 之局部麻醉劑，在 30 分鐘內注射之 epinephrine 劑量最多不可超過多少毫克？","options":["(A) 0.01","(B) 0.02","(C) 0.03","(D) 0.04"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-45","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"有關過敏反應之敘述，下列何者錯誤？","options":["(A) type I hypersensitivity主要由IgE媒介，會引發蕁麻疹、氣喘、藥物全身性過敏反應（anaphylaxis）等疾病","(B) 輕微的過敏反應，可靜脈或肌肉注射抗組織胺來改善症狀","(C) 立即且嚴重的過敏反應，應馬上施打1:1000之0.3 mg腎上腺素","(D) 輸血反應也屬於type I hypersensitivity"],"answer":3,"clinical_level":"重點"},{"id":"ya4-107-2-46","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"有關咬合板之敘述，下列何者錯誤？","options":["(A) 咬合板的設計主要可分為自動復位式咬合板（autorepositioning splints）及前復位式咬合板（anterior repositioning splints）","(B) 自動復位式咬合板調整時，應與所有牙齒均勻接觸，且咬合板表面不能有斜坡或凹陷等干擾","(C) 使用自動復位式咬合板時，髁頭會位於關節窩的中央","(D) 前復位式咬合板會使下顎位於向前突出位置"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-47","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"根據 Wilkes 對顳顎關節內部紛亂（internal derangement）之分類，中期（intermediate stage）之放射線影 像敘述何者正確？","options":["(A) 關節盤些微前位移，關節盤後緣略增厚","(B) 關節盤向前位移，關節盤變形、後緣增厚","(C) 早期至中度退化（degenerative change），隆凸扁平化（flattening of eminence），髁頭變形（deformed condylar head）","(D) 關節盤穿孔（perforation），關節盤及硬組織顯著變形，退化性關節變化（degenerative arthritic change）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-107-2-48","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"下列何種處置目前最少用來治療顳顎關節習慣性脫臼？","options":["(A) LeClerc procedure","(B) eminectomy","(C) sclerosing agent","(D) capsular plication"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-49","subject":"ya4","topic":"口腔外科基礎","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"根據1981年世界醫學聯盟在里斯本所作成的病人權利宣言（Declaration of Lisbon on the Rights of the Patient），病人應有自主決定的權利。依據病人權利宣言之精神，病人可以決定下列那些事項？①自己的健 康 ②治療方式與程度 ③生命意義","options":["(A) 只有①②","(B) 只有②③","(C) 只有①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-50","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"今有一18歲青年因騎單車時不慎滑倒，造成上唇人中部位及兩側鼻翼一處長達6.5公分之穿通性不規則撕裂 傷口。（請依序回答下列2題） 1.請問欲為其做清創、縫合手術前，必須先予局部麻醉那些主要感覺神經比較適當？","options":["(A) bilateral infraorbital nerves + nasopalatine nerve","(B) bilateral infraorbital nerves","(C) bilateral anterior superior alveolar nerves + bilateral middle superior alveolar nerves","(D) bilateral anterior superior alveolar nerves + bilateral middle superior alveolar nerves + nasopalatine nerve"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-51","subject":"ya4","topic":"局部與全身麻醉","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"2.若該名青年合併上顎四顆門齒也有鬆脫移位及唇側、腭側牙齦撕裂的現象，必須同時予以縫合、復位固定 時，應如何給予局部麻醉最適當？","options":["(A) bilateral infraorbital nerves + nasopalatine nerve","(B) bilateral anterior superior alveolar nerves + bilateral middle superior alveolar nerves","(C) bilateral infraorbital nerves","(D) bilateral anterior superior alveolar nerves + bilateral middle superior alveolar nerves + nasopalatine nerve"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-52","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"張先生，45歲，有抽菸及嚼檳榔史，無重大系統性疾病，在右頰黏膜上發現一快速生長之腫塊，最大徑長3 公分，右頸部有一1.5公分之可動淋巴結。（請依序回答下列3題） 1.其合理的下一步處理是：","options":["(A) 患區斷層掃瞄（CT scanning）","(B) 患區磁振造影檢查（MR imaging）","(C) 切取式切片檢查（incisional biopsy）","(D) 切除式切片檢查（excisional biopsy）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-53","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"2.切片檢查報告為鱗狀細胞癌，影像檢查疑有一淋巴結轉移，張先生的口腔癌，依美國癌症委員會之TNM分 期，屬於那一期癌症？","options":["(A) T1N1M0第三期","(B) T2N0M0第二期","(C) T2N1M0第三期","(D) T3N0M0第三期"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-54","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"3.下列何種方式處理頸部淋巴結最合理？","options":["(A) 密切觀察（observation）","(B) 淋巴結之切片檢查（lymph node biopsy）","(C) 頸部廓清術（radical neck dissection）","(D) 放射線治療"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-55","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"一位20歲患者於兩天前至診所拔牙，拔牙後傷口一直滲血不止。經抽血檢驗發現「PT」、「PTT」都延長， 更進一步發現其中一個凝血因子「Factor VIII」明顯短少。請問最可能的診斷為何？","options":["(A) von Willebrand’s disease","(B) Hemophilia A","(C) Hemophilia B","(D) Hemophilia C"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-56","subject":"ya4","topic":"全身性疾病與急症","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"承上題，兩年後這名青年又因左下顎智齒必須拔除而來求診；問診時得知這兩年內，他曾因牙齦嚴重出血而 接受過兩次補充凝血因子的內科治療。請問下列那一項處置不合理？","options":["(A) 應該安排先補充凝血因子後，當天立刻拔牙","(B) 拔牙傷口應小心縫合，並可以使用適當的藥物促進局部傷口凝血","(C) 術後傷口疼痛方面，可以用非類固醇之抗炎藥物（NSAIDs）來控制","(D) 應於術中小心操作、術後徹底消毒器械及治療區域，以免醫護人員於無意間感染肝炎、愛滋病……等傳染 病"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"高頻恆壓（constant potential）裝置之口內X光機與傳統（self-rectified）口內X光機之比較，何者正確？","options":["(A) 高頻恆壓裝置之口內X光機產生之影像有較高之對比","(B) 高頻恆壓裝置之口內X光機產生之放射線有較高之平均能量","(C) 傳統口內X光機產生之影像有longer contrast scale","(D) 高頻恆壓裝置之口內X光機產生之放射線有較高之輻射劑量"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"口腔顎顏面領域的電腦斷層檢查，可分為全身電腦斷層設備與顎顏面領域專用設備，一般兩者均可用時，我 們會鼓勵牙科醫師儘量選用後者，其主要原因為何？","options":["(A) 曝露量較少","(B) 收費較便宜","(C) 操作較方便","(D) 影像較精確"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"依據位置與距離的準則（position-and-distance rule），若未使用X光隔離屏（barrier），操作人員至少要離 患者多遠？","options":["(A) 2英呎","(B) 4英呎","(C) 6英呎","(D) 10英呎"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"牙科X光機的陽極呈斜面的目的為何？","options":["(A) 減少放射線能量","(B) 增大焦距點（focal spot）","(C) 可使影像清晰","(D) 增加X光劑量"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"下列有關Waters' projection之敘述，何者錯誤？","options":["(A) canthomeatal line與底片夾成37°","(B) canthomeatal line與底片夾成47°","(C) 下頦（chin）向上向前貼著頂住底片夾","(D) 可以避開temporal bone的岩部（petrous ridge），讓maxillary sinus的呈像更清楚"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-62","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"正常情況下若採近心的角度（mesial angulation）照射上顎具雙根管之第一小臼齒，下列敘述何者正確？","options":["(A) 頰側根應位於顎側根的近心處","(B) 頰側根應位於顎側根的遠心處","(C) 頰側根應有比顎側根較小的放大率","(D) 頰側根應比顎側根接近咬合面"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-63","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"下列何項放射線攝影角度，會使下顎舌骨嵴（mylohyoid ridge）之影像較明顯？","options":["(A) 垂直角度較由上向下","(B) 垂直角度較由下向上","(C) 水平角度較由前向後","(D) 水平角度較由後向前"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-64","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"下列那一種放射線照射方法對於顴骨弓（zygomatic arch）的影像有最好的效果？","options":["(A) Waters' projection","(B) lateral cephalometric projection","(C) posteroanterior cephalometric projection","(D) submentovertex projection"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-65","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"在上顎正中前牙的根尖片中（periapical film）可見到前鼻棘（anterior nasal spine）約在齒槽嵴（alveolar crest）的上方多少公分出現？","options":["(A) 0.1","(B) 0.5","(C) 2","(D) 4"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-66","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"對於頦孔（mental foramen）的敘述，下列何者錯誤？","options":["(A) 當頦孔位於下顎小臼齒根尖的位置時會被誤為根尖病灶","(B) 通常位於下顎第二小臼齒根尖附近","(C) X光片的影像為明顯的放射線不透性（radiopaque）","(D) 位於下顎骨下緣與齒槽骨嵴上緣一半的位置"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-2-67","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"附圖根尖片中，左下顎第一小臼齒影像之敘述，下列何者正確？","options":["(A) Loss of the lingual alveolar crest with associated interproximal bone loss","(B) Loss of the lingual alveolar crest without associated interproximal bone loss","(C) Loss of the buccal alveolar crest with associated interproximal bone loss","(D) Loss of the buccal alveolar crest without associated interproximal bone loss"],"answer":1,"image":"ya4-107-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-107-2-68","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"圖A中可見雙側性的放射線透過性（radiolucent）病灶環繞恆牙第一大臼齒，並使鄰近牙位移，圖B及C可見 雙側之皮質骨膨大，下列病變中何者較符合這些特徵？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 頰側雙叉囊腫（buccal bifurcation cyst）","(C) 美童臉（cherubism）","(D) 纖維性發育不良（fibrous dysplasia）"],"answer":1,"image":"ya4-107-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-107-2-69","subject":"ya4","topic":"口腔病理基礎","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"下列何種齒源性病變，其顎骨X光影像，最有可能呈現多房性放射線透過性病變（multilocular radiolucent lesion），且其中可能有如網球拍或摺梯樣之格子線（tennis racket-like or stepladder-like pattern）？","options":["(A) 中心性齒源性纖維瘤（central odontogenic fibroma）","(B) 鈣化上皮齒源性腫瘤（calcifying epithelial odontogenic tumor）","(C) 鈣化齒源性囊腫（calcifying odontogenic cyst）","(D) 齒源性黏液瘤（odontogenic myxoma）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-70","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"下列何病變不會造成如附圖所示之帶骨性中隔（bony septa）的多房性放射線透過性病灶（multilocular radiolucent lesions）？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 纖維性發育不良（fibrous dysplasia）","(C) 中心型巨細胞肉芽腫（central giant cell granuloma）","(D) 齒源性角化囊腫（odontogenic keratocyst）"],"answer":1,"image":"ya4-107-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-107-2-71","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"附圖咬合片（occlusal film）中，箭頭所指之放射線影像，最適切之描述為何？","options":["(A) 洋蔥皮狀影像（onion-skin appearance）","(B) 陽光線狀影像（sun-ray appearance）","(C) 羊毛棉花狀影像（cotton-wool appearance）","(D) 毛玻璃狀影像（ground-glass appearance）"],"answer":1,"image":"ya4-107-2-71.jpeg","clinical_level":"重點"},{"id":"ya4-107-2-72","subject":"ya4","topic":"口腔病理基礎","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"造釉細胞瘤（ameloblastoma）移除不全而造成復發，其最明顯的放射線影像特徵為何？","options":["(A) 邊界很不清楚","(B) 形狀多為不規則","(C) 呈多囊性外觀之構造，且病灶邊緣伴隨一圈硬化的皮質骨（sclerotic cortical margin）","(D) 不會造成鄰近的牙根吸收"],"answer":2,"clinical_level":"重點"},{"id":"ya4-107-2-73","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"患者無任何症狀，但在放射線影像檢查時發現在下顎正門齒根尖部有放射線透過性影像的病灶，下列何者最 不可能？","options":["(A) 根尖囊腫（radicular cyst）","(B) 根尖周圍牙骨質骨發育不良（periapical cemento-osseous dysplasia）","(C) 造釉細胞瘤（ameloblastoma）","(D) 急性根尖牙周炎（acute apical periodontitis）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-107-2-74","subject":"ya4","topic":"口腔病理基礎","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"由贅生牙（supernumerary tooth）來源之含齒囊腫（dentigerous cyst），最常發生於顎骨中那一位置？","options":["(A) 上顎前齒區","(B) 上顎臼齒區","(C) 下顎前齒區","(D) 下顎臼齒區"],"answer":0,"clinical_level":"一般"},{"id":"ya4-107-2-75","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"附圖CT scan 3D重組所呈現的影像，其臨床診斷最可能為下列何者？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(C) 鱗狀細胞癌（squamous cell carcinoma）","(D) 纖維性發育不良（fibrous dysplasia）"],"answer":2,"image":"ya4-107-2-75.jpeg","clinical_level":"重點"},{"id":"ya4-107-2-76","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"下列何者為描述正常腮腺造影術之影像（如圖）？","options":["(A) tree in winter appearance","(B) cherry blossom appearance","(C) sausage-link appearance","(D) snowstorm appearance"],"answer":0,"image":"ya4-107-2-76.jpeg","clinical_level":"一般"},{"id":"ya4-107-2-77","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"附圖影像中箭頭所指病變最可能的診斷為何？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 脂肪瘤（lipoma）","(C) 囊腫（cyst）","(D) 鱗狀細胞癌（squamous cell carcinoma）"],"answer":0,"image":"ya4-107-2-77.jpeg","clinical_level":"重點"},{"id":"ya4-107-2-78","subject":"ya4","topic":"放射影像診斷","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"有關顎骨良性腫瘤放射線影像特徵之敘述，下列何者正確？","options":["(A) 邊緣通常呈不規則形狀","(B) 放射線不透過性（radiopaque）病灶多為良性","(C) 放射線透過性（radiolucent）病灶中有分隔（septa）或鈣化點者多為良性","(D) 齒源性病灶多發生於下齒槽神經管（inferior alveolar canal）之下"],"answer":2,"clinical_level":"一般"},{"id":"ya4-107-2-79","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"數位影像比傳統放射線影像檢查時所需輻射劑量低，主要的原因為何？","options":["(A) sensor比較大","(B) sensor比較靈敏","(C) exposure time增長","(D) sensor的放射線透過性較高"],"answer":1,"clinical_level":"一般"},{"id":"ya4-107-2-80","subject":"ya4","topic":"放射線原理與技術","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"下列何者不是細胞、組織或器官對於輻射反應的修改因素（modifying factors）","options":["(A) 劑量","(B) 劑量給予速率","(C) 非線性能量傳輸（non-linear energy transfer）","(D) 氧氣"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"在傷⼝癒合的proliferative phase，下列何者不是正常的症狀？","options":["(A) 傷⼝顏⾊變化","(B) 傷⼝張⼒增加","(C) 傷⼝分泌物增多","(D) 傷⼝收縮嚴重時可能造成骨性變形"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-2","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"牙科⾨診的病⼈接受治療時，發⽣暈厥最常⾒的原因為下列何者？","options":["(A) ⾎管迷⾛性暈厥","(B) 藥物過敏引發暈厥","(C) 代謝症候群","(D) 神經原性暈厥"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"關於傷⼝癒合過程發炎期（inflammatory stage）的敘述，下列何者錯誤？","options":["(A) ⾎管收縮的作⽤，減少⾎流進入組織受傷區域，因⽽促進⾎液凝固","(B) 發炎期的⾎管層⾯⾸先是對被弄斷的⾎管，進⾏⾎管收縮的作⽤","(C) 發炎期是組織受傷後12⼩時才開始進⾏","(D) 發炎期是傷⼝癒合的第⼀期"],"answer":[1,2],"clinical_level":"重點","explanation_pending":false},{"id":"ya4-108-1-4","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"iodophors與chlorhexidine為開⼑房常⽤的刷⼿液，下列有關兩者的差別敍述，何者錯誤？","options":["(A) iodophors的殺菌範圍較廣，chlorhexidine較窄","(B) iodophors可以有效抑制結核桿菌，chlorhexidine不⾏","(C) 孕婦不可使⽤chlorhexidine，但可使⽤iodophors","(D) chlorhexidine每次洗⼿後會沉積⼀些在⽪膚上⽽達到持續的抑菌作⽤，iodophors則不會"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-5","subject":"ya4","topic":"口腔外科基礎","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"有關⼝腔⼿術之敘述，下列何者錯誤？","options":["(A) ⼿術下⼑時，long，continuous stroke比short，interrupted stroke傷⼝癒合較好","(B) 使⽤電⼑前，要先移除周圍的液體及⾎⽔，才能達到有效的⽌⾎","(C) 儘量將切線設計在unattached gingiva或骨缺損處（missing bone）上","(D) 有齒的組織鑷比無齒的組織鑷，對組織的傷害較⼩"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"病⼈於施打下顎阻斷術後出現了圖⽰症狀，下列敘述何者最為正確？","options":["(A) 為三叉神經受損，導致臉歪嘴斜","(B) 為使⽤短針，對下齒槽神經反覆刺激造成創傷所引起","(C) 在⾝材⾼⼤，骨架壯碩，神經直徑較粗的的患者常⾒","(D) 針對病⼈的症狀，可告知病⼈其情況無須過於擔憂，通常會⾃⾏緩和消解"],"answer":3,"image":"ya4-108-1-6.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"下列牙科⿇醉藥，依其分類屬於酯類（ester）的為何者？","options":["(A) articaine","(B) dibucaine","(C) piperocaine","(D) ropivacaine"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"下列何者不是牙周韌帶注射⿇醉的適應症？","options":["(A) 治療兒童乳牙時","(B) 三叉神經痛的鑑別診斷時","(C) ⾎友病病⼈需進⾏下顎⾅齒⿇醉時","(D) 需進⾏雙側下顎⾅齒⿇醉時"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-9","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"50公⽄健康成⼈，若以1.8mL 2％ lidocaine含1：100,000 epinephrine的⿇藥管注射，最⾼推薦劑量約為幾⽀ ⿇藥管？","options":["(A) 6⽀","(B) 8⽀","(C) 10⽀","(D) 12⽀"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"關於急性齒槽骨炎（dry socket；alveolar osteitis）的敘述，下列何者正確？","options":["(A) 是⼀種感染（infection）症狀，常有發燒及紅腫反應","(B) 最常發的齒位為上顎⼩⾅齒","(C) 原因不明但可能與纖維溶解活性（fibrinolytic activity）有關","(D) 最佳的治療⽅法是⽤刮匙（curette）將齒槽骨刮流⾎以助傷⼝癒合"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"需要同時拔除多顆牙時，下列敘述何者正確？","options":["(A) 先拔除上顎牙齒的原因是因為浸潤⿇醉的效果持續較久","(B) 先拔除具有補綴物的牙齒可以避免牙齒及補綴物碎片掉入傷⼝","(C) 相較於下顎牙齒，拔除上顎牙齒需要較多的⼒量弄鬆頰側⽪質骨板","(D) 先拔除前⽅的牙齒利於拔牙挺（elevator）的操作"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-12","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"拔除⼀位健康成⼈之無感染阻⽣齒，下列何種處置是正確的？","options":["(A) 須使⽤術前抗⽣素","(B) 須使⽤術中抗⽣素","(C) 須使⽤術後抗⽣素","(D) 均不須使⽤抗⽣素"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-13","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"上顎正中贅⽣齒阻⽣，埋伏於腭側。⼿術拔除之翻瓣設計，下列何者最為適當？","options":["(A) 三⾓瓣膜（triangular flap），垂直切線位於正中","(B) 三⾓瓣膜（triangular flap），垂直切線位於⽝齒","(C) 梯狀瓣膜（trapezoid flap），⼆側切線位於⽝齒","(D) 袋⼝瓣膜（envelope flap），無垂直切線"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-14","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"當執⾏拔牙⽽須移除覆蓋骨頭時，⽪瓣切線位置與預期的骨缺損邊緣⾄少應有多少毫米的距離？","options":["(A) 1～2","(B) 3～4","(C) 6～8","(D) 10～12"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-15","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"以溫特式挺（Winter's elevator）拔除牙根的⼯作機械原理為：","options":["(A) 槓桿原理","(B) 楔型原理","(C) 輪軸原理","(D) 齒輪原理"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"治療齒源性感染的殺菌型抗⽣素中，具有殺菌範圍窄、毒性低的藥物，為下列何者？","options":["(A) azithromycin","(B) clarithromycin","(C) penicillin","(D) tetracycline"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"齒源性感染蔓延⾄下列何間隙時，會影響呼吸道的通暢？","options":["(A) submandibular space","(B) buccal space","(C) lateral pharyngeal space","(D) infratemporal space"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"關於複雜（complex）齒源性感染的敘述，下列何者正確？","options":["(A) 感染僅限於齒槽骨與前庭內","(B) 先前感染治療失敗","(C) 速度快的侷限腫脹","(D) 厭氧菌所造成的感染"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"下列何者為齒源性感染治療的原則？","options":["(A) ⽀持性療法，並設法控制病⼈與感染相關之疾病","(B) 使⽤抗⽣素的原則⾄少需使⽤兩種以上","(C) 切開引流位置應選擇感染部位之⾼位","(D) 等待細菌培養結果後再投以抗⽣素"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-20","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"對於服⽤⼝服雙磷酸鹽（oral bisphosphonates）超過三年的病患，如果要接受齒槽骨區⼿術治療，建議停 藥多久？","options":["(A) 3～4個⽉","(B) 6～9個⽉","(C) 12個⽉以上","(D) 無需停藥"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-21","subject":"ya4","topic":"植牙外科","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"關於齒槽嵴保存術（alveolar ridge preservation）的基礎為下列何者？","options":["(A) 盡可能在拔牙的過程中減少齒槽嵴的破壞","(B) 在牙齒還可以補綴修復的狀態下，就應將其拔除以⽅便齒槽嵴之保存","(C) 拔牙的過程中應保留完整的牙齒","(D) 拔牙的速度不可過慢"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-22","subject":"ya4","topic":"植牙外科","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"使⽤側⽅開窗（lateral window）來進⾏⿐竇增⾼術（sinus lift）時，對於使⽤的骨移植物的考慮，下列何者 最適當？","options":["(A) 僅可使⽤⾃體骨移植物","(B) 底部骨頭的⾼度為3 mm建議使⽤單⼀階段，增⾼術與植體同時置放","(C) 如使⽤兩階段，建議3～6個⽉後再進⾏植體的植入","(D) 使⽤異體骨移植物時建議混合類固醇以減低免疫發炎反應"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-23","subject":"ya4","topic":"植牙外科","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"表⽪細胞藉由何種構造與植體連接？","options":["(A) hemidesmosome","(B) desmosome","(C) integrin","(D) fibronectin"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"關於AJCC 6th edition⼝腔癌TNM系統中，T4a的定義是腫瘤侵犯到鄰近組織，下列敘述何者正確？","options":["(A) 頰黏膜3公分腫瘤，侵犯到咬肌","(B) 頰黏膜1公分腫瘤，侵犯到⽪膚","(C) 舌側3公分腫瘤，侵犯到舌內在肌（intrinsic muscle）","(D) 舌根2公分腫瘤，侵犯到舌扁桃腺"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-1-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"在頭頸部位之癌症放射線治療中，初期最常產⽣的併發症為下列何者？","options":["(A) 嚴重的⼝腔黏膜炎","(B) 全⼝性齲齒","(C) 產⽣⾁瘤（sarcoma）","(D) 顎骨放射線骨壞死"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-26","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"⼤部分根尖囊腫的來源為下列何者？","options":["(A) rests of Malassez","(B) stratum intermedium","(C) dental papilla","(D) Hertwig's root sheath"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-27","subject":"ya4","topic":"口腔外科基礎","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"下列何者為放射線治療之後遺症？①雙磷酸鹽之顎骨壞死BRONJ（bisphosphonate-related osteonecrosis of the jaw） ②疤痕攣縮 ③⽪膚顏⾊變暗沉 ④唾液腺萎縮⼝乾","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-28","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"關於顎骨囊腫或類囊腫的敘述，下列何者錯誤？","options":["(A) 根尖囊腫（radicular cyst）常⾒於前上顎⾨齒區域，囊腫膨⼤後以鄰近牙齒移位為特徵，較少造成牙根的吸 收","(B) 含齒囊腫（dentigerous cyst）常伴隨於阻⽣恆牙的下顎第三⼤⾅齒區域，較少侵犯乳牙","(C) 牙周側囊腫（lateral periodontal cyst）常⾒於下顎⼤⾅齒之間，好發於年齡⼩於18歲的族群","(D) 孤立性骨囊腫（solitary bone cyst）常⾒於下顎骨體，其上⽅齒列的牙髓活性通常不受到囊腫的影響"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-1-29","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"痣樣基底細胞癌症候群（nevoid basal cell carcinomas syndrome）的骨骼症狀中，不包括下列那⼀項？","options":["(A) 多發性齒源性⾓化囊腫（odontogenic keratocyst）","(B) 肋骨分叉","(C) 脊椎骨異常","(D) 頭圍過⼩"],"answer":3,"clinical_level":"重點"},{"id":"ya4-108-1-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"關於正顎⼿術中雙側⽮向分裂骨切開術（bilateral sagittal split osteotomy，BSSO）的敘述，下列何者正 確？","options":["(A) 僅能應⽤在下顎骨發育不⾜（mandibular deficiency）","(B) 僅能應⽤在下顎骨過度發育（mandibular excessive）","(C) 可應⽤在下顎骨發育不⾜（mandibular deficiency）及下顎骨過度發育（mandibular excessive）","(D) 造成下齒槽神經（inferior alveolar nerve）傷害之風險，較⼝內垂直下顎枝切開術（bilateral vertical ramus osteotomy，BVRO）為低"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-1-31","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"Bilateral sagittal split osteotomy的後遺症中，有關未預期之骨折，下列敘述何者正確？","options":["(A) 發⽣骨折以遠⼼段較多","(B) 發⽣不利骨折（unfavorable fracture）時，仍依照原定骨切線將近⼼段及遠⼼段分離後，再依情況固定骨折 之骨片","(C) 舌側骨片骨折發⽣率較低，與阻⽣智齒無關","(D) 頰側骨片的骨折，多肇因於上緣骨頭切線不完整"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-1-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"下列何者不是下顎過⻑患者可能的正顎⼿術⽅式？","options":["(A) 下顎骨體骨切開術（mandibular body osteotomy）","(B) 下顎骨前區骨切開術（anterior mandibular subapical osteotomy）","(C) 下顎枝垂直骨切開術（vertical ramus osteotomy）","(D) 上顎骨後區骨切開術（posterior maxillary subapical osteotomy）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-33","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"⼝腔灼熱感症候群（burning mouth syndrome）之病患，最常出現疼痛之部位是下列何者？","options":["(A) 上顎","(B) 舌","(C) 下顎齒齦","(D) 頰黏膜"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-1-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"下列何種病變，較常做顳顎關節⼿術（open surgery）治療？","options":["(A) 關節彈響聲（clicking sounds）","(B) TMJ ankylosis","(C) 類風濕性關節炎","(D) TMJ disc displacement"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"下列何種咬合板，其理論基礎為藉由改變關節位置使移位之關節盤回復合理位置？","options":["(A) stabilization splint","(B) anterior repositioning splint","(C) autorepositioning splint","(D) soft splint"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-36","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"關於壞死性涎腺變⽣（necrotizing sialometaplasia）的敘述，下列何者正確？","options":["(A) 為位於⼤唾液腺體的腫瘤發炎性過程","(B) 常與⾃體免疫疾病有關，多發⽣於70歲以上的老年⼈","(C) 病灶中常⾒結⽯阻塞唾液腺管，導致腺體感染及腫脹疼痛","(D) 在臨床及組織病理上，與黏液表⽪樣瘤（mucoepidermoid carcinoma）相似"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-37","subject":"ya4","topic":"唾液腺疾病","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"顏⾯神經⽀配下列那兩個⼤唾液腺的分泌？","options":["(A) 腮腺與顎下腺","(B) 腮腺與舌下腺","(C) 顎下腺與舌下腺","(D) 顎下腺與頰腺"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-38","subject":"ya4","topic":"唾液腺疾病","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"以唾液腺攝影術（sialography）來檢查腮腺時，若影像中呈現為ball-in-hand，最有可能的診斷為何？","options":["(A) tumor","(B) Sjögren's syndrome","(C) sialadenitis","(D) sialodochitis"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-39","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"3歲的⼩朋友因為外傷，導致乳牙⾨牙疑似壓迫下⽅恆牙⾨牙之牙胚，下列敘述何者較為合理？","options":["(A) 應先確認乳牙⾨牙牙根是否確實壓迫恆牙牙胚，若是，則該乳牙需再盡量修磨骨質，解除阻⼒後，將乳⾨ 牙徹底移除","(B) 乳牙⾨牙還有可能再萌發，觀察就可以，不需要介入處理","(C) 若位置不能確定乳牙⾨牙是否真正壓迫其下恆牙⾨牙牙胚，原則上預防性的⼩⼼的移除乳牙⾨牙以確保恆 牙⾨牙牙胚的狀況","(D) 應該⽤⼿術復位的⽅式，及時將乳牙⾨牙復位，可以確保空間維持"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-40","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"根據所附圖⽰，靠近牙齒的黏膜處可⾒骨暴露，其骨折最接近⽤下列那⼀個名詞形容？","options":["(A) greenstick fracture","(B) simple fracture","(C) comminuted fracture","(D) compound fracture"],"answer":3,"image":"ya4-108-1-40.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-41","subject":"ya4","topic":"唾液腺疾病","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"某位右臉頰有深度撕裂傷（laceration）的患者，在傷⼝縫合2～3天之後，其臉頰明顯腫⼤起來，但是外表⽪ 膚沒有變⾊，最可能造成的原因是：","options":["(A) 顏⾯動脈破裂","(B) 顏⾯神經⿇痺","(C) 腮腺管堵塞","(D) 傷⼝處發炎"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-42","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"有關唇腭裂患者齒槽骨裂修補的敘述，下列何者正確？","options":["(A) 齒槽骨裂修補最好在⿐翼再修補前","(B) 齒槽骨裂修補最好在鄰近牙齒如canine⻑入裂縫後再補，以避免補骨流失","(C) 盡量避免使⽤⾃體骨作為移植骨材以減少傷害","(D) 補骨區骨質不若原⽣骨，所以不宜將矯正的牙齒移入此區"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-43","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"唇裂及腭裂（cleft lip and palate）之⼿術重建時程，下列何者錯誤？","options":["(A) 腭裂之⼿術修復建議於病患年齡9⾄18個⽉時施⾏","(B) 咽瓣（pharyngeal flap）或咽造形術（pharyngoplasty）建議於病患年齡3⾄5歲時施⾏，以矯治咽腭帆關閉 不全（velopharyngeal insufficiency）","(C) ⿐整形術（rhinoplasty）建議於病患年齡5歲以後施⾏，如可能最好在正顎⼿術（orthognathic surgery）後 為之","(D) 上顎及齒槽嵴之骨移植（bone graft）重建，建議於病患年齡12⾄14歲時施⾏"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-44","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"關於腭裂形成之原因，下列何者錯誤？","options":["(A) 原⽣腭裂（primary palate cleft）起因於中胚層（mesoderm）無法穿過內側⿐腫（medial nasal process） 及上顎腫（maxillary process）之間的溝槽（groove）","(B) 繼⽣腭裂（secondary palate cleft）起因於腭架（palatine shelf）無法互相融合","(C) 腭架（palatine shelf）無法互相融合之原因不明，推測可能為舌頭未能下降⾄⼝腔所造成","(D) 腭架（palatine shelf）初期處於舌頭之斜上⽅向，若於胎兒7週時無法向下降則無法互相融合，形成腭裂"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-45","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"狹⼼症（angina）病患接受⾨診⼝腔⼿術時，下列敍述何者錯誤？","options":["(A) 如果劇烈運動時才引發狹⼼症，但⼀經休息或⼝服硝化⽢油（nitroglycerin）可以緩解者，仍然可以接受⼿ 術","(B) 嚴禁使⽤含有⾎管收縮劑的局部⿇藥","(C) ⼿術中病⼈的焦慮（anxiety）升⾼，可能增加⼼臓肌⾁的氧需求量（oxygen demand）","(D) 正確注射局部⿇藥，產⽣最佳⽌痛效果，以降低焦慮"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-46","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"在進⾏⼝腔⼿術時，病⼈聲稱頭痛，呈現單側⾯部肌⾁、肢體癱瘓、語意不清、⼩便失禁，可能發⽣的疾病 為：","options":["(A) 進⾏中的腦⾎管危機（cerebrovascular compromise in progress）","(B) ⾎糖過低（hypoglycemia）","(C) 甲狀腺風暴（thyroid storm）","(D) 腎上腺功能不⾜（adrenal insufficiency）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-47","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"⼀位正接受牙科治療的病患，突然呈現嘔⼼、情緒改變、眩暈、焦慮、冒汗、臉⾊蒼⽩及⼼跳過速，最可能 原因為：","options":["(A) 低⾎糖症（hypoglycemia）","(B) 過敏性休克（anaphylactic shock）","(C) ⼼肌缺⾎或梗塞（myocardial ischemia or infarction）","(D) 哮喘（asthma）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-48","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"下列何種過敏症會出現IgE增加？","options":["(A) 第I型","(B) 第II型","(C) 第III型","(D) 第IV型"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-49","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"顳顎關節盤重置（disk repositioning）⼿術，術後通常需要多久時間才能進⾏正常的下顎骨運動？","options":["(A) 0～2週","(B) 3～5週","(C) 6～8週","(D) 10～12週"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-50","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"關於pannus formation的敘述，下列何者錯誤？","options":["(A) 其症狀與其他退化性關節炎相似","(B) 與風濕性關節炎無關","(C) 為⼀種發炎反應","(D) 為滑液組織之不正常增⽣"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-51","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"Cyclo-oxygenase-2（COX-2）inhibitors是⼀個治療初期顳顎關節疾患的藥物，但是下列何者要特別謹慎⼩ ⼼使⽤？","options":["(A) 有胃潰瘍病史","(B) 有骨骼疾病病⼈","(C) 有⼼臟問題病⼈","(D) 有對碘過敏者"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-52","subject":"ya4","topic":"口腔外科基礎","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"下列何情況下，醫師仍應對病⼈告知病情？","options":["(A) 病⼈家屬要求隱匿病情","(B) 病⼈⾃動放棄被告知","(C) 病⼈無⾃主能⼒","(D) 緊急醫療狀況"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-53","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"成⼈之含牙囊腫（dentigerous cyst）最好發在⼝腔中的那⼀個區域？","options":["(A) 下顎⾅齒區","(B) 上顎⽝齒區","(C) 下顎⽝齒區","(D) 上顎⾅齒區"],"answer":0,"clinical_level":"重點"},{"id":"ya4-108-1-54","subject":"ya4","topic":"口腔外科基礎","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"承上題，若是利⽤造袋術（marsupialization）作治療，下列那⼀項缺點是錯誤的？","options":["(A) 無法將囊腫完全取出","(B) 無法做詳細之病理檢查","(C) 病患回家後需作沖洗清潔等居家照顧","(D) 易造成病理性骨折"],"answer":3,"clinical_level":"重點"},{"id":"ya4-108-1-55","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"⼀位頭戴半罩式安全帽的機⾞騎⼠，因⾞禍跌倒，下顎頦部（chin）直接撞擊地⾯，下列何部位相對其他部 位發⽣骨折的機率較低？","options":["(A) 下顎骨聯合區（symphysis）","(B) 下顎骨骨體（body）","(C) 下顎骨喙狀突（coronoid process）","(D) 下顎骨關節區（temporomandibular joint）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-56","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"承上題，該病患送⾄醫院急診處，經臨床檢查後，發現除下顎骨折外，亦懷疑中顏⾯部也有骨折現象 （midface fracture），下列何種平⾯X光片（plain radiograph），對中顏⾯部骨折的診斷幫助較少？","options":["(A) Waters' view","(B) lateral skull view","(C) PA skull view","(D) Towne's view"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"下列何者其相對放射線敏感度（relative radiosensitivity）最低？","options":["(A) 黏膜（mucous membranes）","(B) 唾液腺（salivary glands）","(C) 腸（intestines）","(D) 神經元（neurons）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"下列何者為影響 X 光影像診斷品質（diagnostic quality）最關鍵的因素？","options":["(A) X光管電壓","(B) X光管電流","(C) 曝光時間","(D) 陽極⾓度"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"下列何者是photostimulable phosphor（PSP）X光感應片中最重要的⾦屬成分？","options":["(A) 銀（silver）","(B) 銅（copper）","(C) 銪（europium）","(D) 鉛（lead）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-60","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"下列那⼀種影像攝影法最能精確的評估顳顎關節的骨頭狀況？","options":["(A) magnetic resonance imaging","(B) cephalometric imaging","(C) panoramic imaging","(D) cone-beam CT imaging"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-61","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"⼝腔內咬翼片無法⽤來檢查下列那⼀種構造或病變？","options":["(A) 牙周骨頭的⾼度","(B) 牙根尖周圍病變","(C) 牙齒鄰接⾯齲蝕","(D) 復形物底下的齲蝕"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-62","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"環⼝放射線攝影（panoramic radiography）時，若下顎⾨齒⽔平⽅向放⼤率過⼤，則最可能的原因是在定位 病⼈時，病⼈頭部於下列何種情況所造成？","options":["(A) 上仰","(B) 太靠近X 光片","(C) 下傾","(D) 太遠離X 光片"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-63","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"下列那⼀種攝影⽅法最合適⽤來診斷 LeFort III fracture？","options":["(A) Waters' view radiography","(B) occlusal radiography","(C) panoramic radiography","(D) submentovertex radiography"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-64","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"在正常情形下的放射線影像，其解剖結構呈現放射線不透過性（radiopaque）為下列何者？","options":["(A) lateral fossa","(B) genial tubercle","(C) nasolabial fold","(D) periodontal ligament"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-1-65","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"圖中箭頭所指之放射線透過性線條（radiolucent line）為下列何者在下顎上升枝的重疊影像？","options":["(A) ⿐腔氣道（nasal airway）","(B) ⿐咽（nasopharynx）","(C) ⼝腔氣道（oral airway）","(D) 咽帆（velopharynx）"],"answer":2,"image":"ya4-108-1-65.jpeg","clinical_level":"重點"},{"id":"ya4-108-1-66","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"11歲男孩因左下顎⾅齒區有⼀無痛之腫脹⽽來求診，經X光檢查如附圖所⽰，此病患最可能罹患下列何種疾 病？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 造釉細胞纖維瘤（ameloblastic fibroma）","(C) 造釉細胞纖維齒瘤（ameloblastic fibro-odontoma）","(D) 齒源性纖維瘤（odontogenic fibroma）"],"answer":2,"image":"ya4-108-1-66.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-67","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"附圖之根尖片中，⿊⾊箭頭所⽰的⽩⾊點狀物，最有可能為下列何者？","options":["(A) 竇結⽯（antrolith）","(B) 汞⿑（amalgam）","(C) 牙結⽯（dental calculus）","(D) 牙釉質（enamel）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-1-68","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"下列何種疾病的牙齒影像不會看到牙周韌帶變寬？","options":["(A) 低磷酸酯酶症（hypophosphatasia）","(B) 牙周炎（periodontitis）","(C) 進⾏性全⾝性硬化症（progressive systemic sclerosis）","(D) 骨⾁瘤（osteosarcoma）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-1-69","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"如圖所⽰之病灶，好發於年輕患者之顎骨，於疾病中期顎骨X光影像常呈現⽑玻璃狀（ground glass appearance）且病灶周圍界線不清楚，下列何疾病最有可能？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 增殖性骨膜炎（proliferative periostitis）","(C) 蘭格罕⽒細胞組織細胞增多症（Langerhans' cell histiocytosis）","(D) 柏哲德⽒病（Paget's disease of bone）"],"answer":0,"image":"ya4-108-1-69.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-70","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"顎骨的柏哲德⽒病（Paget's disease）於疾病後期（late stage），其放射線影像呈現下列何種特徵？","options":["(A) sun-ray appearance","(B) punched-out appearance","(C) onion-skin appearance","(D) cotton-wool appearance"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-71","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"下列何者與放射線性齲齒的主要成因無關？","options":["(A) 唾液的黏性增加","(B) 唾液量減少","(C) 唾液之 pH 值增加","(D) 唾液緩衝（buffer）作⽤降低"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-72","subject":"ya4","topic":"唾液腺疾病","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"圖中箭頭所指之病變，下列診斷何者最有可能？","options":["(A) 壞死性涎腺變⽣（necrotizing sialometaplasia）","(B) 謝格連⽒症候群（Sjogren's syndrome）","(C) 慢性涎腺炎（chronic sialadenitis）","(D) 蝦蟆腫（ranula）"],"answer":2,"image":"ya4-108-1-72.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-73","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"下列何者最不會呈現放射線透過性及不透過性之混合病灶（mixed radiolucent-radiopaque lesion）？","options":["(A) ⼽林囊腫（Gorlin cyst）","(B) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(C) 平伯⽒腫瘤（Pindborg tumor）","(D) 齒源性黏液瘤（odontogenic myxoma）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-74","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"圖中下顎骨之多發性病變，最符合下列那⼀種疾病？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）","(C) 中⼼型骨化纖維瘤（central ossifying fibroma）","(D) 慢性骨髓炎（chronic osteomyelitis）"],"answer":1,"image":"ya4-108-1-74.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-75","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"圖中放射線透過性病變之診斷為何？","options":["(A) ⿐唇囊腫（nasolabial cyst）","(B) ⿐腭管囊腫（nasopalatine duct cyst）","(C) 單純性骨囊腫（simple bone cyst）","(D) 甲狀腺舌管囊腫（thyroglossal duct cyst）"],"answer":1,"image":"ya4-108-1-75.jpeg","clinical_level":"一般"},{"id":"ya4-108-1-76","subject":"ya4","topic":"放射線原理與技術","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"下列有關⼝腔傳統X光片與數位影像的比較，何者錯誤？","options":["(A) 數位成像可免去化學藥劑成像流程，不會產⽣有害廢棄物","(B) 不同醫院之間可以使⽤電⼦檔案傳送，不像傳統影像需要拷⾙⽽失真","(C) 數位影像因成像複雜，所以不易造假","(D) 拍攝數位影像所受的輻射劑量比傳統X光片少"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-1-77","subject":"ya4","topic":"放射線原理與技術","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"根據2004年歐洲牙科放射線輻射防護準則，接受相同輻射劑量時，10歲以下兒童的輻射風險因素是30⾄50 歲成⼈之輻射風險（risk）因素的多少倍？","options":["(A) 2","(B) 3","(C) 4","(D) 6"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-1-78","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"請依此X光影像，依序回答下列3題。 圖中影像是以何種⽅法拍攝？","options":["(A) Waters' view radiography","(B) occlusal radiography","(C) panoramic radiography","(D) cone beam computed tomography"],"answer":3,"image":"ya4-108-1-78.jpeg","clinical_level":"重點"},{"id":"ya4-108-1-79","subject":"ya4","topic":"放射影像診斷","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"影像中⽩⾊箭頭所指的解剖位置為何？","options":["(A) left maxilla","(B) right maxilla","(C) left mandible","(D) right mandible"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-1-80","subject":"ya4","topic":"口腔病理基礎","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"影像中⽩⾊箭頭所指的病變最可能為何？","options":["(A) 殘餘囊腫（residual cyst）","(B) 複合性牙瘤（compound odontoma）","(C) 根尖囊腫（radicular cyst）","(D) 含齒囊腫（dentigerous cyst）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"為減少口腔手術後水腫的程度，下列處置何者最正確？","options":["(A) 術後前幾天，儘量保持頭部位置不高於身體其他部位","(B) 術前就開始使用短期高劑量全身性類固醇（corticosteroid）","(C) 抗生素的使用","(D) 許多臨床試驗（well controlled study）已證實術後冰敷可有效減少術後水腫程度"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"以含chlorhexidine消毒液做為術前手術區域之消毒，下列敘述何者錯誤？","options":["(A) 皮膚及口內都可以使用","(B) 對G（+）菌種比對G（-）菌種有效","(C) 與iodophors消毒液相比，chlorhexidine消毒液對結核桿菌、孢子（spores）以及病毒消毒效果也較好","(D) 同日反覆以chlorhexidine消毒液洗手，可累積於皮膚上，增加抗菌效果"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-3","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"以刀片切開口腔黏膜，施行口腔黏膜翻瓣手術進行智齒拔除時，下列敘述何者正確？","options":["(A) 刀片需與組織表面呈45度斜面","(B) 最適合的刀片是11號","(C) 不要切開骨膜，以確保皮瓣血液供應","(D) 刀片不易切到之牙齒遠心端牙齦，較適合使用12號刀片"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-4","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"有關通常拔牙傷口癒合的敘述，下列何者正確？","options":["(A) 屬於「primary intention healing」","(B) 屬於「secondary intention healing」","(C) 通常大約只要一星期的時間，新的上皮就能完全覆蓋住拔牙傷口","(D) 拔牙傷口通常至少要一年的時間，齒槽窩的皮質骨才會完全被吸收掉，而無法在 X光片中看到齒槽骨板 （lamina dura）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-5","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"下列何種病人不適合使用笑氣？①中耳炎 ②鼻竇炎 ③慢性阻塞性肺臟疾病 ④精神疾病","options":["(A) 僅①④","(B) 僅②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"clinical_level":"重點"},{"id":"ya4-108-2-6","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"lidocaine嚴重過量引起的身體反應機制，下列何者正確？","options":["(A) 抑制中樞神經系統及興奮心臟血管系統","(B) 興奮中樞神經系統及抑制心臟血管系統","(C) 興奮中樞神經系統及興奮心臟血管系統","(D) 抑制中樞神經系統及抑制心臟血管系統"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"頦神經阻斷時，打入頦孔（mental foramen）內的進針方向為何？","options":["(A) 向下、向後、向外","(B) 向下、向前、向外","(C) 向下、向前、向內","(D) 向下、向後、向內"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"有關鼻腭神經阻斷（nasopalatine nerve block）的敘述，下列何者正確？","options":["(A) 注射時應由門齒乳頭（incisive papilla）的正中央打入","(B) 又稱為門齒神經阻斷術（incisive nerve block）","(C) 注射位置在第二大臼齒腭側之牙齦","(D) 麻醉範圍達兩側第二小臼齒區"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"拔牙前雖然進行了局部麻醉，但拔牙時病人仍有牙齒受到壓力的感覺，這是因為下列何種感覺未被阻絕？","options":["(A) 痛覺（pain）","(B) 溫覺（temperature）","(C) 觸覺（touch sensations）","(D) 本體覺（proprioceptive sensations）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"拔牙時一個大的牙根被推入鼻竇可用下列何種術式取出？","options":["(A) Winters' operation","(B) Caldwell-Luc approach","(C) Bell's method","(D) Enlow's osteotomy"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"拔牙後若造成牙齒誤嚥時，下列敘述何者錯誤？","options":["(A) 先確定患者的呼吸是否順暢","(B) 不論是誤入氣管或食道均需照胸部及腹部Ｘ光片確認牙齒實際位置","(C) 誤入消化道之牙齒最多兩天即可自然排出","(D) 由於牙齒不易卡在消化道，經腹部Ｘ光片確認牙齒進入消化道後，會隨糞便排出，不用再照Ｘ光片確認"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"關於拔牙術後產生感染併發症的敘述，下列何者錯誤？","options":["(A) 發生感染時，嗜氧性細菌（aerobes）為主要致病菌種","(B) 通常需要以抗生素並配合外科的切開引流手術治療","(C) 有些系統性疾病可能會導致術後嚴重感染，需要接受抗生素預防","(D) 通常在拔牙後3～4天，產生感染的併發症"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"根據下圖影像判讀牙齒與下顎管（mandibular canal）關係，拔牙時何者最容易傷害下齒槽神經？","options":["(A) A","(B) B","(C) C","(D) 三者機會均等"],"answer":2,"image":"ya4-108-2-13.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-14","subject":"ya4","topic":"拔牙學與併發症","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"拔牙後若有輕微之口竇相通時，下列敘述何者錯誤？","options":["(A) 不可進食流質食物","(B) 避免擤鼻涕或劇烈打噴嚏","(C) 不要用吸管","(D) 不可吸菸或抽雪茄"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"關於使用clotrimazole治療口腔黏膜念珠菌感染的敘述，下列何者正確？","options":["(A) 低價位，但含有高毒性","(B) 須持續服藥四星期，不可中斷方可控制","(C) 如患者帶有活動假牙，建議移除假牙之內層並浸泡此抗菌劑至隔日","(D) 此療效一次即可根治，無須後續處置"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"病人服用clindamycin三天後腹瀉最常見的原因為下列何者？","options":["(A) 過敏反應","(B) 服用過量","(C) 有藥物拮抗作用","(D) 毒素在腸中產生"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"治療齒源性感染時，如果患者對penicillin 過敏，下列抗生素何者最適合使用？","options":["(A) vancomycin","(B) clindamycin","(C) amoxicillin","(D) cefazolin"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"關於影響宿主免疫力導致齒源性感染的敘述，下列何者錯誤？","options":["(A) 不受控制的第一型糖尿病會影響體內免疫系統破壞細菌的功能","(B) 不受控制的第二型糖尿病會影響體內免疫系統吞噬細菌的功能","(C) 白血病會減少白血球功能","(D) 末期腎病會減少抗體合成及產生"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"下顎牙齒之感染，若其感染穿過下顎骨內側處，且位於舌骨肌mylohyoid muscle 附著線之上，則此感染會進 入下列何區域？","options":["(A) submandibular space","(B) masseteric space","(C) sublingual space","(D) submental space"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-20","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"手術進行lingual frenectomy的原則，關於舌頭底部纖維結締組織敘述，下列何者正確？","options":["(A) 縱向切斷，縱向縫合","(B) 縱向切斷，橫向縫合","(C) 橫向切斷，縱向縫合","(D) 橫向切斷，橫向縫合"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-21","subject":"ya4","topic":"植牙外科","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"右側下顎第一大臼齒進行牙科植體手術，術後隔日發現同側下嘴唇麻麻的感覺，用探針針剌沒有痛覺，此時 最好的處置為下列何者？","options":["(A) 給予綜合維他命","(B) 將植體取出","(C) 再給予止痛藥","(D) 改用熱敷"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-22","subject":"ya4","topic":"植牙外科","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"在植牙鑽孔超過1分鐘，鑽針周圍溫度一旦超過多少度時，將造成骨細胞損傷或死亡？","options":["(A) 39℃","(B) 43℃","(C) 47℃","(D) 51℃"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-23","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"關於硬組織切片的敘述，下列何者錯誤？","options":["(A) 最常見的顎骨內病灶大部分為根尖肉芽腫（periapical granulomas）及齒源性囊腫（odontogenic cysts）","(B) 通常在翻開黏膜瓣後，會先針對骨內病灶做抽吸（needle aspiration），若抽出來的是單純的透明液體，此病 灶極有可能是外傷性骨病灶（traumatic bone lesion）","(C) 大部分的骨內病灶，在取組織檢體前，需要用手術骨鑽製造一個骨窗（bone window）以利我們取樣","(D) 儘可能將患者的臨床資料，甚至是放射線影像提供給病理科醫師，可以更有助於精確的病理診斷"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-2-24","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"關於odontoma的敘述，下列何者錯誤？","options":["(A) 是最常見的odontogenic tumors之一","(B) 其中一種類型complex odontoma指的是含有多顆小齒樣的結構","(C) compound odontoma好發於上顎前區","(D) complex odontoma好發於上下顎後區"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-2-25","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"下列何者為口腔癌前病變？①黏膜紅斑 ②黏膜白斑 ③纖維瘤 ④疣狀突起增生","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-26","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"對於顎骨囊腫的治療，下列何者病灶是剜出術（enucleation）的適應症？","options":["(A) 病灶有顎骨沾黏","(B) 病灶有下顎齒槽神經管沾黏","(C) 可確認完整病灶病理性變化","(D) 懷疑病灶有病理性骨折（pathological fracture）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"罹患下列何種疾病時，會同時有肋骨分叉、基底細胞癌、齒源性角化囊腫（odotogenic keratocyst）之症狀？","options":["(A) 馬芬氏症候群（Marfan's syndrome）","(B) 加德耐氏症候群（Gardner's syndrome)","(C) 柏哲德氏病（Paget's Disease）","(D) 戈林症狀羣（Gorlin's syndrome）"],"answer":3,"clinical_level":"重點(深度)"},{"id":"ya4-108-2-28","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"以囊腫造袋術（cystic marsupialization）對下顎骨囊腫做減壓治療時，下列敘述何者正確？","options":["(A) 術後居家傷口清潔照顧對病人來說方便又簡單","(B) 不適合用於巨大的顎骨囊腫病灶","(C) 無法做出完整的病理組織學檢查","(D) 容易造成囊腫附近重要器官的損傷（如下顎齒槽神經）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"痣樣基底細胞癌症候群（nevoid basal cell carcinoma syndrome）在全身造成的症狀中，下列何者錯誤？","options":["(A) 眼距過小","(B) 肋骨分岐","(C) 併指","(D) 齒源性角化囊腫"],"answer":0,"clinical_level":"重點"},{"id":"ya4-108-2-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"關於下顎兩側垂直骨截開術（mandibular bilateral vertical osteotomy）正顎手術，下列何者錯誤？","options":["(A) 常用於治療下顎前突症（mandibular prognathism）","(B) 顎間固定（IMF）通常需要4～6周","(C) 常用於治療下顎後縮症（mandibular retrognathism）","(D) 於下顎枝後緣做一垂直切開，將下顎骨分為前後兩部分"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-31","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"下列何種正顎手術術式較不會造成下齒槽神經的傷害，而導致下唇產生麻木感？","options":["(A) 雙側垂直下顎枝骨切開術（bilateral vertical ramus osteotomy, BVRO）","(B) 雙側矢向分裂骨切開術（bilateral sagittal split osteotomy, BSSO）","(C) 頦成形術（genioplasty）","(D) 勒福一型截骨術（Le Fort I osteotomy）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"對於顎骨發育不足患者，何時最適合施行正顎手術？","options":["(A) 應較顎骨過度發育病例晚","(B) 可較顎骨過度發育病例早","(C) 20歲以後","(D) 一定要在發育停止後"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-33","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"關於造成myofascial pain and dysfunction原因之敘述，下列何者錯誤？","options":["(A) 主要是來自於不正常的肌肉過度活動","(B) 有時也會合併顳顎關節內部問題（internal derangement )","(C) 大部分患此症狀的患者，其TMJ的X光影像也會有相對應的病灶","(D) 由於壓力所導致的磨牙症（bruxism）也可能是原因之一"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-2-34","subject":"ya4","topic":"唾液腺疾病","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"7歲兒童患者因耳前腫脹及疼痛求診，並伴隨有發燒、寒顫及頭痛等症狀；經支持性及藥物治療，於兩週後再 度回診時，症狀已完全消解。你認為此患者疾病最可能的診斷為何？","options":["(A) 謝格連氏症候群（Sjögren's syndrome）","(B) 病毒性腮腺炎","(C) 唾液腺結石","(D) 腮腺良性腫瘤"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-35","subject":"ya4","topic":"唾液腺疾病","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"40歲男性患者來醫院求診，主訴於口腔底部腫脹數月之久，特別在進食的時段容易出現腫脹疼痛；觸診時發 現在右側口底腔部出現壓痛性的腫塊，電腦斷層在不同切面的影像如下圖所顯示。關於此類唾液腺疾病的敘 述，下列何者正確？","options":["(A) 發生率女性高於男性九倍","(B) 好發年齡為65歲至80歲之間","(C) 85％的病患可能為多發性病症，同時侵犯數個腺體","(D) 顎下腺發生率最高，約占85％"],"answer":3,"image":"ya4-108-2-35.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-36","subject":"ya4","topic":"唾液腺疾病","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"具有下列那一項疾病或病史的患者，最不適合接受唾液腺攝影（sialography）檢查？","options":["(A) 具有對鋇劑過敏病史","(B) 不明原因的唾液腺體疼痛","(C) 唾液腺惡性腫瘤疾病","(D) 急性唾液腺感染"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-37","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"附圖A及B為牙根斷裂的牙齒，臨床檢視A不太搖動，B搖動度很大，就牙根斷裂的位置估計其預後，下列敘 述何者最合理？","options":["(A) A圖中牙根斷裂位置較偏向根尖處，預後應該較B斷裂處偏向齒頸部者為佳","(B) A圖中牙根斷裂位置較偏向根尖處，雖臨床上不搖，預後應該較B斷裂處偏向齒頸部者為差","(C) 無論A或B，預後都很差，一定都要拔除並以植牙重建最好","(D) 無論A或B，只要做好根管治療，並在根管中放投藥，增進牙本質修復，預後都可以很好"],"answer":0,"image":"ya4-108-2-37.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-38","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"考量外力的衝擊及下顎骨的解剖特性，就下顎骨骨折分布區域，下列何者發生的機率最低？","options":["(A) 關節髁處（condylar）","(B) 下顎骨上升枝處（ramus）","(C) 下顎骨角處（angle）","(D) 下顎骨聯合處（symphysis）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-39","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"病人的眼瞼不能關閉，是下列那一個神經受到損傷？","options":["(A) 第三對腦神經","(B) 第五對腦神經","(C) 第六對腦神經","(D) 第七對腦神經"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-40","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"頭部外傷的患者於理學檢查時，發現眼球運動的範圍及受限情況如附圖，下列敘述何者最為合理？","options":["(A) 圖A及圖B中可見眼球運動受限，應該是腦神經的問題，可以確定前顱窩一定有骨折，使動眼神經受損","(B) 圖A中，雙眼眼球皆可以向上運動，圖B中，左眼眼球不能向下運動，有可能是眼眶下的掌管眼球運動的肌 肉因為眼眶底之骨折而使眼球運動功能受限","(C) 圖A及圖B左眼可以見到眼球有結膜下出血的現象，但右眼未見類似的出血，故右眼眶及周邊顏面骨應該沒 有骨折","(D) 其實眼眶附近的理學檢查可以省略，直接安排電腦斷層攝影更可以迅速而精確地診斷顏面骨斷裂的位置"],"answer":1,"image":"ya4-108-2-40.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"下列有關上顎骨骨折的敘述，何者正確？","options":["(A) Le Fort II：斷裂的位置最高","(B) Le Fort III：斷裂的位置最低","(C) Le Fort I：會傷及眼眶及鼻樑骨","(D) 複雜性的粉碎骨折時，未必有辦法以鈦金屬板做骨內固定術"],"answer":3,"clinical_level":"重點"},{"id":"ya4-108-2-42","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"下列有關唇腭裂治療的順序何者正確？①齒槽骨裂修補 ②軟腭修補 ③唇裂修補 ④牙齒矯正","options":["(A) ③①②④","(B) ③④②①","(C) ③②①④","(D) ③④①②"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-43","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"處理唇腭裂病人之鼻部畸形的最佳時機為何？","options":["(A) 施行唇裂修補手術時","(B) 施行腭裂修補手術時","(C) 施行齒槽骨缺損的補骨手術時","(D) 當所有手術與相關治療都完成後"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-44","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"鹽酸那囉克松（naloxone） 的藥理作用，下列何者正確？","options":["(A) 長效麻醉藥（long acting narcotics）的拮抗劑","(B) 降血壓","(C) 利尿劑","(D) 氣管擴張劑"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-45","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"當發生癲癇（seizure）時，應避免下列那一項處置方式？","options":["(A) 如發現呼吸道不暢通時，應使頸部適當伸直（moderate extension），或推下顎離開咽部","(B) 若有嘔吐時，應使頭部轉向一側，讓嘔吐物順利由口腔流出","(C) 若呼吸暫停超過30秒，需施行基本救命術（BLS）","(D) 應放置一物體於上下牙齒之間，以預防自己咬傷舌頭"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-46","subject":"ya4","topic":"全身性疾病與急症","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"患者在接受牙科治療時，若發生換氣過度現象，下列處置何者比較不恰當？","options":["(A) 停止牙科治療","(B) 給予氧氣以免二氧化碳濃度過高","(C) 言語安撫病人情緒","(D) 給予鎮定類藥物"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-47","subject":"ya4","topic":"齒源性感染與藥物","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"下列那些患者不適宜使用aspirin作手術後止痛？①氣喘病患 ②腎功能不良病患 ③授乳中之婦女","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-48","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"關於TMJ dislocation的敘述，下列何者正確？","options":["(A) 通常脫位後五分鐘後才會感覺疼痛","(B) 復位的方法，用大拇指將後牙下壓","(C) 復位的方法，將頦部（chin）往上提","(D) 復位一周後即可進行正常張口活動"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-49","subject":"ya4","topic":"局部與全身麻醉","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"80歲阿嬤送到急診，有習慣性的下巴脫臼病史，之前都可以輕易推回去，這次已經兩三個小時無法閉合，治 療時可以麻醉下列那一條神經？","options":["(A) 耳顳神經（auriculotemporal nerve）","(B) 下齒槽神經（inferior alveolar nerve）","(C) 上齒槽神經（superior alveolar nerve）","(D) 舌神經（lingual nerve）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-50","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"一位病人坐輪椅來院求診，他表示漸漸表現出前牙開咬，張口疼痛，Ｘ光影像表現發現下顎骨髁頭似乎部分 被吸收掉，直枝高度減少，病人填寫初診紀錄時，握筆亦不方便，為了確立診斷，可以抽血檢查下列項目， 以確立診斷？","options":["(A) rheumatoid factor and erythrocyte sedimentation rate（ESR）","(B) 僅C-reactive protein","(C) 僅erythrocyte sedimentation rate（ESR）","(D) white blood cell count，neutrophil percentage and C-reactive protein"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-51","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"下列有關pseudodisc adaptation的敘述，何者正確？","options":["(A) 病患顳顎關節的症狀變得更加嚴重","(B) 是一種生理性及解剖性的適應","(C) 會產生關節內黏連（ankylosis）","(D) 會產生關節盤破裂（disc perforation）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-52","subject":"ya4","topic":"口腔外科基礎","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"規定拔牙與植牙病人必須有手術與麻醉同意書，有關此議題之敘述，下列何者錯誤？","options":["(A) 此種倫理規範稱為知情同意 ( informed consent )","(B) 此種倫理規範最早見於1947年的紐倫堡規則","(C) 最初是用於人體實驗的規範","(D) 用於醫療診斷與治療時，經醫師詳細說明與病人充分理解，即完成法定契約手續"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-53","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"一位54歲男性前來就診，主訴左舌部潰瘍持續半年之久，門診檢查發現病患舌背側有5×4 cm之不動硬塊，舌 部活動受限導致病患發音異常，二側頸部有多個小於1 cm之活動性淋巴結，切片檢查結果為舌癌，應為病患 安排何種檢查？①Liver ultrasonography ②Whole body bone scan ③CT scan or MRI scan ④Chest X-ray ⑤Panoramic X-ray","options":["(A) 僅①②③⑤","(B) 僅②③④⑤","(C) 僅①③④⑤","(D) ①②③④⑤"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-54","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"承上題，這位病患經電腦斷層攝影檢查發現腫瘤為5.5×4×3 cm，且侵犯到舌外屬肌肉群（extrinsic muscle）， 左側level II淋巴結有一顆2 cm LAP（lymphadenopathy）且有central necrosis，其餘檢查均無遠處轉移。根據 AJCC臨床分期為下列何者？","options":["(A) T3N1M0，Stage III","(B) T3N2aM0，Stage IV","(C) T4N1M0，Stage IV","(D) T4N1M0，Stage III"],"answer":[0,2],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-108-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"一位60歲患者，主訴右側鼻翼部位疼痛，其疼痛期間只有約15～20秒，疼痛指數約8／10 （VAS），洗臉時 常會引起疼痛，痛時像刀割或電擊，這位病人最可能罹患下列何種疾病？","options":["(A) 鼻竇炎","(B) 三叉神經痛","(C) 非典型顏面疼痛","(D) 牙髓炎"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-56","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"承上題，下列那一種藥物治療對上述病人療效最差？","options":["(A) carbamazepine（Tegretol）","(B) gabapentin（Neurontin）","(C) phenytoin（Dilantin）","(D) acetaminophen（Scanol）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"下列何者為輻射吸收劑量（radiation absorbed dose, rad）在國際標準系統的單位名稱？","options":["(A) curie（Ci）","(B) gray（Gy）","(C) sievert（Sv）","(D) becquerel（Bq）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"在X光機的kVp值較低且適宜的情況下，增加曝光時間會導致X光影像產生何種變化？","options":["(A) 銳利度增強","(B) 銳利度降低","(C) 對比增強","(D) 對比降低"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"在距X光射源正前方2公尺處測得輻射劑量為1 Gy，則在相同環境下，距X光射源正前方 1 公尺處測得輻射劑 量為多少Gy？","options":["(A) 0.5","(B) 1","(C) 2","(D) 4"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-60","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"有關口內放射線攝影之平行法（paralleling technique）的敘述，下列何者錯誤？","options":["(A) 拍攝出的影像可重覆性高","(B) 各種位置的牙齒都能適用此拍攝法","(C) 在上顎後牙區可避開顴骨弓（zygomatic buttress）與牙根尖重疊","(D) 可用來偵測鄰接面齲齒（proximal caries）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"關於拍攝口內根尖片時，改善病人嘔吐反射（gag reflex）的作法，下列何者錯誤？","options":["(A) 在拍攝前詳細說明拍攝流程","(B) 可安排病人在早上拍攝","(C) 請病人專注於口呼吸","(D) 放置 X 光片時，減少對組織的刺激"],"answer":2,"clinical_level":"一般"},{"id":"ya4-108-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"使用分角線法拍攝上顎大臼齒根尖片時，採用的角度為何？","options":["(A) +0° to +15°","(B) +20° to +30°","(C) -15° to - 25°","(D) -30° to -35°"],"answer":1,"clinical_level":"一般"},{"id":"ya4-108-2-63","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"附圖之電腦斷層影像中，白色箭號所指的是下列何者？","options":["(A) 外耳道（external auditory canal）","(B) 內耳道（internal auditory canal）","(C) 耳咽管（Eustachian tube）","(D) 鼓索神經（chorda tympani nerve）"],"answer":0,"image":"ya4-108-2-63.jpeg","clinical_level":"重點"},{"id":"ya4-108-2-64","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"附圖中白色箭頭所指的部位，最不可能是下列何者？","options":["(A) normal bony nodule","(B) normal variant of maxillary sinus floor","(C) retained root fragment from a prior extraction","(D) zygomatic process of maxilla"],"answer":3,"image":"ya4-108-2-64.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-65","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"有關牙齒根尖片中營養管（nutrient canals）的敘述，下列何者錯誤？","options":["(A) 上顎比下顎容易看到","(B) 內含神經血管束","(C) 在嚴重牙周病的病人容易看到","(D) 在糖尿病的病人容易看到"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-66","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"46歲男性因下顎右側疼痛且腫脹而來求診，經影像檢查如附圖所示，則患者最不可能罹患下列何種疾病？","options":["(A) 蘭格罕氏細胞組織細胞增多症（Langerhans' cell histiocytosis）","(B) 轉移性癌（metastatic carcinoma）","(C) 多發性骨髓瘤（multiple myeloma）","(D) 成骨細胞瘤（osteoblastoma）"],"answer":3,"image":"ya4-108-2-66.jpeg","clinical_level":"重點"},{"id":"ya4-108-2-67","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"45歲男性因全口重建求診，經X光檢查如附圖所示，其中箭頭所指的病變最可能為下列何者？","options":["(A) 牙結石（dental calculi）","(B) 頸動脈鈣化（carotid artery calcifications）","(C) 鼻竇結石（antroliths）","(D) 扁桃腺結石（tonsilloliths）"],"answer":3,"image":"ya4-108-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-68","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"下列何者可診斷為牙本質形成不良（dentinogenesis imperfecta）？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011209-j5ub.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011216-gxpo.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011223-5yxs.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011229-rul6.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-108-2-69","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"下圖為典型之頭頸部軟組織鈣化或骨化的部位示意圖，其中標示2者為 何？","options":["(A) 涎石（sialoliths）","(B) 骨化莖突舌骨韌帶（ossified stylohyoid ligament）","(C) 鈣化淋巴結（calcified lymph nodes）","(D) 鈣化粉瘤斑（calcified atheromatous plaque）"],"answer":1,"image":"ya4-108-2-69.jpeg","clinical_level":"重點"},{"id":"ya4-108-2-70","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"下列何種疾病患者顎骨之放射線影像，較常見齒槽骨板（lamina dura）的喪失？","options":["(A) 副甲狀腺功能過旺（hyperparathyroidism）","(B) 副甲狀腺功能不足（hypoparathyroidism）","(C) 腦下垂體功能過旺（hyperpituitarism）","(D) 腦下垂體功能不足（hypopituitarism）"],"answer":0,"clinical_level":"重點"},{"id":"ya4-108-2-71","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"根據圖中X光影像，最可能的疾病為下列何者？","options":["(A) 鎖顱骨成骨不全（cleidocranial dysostosis）","(B) 半邊顎面發育異常（hemimaxillofacial dysplasia）","(C) 顱顏面成骨不全症（Crouzon syndrome）","(D) 阿部萊特氏症候群（Albright's syndrome）"],"answer":0,"image":"ya4-108-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-72","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"下列何者最不會呈現多發性放射線不透過性病變（multiple radiopacities）？","options":["(A) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）","(B) 嘉德耐氏症候群（Gardner's syndrome）","(C) 戈林症狀群（Gorlin syndrome）","(D) 柏哲德氏病（Paget's disease）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-108-2-73","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"圖中X光影像最符合下列那一種疾病？","options":["(A) 牙釉質發育不全（amelogenesis imperfecta）","(B) 牙本質形成不良（dentinogenesis imperfecta）","(C) 牙本質發育不良第一型（dentin dysplasia type I）","(D) 牙本質發育不良第二型（dentin dysplasia type II）"],"answer":0,"image":"ya4-108-2-73.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-74","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"Le Fort I fracture 在X光影像呈現的骨折斷線與下列何者最相似？","options":["(A) mandibular angle oblique fracture","(B) maxillary vertical fracture","(C) mandibular body vertical fracture","(D) maxillary horizontal fracture"],"answer":3,"clinical_level":"一般"},{"id":"ya4-108-2-75","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"有關CBCT，下列敘述何者錯誤？","options":["(A) 一張影像對患者幅射劑量介於52-1025 μSv","(B) 一張影像幅射劑量等於在美國地區200天日照幅射劑量","(C) 一張影像對患者幅射劑量是1-42張數位環口攝影術（digital panoramic radiography）的劑量","(D) 其幅射劑量是傳統頭部CT幅射劑量的51%～96%"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-2-76","subject":"ya4","topic":"放射線原理與技術","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"下列何者不是游離輻射造成的細胞複製死亡（reproductive death）的機轉？","options":["(A) 去氧核糖核酸（DNA）的破壞","(B) 粒線體分解（mitochondria breakdown）","(C) 細胞凋亡（apoptosis）","(D) 旁觀者效應（bystander effect）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-108-2-77","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"患者身體健康且發育正常，但上顎大門牙卻始終長不出來。其X光影像如圖所示，請問患者的年齡大約是幾 歲？","options":["(A) 8歲","(B) 10歲","(C) 12歲","(D) 14歲"],"answer":0,"image":"ya4-108-2-77.jpeg","clinical_level":"一般"},{"id":"ya4-108-2-78","subject":"ya4","topic":"口腔病理基礎","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"承上題，此患者之上顎門牙區有何異常？","options":["(A) 正中贅齒（mesiodens）","(B) 旁邊贅齒（paradens）","(C) 含牙囊腫（dentigerous cyst）","(D) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-108-2-79","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"圖示影像是以何種方法拍攝？","options":["(A) periapical radiography","(B) occlusal radiography","(C) panoramic radiography","(D) cone beam computed tomography"],"answer":1,"image":"ya4-108-2-79.jpeg","clinical_level":"重點"},{"id":"ya4-108-2-80","subject":"ya4","topic":"放射影像診斷","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"承上題，圖中白色箭頭所指的病變，最可能為下列何者？","options":["(A) 牙瘤（odontomae）","(B) 下顎骨贅生（mandibualr exostoses）","(C) 腭隆突（palatal tori）","(D) 涎石（sialoliths）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"傷口癒合過程中，有較多的血管生成angiogenesis是屬那一個階段？","options":["(A) inflammatory","(B) proliferative","(C) remodeling","(D) differentiation"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"口腔軟組織傷口癒合期中的第二期，又稱為下列何者？","options":["(A) remodeling stage","(B) inflammatory stage","(C) fibroplastic stage","(D) epthelilization stage"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"口腔手術前，施行手術者以消毒液洗手，範圍建議為下列何者？","options":["(A) 手掌處","(B) 手掌及手腕處","(C) 手掌、手腕及前臂至接近手肘處","(D) 手掌、手腕及前臂延伸至手肘以上5公分處"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-4","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"口腔軟組織傷口癒合期中的發炎期（inflammatory stage），正常情況下會持續幾天？","options":["(A) 1～2天","(B) 3～5天","(C) 6～10天","(D) 11～14天"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-1-5","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"成骨細胞（osteoblast）在拔牙傷口的骨癒合上很重要，下列何者非其之起源？","options":["(A) periosteum","(B) endosteum","(C) circulating pluripotential mesenchymal cells","(D) monocyte precursor cells"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"參考所附圖示（單位為毫米），下列敘述何者最不合理？","options":["(A) 此針最適合用來施打成人的下顎阻斷術，是較為安全的作法","(B) 此針建議用來打成人的後上齒槽神經，就入針深度而言相對安全","(C) 此針用來施打成人或兒童的局部浸潤（infiltration）應該都可以","(D) 若針需彎折，選擇彎折於10的位置，比在0的位置好"],"answer":0,"image":"ya4-109-1-6.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"下列有關麻醉注射過程中的細節，何者最不合理？","options":["(A) 針尖有魚鉤樣倒勾或刺的情況，可能導致將針拉回時，使病人產生疼痛的情況","(B) 麻醉針有可能因為廠商製造過程中，產生針尖有魚鉤樣倒勾或刺的情況","(C) 針尖有魚鉤樣倒勾或刺的情況，最常產生的情況可能是過度用力將麻醉針推向及碰觸硬組織","(D) 就同一患者同一次治療過程而言，雖有超過五次以上的多次注射需求，麻醉針仍不應更換，以減少污染的 機會"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"乳牙期兒童，使用1.8mL 2％ lidocaine麻藥管進行局部麻醉時，下列敘述何者錯誤？","options":["(A) 下齒槽神經阻斷麻醉劑量為半管","(B) 下門牙神經（incisive nerve）傳導麻醉可麻醉同側下顎前牙齒列","(C) 若上下左右均需麻醉，應一次施打完成","(D) 除非有禁忌病情，否則應使用含epinephrine麻藥"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-9","subject":"ya4","topic":"局部與全身麻醉","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"施打下齒槽神經阻斷麻醉時，為避免針頭斷離，下列何種作為最有效？","options":["(A) 使用＃30大小的針頭","(B) 使用短針頭","(C) 使用時不彎曲針頭","(D) 不使用不銹鋼針頭"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"拔牙後造成trismus，常因局部麻醉注射所影響，下列那一肌肉最常受到影響？","options":["(A) medial pterygoid muscle","(B) buccinator muscle","(C) lateral pterygoid muscle","(D) temporalis muscle"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"關於上顎阻生第三大臼齒的敘述，下列何者正確？","options":["(A) 遠心阻生（distoangular impaction）是最常見的情況","(B) 近心阻生（mesioangular impaction）較容易拔除","(C) 上顎第三大臼齒的牙根型態多為錐形","(D) 大部分的阻生第三大臼齒牙冠朝向腭側"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"如下圖所示，下顎左側第三大臼齒依Pell and Gregory classification方法分類，下列何者正確？","options":["(A) class A","(B) class 2","(C) class B","(D) class 3"],"answer":2,"image":"ya4-109-1-12.jpeg","clinical_level":"重點"},{"id":"ya4-109-1-13","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"手術拔除下顎第三大臼齒水平阻生，翻瓣設計上，下列何者正確？","options":["(A) 後方切線偏頰側延伸，以免傷及舌神經","(B) 後方切線偏舌側延伸，以免傷及頰神經","(C) 後方切線直往後方延伸，以免傷及舌神經及頰神經","(D) 不做後方切線"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-14","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"下列何種口服抗生素對於齒源性感染成效較差？","options":["(A) metronidazole","(B) ceftriaxone","(C) amoxicillin","(D) clindamycin"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"病人在接受化學治療之後，抱怨口腔內有疼痛性燒灼感與白色斑塊，經藥物治療後，白色斑點消失，症狀也 緩解。此一有效及毒性低的藥物，為下列何者？","options":["(A) azithromycin","(B) fluconazole","(C) ketoconazole","(D) nystatin"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-16","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"一位病人兩個月前因為車禍導致右下顎骨骨折與右下第一小臼齒喪失，他接受閉合式整復治療。最近發現右 下顎骨下緣處有膿瘍產生，如下圖，下列原因何者較不可能？","options":["(A) 細菌進入骨折區域","(B) 抗生素劑量不足夠","(C) 有砂石在傷口內","(D) 患者免疫力較低"],"answer":1,"image":"ya4-109-1-16.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"依下圖，病人右側大臼齒區疼痛，五天前患區開始腫脹，並往口底蔓延，吞嚥困難，體溫為39°C，下列何者 診斷合理？","options":["(A) 惡性淋巴瘤（malignant lymphoma）","(B) 右下顎骨瀰漫性骨髓炎（diffuse osteomyelitis）","(C) 口底區纖維肉瘤（fibrosarcoma）","(D) 盧德威氏口峽炎（Ludwig's angina）"],"answer":3,"image":"ya4-109-1-17.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"72歲女性病患，患有第二型糖尿病，控制情況不佳，因拔牙後第4個月傷口仍持續癒合不良，放射線檢查發現 拔牙傷口鄰近骨質呈透射與不透射區域混雜，口內傷口處仍存在肉芽腫。關於此病例之敘述，下列何者錯 誤？","options":["(A) 病患之診斷應為慢性骨髓炎","(B) 應投予penicillin 1個月","(C) 應進行手術治療","(D) 應加強控制糖尿病"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-19","subject":"ya4","topic":"植牙外科","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"植入牙科植體時，其與骨頭間隙最多不可超過多少，以避免無法達到初級穏固（primary stability），進而引 起骨整合（osseointegration）失敗？","options":["(A) 1 mm","(B) 2 mm","(C) 3 mm","(D) 3.5 mm"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-20","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"關於覆蓋義齒手術（overdenture surgery）的敘述，下列何者錯誤？","options":["(A) 是把牙齒保留下來以減少義齒下的骨頭吸收","(B) 增加配戴義齒時的本體感覺","(C) 增加義齒的固位（retention）和穩定性（stability）","(D) 兩側小臼齒被視為最該保留住的牙齒"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-21","subject":"ya4","topic":"植牙外科","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"使用於上下顎自體骨移植的部位時，下列那個部位可同時提供適量的cortical bone與cancellous bone？","options":["(A) symphysis","(B) ramus-posterior body","(C) maxillary tuberosity","(D) mandible coronoid process"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-22","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"下列何者為口腔癌致癌因子？①檳榔 ②菸草 ③人類乳突病毒（HPV） ④單純皰疹病毒（HSV）","options":["(A) ①②④","(B) ①②③","(C) ②③④","(D) ①③④"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"下列口腔內的惡性腫瘤之淋巴結轉移率，何者最快？","options":["(A) 惡性黑色素瘤（malignant melanoma）","(B) 黏液表皮樣癌（mucoepidermoid carcinoma）","(C) 鱗狀細胞癌（squamous cell carcinoma）","(D) 疣狀癌（verrucous carcinoma）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-24","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"使用剜出術（enucleation）合併刮除術（curettage）治療高復發率的囊腫病灶的敘述，下列何者正確？","options":["(A) 可以使用刮勺（curette），但不可以使用鑽針","(B) 必須移除1～2 mm周圍的骨質","(C) 必須移除0.5 mm以下周圍的骨質","(D) 側方牙周囊腫（lateral periodontal cyst）的標準療法"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-25","subject":"ya4","topic":"口腔病理基礎","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"側方牙周囊腫（lateral periodontal cyst）好發於下列那個區域？","options":["(A) 上顎犬齒及小臼齒間","(B) 上顎小臼齒及大臼齒間","(C) 下顎犬齒及小臼齒間","(D) 下顎小臼齒及大臼齒間"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-26","subject":"ya4","topic":"口腔病理基礎","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"關於齒源性角化囊腫的病灶好發區域，下列敘述何者錯誤？","options":["(A) 好發在下顎骨","(B) 下顎骨中又以下顎骨角最常發生","(C) 超過50歲以後的病人發生在上顎骨的機率增加","(D) 發生在下顎骨之病灶較容易伴隨全身性之症候群"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-27","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"下列何者不是造袋術（marsupialization）的優點？","options":["(A) 不必全身麻醉，也可進行","(B) 當病灶較小時更容易進行","(C) 手術中可以降低產生骨折的風險","(D) 不會因手術而產生附近神經的損傷"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-1-28","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"造成顏面畸形的原因，下列何者錯誤？","options":["(A) 基因遺傳會造成顏面畸形","(B) 生長中的顏面骨，受到外傷會造成顏面畸形","(C) 環境因子不會造成顏面畸形","(D) 唇腭裂是一種顏面畸形"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-29","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"顏面骨骼生長會受到鄰近軟組織的影響，下列何者錯誤？","options":["(A) 鼻部軟組織會影響顏面骨骼生長","(B) 口腔軟組織會影響顏面骨骼生長","(C) 下咽呼吸道軟組織不會影響顏面骨骼生長","(D) 顏面肌肉軟組織會影響顏面骨骼生長"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"關於上顎前後向生長過多（anteroposterior maxillary excess）的特徵，下列敘述何者錯誤？","options":["(A) 側面觀呈現著突出（convex）的臉型","(B) 上顎前牙突出","(C) 上顎前牙牙齦暴露（gingival exposure）較多","(D) 病人的齒列常見是異常咬合Class III"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-1-31","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"骨牽引生成術（distraction osteogenesis）應用於正顎手術，何者正確？","options":["(A) 一般之等待期（latency period）為二星期","(B) 牽引速度，每次1.0 mm，每天兩次","(C) 鞏固期（consolidation phase）通常約為牽引期（distraction phase）的2～3倍時間","(D) 可用於需將下顎骨後縮的病人"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-32","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"關於口腔顏面疼痛（orofacial pain）的評估，下列敘述何者錯誤？","options":["(A) 儘可能獲得關於疼痛的時間、類型、加重或緩解因子、過去治療的方式及反應等等","(B) 一般牙醫師施行理學檢查需包括正式的神經學檢查，如眼底鏡檢查、嗅覺檢查等","(C) 診斷性麻醉測試（diagnostic anesthetic testing）需使用無血管收縮劑之溶液，並依循表面麻醉、浸潤麻醉、 阻斷麻醉的步驟逐步進行","(D) 牙醫師的職責在於建立診斷，避免不必要的牙科治療，以免危害病人健康，實際疼痛治療應轉診至其他專 科醫師"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-1-33","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"關於神經失用症（neurapraxia）的敘述，下列何者錯誤？","options":["(A) 神經失用症（neurapraxia）一般在4週以內會復原","(B) 局部缺血或神經周圍發炎時可能發生","(C) 當植入植體輕微觸壓到下齒槽神經時，可能發生神經失用症","(D) 為周邊神經受損時，神經鞘膜及軸突皆斷裂之病症"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-1-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"有關疱疹後（postherpetic）神經痛的敘述，下列何者錯誤？","options":["(A) 可以發生在任何年齡層","(B) 早年罹患水痘，病毒經一段潛伏期後，再度爆發","(C) 急性期大約可以持續10週以上","(D) 治療藥物包括了anticonvulsants or tricyclic or other antidepressants"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-35","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"關於唾液腺攝影（sialography）的敘述，下列何者正確？","options":["(A) 病患經由口腔喝下顯影劑後，再進行一系列的X光片攝影檢查","(B) 顯影劑滯留在唾液腺體及腺管的時間，超過15分鐘可視為具有正常的代謝功能","(C) 唾液腺攝影無法評估唾液腺結石及腫瘤性疾病","(D) 除診斷外，唾液腺攝影亦兼具治療的效果"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-36","subject":"ya4","topic":"唾液腺疾病","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"患者因顎下區域腫脹求診，經醫師診斷為顎下腺結石，臨床上處理的方式常取決於與此疾病相關的因素。下 列何者不是唾液腺結石處理，必須要考慮的主要因素？","options":["(A) 結石發生的部位及大小","(B) 唾液量異常的改變","(C) 症狀持續的期間","(D) 重複發生的次數"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-37","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"有關唾液腺攝影術（sialography）檢查，若Stensen duct在影像中呈現香腸狀，最有可能的診斷是下列何者？","options":["(A) sialolithiasis","(B) sialodochitis","(C) sialadenitis","(D) sialocele"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-38","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"應用於中顏面骨折時固定用的鈦合金骨板（titanium plate），一般較常見的厚度約為？","options":["(A) 小於 0.25 mm","(B) 介於 0.6～1.5 mm","(C) 介於2.2 mm～3.0 mm","(D) 3.5 mm以上"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-39","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"關於骨內固定（internal fixation）的敘述，下列何者正確？","options":["(A) 上下顎間固定提供剛硬（rigid）的骨內固定","(B) 上下顎間固定提供半剛硬（semi-rigid）的骨內固定","(C) 上下顎間固定提供非剛硬（non-rigid）的骨內固定","(D) 上下顎間固定不是骨內固定方法"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-40","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"下列骨折，何者不會出現結膜下出血（subconjuntival hemorrhage）？","options":["(A) 勒福氏第一級（Le Fort I）骨折","(B) 勒福氏第二級（Le Fort II）骨折","(C) 勒福氏第三級（Le Fort III）骨折","(D) 顴骨上顎骨複合體（zygomaticomaxillary complex）骨折"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"牙齒外傷後，有搖動沒有移位稱為：","options":["(A) 齒震盪（concussion）","(B) 齒半脫臼（subluxation）","(C) 齒內縮（intrusion）","(D) 齒敏感（sensitivity）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"下列有關zygomatic complex fracture的敘述，何者錯誤？","options":["(A) 是中顏面區最容易發生骨折的部位之一","(B) 患側外眼眶及下眼眶會有壓痛感","(C) 患側眶下神經支配的範圍會有感覺異常的現象","(D) 病人通常不會有張口困難的症狀"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-1-43","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"關於唇腭裂的敘述，下列何者正確？","options":["(A) primary palate與secondary palate同硬腭及軟腭交界為界","(B) 隱藏性腭裂（occult clefts）是指肌肉與黏膜組織完整，但硬腭（hard palate）分裂","(C) 分岔懸雍垂（bifid uvula）是一種輕微的腭裂","(D) 單側唇腭裂占四分之一，雙側唇腭裂占四分之三"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-1-44","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"有關腭裂病人聽力不好的主要原因為何？","options":["(A) 神經傳導異常","(B) 大多與慢性感染有關","(C) 耳膜結構異常","(D) 聽覺神經先天性異常"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-45","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"腎臟移植（renal transplantation）病人需要接受口腔手術時，下列何者錯誤？","options":["(A) 避免使用具腎臟毒性（nephrotoxic）藥物","(B) 手術中注意低血壓（hypotension）的發生","(C) 手術前考慮增加皮質類固醇（corticosteroids）劑量","(D) 手術前考慮使用預防性抗生素（prophylactic antibiotics）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-1-46","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"下列何種症狀常需長期服用phenytoin（Dilantin）藥物？","options":["(A) 姿勢性低血壓（orthostatic hypotension）","(B) 癲癇（seizure）","(C) 慢性阻塞性肺病（chronic obstructive pulmonary disease）","(D) 血管迷走性暈厥（vasovagal syncope）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-47","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"下列何種情況是拔牙的局部禁忌症？","options":["(A) 惡性腫瘤區內的牙齒","(B) 根尖膿瘍","(C) 齲齒","(D) 牙周炎"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-48","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"下列那一項內科急症於門診手術過程中因緊張、焦慮而誘發無關？","options":["(A) 狹心症（angina pectoris）","(B) 癲癇（seizure）","(C) 換氣過度（hyperventilation）","(D) 體位性低血壓（orthostatic hypotension）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-49","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"病人主訴有雙側髮鬢區頭痛，但沒有耳前壓痛，張口困難，且牙齒有磨耗現象，顳顎關節影像沒有特殊發 現，最可能的診斷為下列何者？","options":["(A) 肌筋膜疼痛及功能障礙（myofascial pain and dysfunction）","(B) 關節盤內紛亂（internal derangement）","(C) 可復位之關節盤前異位（anterior disc displacement with reduction）","(D) 退化性關節炎（degenerative joint disease）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-50","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"關於anterior repositioning splints咬合板治療顳顎關節疾病，下列何者錯誤？","options":["(A) 配戴於上顎牙齒","(B) 可以使下顎骨髁頭達到稍微向後向上的位置","(C) 可以讓肌肉和關節都得到休息","(D) 可以矯治關節盤前異位（anterior disk displacement）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-51","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"有關顳顎關節黏連之敘述，下列何者錯誤？","options":["(A) 關節囊內黏連常見於髁頭骨折的患者","(B) 關節囊外黏連造成原因，主要為喙狀突增生、顴骨弓外傷或顳肌感染","(C) 關節囊外黏連常合併關節囊內黏連","(D) 關節囊內黏連會嚴重影響患者的張口度"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-1-52","subject":"ya4","topic":"口腔外科基礎","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"下列何者可證明不當醫療（malpractice）？①existence of a duty ②breach of the duty ③damage ④caution","options":["(A) 僅①","(B) 僅②④","(C) 僅②③④","(D) ①②③④"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-53","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"病患之X光片（如下圖所示），在以拔牙鉗拔除其左側上顎第一大臼齒時，牙齒尚未鬆動，即發生近心頰側 （mesiobuccal）牙根於根尖1／3處斷裂，斷根殘留齒槽內，此時下列何種處置最合理？","options":["(A) 由於殘留之根尖不大，可將之留置，追蹤觀察即可","(B) 用溫特氏（Winter's）挺將根間分隔（inter-radicular septum）移除及取出斷根","(C) 以柯特威爾－路克（Caldwell-Luc）手術取出斷根","(D) 以鑽針或骨鑿去除斷根周圍部分牙床骨後，再取出斷根"],"answer":3,"image":"ya4-109-1-53.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-54","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"承上題，當你欲移除斷根時，不小心將之推入上顎竇，此時下列何種處置最合理？","options":["(A) 由於斷根不大，可將之留置，追蹤觀察即可","(B) 先給予抗生素，待斷根周圍纖維化後，再用內視鏡將之取出","(C) 在齒槽窩內將上顎竇底之骨骼全部移除，再用抽吸器將斷根取出","(D) 採用柯特威爾－路克（Caldwell-Luc）手術取出斷根"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-55","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"舌癌病人術後病理報告發現腫瘤大小為6×5 cm，並侵犯到下顎骨及肌肉層，無淋巴結轉移，此時之病理分期 為何？","options":["(A) cT3N0M0","(B) pT4aN0M0","(C) cT4aN0M0","(D) pT3N0M0"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-56","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"承上題，病人順利出院，術後恢復良好時，關於後續治療之安排，下列敘述何者正確？","options":["(A) 因腫瘤切除乾淨且淋巴未轉移故不需任何處理，追蹤即可","(B) 先追蹤半年，若有復發再安排後續治療","(C) 需安排放射線治療並考慮化學治療","(D) 僅安排化學治療即可"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"X光之波長為何？","options":["(A) 100 μm～700 nm","(B) 700 nm～400 nm","(C) 400 nm～10 nm","(D) 10 nm～0.01 pm"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"下列何者不是國際放射防護委員會（ICRP）2007年建議之輻射防護標準？","options":["(A) 一般人之年有效劑量為1毫西弗","(B) 工作人員之年有效劑量最大為50毫西弗","(C) 工作人員之5年平均有效劑量最大為20毫西弗","(D) 接受牙科治療之病人的年平均有效劑量比照工作人員"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"依2007年國際放射防護委員會（ICRP）將每年曝露放射線的危險性分類，牙醫師屬於那一類別？","options":["(A) classified worker","(B) non-classified worker","(C) classified general public","(D) non-classified general public"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-1-60","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"進行口內根尖片放射線攝影時，放射線接觸傳統X光片部位的先後次序為何？①封套 ②黑紙 ③鉛片 ④ 底片","options":["(A) ①②④③","(B) ①③②④","(C) ①④③②","(D) ①②③④"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"下列何者為X光片沖洗時之硬化劑（hardening agent）？","options":["(A) 醋酸","(B) 硫酸鉀","(C) 硫酸鋁","(D) 氫氧化鉀"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-62","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"附圖箭頭所指，1與2之影像分別為：","options":["(A) 1為border of maxillary sinus，2為zygomatic process","(B) 1為floor of nasal fossa，2為zygomatic process","(C) 1為zygomatic process，2為sinus septum","(D) 1為floor of nasal fossa，2為border of maxillary sinus"],"answer":3,"image":"ya4-109-1-62.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-63","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"附圖根尖X光片中，白色箭頭所指為何種構造？","options":["(A) anterior floor of the maxillary sinus","(B) floor of the nasal aperture","(C) cortical bone of the hard palate","(D) posterior extension of nasal septum"],"answer":1,"image":"ya4-109-1-63.jpeg","clinical_level":"重點"},{"id":"ya4-109-1-64","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"有關牙周韌帶（periodontal ligament）寬度在X光片中呈現之敘述，下列何者錯誤？","options":["(A) 個體不同，寬度可能不同","(B) 每一顆牙的寬度可能不同","(C) 同一顆牙在根尖處通常會比牙根中間來的窄","(D) 同一顆牙在齒槽嵴（alveolar crest）處通常會比牙根中間來的寬"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-1-65","subject":"ya4","topic":"口腔病理基礎","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"15歲少女左側臉部和口腔有許多長得很慢的腫塊，全身皮膚有café-au-lait的spots， 在pterygoid space的腫瘤 MRI的影像中，呈現T1沒有signal而T2有high signal（如附圖），則此腫瘤最可能是： T2 T1","options":["(A) 神經纖維瘤病（neurofibromatosis）","(B) 多形性腺瘤（pleomorphic adenoma）","(C) 造釉細胞瘤（ameloblastoma）","(D) 瓦新氏腫瘤（Warthin's tumor）"],"answer":0,"image":"ya4-109-1-65.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-66","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"24歲女性主訴一個小時前跌倒，撞到上顎前牙，臨床檢查發現右下唇有1.5 cm撕裂傷、右上側門牙動搖度增 加，且超出門齒切緣，根尖片影像如附圖，下列敘述何者錯誤？","options":["(A) 右上側門牙牙根斷裂","(B) 右上側門牙牙冠部須持續追蹤牙髓活性，必要時進行根管治療","(C) 水平牙根斷裂，須以不同的X光水平入射角照射，以得知斷裂線位置","(D) 水平牙根斷裂之斷裂線越靠近牙根中段預後較差"],"answer":2,"image":"ya4-109-1-66.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-67","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"有關根尖囊腫經剜除後，癒合過程中的放射線影像敘述，下列何者錯誤？","options":["(A) 病灶範圍會變小","(B) 病灶邊緣會呈現更清晰的一圈白線","(C) 病灶邊緣會變得比較不明顯","(D) 病灶內的放射線透射區域會變小"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-68","subject":"ya4","topic":"口腔病理基礎","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"下列何種齒源性病變，其X光影像較常呈現單房或多房性放射線透過性病變（unilocular or multilocular radiolucent lesion），且較好犯於18歲以下小孩之下顎臼齒區及上升枝（ascending ramus）？","options":["(A) 造釉細胞纖維齒瘤（ameloblastic fibro-odontoma）","(B) 造釉細胞瘤（ameloblastoma）","(C) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(D) 造釉細胞纖維瘤（ameloblastic fibroma）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-1-69","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"下列何種囊腫是位於軟組織內之囊腫，通常要打入對比劑（contrast media），才能照出其X光影像？","options":["(A) 完全角化齒源性囊腫（orthokeratinized odontogenic cyst）","(B) 鼻唇囊腫（nasolabial cyst）","(C) 側位牙周囊腫（lateral periodontal cyst）","(D) 殘餘根尖囊腫（residual radicular cyst）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-70","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"50歲男性於環口X光檢查中（圖A），發現了右下顎骨角附近，有一個無症狀且有白色邊緣的放射線透射病 灶，電腦斷層檢查如圖B。則其最可能的診斷為何？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 戈林氏囊腫（Gorlin's cyst）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 史塔尼氏骨囊腫（Stafne bone cyst）"],"answer":3,"image":"ya4-109-1-70.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-71","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"附圖為上顎後牙區根尖片影像，最可能的牙齒變異（tooth anomaly）為何？","options":["(A) 缺牙（missing tooth）","(B) 多生牙（supernumerary tooth）","(C) 牙本質發育不全（dentinogenesis imperfecta）","(D) 牙釉質發育不全（amelogenesis imperfecta）"],"answer":1,"image":"ya4-109-1-71.jpeg","clinical_level":"重點"},{"id":"ya4-109-1-72","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"附圖X光片中，黑色箭頭所指為惡性細胞侵犯牙周韌帶所造成之影像，下列何種病變較不可能有此影像？","options":["(A) 多發性骨髓瘤（multiple myeloma）","(B) 軟骨肉瘤（chondrosarcoma）","(C) 骨性肉瘤（osteogenic sarcoma）","(D) 纖維肉瘤（fibrosarcoma）"],"answer":0,"image":"ya4-109-1-72.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-73","subject":"ya4","topic":"口腔病理基礎","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"45歲女性接受牙周病治療時，牙醫師發現其下顎根尖X光片有如圖之異常表現。下列診斷及處置何者錯誤？","options":["(A) 先測量牙齒活性，檢查有無臨床症狀","(B) 可能是纖維骨性病灶（fibro-osseous lesion）","(C) 即使無症狀，也應立即切片作病理檢查","(D) 通常不需要治療"],"answer":2,"image":"ya4-109-1-73.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-74","subject":"ya4","topic":"放射影像診斷","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"評估牙周病狀態時，從根尖X光片檢視齒槽嵴（alveolar crest）的高度很重要，正常的齒槽嵴位於牙骨質牙釉 質連接處（CEJ）下方約多少mm？","options":["(A) 0.1～0.3","(B) 0.5～2.0","(C) 3.0～4.0","(D) 5.0～6.0"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-75","subject":"ya4","topic":"口腔病理基礎","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）最常發生於顎骨中那一區域？","options":["(A) 上顎前齒區","(B) 上顎臼齒區","(C) 下顎前齒區","(D) 下顎臼齒區"],"answer":0,"clinical_level":"重點"},{"id":"ya4-109-1-76","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"患者56歲，舌癌手術後接受放射線治療，手術後臉部傷口有流膿現象。如圖CT scan可以看到以下那些現象？ ①陽光線狀影像（sun-ray appearance） ②病灶邊緣不整齊 ③病灶邊緣整齊 ④有死骨（sequestrum）的 影像","options":["(A) ①②③④","(B) ②③","(C) ②④","(D) ①③④"],"answer":2,"image":"ya4-109-1-76.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-77","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"Dental digital radiography比傳統dental radiography需要較低的放射線能量，其最主要的原因為何？","options":["(A) sensor比較大","(B) sensor比較sensitive","(C) exposure time較長","(D) pixel傳送比較快"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-1-78","subject":"ya4","topic":"放射線原理與技術","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"下列何種組織或器官對放射線敏感度最低？","options":["(A) optic lens","(B) bone marrow","(C) salivary gland","(D) intestines"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-1-79","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"附圖影像之拍攝方式為何？","options":["(A) 核磁共振造影（magnetic resonance imaging）","(B) 電腦斷層掃描（computerized tomography）","(C) 同位素骨掃描（radioisotope bone scan）","(D) 超音波掃描（ultrasonography）"],"answer":2,"image":"ya4-109-1-79.jpeg","clinical_level":"一般"},{"id":"ya4-109-1-80","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"承上題，附圖黑色箭頭所示之影像最可能之解釋為何？","options":["(A) 假像（artifact）","(B) 同位素之活性（activity of isotope）","(C) 鈣化區（calcification）","(D) 放射線透過區（radiolucency）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-1","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"神經受傷後，再生過程中神經纖維遇到結締組織阻礙時，會包覆（around）此阻礙，而形成讓患者產生痛感之 腫塊，此腫塊又稱為下列何者？","options":["(A) traumatic neurilemmoma","(B) traumatic schwannoma","(C) traumatic neuroma","(D) traumatic fibroma"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"周邊神經傷害後，神經斷端纖維再生之速率，每天約生長多少 mm？","options":["(A) 0.1～0.5","(B) 1～1.5","(C) 2～2.5","(D) 3～3.5"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"傷口癒合過程中發炎期（inflammatory stage）的敘述，下列何者錯誤？","options":["(A) 發炎期又稱遲延期（lag phase）","(B) 發炎期就能產生很多膠原蛋白（collagen）","(C) 傷口強度（wound strength）沒有增強許多","(D) 此期固持住傷口主要是纖維蛋白（fibrin）的作用"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-2-4","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"關於傷口癒合過程中再塑期（remodeling stage）的敘述，下列何者錯誤？","options":["(A) 又稱傷口成熟期","(B) 此期最後傷口的強度，會恢復到未受傷前狀態 90%以上的組織強度","(C) 上皮組織細胞的排列，再度形成正常細胞的分層（stratification）狀況","(D) 重建血管的完整性"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-2-5","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"使 greenstick fracture 癒合時，其過程屬於下列何者？","options":["(A) healing by primary intention","(B) healing by secondary intention","(C) healing by tertiary intention","(D) healing by quaternary intention"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-6","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"下列有關周邊神經之纖維粗細大小（size）與生理功能的敘述，何者最不適當？","options":["(A) A alpha 纖維直徑較粗，傳導速度較快，主要參與痛覺的傳導","(B) A beta 纖維直徑較粗，傳導速度較快，主要參與運動及本體感覺傳導","(C) A gamma 纖維一般比A alpha 纖維細，主要參與肌肉組織張力覺（muscle tone）之傳導","(D) C 纖維一般比 A alpha 纖維細，主要參與交感神經與痛覺傳導"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"下列何者的阻斷麻醉，最易發生血管內注射？","options":["(A) 頦神經（mental nerve）","(B) 下齒槽神經（inferior alveolar nerve）","(C) 前上齒槽神經（anterior superior alveolar nerve）","(D) 後上齒槽神經（posterior superior alveolar nerve）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"有關牙科治療所使用麻醉劑中的血管收縮劑之敘述，下列何者正確？","options":["(A) 含 epinephrine 的麻醉劑比含 norepinephrine 的麻醉劑更安全","(B) 含 epinephrine 的濃度通常為 1：10000","(C) epinephrine 對血壓的影響，主要是使舒張壓上升","(D) 正常人一次門診可接受 epinephrine 的最大劑量為 2 mg"],"answer":0,"clinical_level":"重點"},{"id":"ya4-109-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"拔牙時若不慎造成鄰牙鬆動，下列處置何者錯誤？","options":["(A) 若只有輕微鬆動，將牙齒壓回齒槽骨即可","(B) 必須確定咬合以避免造成 hyperocclusion 及 traumatic occlusion","(C) 如果造成牙齒明顯鬆動須使用 semirigid fixation 固定牙齒即可","(D) 使用 arch bar 及 wire fixation 是固定拔牙所造成牙齒鬆動最好的方法"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"關於拔牙止血的處理，下列敘述何者正確？","options":["(A) 膠原蛋白能幫助傷口的止血","(B) 長期服用抗凝血藥物的病患，若抽血檢驗值為INR 2.5，絕對不能拔牙","(C) 清除肉芽組織會增加出血風險","(D) 齒槽骨內的出血應立即使用電燒止血"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"拔除上顎正中門齒時，下列那種器械不適合使用？","options":["(A) 牙周刀（periotome）","(B) 直的拔牙挺（elevator）","(C) 150A 拔牙鉗（forceps）","(D) 150 拔牙鉗（forceps）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"使用拔牙鉗夾住牙齒時，第一個施在牙齒的會是何方向的力量？","options":["(A) 朝向頰側","(B) 朝向舌（腭）側","(C) 朝向根尖","(D) 朝向遠心側"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"拔除阻生牙的基本步驟，不包括下列那一項？","options":["(A) 翻開足夠的軟組織","(B) 移除足夠的齒槽骨","(C) 將移除的齒槽骨植回","(D) 用 bur 或 chisel 切除牙齒"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-14","subject":"ya4","topic":"拔牙學與併發症","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"下列何者之牙根型態變異性最大？","options":["(A) 上顎第一小臼齒","(B) 下顎第二小臼齒","(C) 下顎第三大臼齒","(D) 上顎第三大臼齒"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"心內膜炎（bacterial endocarditis）高風險的病人進行侵入性口腔手術時，如對 amoxicillin 過敏，不應選擇下 列何種抗生素？","options":["(A) azithromycin","(B) clarithromycin","(C) clindamycin","(D) doxycycline"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"舌下間隙（sublingual space）感染，最容易由下顎那一顆牙齒引起？","options":["(A) 第三大臼齒","(B) 牙根比較長的第二大臼齒","(C) 小臼齒","(D) 前牙"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"關於骨髓炎（osteomyelitis）的敘述，下列何者錯誤？","options":["(A) 骨髓炎發生在下顎的機率會比上顎高","(B) 通常都是病人的免疫力較低才會出現","(C) 治療急性骨髓炎通常使用抗生素治療，應在症狀改善後繼續使用6周","(D) 嚴重難以治療的慢性骨髓炎應積極使用抗生素治療3個月"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-2-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"關於蜂窩性組織炎（cellulitis）與膿瘍（abscess）的差異，下列敘述何者正確？","options":["(A) 蜂窩性組織炎有波動感（fluctuance）","(B) 蜂窩性組織炎病程變化較膿瘍快速","(C) 膿瘍的宿主抵抗力較為衰弱","(D) 膿瘍危險性較高"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"關於預防性抗生素的使用，下列敘述何者正確？","options":["(A) 預防性抗生素一定要在手術開始前4個小時前投藥","(B) 當長時間手術時，通常會增加抗生素使用的次數，手術中給藥的時間間隔應予縮短","(C) 比較短的手術，術前的2劑抗生素就已經足夠","(D) 以齒源性感染來說就是可以對付嗜氧性球菌，殺菌範圍較窄，毒性低的殺菌型抗生素，最符合條件的就是 clindamycin"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-20","subject":"ya4","topic":"植牙外科","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"一般就牛骨所製成的骨移植物屬於下列何種類？","options":["(A) autogenous grafts","(B) allografts","(C) alloplastic grafts","(D) xenografts"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-21","subject":"ya4","topic":"植牙外科","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"植體周邊軟組織增高（augmentation）其處理最基本原則為下列何者？","options":["(A) 受移植區（recipient）必須提供足夠的血液循環讓移植的軟組織生長","(B) 移植的軟組織也需要有足夠的血管組織","(C) 受移植區（recipient）的發炎組織無需移除","(D) 移植的軟組織越薄越有利植體的需要"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-22","subject":"ya4","topic":"植牙外科","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"有關影響牙科植體長期成功率的生物機械因素，下列敘述何者錯誤？","options":["(A) 牙科植體過早受過大力量","(B) 過大的側方力量","(C) 側方力量對於前牙區的破壞比後牙區來得嚴重","(D) 過長的懸臂（cantilever），會造成過大的受力"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-23","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"關於細胞學檢查（cytology-based procedures）的敘述，下列何者錯誤？","options":["(A) 基本上有兩種主要的檢查方法","(B) 剝落細胞學（exfoliative cytologic examination）最早使用並最常使用在口腔黏膜細胞的檢查","(C) 細胞學檢查結果為陰性（negative），臨床上仍需持續追蹤","(D) 細胞學檢查結果為陽性（positive），需要進一步切片檢查確定"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-24","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"關於口腔病灶診斷，抽血檢查的敘述，下列何者正確？","options":["(A) 口腔病灶不需要抽血檢查作為診斷的依據","(B) 齒槽骨板（lamina dura）變寬時，表示病人可能有甲狀腺機能亢進的問題，可以抽血檢查病人的T3、T4、 TSH是否有異常","(C) 影像上發現顎骨有多處溶骨性病變（osteolytic lesion）時，可以抽血檢查以確定是否有異常","(D) 白血病（leukemia）和淋巴瘤（lymphoma）屬於血液性疾病，可經抽血診斷，但不會在口腔發生病灶"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-25","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"關於肩胛舌骨上頸部廓清術（supraomohyoid neck dissection）的敘述，下列何者錯誤？","options":["(A) 需保留頸內靜脈及胸鎖乳突肌","(B) 一般主要用於預防性之淋巴轉移","(C) 需清除頸部 level II至IV之淋巴組織","(D) 病人的併發症較radical neck dissection少"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-2-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"下列何者不是化學藥物治療惡性腫瘤所產生的併發症？","options":["(A) 感染","(B) 貧血","(C) 容易流血","(D) 血小板增多"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-27","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"單純發生在下唇的早期鱗狀細胞癌，有關治療之敘述，下列何者錯誤？","options":["(A) 手術比放射線治療的治癒機會高出甚多","(B) 五年存活率約80～90％","(C) 切除部分若小於唇長度30％，以初級縫合（primary closure）為宜","(D) 手術切除時，小於1 cm之病灶其安全邊緣（safety margin）可以比較大之病灶來的小"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-28","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"顎骨囊腫手術（jaw bone cyst）中，治療目的相同的術式為下列何者？①減壓術（decompression） ②Partsch operation ③造袋術（marsupialization） ④刮除術（curettage）","options":["(A) ①②④","(B) ②③④","(C) ①③④","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"下列何者最不適合使用造袋術（marsupialization）治療？","options":["(A) 齒源性角化囊腫（odontogenic keratocyst）","(B) 兒童之含牙囊腫（dentigerous cyst）","(C) 單囊狀造釉細胞瘤（unicystic ameloblastoma）","(D) 動脈瘤性骨囊腫（aneurysmal bone cyst）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-2-30","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"以口內垂直下顎枝切開術（intraoral bilateral vertical ramus osteotomy, BVRO）治療下顎骨過度發育，下列敘述 何者正確？","options":["(A) 沿著下顎枝前緣做垂直顎枝截骨術","(B) 截骨後近心端骨片應包含下顎骨角（mandible angle）","(C) 截骨後下顎骨後移，近心端骨片與遠心端骨片重疊時，近心端骨片應在遠心端骨片內側方向","(D) 近心端骨片與遠心端骨片需以骨釘或骨板固定，因此上下顎間固定時間可縮短至1～2星期"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-2-31","subject":"ya4","topic":"放射影像診斷","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"評估一個人的顏面不對稱，可以利用X光片來衡量，下列敘述何者錯誤？","options":["(A) 全景 X 光片","(B) 側面顱 X 光片","(C) 電腦斷層 X 光片","(D) 正面 X 光片"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"施行Le Fort I osteotomy手術時，下列何者最不可能被損傷？","options":["(A) nasal mucosa","(B) antral membrane","(C) infraorbital nerve","(D) facial nerve"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-33","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"下列何者不是常用來治療三叉神經痛的藥物？","options":["(A) tricyclic antidepressants","(B) anticonvulsants","(C) antispastic","(D) NSAIDs"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"關於肌筋膜疼痛障礙（myofascial pain and dysfunction），下列何者錯誤？","options":["(A) 主要和咬肌及顳肌痙攣有關，也可能影響翼內肌或其他咀嚼肌群","(B) 非功能性習慣（parafunctional habits）會加重其症狀，是造成關節急性閉鎖（closed-lock）的原因","(C) 治療方式包括咬合調整、配戴夜間護套、藥物治療、物理治療等","(D) 藥物治療不建議使用抗憂鬱劑"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-2-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"關於顱神經痛（cranial neuralgia）的敘述，下列何者錯誤？","options":["(A) 三叉神經痛最為常見，其誘發區（trigger zone）多位於第二及第三分支","(B) 為舌咽神經痛，其誘發區（trigger zone）位於口咽或舌根部","(C) 顏面神經痛可能的表徵為顳顎關節痛，因顏面神經感覺部分分布在顳部","(D) 迷走神經痛可能造成咽部深處的疼痛，甚至反射至下顎骨上升枝（ramus）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-36","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"關於唾液腺腫瘤的敘述，下列何者錯誤？","options":["(A) 最常見的唾液腺非惡性腫瘤是多形性腺瘤（pleomorphic adenoma）","(B) 發生率最高的唾液腺惡性腫瘤是adenoid cystic carcinoma","(C) 唾液腺adenoid cystic carcinoma之預後以solid type最差","(D) mucoepidermoid carcinoma發生在大唾液腺時，最常發生在腮腺"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-2-37","subject":"ya4","topic":"唾液腺疾病","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"下列何者不是謝格連氏症候群（Sjögren’s syndrome）的臨床常用檢查方式？","options":["(A) Schirmer test","(B) 小唾液腺切片","(C) 唾液腺攝影","(D) 主腺體細針抽吸"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"一位45歲男性來院求診，主訴吃飯時，偶有右側顎下區腫脹及疼痛的情形，但每次發作後大約 1小時，腫痛 便逐漸消退，已有半年之久，最近發生頻率增加，根據以上資料，你的初步診斷為何？你會採取那種處置步 驟？","options":["(A) 懷疑顎下腺管道阻塞，做插管引流","(B) 懷疑顎下區感染，照環口攝影（Panorex）","(C) 懷疑顎下腺腫瘤，做切片檢查","(D) 懷疑顎下腺結石，先照咬合片"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"Mucocele最易發生在下列那一唾液腺？","options":["(A) 顎下腺","(B) 腮腺","(C) 舌下腺","(D) 小唾液腺"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-40","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"在牙冠破損的情況中，一旦合併牙髓暴露，治療的目的就是保存在牙髓仍具健康的狀態，通常藉由覆髓 （pulp capping）來完成，下列何種狀態出現時，並不適合利用覆髓？","options":["(A) 牙髓暴露量極小","(B) 患者在受傷後數日才來就診","(C) 受外傷的影響之患齒，其牙根處無伴隨骨折","(D) 患齒牙根並沒有發生移位（displacement）或鬆動"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"關於開放性骨折（open fracture）的敘述，下列何者正確？","options":["(A) 骨折通過已萌出牙齒的牙周膜為開放性骨折","(B) 開放性復位手術處理的骨折為開放性骨折","(C) 開放性骨折旁的牙齒應拔除以避免感染","(D) 開放性骨折以開放性復位手術為優先選擇"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"關於成人髁狀突骨折（condylar fracture）的敘述，下列何者錯誤？","options":["(A) 大多導致咬合改變","(B) 上下顎間固定的目的並非骨折復位","(C) 骨折完全復位，才能回復原來咬合","(D) 骨折位移愈大，愈偏向使用開放式復位（open reduction）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"下列何種骨折，不會影響咬合？","options":["(A) 顴骨骨折（zygomatic fracture）","(B) 勒福三型骨折（Le Fort III fracture）","(C) 下顎髁狀突骨折（condylar fracture）","(D) 牙齒齒槽骨折（dento-alveolar fracture）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"最常見的中顏面骨折為顴骨複合體骨折（zygomatic complex fracture），其原因為何？","options":["(A) 骨骼結構較薄","(B) 骨骼結構較脆","(C) 骨骼解剖位置最靠顏面外側","(D) 骨骼解剖位置太近顳顎關節"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-2-45","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"下列有關唇腭裂修補手術之敘述，何者正確？","options":["(A) 通常進行腭裂修補手術時進行齒槽骨裂（alveolar cleft）骨移植","(B) 齒槽骨裂骨移植之骨材常為病人的髖骨（ilium）、顱骨 （cranium）或異質骨（allogeneic bone）","(C) 理想的齒槽骨裂（alveolar cleft）骨移植之時機為該位置之犬齒牙根完全形成時","(D) velopharyngeal flap手術成功後才可配戴prosthetic speech aid"],"answer":1,"clinical_level":"重點"},{"id":"ya4-109-2-46","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"關於唇腭裂發生的機率，下列敘述何者正確？","options":["(A) 一般來說，新生兒唇腭裂發生的機率是 7000分之一","(B) 若哥哥出現唇腭裂，接下來出生的弟弟得到的機會是 2～5%","(C) 若父母親其中一人是唇腭裂患者，生出具有唇腭裂的小孩機率高達七成","(D) 若是弟弟有唇腭裂，哥哥的小孩有唇腭裂的機率是五成"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-47","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"下列藥物何者屬於支氣管擴張（bronchodilator）類？","options":["(A) midazolam","(B) nitroglycerine","(C) chlorpheniramine","(D) metaproterenol"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-48","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"病患的用藥紀錄上有長期服用毛地黃（digoxin），最可能患有下列何種疾病？","options":["(A) 糖尿病（diabetes mellitus）","(B) 鬱血性心衰竭（congestive heart failure）","(C) 腎上腺的功能不足（adrenal insufficiency）","(D) 心肌梗塞（myocardial infarction）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"在進行口腔手術前時，病人聲稱肚子痛、呈現體温升高、心跳加快、煩躁、胡言亂語，可能發生的疾病？","options":["(A) 血糖過低（hypoglycemia）","(B) 心肌缺血或梗塞（mycardial ischemia or infarction）","(C) 甲狀腺風暴（thyroid storm）","(D) 血管迷走性暈厥（vasovagal syncope）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-50","subject":"ya4","topic":"全身性疾病與急症","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"在牙科門診中，病患若發生急性腎上腺皮質功能不足（acute adrenocortical insufficiency），應給予下列那些處 置？①讓病患平躺並使病患之腳高於頭部位置 ②注射類固醇 ③給予氧氣","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-2-51","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"病人接受耳前切線進行顳顎關節手術後，產生 Frey's syndrome，下列那一項是最不宜進行的治療方式？","options":["(A) 腮腺切除","(B) 局部使用副交感神經拮抗劑","(C) 皮下置入筋膜","(D) 繼續觀察"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-52","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"病人有顳顎關節問題，且喜歡嚼食口香糖及嚼食硬的食物，建議病人要改變飲食，先吃軟食，要多久才可以 漸漸恢復正常飲食？","options":["(A) 1週","(B) 2週","(C) 4週","(D) 6週"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"關於顳顎關節慢性復發性脫臼（chronic recurrent dislocation）的外科治療，下列何者錯誤？","options":["(A) 隆凸切除術（eminectomy）","(B) 外翼肌切斷術（lateral pterygoid myotomy）","(C) 關節囊皺襞術（capsule plication）","(D) 咬肌翼肌肌切斷術（masseter-pterygoid sling myotomy）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-54","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"病人需要進行口腔顎面外科手術時，手術相關準備事項，下列何者錯誤？","options":["(A) 手術前必須給予手術說明書","(B) 手術前必須給予手術同意書","(C) 手術前必須給予麻醉同意書","(D) 手術中使用自費醫療器材，手術後等病人清醒後，再給予自費同意書"],"answer":3,"clinical_level":"一般"},{"id":"ya4-109-2-55","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"如全口環狀X光片所示，下顎骨左側可以發現多房性（multilocular）放射線透光性病灶，並呈現有多顆牙齒之 牙根吸收，下列何者是較為可能之診斷？","options":["(A) 鈣化齒源囊腫（calcified odontogenic cyst）","(B) 含齒囊腫（dentigerous cyst）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 始基囊腫（primordial cyst）"],"answer":2,"image":"ya4-109-2-55.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-56","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"承上題，該病患的手掌以及腳掌都呈現有小窩狀凹陷，那麼他可能同時罹患下列那一個症狀？","options":["(A) 眼距過寬","(B) 鱗狀細胞上皮癌","(C) 歐伯來氏症候群","(D) 頭圍過小"],"answer":0,"clinical_level":"一般"},{"id":"ya4-109-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"下列那一項因素最不會影響X光束強度（beam intensity）？","options":["(A) X光管電流（tube current）","(B) X光管電壓（tube voltage）","(C) 瞄準管（aiming cylinder）厚度","(D) 曝光時間（exposure time）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"下列何者不是輻射劑量之偵測器（monitoring device）？","options":["(A) thermoluminescent dosimeter（TLD）","(B) personal electronic dosimeter（PED）","(C) light-emitting diode（LED）","(D) optically stimulated luminescence dosimeter（OSLD）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-109-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"目前牙科X光攝影使用的有線數位CCD（charge-coupled device）感應片，其接受到X光至傳送訊號至電腦的正 確流程依序為何？①電極（electrode） ②隔離層（insulating layer） ③N型矽片（N-type silicone） ④P型 矽片（P-type silicone） ⑤閃爍層（scintillation layer）","options":["(A) ①②③④⑤","(B) ⑤④③②①","(C) ⑤③④②①","(D) ②④③⑤①"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"使用口腔分角線攝影法時，當X光垂直入射角愈大，牙齒的影像將會如何改變？","options":["(A) 變長","(B) 變短","(C) 變寬","(D) 變窄"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"有關使用標籤（tab）方式之口腔咬翼放射線攝影法（bitewing radiography）的優缺點，下列敘述何者正確？","options":["(A) 咬翼X光片可以穩固地在病人口腔內，不會被舌頭推開","(B) 可重覆性高，所以可用來監測牙周狀況","(C) 容易應用在兒童上","(D) X光片邊緣不容易有影像缺失的情況"],"answer":2,"clinical_level":"重點"},{"id":"ya4-109-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"目前牙科X光機所建議採用之瞄準儀（collimator）為下列何者？","options":["(A) 長距圓筒型","(B) 短距圓筒型","(C) 長距長方型","(D) 短距長方型"],"answer":[0,2],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-109-2-63","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"關於牙科X光平行照射法優點之敘述，下列何者正確？","options":["(A) 影像比例不如以分角線法拍攝出來的好","(B) 顴骨（zygomatic bone）較不會遮蓋臼齒區的根尖部","(C) 不適合觀察牙周骨高度（periodontal bone level）","(D) 不需使用輔助設備（positioned-indicating device）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-64","subject":"ya4","topic":"口腔外科基礎","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"關於附圖中箭頭所指之解剖構造，下列敘述何者錯誤？","options":["(A) 是下顎骨舌側表面上的突起","(B) 是geniohyoid muscle附著之處","(C) 稱為mylohyoid ridge","(D) 稱為internal oblique ridge"],"answer":1,"image":"ya4-109-2-64.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-65","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"46歲女性因上顎左側犬齒牙根尖區域至鼻翼處腫脹來求診，經X光檢查如附圖1所示，犬齒牙髓活性測試有活 性反應，病患接受進一步影像檢查如附圖2，圖2影像之拍攝方式為下列何者？","options":["(A) 電腦斷層掃描（computerized tomography）","(B) 骨掃描（bone scan）","(C) 磁共振造影（magnetic resonance imaging）","(D) 超音波掃描（ultrasongraphy）"],"answer":0,"image":"ya4-109-2-65.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-66","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"15歲女孩因下顎前方有一個無疼痛的腫脹而來求診，經X光檢查如附圖所示，病變區切片後，病理診斷為齒 源性角化囊腫，則此病患最可能罹患下列何種疾病？","options":["(A) 艾迪森氏病（Addison’s disease）","(B) 天使症（cherubism）","(C) 麥克滾-阿爾布萊德氏症候群（McCune-Albright syndrome）","(D) 痣樣基底細胞癌症候群（nevoid basal cell carcinoma syndrome）"],"answer":3,"image":"ya4-109-2-66.jpeg","clinical_level":"重點"},{"id":"ya4-109-2-67","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"17歲男性在定期追蹤的X光檢查時，發現右下顎第一大臼齒下方有一放射線不透過性病變如附圖所示，經牙 髓活性檢測發現右下顎第一大臼齒無活性，此病變最可能的診斷為下列何者？","options":["(A) 造牙骨質細胞瘤（cementoblastoma）","(B) 硬化性骨炎（condensing osteitis）","(C) 牙骨質骨發育不良（cemento-osseous dysplasia）","(D) 病因不明性骨硬化（idiopathic osteosclerosis）"],"answer":1,"image":"ya4-109-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-68","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"70歲男性於一年前拔除下顎左側第一大臼齒，至今仍有疼痛，經X光檢查如附圖所示，此病患最有可能有下 列何種病變？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 萌牙囊腫（eruption cyst）","(C) 側位牙周囊腫（lateral periodontal cyst）","(D) 殘餘囊腫（residual cyst）"],"answer":3,"image":"ya4-109-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-69","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"下列何者可診斷為牙本質發育不良（dentin dysplasia）？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011253-x4m6.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011302-jaff.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011327-8ejn.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011336-qxod.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-109-2-70","subject":"ya4","topic":"放射影像診斷","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"下列那一唾液腺攝影圖像可以診斷為涎腺管炎（sialodochitis）？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-003752-8ibb.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-003800-oas4.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-003814-p99f.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-003832-sdlk.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-109-2-71","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"下列何者符合地中海型貧血（thalassemia）之影像學特徵？","options":["(A) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011412-vd33.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(B) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011419-0ina.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(C) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011425-5tv9.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">","(D) <img src=\"https://cdn.jsdelivr.net/gh/Victor19940313/2nd-dental-exam@main/notebook-images/try/20260518-011431-jzo6.png\" style=\"max-width:100%;display:block;margin-top:6px;border-radius:6px\">"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-109-2-72","subject":"ya4","topic":"放射影像診斷","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"下列關於齒頸部照蝕（cervical burnout）之敘述何者錯誤？","options":["(A) 為周界不明顯的X光透過性陰影（radiolucent shadow）","(B) 前牙的發生率比後牙高","(C) 在臨床診斷上，容易和齒頸部的齲齒混淆","(D) 形成的原因是牙釉質與齒槽骨的放射線不透過性（radiopaque）相對較高所造成"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-73","subject":"ya4","topic":"放射影像診斷","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"附圖中牙齒周邊的骨質喪失，最可能是下列何種疾病造成？","options":["(A) 造牙骨質細胞瘤（cementoblastoma）","(B) 蘭格罕氏細胞組織細胞增多症（Langerhans' cell histiocytosis）","(C) 骨化纖維瘤（ossifying fibroma）","(D) 柏哲德氏病（Paget' s disease）"],"answer":1,"image":"ya4-109-2-73.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-74","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"下列何種疾病最常造成如圖中洋蔥皮狀骨膜反應之影像？","options":["(A) 牙骨質骨發育不良（cemento-osseous dysplasia）","(B) 柏哲德氏病 （Paget's disease）","(C) 平伯氏腫瘤（Pindborg's tumor）","(D) 加勒氏骨髓炎（Garre's osteomyelitis）"],"answer":3,"image":"ya4-109-2-74.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-75","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"附圖中X光影像最符合下列何種疾病的病徵？","options":["(A) 牙本質形成不良（dentinogenesis imperfecta）","(B) 牙本質發育不良第一型（dentin dysplasia type I）","(C) 牙本質發育不良第二型（dentin dysplasia type II）","(D) 牙中牙（dens in dente）"],"answer":1,"image":"ya4-109-2-75.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-76","subject":"ya4","topic":"放射影像診斷","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"下列何者是史特吉-韋柏氏症候群（Sturge-Weber syndrome）側顱片（lateral cephalometric film）之可能發現？","options":["(A) 棉絮狀（cotton wool）鈣化","(B) 電車軌道狀（tramline）鈣化","(C) 毛玻璃狀（ground glass）鈣化","(D) 洋蔥皮狀（onion-skin）鈣化"],"answer":1,"clinical_level":"一般"},{"id":"ya4-109-2-77","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"CCD（charge-coupled device）與CMOS（complementary metal oxide semiconductors）的技術，主要在像素電荷 （pixel charges）上的差異為何？","options":["(A) 讀取方式","(B) 排列方式","(C) 大小","(D) 密度"],"answer":0,"clinical_level":"重點"},{"id":"ya4-109-2-78","subject":"ya4","topic":"放射線原理與技術","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"為避免輻射傷害，操作牙科放射線儀器人員或接受照射病患所使用的鉛衣（apron）防護至少要多少公釐 （mm）？","options":["(A) 0.1","(B) 0.15","(C) 0.2","(D) 0.25"],"answer":3,"clinical_level":"重點"},{"id":"ya4-109-2-79","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"35歲男性因下顎左側後方不適而來求診，經X光檢查如附圖所示，黑色長箭頭所指的病變，最可能為下列何 者？","options":["(A) 外傷性骨囊腫（traumatic bone cyst）","(B) 含齒囊腫（dentigerous cyst）","(C) 根尖囊腫（radicular cyst）","(D) 殘餘囊腫（residual cyst）"],"answer":1,"image":"ya4-109-2-79.jpeg","clinical_level":"一般"},{"id":"ya4-109-2-80","subject":"ya4","topic":"口腔病理基礎","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"承上題，附圖中此病患之下顎右側後方有一偶然發現如黑色短箭頭所指的放射線透過性（radiolucent）病變， 最可能為下列何者？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 殘餘囊腫（residual cyst）","(C) 單純性骨囊腫（simple bone cyst）","(D) 史塔尼凹陷（Stafne defect）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"對廣泛性焦慮（general anxiety）患者，牙科約診治療中及治療後需注意事項，下列何者正確？","options":["(A) 術後可能產生之不適副作用含糊告知，以免造成更焦慮","(B) 治療前或治療中言語安慰保證，堅定說一次就好，不要反覆說","(C) 與病人聊天分散其注意力","(D) 讓病人眼睛能看到手術要用的器械，以免產生未知的恐懼"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"手術前將稀釋之腎上腺素（epinephrine）皮下注射入欲下刀處，可造成血管收縮，減少傷口切開時的出血。打 入腎上腺素後，至少需等待幾分鐘，才建議開始將傷口切開？","options":["(A) 可立即切開","(B) 1分鐘","(C) 4分鐘","(D) 7分鐘"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"有關手術後產生的死腔（dead space），下列敘述何者錯誤？","options":["(A) 死腔是手術後縫合傷口後產生的","(B) 通常是手術中移除部分深層組織所造成的","(C) 可能是傷口縫合時，沒有將組織的各個層次適當的靠近對齊","(D) 死腔通常是充填著組織液而非血液"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-1-4","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"關於傷口癒合過程中纖維形成期（fibroplastic stage）的敘述，下列何者錯誤？","options":["(A) 此期傷口的痂皮（scab）下方的上皮細胞組織，由兩端向傷口中央移動","(B) 纖維母細胞（fibroblast）沿著纖維蛋白股（fibrin strand），由兩端向傷口中央移動","(C) 是組織受傷開始後，持續進行3到5天","(D) 是屬於傷口癒合的第2期"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-1-5","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"有關一級癒合（healing by primary intention），下列敘述何者錯誤？","options":["(A) 傷口的兩側邊緣是沒有任何組織喪失的","(B) 可以穩定的癒合，與受傷前相比，解剖位置相同","(C) 沒有任何的疤痕組織形成","(D) 在黃金時間內，撕裂傷的縫合宜採用一級癒合方式"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-1-6","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"下列何種藥物是 heparin 的拮抗劑？","options":["(A) digoxin","(B) ibuprofen","(C) protamine sulfate","(D) nitroglycerin"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"進行下齒槽神經的阻斷麻醉時，引起顏面神經麻痺，最常見的原因為何？","options":["(A) 麻醉劑過量","(B) 注入部位太高","(C) 注入部位太後","(D) 病人年紀較大"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"病人在接受局部麻醉後，產生局部口腔知覺麻痺超過 8 星期之久，最不可能發生的原因為何？","options":["(A) 麻醉藥物之毒性","(B) 神經被針頭直接穿刺","(C) 針頭穿刺後產生之血腫壓迫","(D) 手術前進行口腔消毒，消毒劑所引發"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-1-9","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"有關麻醉針的敘述，何者正確？","options":["(A) 確定 27 號針是否打入血管的倒抽成功率為 100 ％","(B) 27 號針內徑為 0.008 英吋","(C) 30 號針最適合用於下齒槽神經麻醉","(D) 針尖要進入黏膜時，黏膜要拉緊，針的斜面（bevel）要背向骨頭"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"關於孕婦拔牙的敘述，下列何者正確？","options":["(A) 第一孕期（first trimester）是拔牙的最佳時機","(B) 第三孕期（third trimester）均可拔牙","(C) 第二孕期（middle trimester）拔牙最不安全","(D) 非複雜性拔牙可以在第一孕期的後期執行"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"關於一個健康成人無感染之下顎第三大臼齒的拔除手術，下列何者並非必要處置？","options":["(A) 縫合前使用大量生理食鹽水沖洗傷口","(B) 術後使用抗生素","(C) 術前使用chlorhexidine漱口","(D) 術後使用適當止痛藥"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-12","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"縫合時進針的最佳角度為多少度？","options":["(A) 45度","(B) 60度","(C) 75度","(D) 90度"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-13","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"關於阻生齒的敘述，下列何者正確?","options":["(A) 拔除上顎阻生第三大臼齒時，可能會出現牙齒被推入顳下空間（infratemporal space）","(B) 正常情況下，約在10歲的時候才能在X光照片底下見到第三大臼齒的牙苞（tooth bud）","(C) 所有的阻生齒都需要拔除","(D) 最適合的阻生齒拔除年齡是30歲"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-14","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"下列何者是使用拔牙挺拔牙的基本力學原理？①wedge ②lever ③wheel-and-axle","options":["(A) 僅①","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-15","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"下列有關口腔外科基本器械的敘述，何者正確？","options":["(A) 骨銼（bone file）的使用必須避免拉（pulling）的方式，否則會造成骨磨光（burnishing）及壓碎","(B) 拔除下顎門牙可以用No.1, 150, 150A三支拔牙鉗","(C) 鉻腸線（chromic gut）為多股纖維（polyfilament）","(D) 彎針一般夾在近針尾的1/3距離處"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-1-16","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"病人主訴左下顎骨智齒區域腫痛已經超過半年，且臨床及影像學上皆無明顯變化，如圖所示，下列診斷何者 最適當？","options":["(A) 牙冠周炎（pericoronitis）","(B) 齒源性腫瘤（odontogenic tumor）","(C) 鱗狀細胞癌（squamous cell carcinoma）","(D) 化膿性肉芽腫（pyogenic granuloma）"],"answer":3,"image":"ya4-110-1-16.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"病人主訴其左臉頰有無痛性、具波動感的腫大，有時消失有時出現，已經有幾個月了，如圖示。下列敘述何 者錯誤？","options":["(A) 屬於顏面部感染蜂窩性組織炎階段","(B) 齒源性感染的機會最大","(C) 切開引流手術是必須的治療","(D) 要找出感染源"],"answer":0,"image":"ya4-110-1-17.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-18","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"下列那一個藥物最常引起顎骨壞死？","options":["(A) 類固醇","(B) Bleomycin","(C) 甲狀腺素（thyroxin）","(D) 雙磷酸鹽藥物（bisphosphonates）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-19","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"有關顏面顎骨區放射線性骨壞死（osteoradionecrosis）的敘述，下列何者錯誤？","options":["(A) 如果是單獨使用放射線來治療口腔癌，因為使用的放射線劑量較大，所以較手術後輔助放射線治療容易造 成","(B) 在X光片檢查時，放射線骨壞死區域都呈現骨頭被蠶食（moth-eaten bone）的外觀","(C) 臨床上放射線骨壞死的區域暴露後通常都會疼痛","(D) 根據學者Marx之報告，癌症病人在放射線治療後，為了防止放射線性骨壞死的發生，在拔牙前後可以接受 高壓氧治療"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-20","subject":"ya4","topic":"齒源性感染與藥物","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"有關streptococcus milleri （S.milleri）族群侵犯口腔時，如何產生臨床症狀之敘述，下列何者正確？","options":["(A) 在感染初期S. milleri先分泌出collagenase好讓細菌能沿著結締組織擴散","(B) 在擴散時期aerobic group分泌出來的代謝物能讓四周的環境變成anaerobic group生長的良好環境","(C) Anaerobic group分泌hyaluronidase將被侵犯的組織液化，並與其他已死的組織形成膿瘍","(D) 當膿瘍沿著軟組織擴散之後，在臨床上就稱之為蜂窩性組織炎"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-21","subject":"ya4","topic":"植牙外科","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"關於bone morphogenetic proteins（BMP）的使用，下列敘述何者正確？","options":["(A) BMP不可與allografts 共同使用來增加骨移植物的量","(B) 常用的BMP為BMP-7","(C) 可單獨置放於植體周圍空隙增加骨整合","(D) BMP的缺點是術後可能造成明顯的edema"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-22","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"關於前庭整形術（vestibuloplasty）的術式中，Kazanjian flap vestibuloplasty 與transpositional flap（lip-switch） vestibuloplasty的差異，下列敘述何者正確？","options":["(A) Kazanjian flap vestibuloplasty其前庭前緣為一級癒合（primary intention healing）","(B) transpositional flap（lip-switch）vestibuloplasty 會將下顎骨唇側的periosteum 縫至唇內側","(C) Kazanjian flap vestibuloplasty 會使用大腿外側的皮膚進行移植","(D) 兩者皆會使用皮膚移植，但是transpositional flap（lip-switch）vestibuloplasty 會將皮膚移植至下唇內側"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-23","subject":"ya4","topic":"植牙外科","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"下列何者為接受植牙之絕對禁忌症（absolute contraindication） ？","options":["(A) 懷孕病人","(B) 受控制之糖尿病病人","(C) 骨質疏鬆（osteoporosis）病人","(D) 急性病（acute illness）病人"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-24","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"有關骨化纖維瘤（ossifying fibroma）的敘述，下列何者錯誤？","options":["(A) 在X光片上的影像通常呈現well-demarcated mixed radiolucency/radiopacity with smooth and often sclerotic borders","(B) 通常認定為true neoplasm，好發年齡在30歲以後","(C) 好發於上顎前牙區","(D) 治療以手術切除為主"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-25","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"在口腔癌患者的手術治療過程中，常需考量患者是否合併medical co-morbidities，下列敘述何者錯誤？","options":["(A) 若考量患者手術後有呼吸道難以維持的疑慮，應在術前治療計劃納入氣管造口術，並充分向患者告知","(B) 預計術後需長期臥床的患者，需謹慎提防深層靜脈栓塞的風險","(C) 嚴重的酒精禁斷症候群（alcohol withdrawal）可能會併發譫妄甚至因心血管塌陷導致死亡","(D) 大多數的口腔手術傷口被視為污染性傷口，所以術前和術後72小時內絕對需要給予抗生素"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-26","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"關於unicystic ameloblastoma的敘述，下列何者錯誤？","options":["(A) 好發於年輕族群","(B) 好發於下顎骨，特別是前牙區","(C) 由於其X光特徵為unilocular radiolucency，需跟dentigerous cyst做鑑別診斷","(D) mural unicystic ameloblastoma的手術後復發率高於luminal unicystic ameloblastoma"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-27","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"王先生50歲，平日身體硬朗。因為左下舌頭持續三個月的疼痛，合併發音及吞嚥異常等症狀至醫院就診，臨 床檢查發現王先生於左側舌頭舌腹處有約5×3cm之糜爛性潰瘍。此時最適宜的處理為何？","options":["(A) 先給予類固醇塗抹即可","(B) 先給予抗生素治療，兩周後再回診，視情況再進行處理","(C) 儘快安排切片檢查","(D) 先安排吞嚥功能檢查"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-28","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"關於檢查與診斷口腔內病灶的敘述，下列何者正確 ？","options":["(A) 口腔內病灶從肉眼即可判斷，不需要詳細問診","(B) 口腔內病灶大多可以經由抽血診斷","(C) 各種口腔內病灶，最好在初次檢查時就做切片檢查，以免延誤病情","(D) 口腔內病灶有可能是全身性疾病的表徵之一"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-29","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"關於造袋術後施行剜出術（enucleation after marsupialization）用來治療巨大之顎骨囊腫的敘述，下列何者錯 誤？","options":["(A) 實施造袋術後，經過一個月，即可操作剜出術","(B) 最好是等到囊腫病灶離開下顎齒槽神經管後再實施剜出術","(C) 對於有嚴重心血管疾病的人是很好的適應症","(D) 含齒囊腫（dentigerous cyst）是很好的適應症"],"answer":0,"clinical_level":"重點"},{"id":"ya4-110-1-30","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"關於鈣化齒源性囊腫（calcifying odontogenic cyst）的敘述，下列何者正確？","options":["(A) 好發於下顎骨之病灶","(B) 又稱為Gorlin's cyst","(C) 通常不會伴隨有齒瘤（odontoma）的發生，但常伴隨有阻生齒發生","(D) 僅使用剜出術（enucleation）治療可以達到很好的治療效果"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-31","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"關於含齒囊腫（dentigerous cyst）病灶的敘述，下列何者錯誤？","options":["(A) 是顎骨囊腫病灶中發生率最高的","(B) 最常發生在下顎骨第三大臼齒處","(C) 第二常發生的位置是上顎犬齒","(D) 下顎小臼齒也常發生"],"answer":0,"clinical_level":"重點"},{"id":"ya4-110-1-32","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"有關齒源性角化囊腫，下列何種方法不適合用來做骨腔的處理，以降低復發率？","options":["(A) 周邊骨切骨術（peripheral ostectomy）","(B) 石碳酸（phenol）燒灼法","(C) 液態氮冷凍法","(D) 蒸餾水浸泡法"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"下列何者不是下顎發育不足（mandibular deficiency）的特徵？","options":["(A) 側面觀呈現下顏面三分之一的部分明顯的突出","(B) 唇頦皺摺（labiomental fold）比較明顯","(C) 常見是屬於Class II異常咬合（malocclusion）","(D) 側面觀呈現著下顏面三分之一的部分明顯的內縮"],"answer":0,"clinical_level":"重點"},{"id":"ya4-110-1-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"過去術前以X光片及2D電腦輔助預測正顎手術術後變化（facial esthetic change），常無法達到精確預測之結 果，下列何者不是主要原因？","options":["(A) 肌肉張力","(B) 皮膚厚度","(C) 軟組織反應差異性","(D) 骨密度之差異"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-35","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"評估一個人的顏面骨發育是否異常，可以利用X光片來衡量，下列何者不適合用於評估？","options":["(A) Panoramic X-ray","(B) Towne's view X-ray","(C) Lateral cephalometric X-ray","(D) Posteroanterior facial X-ray"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"關於口腔灼感症候群（burning mouth syndrome）的敘述，下列何者較不適當？","options":["(A) 病因尚不清楚，一般認為與疼痛調控（pain modulation）異常有關","(B) 舌頭為常見的患部，口腔黏膜乾燥及味覺改變是常見的症狀","(C) 好發於停經後女性，使用荷爾蒙替代療法可明顯改善","(D) 患者不治療也可能自行痊癒，初步可以抗痙攣藥（anticonvulsants）或抗憂鬱劑（antidepressants）來控制症 狀"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-1-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"叢發型頭痛（cluster headache）在發作時，其疼痛部位不包括下列那個區域？","options":["(A) 上顎後牙區","(B) 眼窩附近（around the eye）","(C) 顳部（temporal region）","(D) 下顎後牙區"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-1-38","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"使用診斷性麻醉測試（diagnostic anesthetic testing）來鑑別顏面疼痛的注意事項，下列何者錯誤？","options":["(A) 目的是確診神經痛是否有顯著的周邊持續性疼痛","(B) 注射需使用無血管收縮劑之溶液","(C) 依據表面麻醉、浸潤麻醉、阻斷麻醉的步驟逐步進行","(D) 僅需紀錄疼痛消失時使用的麻醉方式"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-39","subject":"ya4","topic":"唾液腺疾病","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"關於唾液腺的敘述，下列何者錯誤？","options":["(A) 腮腺分泌之唾液佔所有唾液量之25%","(B) 顎下腺主唾液腺切除後，唾液量減少最多","(C) 腮腺分泌液中鈣離子濃度最高","(D) 分泌液中黏性最高－舌下腺"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-40","subject":"ya4","topic":"唾液腺疾病","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"關於復發及持續性蝦蟆腫（ranula）的手術處置，下列何者正確？","options":["(A) 通常以經由口外法的術式，由顎下空間進入手術區","(B) 手術時通常會合併摘除病灶區的顎下腺","(C) 進行摘除腺體手術時，通常會結紮舌下動脈的分支","(D) 進行摘除腺體手術時，通常會合併摘除唾液腺管Wharton’s duct"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-41","subject":"ya4","topic":"唾液腺疾病","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"唾液腺結石容易發生在顎下腺，有關其原因的敘述，下列何者錯誤？","options":["(A) 所分泌唾液的鈣離子含量較高","(B) 所分泌唾液較呈酸性","(C) 分泌導管較長","(D) 導管的開口較窄"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"關於牙冠牙根斷裂，下列敘述何者最不合理？","options":["(A) 牙冠牙根斷裂後患齒的預後，需參考斷裂的位置，有無牙髓腔受影響等因素，評估其預後","(B) 臨床上X片的診斷牙冠牙根斷裂的患齒非常重要，所有牙冠牙根斷裂的患齒皆可由X光片判定裂線所在及程 度","(C) 牙冠牙根斷裂，若斷裂處最低處仍在牙齦之上，且無波及髓腔，其治療可以補綴復形等方式進行修復","(D) 若合併齒槽骨斷裂的牙冠牙根斷裂，雖患齒斷裂部分觸及於牙根底部，預後不佳，仍可以延遲拔牙，待齒槽 骨斷裂癒合後，再行拔除預後不佳的患齒"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"關於顎骨有牙區骨折開放性手術，下列手術步驟的順序何者正確？","options":["(A) 骨折復位，骨板固定，上下顎間固定","(B) 上下顎間固定，骨板固定，骨折復位","(C) 骨板固定，上下顎間固定，骨折復位","(D) 上下顎間固定，骨折復位，骨板固定"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"下列何者非骨折區感染的風險因子？","options":["(A) 迷你骨板固定","(B) 骨折區為污染傷口","(C) 粉碎性骨折（comminuted fracture）","(D) 有藥物濫用的病人"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"參考附圖，下列敘述何者最不合理？","options":["(A) A、B、C分別是鼻上顎，顴骨和翼上顎骨支柱（buttress）","(B) A、B、C主要是提供水平支持（horizontal support）的面部支柱（buttress）","(C) A、B、C三處是骨質較為厚實處","(D) 骨折或正顎手術患者，骨釘及骨板必須置放在A、B等位置以提供支持"],"answer":1,"image":"ya4-110-1-45.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-46","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"顏面外傷患者，要記錄生命徵象（vital sign）。所謂生命徵象，不包括下列何者？","options":["(A) 意識狀態是否清楚","(B) 脈搏速率","(C) 血壓高低","(D) 呼吸速率"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"唇裂病患手術條件中的〝rule of 10〞不包含下列何者？","options":["(A) 出生10週以上","(B) 血紅素10g／dL以上","(C) 體重10公斤以上","(D) 體重10磅以上"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"下列何種顎骨關係異常比較常見於唇腭裂患者？","options":["(A) Class II 咬合關係","(B) 上顎水平過剩（maxillary transverse excess）","(C) 下顎後縮（retrognathic mandible）","(D) 前牙錯咬（anterior crossbite）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-49","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"哈姆立克急救法（Heimlich maneuvers）適用下列何種呼吸道異物阻塞情況？","options":["(A) 嘔吐反射（gag reflex）正常，但呼吸道部分阻塞","(B) 呼吸道完全阻塞，但意識清醒","(C) 嘔吐反射（gag reflex）喪失，而且意識不清","(D) 呼吸道完全阻塞，而且意識不清"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-50","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"關於第二型糖尿病 （type II diabetes mellitus），下列何者正確？","options":["(A) 常發生於小孩及青少年","(B) 主要使用胰島素（insulin）治療","(C) 若手術前無法進食，可暫停使用一次胰島素（insulin）","(D) 避免手術中發生高血糖（hyperglycemia），防止發生危險"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-51","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"病人喪失味覺，通常是下列何種腦神經受損？","options":["(A) 僅IX","(B) 僅XII","(C) VII 和 IX","(D) IX 和 XII"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-52","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"病人在藥物注射後，發生過敏性休克（anaphylactic shock），下列處理方法中，何者錯誤？","options":["(A) 置病人於半躺姿勢（semi-reclined）","(B) 注射Epinephrine（0.3mL 1:1000）","(C) 供給氧氣（6 L/min）","(D) 必要時進行環甲切開術（cricothyrotomy）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-53","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"以斷層攝影術（tomography）檢查顳顎關節影像的敘述，下列何者錯誤？","options":["(A) 可以比環口放射線攝影術（panoramic radiography）看得更清楚","(B) 可以看到下顎骨髁頭在不同切面下的影像","(C) 通常提供下顎骨髁頭由上而下的切面影像","(D) 不能看到顳顎關節盤"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-54","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"一位病人坐輪椅來院求診，他表示近來漸漸表現出前牙開咬，張口疼痛的症狀，Ｘ光影像檢查發現下顎骨髁 頭似乎部分被吸收掉，垂直支高度減少，病人填寫初診紀錄時，握筆亦不方便，下列何者是最可能之診斷？","options":["(A) 肌筋膜疼痛及功能障礙","(B) 關節內紛亂","(C) 可復位之關節盤前異位","(D) 類風溼性關節炎"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"關於內紛亂（internal derangement）的敘述，下列何者錯誤？","options":["(A) 不可復位之關節盤異位（disc displacement without reduction）開口會偏移到患側","(B) 不可復位之關節盤前異位（anterior disc displacement without reduction）張口會受限，會有彈響聲（clicking sound）","(C) 傳統顳顎關節Ｘ光片（plain film）和電腦斷層中可復位之關節盤前異位（anterior disc displacement with reduction）和不可復位之關節盤前異位（anterior disc displacement without reduction）的影像都是相近","(D) 不可復位之關節盤異位（disc displacement without reduction）在MRI中關節盤在閉口位置常會位移到前內側 位置"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-56","subject":"ya4","topic":"口腔外科基礎","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"病人的病理報告證實為舌頭之鱗狀細胞癌，病人不想手術，想尋求偏方，這是何種醫學倫理原則的問題？","options":["(A) 公平原則","(B) 無傷原則","(C) 行善原則","(D) 自主原則"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"下列何種粒子（force-carrier particles）與X光束的形成有關？","options":["(A) gluon（g）","(B) photon（γ）","(C) W boson（W）","(D) Z boson（Z）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"下列何者為使用鋁濾片（aluminum filter）最主要的目的？","options":["(A) 移除低能量X光線光子（low-energy x-ray photons）","(B) 增強影像品質（image quality）","(C) 降低X光線光束強度（beam intensity）","(D) 提高影像對比（image contrast）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"下列何者為X光及珈碼射線的波長範圍？","options":["(A) 10 nm～0.01 pm","(B) 400 nm～10 nm","(C) 700 nm～400 nm","(D) 100 μm～700 nm"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-60","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"下列何者不易顯示在標準上顎正前方咬合片（standard upper anterior occlusal radiograph）的影像中？","options":["(A) 鼻淚管（naso-lacrimal canal）","(B) 鼻窩（nasal fossa）","(C) 鼻中隔（nasal septum）","(D) 翼板（pterygoid plate）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"在拍攝口腔咬翼片時，X光的垂直角（vertical angle）照射最理想的角度為幾度？","options":["(A) 負20～30","(B) 負5～10","(C) 正5～10","(D) 正20～30"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"根尖攝影時，採用下列那一種方法較無法拍出完整的下顎第三大臼齒？","options":["(A) 使用止血鉗夾住底片作為拍攝的輔助","(B) 拍攝兩張不同水平角度的根尖X光片","(C) 使用環口攝影法作為輔助","(D) 使用下顎咬合片法作為輔助"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"有關X光照射法及其使用的根尖X光片之敘述，下列何者正確？","options":["(A) 分角線法（bisecting technique）又稱作長錐筒照射技術（long cone technique）","(B) A speed的根尖X光片為快速X光片","(C) X光片上溴化銀結晶（crystals）顆粒較多表示為較快速X光片","(D) 平行法（paralleling technique）又稱作短錐筒照射技術（short cone technique）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-64","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"在電腦斷層影像中，白色箭號所指為下列何者？","options":["(A) 第一頸椎（first cervical vertebra）","(B) 舌骨（hyoid bone）","(C) 莖突（styloid process）","(D) 唾液腺結石（sialolithiases）"],"answer":2,"image":"ya4-110-1-64.jpeg","clinical_level":"重點"},{"id":"ya4-110-1-65","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"有關正常根尖片影像，下列敘述何者正確？","options":["(A) lamina dura之影像為白色的線緊貼於牙根","(B) lamina dura屬於牙根的構造","(C) periodontal ligament space之影像為黑色","(D) periodontal ligament space最窄處常在牙根尖"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-66","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"17歲男孩因上顎右側有一個無疼痛的腫脹而來求診，經X光檢查（如附圖）發現一個放射線不透過性影像如 箭頭所示之區域，根尖片可見到此病變與周圍界線不清楚，此病患最可能罹患下列何種疾病？","options":["(A) 家族性巨大畸形牙骨質瘤（familial gigantiform cementoma）","(B) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）","(C) 纖維性發育不良（fibrous dysplasia）","(D) 骨化纖維瘤（ossifying fibroma）"],"answer":2,"image":"ya4-110-1-66.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-67","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"45歲男性因下顎右側有一個無疼痛的腫脹而來求診，經影像檢查如附圖所示，右上小圖是左大圖虛線位置的 斷層圖，經切片後病理診斷為纖維骨性病變，結合影像的發現，此病患最可能罹患下列何種疾病？","options":["(A) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）","(B) 局部牙骨質骨發育不良（focal cemento-osseous dysplasia）","(C) 根尖周圍牙骨質骨發育不良（periapical cemento-osseous dysplasia）","(D) 骨化纖維瘤（ossifying fibroma）"],"answer":3,"image":"ya4-110-1-67.jpeg","clinical_level":"重點"},{"id":"ya4-110-1-68","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"65歲男性因缺牙要求植牙，口內無不適或異常，且無其他系統性疾病。X光檢查發現之左下顎單房性放射線 透過性影像，最可能為下列何者？","options":["(A) 動脈瘤性骨囊腫（aneurysmal bone cyst）","(B) 史塔尼氏囊腫（Stafne defect）","(C) 單純性骨囊腫（simple bone cyst）","(D) 原基性囊腫（primordial cyst）"],"answer":1,"image":"ya4-110-1-68.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-69","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"接受頭頸部放射線治療後病人容易產生齲齒，有關此類齲齒之敘述，何者錯誤？","options":["(A) 易造成牙冠嚴重缺損，最後只剩殘根的狀態","(B) 唾液腺受到輻射傷害，唾液減少，使得齲齒發生率高","(C) 常見發生於某些特定區域的牙齒","(D) X光影像的特徵為圍繞於齒頸部的radiolucent shadow"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-1-70","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"下列何者最適合使用後牙之咬翼片進行放射線攝影檢查？","options":["(A) 牙齒側根管","(B) 鄰接面齲齒嚴重程度","(C) 牙根數目","(D) 唾液腺結石"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-1-71","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"下列何者最不可能呈現多室型放射線透過性病灶（multilocular radiolucent lesion）？","options":["(A) 齒源性角化囊腫（odontogenic keratocyst）","(B) 造釉細胞瘤（ameloblastoma）","(C) 中心型巨細胞肉芽腫（central giant cell granuloma）","(D) 牙骨質骨發育不良（cemento-osseous dysplasia）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-1-72","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"下列何者為圖中X光影像之最適切診斷？","options":["(A) 慢性牙周炎（chronic periodontitis）","(B) 根尖囊腫（radicular cyst）","(C) 牙根外吸收（external root resorption）","(D) 牙骨質撕裂（cemental tear）"],"answer":1,"image":"ya4-110-1-72.jpeg","clinical_level":"重點"},{"id":"ya4-110-1-73","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"下列何者不是口腔數位影像拍攝與成像過程中常見的問題？","options":["(A) 影像缺失（loss of images）","(B) 雙重影像（double images）","(C) 影像變形（distorted images）","(D) 影像雜訊（noisy images）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-1-74","subject":"ya4","topic":"放射線原理與技術","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"為避免輻射傷害，操作牙科放射線儀器人員至少須距離輻射源或接受照射病患多遠？","options":["(A) 1公尺","(B) 1.5公尺","(C) 1英尺","(D) 1.5英尺"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-1-75","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"一名15歲男孩因下顎右側犬齒附近疼痛而來求診，經X光檢查如附圖所示，發現病患的上下顎骨密度不正 常，其最有可能罹患何疾病？","options":["(A) 變形性骨炎（osteitis deformans）","(B) 骨發生不全（osteogenesis imperfecta）","(C) 骨質石化症（osteopetrosis）","(D) 骨質疏鬆症（osteoporosis）"],"answer":2,"image":"ya4-110-1-75.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-76","subject":"ya4","topic":"齒源性感染與藥物","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"承上題，此病患之下顎右側犬齒附近疼痛區如附圖黑圈區域所示，下列何者為最可能之診斷？","options":["(A) 牙骨質骨化發育異常（cemento-osseous dysplasia）","(B) 慢性骨髓炎（chronic osteomyelitis）","(C) 纖維發育不良（fibrous dysplasia）","(D) 增殖性骨膜炎（proliferative periostitis）"],"answer":1,"image":"ya4-110-1-76.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-77","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"26歲男性因右臉腫脹而照了一張X光片如附圖，下列敘述何者錯誤？","options":["(A) 病灶的X光分類屬於多房性透過性影像（multilocular radiolucency）","(B) 病灶位於右下顎後牙及上升枝，如肥皂泡狀（soap bubble appearance）","(C) 右下顎第三大臼齒被移位","(D) 病灶區的internal oblique ridge及下顎骨板（cortical border）變薄且上下擴張"],"answer":3,"image":"ya4-110-1-77.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-78","subject":"ya4","topic":"口腔病理基礎","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"承上題，從其病灶中抽出一管黃色液體（如圖），下列診斷中何者最不可能？","options":["(A) 造釉細胞瘤（ameloblastoma ）","(B) 含齒囊腫（dentigerous cyst）","(C) 戈林氏囊腫（Gorlin's cyst）","(D) 齒源性黏液瘤（odontogenic myxoma）"],"answer":3,"image":"ya4-110-1-78.jpeg","clinical_level":"一般"},{"id":"ya4-110-1-79","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"圖示影像是以何種方法拍攝？","options":["(A) magnetic resonance imaging","(B) occlusal radiography","(C) panoramic radiography","(D) computed tomography"],"answer":3,"image":"ya4-110-1-79.jpeg","clinical_level":"重點"},{"id":"ya4-110-1-80","subject":"ya4","topic":"放射影像診斷","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"承上題，影像中下顎舌側之放射線不透過性病變，最可能的診斷為下列何者？","options":["(A) 涎石（sialoliths）","(B) 隆突（tori）","(C) 牙瘤（odontomae）","(D) 靜脈結石（phleboliths）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-1","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"慢性阻塞性肺臟疾病的病人接受口腔手術後，下列何者不是常見的併發症？","options":["(A) 肺炎","(B) 肺膨脹不全","(C) 血氧不足","(D) 血碳酸過少"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"關於傷口癒合過程中纖維形成期（fibroplastic stage），下列何者錯誤？","options":["(A) 此期傷口強度（wound strength）會迅速增加","(B) 通常會維持2到3星期","(C) 是屬於傷口癒合的第3期","(D) 在纖維形成期結束時，傷口的張力（tension）強度可達到未受傷組織的70％到80％"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"若下齒槽神經傷害造成axonal及endoneuron二者之連續性皆喪失，在神經傷害的分類上為：","options":["(A) neurapraxia","(B) axonotmesis","(C) neurotmesis","(D) paresthesia"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-4","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"在美國麻醉學會（ASA）的術前麻醉身體狀態的評估上，患者具有嚴重的全身性疾病（severe systemic disease），且經常對生命造成威脅，是屬於第幾級分級？","options":["(A) ASA III","(B) ASA IV","(C) ASA V","(D) ASA VI"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-5","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"施行下齒槽神經阻斷麻醉後，病人自述同側眼睛不能完全閉合，最可能原因為何？","options":["(A) 麻藥到達顏面神經（facial nerve）","(B) 麻藥到達動眼神經（oculomotor nerve）","(C) 麻藥到達視神經（optic nerve）","(D) 麻藥到達上顎神經（maxillary nerve）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"局部麻醉針頭斷裂，最不常見的因素為何？","options":["(A) 病人閃躲","(B) 使用短針頭","(C) 牙醫師事先將針頭彎曲","(D) 注射時用力過度"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"麻醉針最容易斷針的麻醉針型號與注射部位的組合，下列何者正確？","options":["(A) 30號短針與下齒槽神經","(B) 27號短針與下齒槽神經","(C) 27號長針與後上齒槽神經","(D) 30號短針與後上齒槽神經"],"answer":0,"clinical_level":"重點"},{"id":"ya4-110-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"拔除上顎第一大臼齒應阻斷下列那些神經？①posterior superior alveolar nerve ②middle superior alveolar nerve ③anterior superior alveolar nerve ④anterior palatine nerve ⑤nasopalatine nerve","options":["(A) ①②③","(B) ①②④","(C) ①②⑤","(D) ①③④"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-2-9","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"施行下顎阻斷麻醉時，最容易傷到那條肌肉而造成病患張口受限？","options":["(A) 內翼肌","(B) 外翼肌","(C) 咬肌","(D) 顳肌"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"關於拔牙後問題的敘述，下列何者正確？","options":["(A) 拔牙後可讓病人咬茶包30分鐘，其內含tannic acid為局部血管收縮劑","(B) 拔牙後冰敷可以有效消腫","(C) 拔牙後等麻藥退傷口開始感覺疼痛時是使用止痛藥的最佳時機","(D) 拔牙後顏面部瘀血（ecchymosis）會造成病人術後疼痛及感染"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"關於阻生齒拔牙後處置的說明，下列何者正確？","options":["(A) 冰敷不一定能預防術後腫脹，但病人大抵會覺得舒服","(B) 使用類固醇有許多副作用，不建議使用於預防拔牙術後腫脹","(C) 為預防拔牙術後感染，健康病人亦需使用抗生素","(D) 局部使用抗生素如四環黴素，並無證據顯示可以預防dry socket 發生"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"若要拔除牙齒殘根，不包括下列何者？","options":["(A) 良好的照明及清楚的術野","(B) 特殊的牙科診療椅","(C) 合適的器械","(D) 良好的止血"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"手術拔除下顎埋伏阻生齒，使用下列何種鑽頭可能會造成皮下氣腫？","options":["(A) 牙科慢速鑽頭","(B) 牙科高速鑽頭","(C) 手術電動鑽頭","(D) 手術氣動鑽頭"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-14","subject":"ya4","topic":"齒源性感染與藥物","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"病人因齒源性感染投予penicillin治療，3天後不見改善時，常使用下列何種較廣效的抗生素？","options":["(A) augmentin","(B) erythromycin","(C) metronidazole","(D) vancomycin"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"與下顎牙齒感染相關的deep fascial space為下列何者？","options":["(A) superficial temporal space","(B) infraorbital space","(C) maxillary sinuses","(D) cavernous sinus thrombosis"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"急診病患主訴4天前右下顎智齒區附近的牙周組織隱隱作痛，至昨天更形嚴重且張口困難，口腔檢查發現右下 顎智齒附近的牙周組織發炎，右側臉部外觀變得腫脹疼痛，且病人有中度到重度的牙關緊閉的症狀，推斷為 齒源性感染，其感染部位應在何處？","options":["(A) 顎下間隙（submandibular space）","(B) 舌下間隙（sublingual space）","(C) 頰肌間隙（buccal space）","(D) 咬肌下間隙（submasseteric space）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-17","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"25歲男性病人主訴下唇疼痛已有數天，如圖所示，下列何者是最可能造成的原因？","options":["(A) 燙傷","(B) 免疫力降低","(C) 藥物灼傷","(D) 梅毒感染"],"answer":1,"image":"ya4-110-2-17.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-18","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"75歲女病人有長期服用抗骨質疏鬆的藥物，抱怨拔牙後兩個月其左上顎牙齦區有潰爛性腫大，如下圖所示， 請問臨床上下列那一個臆斷的機率比較低？","options":["(A) 鱗狀細胞癌","(B) 上顎骨壞死","(C) 口腔鼻竇相通","(D) 惡性小唾液腺腫瘤"],"answer":3,"image":"ya4-110-2-18.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-19","subject":"ya4","topic":"植牙外科","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"利用骨牽引術增高齒槽骨，最適當的牽引速率為下列何者？","options":["(A) 每天拉開1 mm，一天二次","(B) 每天拉開1 mm，一天四次","(C) 每天拉開2 mm，一天二次","(D) 每天拉開2 mm，一天四次"],"answer":[0,1],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-110-2-20","subject":"ya4","topic":"口腔外科基礎","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"關於簡單齒槽骨成形術（simple alveoloplasty）的敘述，下列何者錯誤？","options":["(A) 若齒槽嵴（alveolar ridge）不平整的地方，可以先翻瓣將不平整的齒槽骨修整好，達到理想齒槽嵴的型態","(B) 齒槽骨修整時，先用骨鉗（rongeur）將大範圍的不平整去除，也可以用修骨頭的牙科磨針（dental bur）來 修平，最後再用骨銼（bone file）把所有不平整都修順，來達到牙槽嵴理想的型態","(C) 齒槽骨成形術過程中用生理食鹽水（normal saline）大量沖洗，以避免過熱造成骨頭壞死","(D) 下顎骨頭萎縮後，很容易形成刀緣式齒槽嵴（knife-edge ridge），修形時先從嵴骨（crestal bone）頰側1公分 切開翻瓣，翻開後用修骨器械把牙槽嵴修整，然後縫合"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-2-21","subject":"ya4","topic":"植牙外科","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"牙科植體離下齒槽神經（inferior alveolar nerve）至少要多少距離？","options":["(A) 0.3 mm","(B) 1 mm","(C) 2 mm","(D) 4 mm"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-22","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"同樣是口腔癌，但針對不同部位的病灶有時會有不同的考量。關於lip cancer的敘述，下列何者錯誤？","options":["(A) 通常較容易早期發現，而且致病原因有時跟口腔其他部位的癌症不同（如：陽光曝曬）","(B) 通常需要比較積極的做頸部淋巴廓清術，因為其發生頸部淋巴轉移的機率比其他部位的口腔癌更高","(C) 若早期發現並早期接受手術治療，其五年存活率的表現是好的","(D) 手術缺損的重建可以使用Abbé-Estlander皮瓣術"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-23","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"病灶在某個區域範圍內有顏色的改變，但表面沒有突出時，稱為下列何者？","options":["(A) 痂（crusts）","(B) 斑（macule）","(C) 鱗屑（scale）","(D) 菌斑（plaque）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-24","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"有關臨床篩檢輔助工具的敘述，下列何者錯誤？","options":["(A) 一般使用490～510奈米的光波照射組織，利用正常及非正常細胞對於光線的吸收、反射不同來鑑別異生或不 正常的細胞","(B) 因準確度高，可取代臨床檢查，特別是用於篩檢及術後追蹤","(C) ViziLite使用前需用1％醋酸漱口，以溶解口腔黏膜表面的醣蛋白，再以白光照射，肉眼可見差異","(D) VELscope使用螢光照射，正常組織顯示為淺綠色，異常組織顯示為深棕色或黑色"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-2-25","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"關於顎骨黏液瘤（myxoma）之敘述，下列何者錯誤？","options":["(A) 放射線影像常見腫瘤會將牙齒推開或牙根吸收","(B) 放射線影像呈現網球拍狀（tennis racket）","(C) 治療原則以手術為主","(D) 復發率低，手術採刮除術（curettage）即可"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-2-26","subject":"ya4","topic":"口腔外科基礎","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"上顎骨惡性腫瘤手術時，最常使用的切線稱為：","options":["(A) 唇頰切開法（Lip-cheek incision）","(B) 韋伯－弗格森切開法（Weber-Fergusson incision）","(C) 李士敦切開法（Risdon incision）","(D) 梯階切開法（Step incision）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-27","subject":"ya4","topic":"口腔外科基礎","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"施行造袋術（marsupialization）來治療顎骨囊腫的病變，下列何者為其缺點？","options":["(A) 囊腫復發率極高","(B) 傷口較大且病患腫痛較明顯","(C) 手術操作複雜且費時","(D) 無法取得整體組織進行病理學檢查"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"關於完全角化齒源性角化囊腫（orthokeratinized odontogenic keratocyst）的敘述，下列何者錯誤？","options":["(A) 與含齒囊腫（dentigerous cyst）相似，也都會有伴隨著未萌發齒","(B) 復發性不高","(C) 在X光片下，大多是呈現多房性（multilocular）的放射性透光病灶","(D) 剜出術（enucleation）加上刮除術（curettage）是很好的治療選擇"],"answer":2,"clinical_level":"重點(深度)"},{"id":"ya4-110-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"關於根尖囊腫（radicular cyst）的敘述，下列何者錯誤？","options":["(A) 是顎骨中最好發的囊腫病灶","(B) 主要是牙髓發炎感染後所引起之續發症","(C) 最好的治療是刮除術（curettage）","(D) 有時在根管治療後亦無法痊癒"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-2-30","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"齒源性角化囊腫的患者同時合併有肋骨分岐的症狀群時，發生下列何種癌症機率較高？","options":["(A) 鱗狀細胞癌","(B) 乳癌","(C) 基底細胞癌","(D) 子宮頸癌"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-2-31","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"下列何種疾病，最不可能出現多發性囊腫？","options":["(A) 鎖顱骨成骨不全（cleidocranial dysostosis）","(B) 戈林－高茲症候群（Gorlin-Goltz syndrome）","(C) 牙本質發育不良（dentin dysplasia）","(D) 牙釉質發育不全（enamel hypoplasia）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"對下顎骨發育不足（mandible deficiency），正顎手術最常施行之術式為何？","options":["(A) 口內雙側垂直下顎枝切開術（bilateral vertical ramus osteotomy，BVRO）","(B) 雙側矢向分裂骨切開術（bilateral sagittal split osteotomy，BSSO）","(C) 頦成形術（genioplasty）","(D) 勒福一型截骨術（Le Fort I osteotomy）"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"對於顎骨過度發育（excessive growth）的病例，正顎手術（orthognathic surgery）最適合開刀之時機為下列何 者？","options":["(A) 發育停止後","(B) 發育停止前","(C) 隨時都可","(D) 一定要在發育停止3～5年後"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"為降低 bilateral sagittal split osteotomy 發生不利骨折的情形，有關下顎阻生智齒之處置，下列敘述何者正確？","options":["(A) 至少是手術前6個月即拔除智齒","(B) 最好是術中拔","(C) 最好不要拔","(D) 最好術後6個月拔"],"answer":0,"clinical_level":"重點"},{"id":"ya4-110-2-35","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"下列何者是 ergots 用來治療偏頭痛的主要機轉？","options":["(A) 鎮靜作用","(B) 血管收縮作用","(C) 血管擴張作用","(D) 抑制前列腺素作用"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"關於顳顎關節盤之不可復位前移（anterior disc displacement without reduction）的敘述，下列何者錯誤？","options":["(A) 在 Wilkes 分類中屬於第3期","(B) 常見張口範圍變小","(C) 無法聽見彈響（click）","(D) 張口時，下巴會向正常側偏移"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-2-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"有關TMJ關節內紊亂（internal derangement）之敘述，下列何者錯誤？","options":["(A) Wilkes 分類中，第1期即有TMJ clicking sound","(B) 出現輾軋音（crepitus），在 Wilkes 分類中屬於late stage","(C) 電腦斷層是用以評估TMJ internal derangement的建議影像檢查","(D) 建議一開始宜採保守性（非手術性）治療"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"關於人體口腔主唾液腺管Stensen duct的敘述，下列何者錯誤？","options":["(A) 腺管長度約12公分，直徑約0.2至0.6公分，最狹窄處常伴隨著結石發生","(B) 為腮腺的主腺管，其路徑有時會出現副腮腺管協助唾液分泌物排出","(C) 經咬肌的表面及前緣處，腺管內彎穿過頰肌後進入口腔","(D) 開口位於上顎第一或第二大臼齒附近的頰黏膜處"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-39","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"對於黏液表皮樣瘤（mucoepidermoid carcinoma）的敘述，下列何者正確？","options":["(A) 為第二常見的唾液腺惡性腫瘤，平均發生年齡為65歲","(B) 佔所有主唾液腺腫瘤的70％，主要影響位置在顎下腺","(C) 佔所有小唾液腺腫瘤的20％，主要影響位置在腭側部位","(D) 組織病理分類為高度（high grade）的病灶，術後復發機率較低"],"answer":2,"clinical_level":"重點"},{"id":"ya4-110-2-40","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"55歲具糖尿病病史且有抽菸習慣的患者，因左側上顎第一大臼齒疼痛，患者於三週前在診所局部麻醉下接受 根管治療；來醫院求診主要的原因，是在其口腔內靠近左側後方硬腭區，近幾日出現直徑約一點五公分的疼 痛性潰瘍，口腔內照片如圖一所示，經手術切片後病理組織圖如圖二所示。綜合以上敘述，此疾病最可能的 診斷為下列何者？","options":["(A) 謝格連氏症（Sjögren's syndrome）","(B) 壞死性涎腺變生（necrotizing sialometaplasia）","(C) 鱗狀細胞癌","(D) 小唾液腺結石"],"answer":1,"image":"ya4-110-2-40.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"六歲兒童發生單側關節囊內髁頭骨折（intracapsular condylar fracture），下列處理何者最適當？","options":["(A) 休息數天後開始功能性治療（functional treatment）","(B) 閉合性處理（closed treatment），上下顎間固定1～2周","(C) 閉合性處理（closed treatment），上下顎間固定2～4周","(D) 開放性復位手術"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"下顎骨折，骨折線從第二大臼齒前方往下延伸並垂直於下顎下緣，下列敘述何者正確？","options":["(A) 是有利性骨折（favorable fracture），容易移位，傾向閉合性復位（closed reduction）","(B) 是有利性骨折，不易移位，傾向開放性復位（open reduction）","(C) 是不利性骨折（unfavorable fracture），容易移位，傾向開放性復位（open reduction）","(D) 是不利性骨折，不易移位，傾向閉合性復位（closed reduction）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"下列何種顏面顎骨外傷最可能會造成上呼吸道阻塞？","options":["(A) LeFort I骨折","(B) 兩側下顎骨髁頭骨折","(C) 兩側下顎骨骨體骨折","(D) LeFort II骨折"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-44","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"經過手術修補後，部分唇腭裂患者講話會有鼻音，可能是下列何種因素導致？","options":["(A) 咽帆閉鎖不全（velopharyngeal incompetence）","(B) 舌頭肥大（tongue hypertrophy）","(C) 前牙缺失","(D) 鼻中隔彎曲（nasal septum deviation）"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-45","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"一位2歲腭裂（cleft palate）患者計劃施行骨移植（bone graft）手術修補骨缺損，考量可取得之骨量及後遺 症，應選擇那種供給部位（donor site）較適當？","options":["(A) 肋骨（rib）","(B) 腸骨脊（iliac crest）","(C) 頭頂骨（calvarial bone）","(D) 脛骨近端（proximal tibia）"],"answer":[0,1,2,3],"clinical_level":"一般","explanation_pending":false},{"id":"ya4-110-2-46","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"病人若有心肌缺血或梗塞（myocardial ischemia or infarction）時，下列何者為可能呈現的症狀？","options":["(A) 胸部有沈重擠壓感覺","(B) 不適感源自胸骨的表面","(C) 不適感輻射至右肩和臂部","(D) 不適感輻射至右頸和下顎"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-47","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"下列那一種情況適用平躺姿勢及雙腳抬高？","options":["(A) 哮喘（asthma）","(B) 換氣過度症候群（hyperventilation）","(C) 慢性阻塞性肺病（chronic obstructive pulmonary disease）","(D) 血管迷走性暈厥（vasovagal syncope）"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-48","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"一位以躺姿正接受牙科治療的病患，突然自行起來呈坐姿，可見焦慮、呼吸急促、呼吸有雜音、呼吸困難及 心跳過速，其最可能發生的疾病為下列何項？","options":["(A) 缺血性心臟病（ischemic heart disease）","(B) 腦血管意外（cerebrovascular accident）","(C) 哮喘（asthma）","(D) 充血性心臟衰竭（congestive heart failure）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"腎功能衰竭（renal failure）病人需要接受口腔手術時，下列何者正確？","options":["(A) 動靜脈分路（atrioventricular shunt）為例行靜脈注射進針處","(B) 選擇性外科手術（elective surgery）最好安排在洗腎後第三天","(C) 嚴重腎功能衰竭病人可用非類固醇抗發炎藥物（nonsteroidal anti-inflammatory drugs）","(D) 注意發生繼發性副甲狀腺功能亢進症（secondary hyperparathyroidism）"],"answer":3,"clinical_level":"重點"},{"id":"ya4-110-2-50","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"關於肉毒桿菌毒素（botulinum toxin）敘述，何者錯誤？","options":["(A) 為一種神經毒（neurotoxin）","(B) 可以阻斷acetylcholine在神經肌肉交接處（neuromuscular junction）的釋放","(C) 為Clostridium botulinum細菌所產生","(D) 不需要常常施打，可以一勞永逸"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-51","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"關於髁切斷術的敘述，下列何者錯誤？","options":["(A) 不需要使用鋼絲和金屬骨釘固定","(B) 與垂直枝切斷術（vertical ramus osteotomy）相同，都需要中間植入物","(C) 最主要用以治療可復位或不可復位關節盤異位（disk displacement with or without reduction）","(D) 可用於治療顳顎關節退化性關節炎及半脫臼"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-52","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"關於顳顎關節全置換（total joint replacement），下列何者正確？","options":["(A) 術後需要張口練習，減少黏連的疤痕反應","(B) 術後髁頭仍有平移（translate）的運動","(C) 術後仍有前突（protrusive）的運動","(D) 術後仍有滑移（excursive）運動"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"低劑量抗憂鬱症藥物（如tricyclic），可以用於治療顳顎關節疾病，下列敘述何者錯誤？","options":["(A) 可以抑制疼痛傳導物質serotonin的再吸收","(B) 無法減緩夜間磨牙","(C) 睡前服用amitriptyline（Elavil）10～25mg，可以改善睡眠","(D) 可以減緩顳顎關節疼痛"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-54","subject":"ya4","topic":"局部與全身麻醉","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"關於牙醫門診手術及麻醉同意書的內容，下列何者正確？","options":["(A) 醫療機構應於病人簽具手術及麻醉同意書後兩個月內，施行手術，超過兩個月應重新簽具同意書，簽具手術 及麻醉同意書後病情發生變化者，亦同","(B) 醫療機構為病人施行手術後，如有再度為病人施行相同手術之必要者，則不需重新簽具同意書","(C) 簽具手術及麻醉同意書時，若病人不識字，得以按指印代替簽名，惟應有兩名見證人於指印旁簽名","(D) 病人接受局部或全身麻醉手術時，需簽具同意書，若麻醉方式為鎮靜術時，則不需簽具同意書"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-55","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"根據這張頭部X光片請選出正確的檢查名稱？","options":["(A) Towne view","(B) Water view","(C) submental vertex view","(D) oblique view"],"answer":2,"image":"ya4-110-2-55.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-56","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"承上題，請問這是屬於何種型式的骨折？","options":["(A) favorable fracture","(B) greenstick fracture","(C) compressive fracture","(D) comminuted fracture"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"造成牙科X光光束衰減（beam attenuation）的原因，不包括下列何者？","options":["(A) coherent scattering","(B) photoelectric absorption","(C) Compton scattering","(D) Curie scattering"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"下列有關放射線劑量當量（equivalent dose）之敘述何者錯誤？","options":["(A) SI unit為joules/kg","(B) 其單位名稱為格雷（Gray）","(C) 其與放射線種類有關","(D) 其為輻射吸收劑量乘上輻射加權因子"],"answer":1,"clinical_level":"重點"},{"id":"ya4-110-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"曝露量1倫琴（R，coulombs/kg）約等於多少air kerma（kinetic energy released in matter）？","options":["(A) 8.73 Gy","(B) 8.73 mGy","(C) 8.73 cGy","(D) 8.73 dGy"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-60","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"在拍攝口腔X光片時，會請病人將眼鏡取下，其最主要的原因為下列何者？","options":["(A) 避免出現不必要的影像而干擾判讀","(B) 考量病人的舒適度","(C) 預防在拍攝過程中產生意外","(D) 眼鏡可能在X光機拍攝進行中造成干擾"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-61","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"關於拍攝口腔根尖片的理想品質標準（ideal quality criteria），下列敘述何者錯誤？","options":["(A) 影像不要有錐切（cone-cutting）","(B) 根尖至少要有1～2 mm的骨頭結構","(C) 拍攝條件須一致，以利於比較前後次拍攝的影像","(D) 牙齒的鄰接面沒有重疊"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-62","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"最常用於第一線篩檢顳顎關節疾病的放射線攝影方法為下列何者？","options":["(A) 關節造影術（arthrography）","(B) 環口放射線攝影術（panoramic radiography）","(C) 電腦斷層攝影術（computerized tomography）","(D) 顳顎關節斷層攝影術（TMJ tomography）"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-63","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"下列何者較不屬於環口放射線攝影法（panoramic radiography）的適用範圍？","options":["(A) 6歲以下兒童","(B) 評估大範圍的顎骨病變","(C) 張口受限的病人","(D) 比較左右兩邊的顳顎關節"],"answer":0,"clinical_level":"一般"},{"id":"ya4-110-2-64","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"附圖中白色箭頭所指部位為下列何者之影像？","options":["(A) 鼻唇皺摺","(B) 下嘴唇","(C) 上嘴唇","(D) X光片刮痕"],"answer":2,"image":"ya4-110-2-64.jpeg","clinical_level":"重點"},{"id":"ya4-110-2-65","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"附圖根尖X光片中，白色箭頭所指為何種構造？","options":["(A) zygomatic process of the maxilla","(B) styloid process","(C) retained root fragment","(D) inferior border of maxillary sinus"],"answer":0,"image":"ya4-110-2-65.jpeg","clinical_level":"重點"},{"id":"ya4-110-2-66","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"附圖之X光影像中黑色長箭頭所指的病變，最有可能為下列何者？","options":["(A) 骨瘤（osteoma）","(B) 骨化纖維瘤（ossifying fibroma）","(C) 牙雙生（gemination of teeth）","(D) 骨性迷離瘤（osseous choristoma）"],"answer":2,"image":"ya4-110-2-66.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-67","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"56歲男性因缺牙來求診，經X光檢查如附圖所示，此病患最可能罹患下列何種疾病？","options":["(A) 鎖顱骨成骨不全（cleidocranial dysplasia）","(B) 外胚層發育異常 （ectodermal dysplasia）","(C) 牙骨質骨發育不良（cemento-osseous dysplasia）","(D) 浦茲-詹賀症候群（Peutz-Jeghers syndrome）"],"answer":0,"image":"ya4-110-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-68","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"關於osteomyelitis之影像學特徵，下列敘述何者錯誤？","options":["(A) 可能有moth-eaten appearance","(B) 可能出現sequestrum","(C) acute suppurative osteomyelitis：well-defined periphery with a loss of internal trabeculae","(D) Garré’ s osteomyelitis：radiopaque lines similar to onion skin"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-69","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"65歲男性因缺牙要求植牙，口內無不適或異常，且無其他系統性疾病。X光檢查如圖，下列敘述何者錯誤？","options":["(A) 左下顎有一單房性界限清晰之放射線透過性（radiolucent）病灶","(B) 左下顎神經管（mandibular canal）向上位移","(C) 建議他作cone beam CT檢查","(D) 可以建議他作切片檢查"],"answer":1,"image":"ya4-110-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-70","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"一位小女孩因左下顎腫脹來就診，其X光影像如圖，請問下列診斷何者最可能？","options":["(A) 成纖維性造釉細胞瘤（desmoplastic ameloblastoma）","(B) 造釉細胞纖維瘤（ameloblastic fibroma）","(C) 造釉細胞纖維齒瘤（ameloblastic fibro-odontoma）","(D) 含牙囊腫併有腐骨（dentigerous cyst with sequestrum ）"],"answer":2,"image":"ya4-110-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-71","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"附圖中X光影像所顯示的顎骨異常，下列敘述何者錯誤？","options":["(A) 短箭頭所指為osteophyte","(B) 長箭頭所指的構造，常稱為\" joint mouse\"","(C) 此一顳顎關節異常，又可稱為\" bifid condyle\"","(D) 此X光影像為sagittal tomogram of TMJ"],"answer":2,"image":"ya4-110-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-72","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"下列放射線影像何者較不易用來診斷coronoid hyperplasia？","options":["(A) panoramic radiography","(B) Waters' view radiography","(C) CBCT image","(D) PA-view cephalogram"],"answer":3,"clinical_level":"一般"},{"id":"ya4-110-2-73","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"附圖中箭頭所指病變之最可能診斷為何？","options":["(A) 伊格爾症候群（Eagle syndrome）","(B) 涎石（sialolith）","(C) 唾腺管囊腫（salivary duct cyst）","(D) 謝格連氏症候群（Sjogren's syndrome）"],"answer":3,"image":"ya4-110-2-73.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-74","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"下列何者為圖中左下第一大臼齒牙根尖病灶之最適切診斷？","options":["(A) 牙骨質骨發育不良（cemento-osseous dysplasia）","(B) 造牙骨質細胞瘤（cementoblastoma）","(C) 凝聚性骨炎（condensing osteitis）","(D) 骨化纖維瘤（ossifying fibroma）"],"answer":2,"image":"ya4-110-2-74.jpeg","clinical_level":"一般"},{"id":"ya4-110-2-75","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"下列何者為附圖圓圈中心點病變影像之最適切診斷？","options":["(A) 齲齒（dental caries）","(B) 咬耗（attrition）","(C) 磨耗（abrasion）","(D) 齒頸部照蝕（cervical burnout）"],"answer":0,"image":"ya4-110-2-75.jpeg","clinical_level":"重點"},{"id":"ya4-110-2-76","subject":"ya4","topic":"放射線原理與技術","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"標準版第三版Digital Imaging and Communications in Medicine（DICOM）的影像儲存採用下列那一種格式？","options":["(A) TIFF（tagged image file format）","(B) BMP（bitmap）","(C) JPEG（joint photographic experts group）","(D) PNG（portable network graphics）"],"answer":2,"clinical_level":"一般"},{"id":"ya4-110-2-77","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"因口腔周圍接受放射線治療造成的味覺喪失，其全部恢復期至少需時多久？","options":["(A) 1個月","(B) 2～4個月","(C) 6～9個月","(D) 一年以上"],"answer":1,"clinical_level":"一般"},{"id":"ya4-110-2-78","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"請依所附圖示影像，依序回答下列3題。 圖示影像是以何種方法拍攝？","options":["(A) magnetic resonance imaging","(B) occlusal radiography","(C) panoramic radiography","(D) cone beam computed tomography"],"answer":3,"image":"ya4-110-2-78.jpeg","clinical_level":"重點"},{"id":"ya4-110-2-79","subject":"ya4","topic":"放射影像診斷","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"附圖中黑色箭頭所指解剖位置為何？","options":["(A) 上顎腭側","(B) 上顎頰側","(C) 下顎舌側","(D) 下顎頰側"],"answer":0,"clinical_level":"重點"},{"id":"ya4-110-2-80","subject":"ya4","topic":"口腔病理基礎","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"附圖中黑色箭頭所指病變最可能的診斷為下列何者？","options":["(A) 牙瘤（odontoma）","(B) 下顎外生贅骨（mandibular exostoses）","(C) 腭隆凸（palatinus torus）","(D) 造牙骨質細胞瘤（cementoblastoma）"],"answer":2,"clinical_level":"重點"},{"id":"ya4-111-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"對廣泛性焦慮（general anxiety）患者，牙科約診治療前需注意事項，下列何者錯誤？","options":["(A) 必要時前一晚上給予安眠藥物","(B) 必要時當天早上給予鎮靜藥物","(C) 牙科治療儘量約診在早上","(D) 在候診室等待應有足夠時間，以做好心理準備。"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"下列口腔部位，何者在口腔手術後較不會產生水腫（edema）情形？","options":["(A) 附連牙齦","(B) 下唇","(C) 口腔底部","(D) 頰黏膜"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-3","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"車禍外傷的病人，出現呼吸淺而快，最常見的原因為下列何者？","options":["(A) 血管迷走性暈厥","(B) 藥物過敏引發暈厥","(C) 代謝症候群","(D) 神經原性休克"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-4","subject":"ya4","topic":"口腔外科基礎","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"顎骨傷口的癒合，造骨細胞（osteoblast）扮演重要角色，它可能源自？ ①periosteum ②endosteum ③circulating pluripotential mesenchymal cells","options":["(A) 僅①③","(B) 僅②③","(C) 僅①②","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-5","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"正常口腔菌叢中，以何菌種為主？","options":["(A) Aerobic，G（+）cocci","(B) Aerobic，G（-）cocci","(C) Aerobic，G（+）rod","(D) Aerobic，G（-）rod"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-6","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"關於腺樣囊狀癌（adenoid cystic carcinoma）的敘述，下列何者正確？","options":["(A) 為最常見的唾液腺惡性腫瘤，平均發生年齡為 40 歲","(B) 通常腫瘤生長緩慢，表徵為慢性鈍痛及無潰瘍性的腫塊","(C) 發生在小唾液腺的比率為 20％，主要影響位置在下唇","(D) 發生在腮腺的病灶，主要會侵犯到病患的三叉神經"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-7","subject":"ya4","topic":"唾液腺疾病","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"關於蝦蟆腫（ranula）的敘述，下列何者錯誤？","options":["(A) 造袋術對於早期病灶是適當的治療方式","(B) 可分為簡單型（simple ranula）與穿入型（plunging ranula）","(C) 最常發生於顎下腺","(D) 屬於假性囊腫"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-8","subject":"ya4","topic":"口腔病理基礎","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"有關瓦新氏腫瘤（Warthin's tumor）之敘述，下列何者正確？","options":["(A) 最常出現在顎下腺","(B) 較常出現在女性","(C) 和抽菸與否無關","(D) 腫瘤源自於唾液腺導管細胞"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-9","subject":"ya4","topic":"唾液腺疾病","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"18 歲男性患者雙側腮腺同時腫大，已三天，體溫 39℃，下列何診斷最有可能？","options":["(A) 腮腺結石（sialolithiasis）","(B) 細菌性腮腺炎（bacterial parotitis）","(C) 病毒性腮腺炎（mumps）","(D) 謝格連氏症候群（Sjögren's syndrome）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-10","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"顴骨（zygoma）骨折二周後，開口仍然只有 25 mm（上下門牙距），其最主要的原因為下列何者？","options":["(A) 骨折壓迫三叉神經","(B) 骨折壓迫髁狀突（condylar process）","(C) 骨折壓迫冠狀突（coronoid process）","(D) 骨折壓迫顳顎關節"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-11","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"關於顎骨骨折開放式復位（open reduction）與剛硬固定（rigid fixation）的敘述，下列何者正確？","options":["(A) 術後上下顎間需固定 4～6 周","(B) 早期功能性施力會造成固定鬆脫","(C) 可觀察到骨塊間有活動度（mobility）","(D) 產生骨痂（callus）量最少"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-12","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"根據力學分析理論，下顎骨骨折的固定，下列何者正確？","options":["(A) 骨聯合處（symphysis）受力為彎曲力（bending force），固定裝置應盡量放置於骨折下緣","(B) 骨聯合處（symphysis）受力為彎曲力（bending force），固定裝置應盡量放置於骨折上緣","(C) 骨聯合處（symphysis）受力為扭力（torsional force），固定裝置應盡量放置於骨折上緣及下緣","(D) 骨聯合處（symphysis）受力為扭力（torsional force），固定裝置應放置於骨折上下緣間的中間位置"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-13","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"一般顏面骨折的處理，會等待生命徵象及生命威脅狀況穩定後才進行。下列那一種情況，最可能需要較為立 即性的處理？","options":["(A) 單純下顎正中聯合區的單一骨折，無軟組織相通，因傷勢單純，要優先處理","(B) 單純右側顴骨骨折，因為影響外觀及妨礙咬合，要優先處理","(C) 下顎骨雙側骨折，合併嚴重下顎後縮，舌體後傾，影響呼吸道，要優先處理","(D) 右側上顎勒福一式（Le Fort I）骨折，造成咬合不正，妨害咀嚼，要優先處理"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-14","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"在急診室看見病人的臨床情況如附圖所示，針對眼睛部位出現的徵狀，下列敘述何者最不合理？","options":["(A) 可能顯示顱骨方面的骨折，特別是耳後如果合併有 Battle's sign","(B) 可能顯示為鼻骨眼眶及篩骨複合體（naso-orbital-ethmoid（NOE）complex）的骨折，若是 NOE，其兩眼眼眥間 距因受傷變寬的機會較變窄為高","(C) 最立即需要處理的方式是直接照會眼科，確定眼睛裏面沒有再出血而確保視力穩定","(D) 應該特別針對與眼球運動與視力相關的腦神經（cranial nerve）仔細評估，並記錄於病歷上，以利評估追蹤變 化"],"answer":2,"image":"ya4-111-1-14.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-15","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"關於咽帆閉鎖不全（velopharyngeal incompetence，VPI），下列敘述何者錯誤？","options":["(A) 主要負責咽帆閉合的肌肉是提腭肌（levator palatini muscle）","(B) 未完整修復肌群容易導致 VPI","(C) 咽瓣（pharyngeal flap）手術是治療 VPI 的標準手術","(D) 手術治療 VPI 後通常會增加呼吸道空間"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-16","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"雙側唇腭裂患者需要接受大量骨移植修補缺損，下列何者是自體骨的最佳來源？","options":["(A) 下顎骨（mandible）","(B) 肋骨（rib）","(C) 腸骨（ilium）","(D) 脛骨（tibia）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-17","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"麻醉時出現 malignant hyperthermia，下列何者是最常見的初期症狀？","options":["(A) 體溫升高","(B) 發汗","(C) 心跳加速","(D) 發紺"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-18","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"病人在藥物注射後，發生第一型過敏症狀，呈哮喘（wheezing）及輕度呼吸困難（mild dyspnea），下列處理方 法中，何者錯誤？","options":["(A) 將病人置於坐的體位","(B) 注射 Medihaler-Epi（0.3 mg）","(C) 供給氧氣（6 L／min）","(D) 注射 Epinephrine（0.3 mL 1：1,000）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-19","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"糖尿病引發的低血糖（hypoglycemia）導致意識改變時，下列緊急處理何者正確？","options":["(A) 飲用高熱量碳水化合物，如含糖飲料","(B) 口服 1mg 昇糖素（glucagon）","(C) 靜脈給予 5％葡萄糖注射液（dextrose）1 安瓿（ampule）","(D) 皮下注射 0.5 mL 的 1：1,000 epinephrine"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-20","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"若病人在治療過程中因過度緊張而昏厥，下列何種處理方式正確？","options":["(A) 立即給予抗焦慮藥，並監測病人的生命徵象","(B) 若病人換氣過度（hyperventilation），可以阿摩尼亞（ammonia）刺激病人","(C) 讓病人躺平，腳高頭低，並給予氧氣，下次治療時先服用抗焦慮藥","(D) 應立即舌下注射 1：1,000 之 0.3 mg 腎上腺素"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-21","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"治療初期顳顎關節疾病，通常會給予止痛劑，建議給藥最長不超過多久？","options":["(A) 7 天","(B) 14 天","(C) 21 天","(D) 28 天"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-22","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"關於內紛亂（internal derangement）在顳顎關節影像的敘述，下列何者錯誤？","options":["(A) 可復位之關節盤前異位（anterior disk displacement with reduction）磁共振（MRI）影像，通常在閉口時可顯示 出關節盤位移","(B) 可復位之關節盤前異位（anterior disk displacement with reduction）磁共振（MRI）影像，通常在張口位置時， 關節盤的 intermediate zone 會在髁頭以及關節隆突（articular eminence）之間","(C) 不可復位之關節盤異位（disk displacement without reduction）在傳統的顳顎關節 X 光片（plain film）的表現與 可復位之關節盤異位（disk displacement with reduction）不同","(D) 不可復位之關節盤異位（disk displacement without reduction）在磁共振（MRI）影像閉口位置，與 Wilkes Stage I and II 相同，關節盤都是在前移位置"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-23","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"根據 Wilkes 對顳顎關節內部紛亂（internal derangement）之分類，早／中期（early／intermediate stage）之臨床症 狀為何？","options":["(A) 開口初期彈響（early-opening clicking），無疼痛或關節運動受限","(B) 偶爾疼痛，開口至中、晚期響亮彈響（mid and late-opening loud clicking），短暫閉鎖（locking）","(C) 多次疼痛，關節閉鎖（locking），運動受限，功能困難","(D) 持續疼痛，輾軋音（crepitus），摩擦音（grating），慢性運動受限，功能困難"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"當國民健康署在推動口腔癌篩檢等醫療政策時，目的是早期發現、早期治療，但醫師因為種種理由沒有這樣 做，結果這位病人在日後被診斷出晚期癌症，當然這樣的醫療行為不會引起什麼法律訴訟或行政裁罰，但這 位醫師違反了醫學倫理的什麼原則？","options":["(A) 自律（discipline）、不歧視（nondiscrimination）","(B) 公平（justice）、自主（autonomy）","(C) 不傷害（nonmaleficence）、行善（beneficence）","(D) 公平（justice）、保密原則"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-25","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"一般 2％ lidocaine（含 1: 100,000 epinephrine）溶液的 pH 值是多少？","options":["(A) 3.5","(B) 7.0","(C) 7.5","(D) 8"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-26","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"依據美國牙醫學會的顏色標籤規範，圖示的紅色環帶代表麻醉藥的主要成分是下列何者？","options":["(A) lidocaine HCl 2％合併腎上腺素 1：100,000","(B) mepivacaine HCl 3％","(C) articaine HCl 4％合併腎上腺素 1：100,000","(D) prilocaine HCl 4％"],"answer":0,"image":"ya4-111-1-26.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-27","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"當局部麻醉劑單獨使用時（無血管收縮劑），下列何種藥物特性決定其臨床麻醉效果（時間及強度）？","options":["(A) 效價（potency）","(B) 血管活性（vasoactivity）","(C) pKa","(D) 親脂能力（lipophilic activity）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-28","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"使用拔牙鉗（forceps）拔牙時，對於下列何種牙齒不建議有旋轉動作（rotation）？","options":["(A) 上顎門齒","(B) 下顎門齒","(C) 上顎小臼齒","(D) 下顎小臼齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-29","subject":"ya4","topic":"口腔外科基礎","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"下列有關 figure-of-eight suture 的敘述何者正確？","options":["(A) 一種以美容為主要需求的縫合方法","(B) 必須使用可吸收的縫線","(C) 可以協助減少術後流血","(D) 必須延長拆線時間"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-30","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"一位 70 公斤的成年人接受拔牙治療，若使用 mepivacaine 3％（無血管收縮劑）做為局部麻醉藥物，最多可注 射幾管（每管 1.8mL）？","options":["(A) 2 管","(B) 4 管","(C) 6 管","(D) 8 管"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-31","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"Pell 及 Gregory 下顎第三大臼齒阻生分類 class A、B、C 是依下列何者為分類基準？","options":["(A) 下顎骨上升枝前緣","(B) 齒槽骨水平高度","(C) 咬合平面位置","(D) 前牙牙根尖最低點之水平線"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-32","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"拔除下顎有兩個牙根以上之遠心傾斜的阻生齒，下列何種齒切除術比較適當？","options":["(A) 先將後側牙冠部分切除","(B) 先將前側牙冠部分切除","(C) 先將牙冠橫切斷","(D) 先將牙齒前後對半切斷"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-33","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"使用類固醇來減少阻生齒拔除後的腫脹時，下列何者是合理的給藥方式？","options":["(A) 術前口服 dexamethasone 1 mg，術後不繼續使用","(B) 術前口服 dexamethasone 8 mg，術後靜脈注射 dexamethasone 1 mg（每日 2 次，持續 2 至 3 日）","(C) 術前靜脈注射 dexamethasone 8 mg，術後口服 dexamethasone 1 mg（每日 2 次，持續 2 至 3 日）","(D) 術後口服 dexamethasone 8 mg（每日 2 次，持續 2 至 3 日）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-34","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"26 歲女子右下臉部腫大已有五天之久（如下圖所示），如果此區域發炎會擴散，下列那一個筋膜間隙受影響 時，可能會有生命危險？","options":["(A) buccal space","(B) lateral pharyngeal space","(C) submandibular space","(D) sublingual space"],"answer":1,"image":"ya4-111-1-34.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-35","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"引起齒源性感染之兼性（facultative）厭氧菌中，下列何者最為少見？","options":["(A) peptostreptococcus species","(B) prevotella species","(C) fusobacterium species","(D) neisseria species"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-36","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"病人疑似罹患下顎骨骨髓炎，且有腎功能障礙，下列何項檢查可以偵測到早期骨髓炎之骨質變化？","options":["(A) 環口 X 光片攝影","(B) 電腦斷層攝影","(C) 磁共振造影","(D) 下顎骨咬合片"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-37","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"治療齒源性感染之最主要原則是：","options":["(A) 控制發燒","(B) 維持正常進食","(C) 投與類固醇","(D) 去除感染源及施行適當之引流"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-38","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"50 歲女性糖尿病患根尖感染，但對盤尼西林過敏，拔牙手術後何種抗生素為首選？","options":["(A) erythromycin","(B) clindamycin","(C) tetracycline","(D) metronidazole"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-39","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"使用 panoramic view 攝影片來評估可植牙之骨骼高度時，應注意此片子在部分區域最大的放大率可達多少？","options":["(A) 9％","(B) 19％","(C) 29％","(D) 39％"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-40","subject":"ya4","topic":"口腔病理基礎","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"關於前庭區腫裂齦瘤（epulis fissuratum）的敘述，下列何者錯誤？","options":["(A) 如果增生的軟組織較初期時，可以把假牙過度接觸的地方修掉，用軟底墊（soft liner）治療， 增生的軟組織 會自行消除","(B) 大量的發炎性纖維組織，可切除後並做繼生上皮形成（secondary epithelialization），因為初級閉合（primary closure）可能導致前庭（vestibule）消失","(C) 手術後戴上暫時性的假牙或手術固定裝置（splint）持續 5～7 天","(D) 只發生在全口無牙的病人"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-41","subject":"ya4","topic":"口腔外科基礎","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"Lip switch 手術不適合應用於下列何者？","options":["(A) 無牙嵴之下顎骨有 16 mm 之高度","(B) 舌側前庭過淺","(C) 舌側前庭深度足夠","(D) 唇側前庭過淺"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-42","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"有關口腔癌放射線治療的敘述，下列何者正確？","options":["(A) T1 病灶對於放射線治療有反應比率約為 60％","(B) T4 病灶對於放射線治療有反應比率約為 20％","(C) 放射線治療前施行牙科處置，產生放射線骨壞死的機率較低","(D) 放射線治療後，如需拔牙，拔牙後做高壓氧治療，比拔牙前做更能有效預防放射線骨壞死"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-43","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"有一左側舌緣口腔癌患者，系統性檢查可發現在磁共振影像上腫瘤大小為 2.5×1.3×2.8 cm，而頸部可以發現左 頸部有 3 顆小於 15 mm 的淋巴結及一顆大於 20 mm 且可見到明顯中央壞死（central necrosis）的淋巴結，右頸 部有數顆小於 12 mm 的淋巴結，胸部 X 光，腹部超音波，及全身骨骼掃瞄並未發現有其他的轉移性病灶。請 依據上述資料及 AJCC 第 8 版（2017）依序回答下列 4 題。 患者的臨床診斷 primary tumor（T）為下列何者？","options":["(A) T1","(B) T2","(C) T3","(D) T4"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-44","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"患者的頸部淋巴結節（cervical lymph node）（N）為下列何者？","options":["(A) N0","(B) N1","(C) N2","(D) N3"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-45","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"患者的遠端轉移（distant metastasis）（M）為下列何者？","options":["(A) Mx","(B) M0","(C) M1","(D) M2"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-46","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"患者的臨床分期（clinic staging）為下列何者？","options":["(A) stage I","(B) stage II","(C) stage III","(D) stage IV"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-47","subject":"ya4","topic":"口腔外科基礎","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"下列何者為顎骨囊腫剜出術（enucleation）的適應症（indication）？","options":["(A) 該囊腫貼近下顎齒槽神經管","(B) 囊腫與鼻竇相連","(C) 可能有病理性骨折之懷疑","(D) 懷疑有囊腫壁之病變"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-48","subject":"ya4","topic":"口腔病理基礎","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"下列何種囊腫是屬於發育性囊腫（developmental cyst）？ ①齒源性角化囊腫（odontogenic keratocyst） ②含齒囊腫（dentigerous cyst） ③鼻腭管囊腫（nasopalatine duct cyst）","options":["(A) 僅①","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-49","subject":"ya4","topic":"口腔病理基礎","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"關於根尖囊腫（radicular cyst）的敘述，下列何者錯誤？","options":["(A) 好發於齲齒或受傷的牙齒","(B) 經由根尖 X 光片的放射線透過性檢查，可分辨為根尖囊腫或肉芽腫","(C) 為最常見的顎骨囊腫","(D) 通常可經由剜出術（enucleation）移除"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-50","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"男性病人環口 X 光顯示下顎第三大臼齒近心角阻生（mesioangular impaction），其連結有一多房性放射透過性 病變（multilocular radiolucency）並侵犯骨體及骨角，同側第二大臼齒牙根尖有吸收，下列何診斷最有可能？","options":["(A) 根尖囊腫（radicular cyst）","(B) 含牙囊腫（dentigerous cyst）","(C) 齒瘤（odontoma）","(D) 造釉細胞瘤（ameloblastoma）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-51","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"嚴重中臉部畸形（midface deformities）合併眶下緣及顴骨發育不足（infraorbital rim and malar eminence deficiency），此時較適合之矯正術式為下列何者？","options":["(A) 勒福一型截骨術（Le Fort I osteotomy）","(B) 勒福二型截骨術（Le Fort II osteotomy）","(C) 勒福三型截骨術（Le Fort III osteotomy）","(D) 上顎前段截骨術（upper anterior segmental osteotomy）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-52","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"關於施行矢向分裂骨切開術（sagittal split osteotomy）的敘述，下列何者錯誤？","options":["(A) 在高下顎平面角（high mandibular plane angle）之病患，遠心端若產生順時針旋轉，則容易復發","(B) 施行矢向分裂骨切開術（sagittal split osteotomy）後，下齒槽神經應位骨切開後之遠心端骨片","(C) 手術前若要拔除第三大臼齒，建議至少 6 個月以上，以避免發生不理想之分裂","(D) 經由之軟組織切口一般是在口內由下顎枝前緣至後牙齒槽之頰側"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-53","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"一般而言正常的顏面輪廓（facial profile），上：中：下顏面的比值正常應為多少？","options":["(A) 1.5：1：1","(B) 1：1.5：1","(C) 1：1：1.5","(D) 1：1：1"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"關於 glossopharyngeal neuralgia 的敘述，下列何者錯誤？","options":["(A) 是除了三叉神經痛之外，最常見的顱神經痛","(B) 其疼痛表現的模式為吞嚥時產生尖銳電擊樣疼痛","(C) 其疼痛的引發區（trigger zone）通常位於口咽部及舌根部","(D) 不會造成下顎區域的投射痛（referred pain）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"關於口腔顏面疼痛（orofacial pain）的敘述，下列何者錯誤？","options":["(A) 肌筋膜疼痛（myofascial pain）造成的肌肉疼痛、張口受限是患者就診的主因","(B) 叢發性頭痛（cluster headache）常會造成上顎後牙區的疼痛，常造成不必要的牙科治療","(C) 非典型牙痛（atypical odontalgia）起因於傳入神經阻滯，常見於拔牙或根管治療後的牙齒，類似四肢的幻肢痛 （phantom pain）","(D) 帶狀皰疹感染後神經痛（postherpetic neuralgia），病毒會沿著皮節（dermatome）侵犯，紅疹僅在表皮表現"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-56","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"有關三叉神經痛（trigeminal neuralgia）的臨床症狀，下列何者正確？","options":["(A) 多數誘發區（trigger zone）位於三叉神經的其中一分支區域，如第二分支，極少侵犯兩分支","(B) 三叉神經痛為燒灼或電擊樣疼痛，並非隨著刺激加強而疼痛度增加，為神經痛的明顯表徵","(C) 治療三叉神經痛的首選藥物為卡馬西平（carbamazepine），副作用少，相當安全，近年也有使用加巴噴丁 （gabapentin）來控制","(D) 手術治療，如血管減壓手術（microvascular decompression）、伽瑪光刀手術（GammaKnife radiosurgery）等對 所有患者皆適用"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"X 光管中 filter 構造是用來阻隔低能量的光子，其成分是？","options":["(A) 銅（copper ）","(B) 鎢（tungsten）","(C) 鋁（aluminum）","(D) 鉛（lead）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"近年來上市之 lead-free apron 不含下列何種金屬？","options":["(A) 錫（tin）","(B) 鎢（tungsten）","(C) 鉍（bismuth）","(D) 銅（copper）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"牙科 X 光機器前端使用瞄準儀（collimator）主要是為了減少下列何種現象？","options":["(A) 光束衰減（beam attenuation）","(B) 光電吸收（photoelectric absorption）","(C) 相干散射（coherent scattering）","(D) 康普頓散射（Compton scattering）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-60","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"觀察上顎大臼齒的根尖病變時，為了要避開顴骨（zygomatic bone），下列何者為最理想的牙科放射線檢查 法？","options":["(A) 分角線法","(B) 咬翼片法","(C) 咬合片法","(D) 平行法"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"在拍攝上顎第一小臼齒時，為了區分頰側與腭側的根管，假設 A、B 兩點，當拍攝水平角往近心移動時，A 點 與 B 點的成像同時往遠心移動，但是 A 點移動的距離較 B 點短。則下列敘述何者正確？","options":["(A) A 點較 B 點靠近頰側","(B) A 點較 B 點靠近腭側","(C) 此原理無法判斷何點靠近頰側","(D) 此原理無法判斷何點靠近腭側"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"有關牙科咬翼片（bitewing）的敘述，下列何者錯誤？","options":["(A) 可以評估齒槽嵴的骨頭","(B) 可以評估牙冠區鄰接面之齲齒","(C) 可以評估假牙牙冠邊緣密合度","(D) 可以評估牙根下半部根管鈣化情形"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"下列何者不是環口攝影 X 光片（panoramic radiograph）中所呈現出的鬼影（ghost shadow）？","options":["(A) 頸椎","(B) 對側下顎骨體","(C) 對側下顎骨角","(D) 顴骨弓"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-64","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"下圖黃色箭頭範圍內的解剖構造為下列何者？","options":["(A) zygomatic process","(B) pterygomaxillary fissure","(C) hamular process","(D) infraorbital canal"],"answer":1,"image":"ya4-111-1-64.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-65","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"下顎咬合片中，黑色箭頭所指的是下列何者？","options":["(A) 頦結節（genial tubercle）","(B) 下顎小舌（lingula mandibulae）","(C) 頦骨嵴（mental ridge）","(D) 下顎舌骨嵴（mylohyoid ridge）"],"answer":0,"image":"ya4-111-1-65.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-66","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"64 歲男性長期使用菸酒檳榔，因左下顎臼齒無牙區牙齦腫瘤而來求診，經 X 光檢查如附圖所示，切片檢查 後，病理診斷為鱗狀細胞癌，在口腔癌分期上，此病患最可能為第幾期？","options":["(A) 第一期","(B) 第二期","(C) 第三期","(D) 第四期"],"answer":3,"image":"ya4-111-1-66.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-67","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"下列何者最可能為顎骨惡性腫瘤之影像？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":0,"image":"ya4-111-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-68","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"下列何者最可能為鎖顱骨成骨不全（cleidocranial dysostosis）之影像？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":0,"image":"ya4-111-1-68.jpeg","clinical_level":"重點"},{"id":"ya4-111-1-69","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"X 光片影像無法幫助評估下列何種牙周狀況？","options":["(A) 牙周韌帶空間的寬度","(B) 齒槽嵴之狀況","(C) 牙根叉處之骨喪失","(D) 增加牙周病嚴重度之系統性因子"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-70","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"下列何項敘述不是咬合創傷（occlusal trauma）常見的放射線影像特徵？","options":["(A) 齒槽骨板（lamina dura）變厚","(B) 齒槽骨喪失","(C) 牙周韌帶空間變寬","(D) 骨小樑（bone trabeculae）的數量及大小減少"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-71","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"關於鄰接面齲齒特徵之敘述，下列何者錯誤？","options":["(A) 初期的鄰接面齲齒在 Xray 上所見病灶大多位於 enamel 內","(B) 當齲蝕深度到達 dentinoenamel junction 之後，會順著 dentinal tubules 的方向，再往深處齲蝕","(C) 若齲蝕深度僅位於 enamel，不容易診斷，其去礦化（demineralization）的程度至少需到達 60%以上，才能從 X 光片上判讀出來","(D) 好發的位置通常介於 contact point 和 free gingival margin 之間"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-72","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"有關咬合面齲齒的敘述，下列何者錯誤？","options":["(A) 是兒童及青少年族群最容易形成的齲齒","(B) 在 X 光影像判讀時，可能會和 buccal pit 或是 non-metal restoration 的影像混淆","(C) 通常實際齲蝕深度都大於 X 光影像所顯示的深度","(D) 以 X 光檢查是最準確的方式"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-73","subject":"ya4","topic":"口腔病理基礎","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"有關蘭格罕氏細胞組織細胞增多症（Langerhans' cell histiocytosis）之敘述，下列何者錯誤？","options":["(A) 呈現 punched-out 之骨破壞放射線透過性影像","(B) 牙齒易被病灶推移，導致大範圍位移","(C) 骨內病灶外形可為圓形、卵圓形或不規則形","(D) 需要和牙周病作鑑別診斷"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-74","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"下列何種疾病，最不會出現廣泛性之齒槽骨板（lamina dura）喪失？","options":["(A) 副甲狀腺機能過旺（hyperparathyroidism）","(B) 軟骨病（osteomalacia）","(C) 戈林症狀群（Gorlin syndrome）","(D) 麥克滾-阿爾布萊德氏症候群（McCune-Albright syndrome）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-75","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"圖中 X 光影像最符合下列那種疾病？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 慢性骨髓炎（chronic osteomyelitis）","(C) 惡性骨肉瘤（osteosarcoma）","(D) 蘭格罕氏細胞組織細胞增多症（Langerhans' cell histiocytosis）"],"answer":2,"image":"ya4-111-1-75.jpeg","clinical_level":"一般"},{"id":"ya4-111-1-76","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"請依此 X 光影像，依序回答下列 3 題。 圖示牙齒的 X 光影像是以何種方法拍攝？","options":["(A) periapical radiography","(B) occlusal radiography","(C) panoramic radiography","(D) cone beam computed tomography"],"answer":0,"image":"ya4-111-1-76.jpeg","clinical_level":"重點"},{"id":"ya4-111-1-77","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"圖中黑色箭頭所指的解剖位置為何？","options":["(A) right maxilla","(B) left maxilla","(C) right mandible","(D) left mandible"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-78","subject":"ya4","topic":"放射影像診斷","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"圖中黑色箭頭所指的病變，最可能為下列何者？","options":["(A) 殘餘囊腫（residual cyst）","(B) 根尖囊腫（radicular cyst）","(C) 根尖牙骨質骨質發育不良症（periapical cemento-osseous dysplasia）","(D) 外生贅骨（exostoses）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-1-79","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"下列何者不是 X 光攝影中，傳統攝影對於數位攝影的競爭優勢？","options":["(A) 單一底片價格較低","(B) 成像品質較高","(C) 容易維護","(D) 成像操作較簡單"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"全身接受到輻射劑量達 1.5Gy，會有以下那種症狀產生？","options":["(A) 胃腸道症狀（gastrointestinal symptoms）","(B) 嚴重血液造血不良（severe hematopoietic symptoms）","(C) 輕微血液造血不良（mild hematopoietic symptoms）","(D) 前驅症狀（prodromal symptoms）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"口腔軟組織傷口癒合期中的纖維組織增生期（fibroplastic stage），正常情況下會持續多久？","options":["(A) 1～7 天","(B) 14～21 天","(C) 28～35 天","(D) 45 天以上"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"傷口癒合過程中發炎期的細胞生成層面，下列敘述何者錯誤？","options":["(A) 由組織受傷後的血漿中補體（serum complement）活化而引發","(B) 補體的衍生物例如 C3a 和 C5a 能避免嗜中性白血球（neutrophils）附著於血管","(C) 嗜中性白血球（neutrophils）遇到細菌時會釋出溶酶體（lysosomes），來摧毀細菌和分解壞死組織","(D) 單核白血球（monocyte）的作用是吞噬壞死物質"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"手術後產生死腔（dead space）的處理，下列何者錯誤？","options":["(A) 直接加壓傷口表面縫合處","(B) 敷料直接加壓到傷口內部的空間直到止血為止，之後再移除加壓敷料，例如用在手術後產生骨頭空腔","(C) 使用引流管來引流累積的血液與其他液體","(D) 死腔通常是充填著組織液而非血液，比較不會感染"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-4","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"關於切線，下列敘述那些正確？①刀片移動時使用前臂 ②刀片應與組織表面垂直 ③拔智齒時，黏膜骨膜瓣 之切線要分層切開 ④切線應讓傷口邊緣縫合時位於健康的骨頭上","options":["(A) ①②","(B) ②③","(C) ③④","(D) ②④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-5","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"關於麻醉藥注射過程的敘述，下列何者最為合理？","options":["(A) 麻醉注射前的準備過程中，要用乾淨的紗布，去除食物殘渣，維持注射區域清潔","(B) 應使用含酒精的消毒劑，消毒口腔黏膜打算注射處，預防注射引起的感染","(C) 注射前所塗抹的表面麻醉劑，要盡量延伸到注射以外的部位","(D) 注射過程絕對不可以跟病人講話溝通，因為要專心一致，準確完成注射"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"下齒槽神經阻斷麻醉時，為減少可能血管中注射而產生的瞬間不良反應，下列措施何者最重要？","options":["(A) 注射前回抽","(B) 使用大小＃25 號針頭","(C) 緩慢注射（每管大於等於 1 分鐘）","(D) 使用含 epinephrine 的麻藥"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"以 2％ lidocaine 進行成人大臼齒的牙周韌帶注射麻醉，每一針施打的建議劑量是多少 mL？","options":["(A) 0.2","(B) 0.4","(C) 0.6","(D) 0.8"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-8","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"確實阻斷 posterior superior alveolar nerve 之後，下列何者完全在其麻醉效果之範圍內？","options":["(A) 上顎第一大臼齒的牙髓及頰側牙齦","(B) 所有上顎大臼齒的牙髓及頰側牙周韌帶（PDL）","(C) 所有上顎大臼齒的牙髓及頰側齒槽骨","(D) 上顎第二、第三大臼齒的牙髓及頰側齒槽骨"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-9","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"下列那條神經支配牙髓腔的感覺？","options":["(A) 舌神經（lingual nerve）","(B) 長頰神經（long buccal nerve）","(C) 鼻腭神經（nasopalatine nerve）","(D) 前上齒槽神經（anterior superior alveolar nerve）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"關於拔牙鉗（forceps）的敘述，下列何者正確？","options":["(A) 151A 拔牙鉗適用於下顎小臼齒","(B) 151 拔牙鉗不能使用於下顎臼齒拔牙","(C) 下顎牛角拔牙鉗（cow horn）可分為左右兩種","(D) 151S 拔牙鉗不適合乳牙拔除"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"使用 Crane pick elevator 拔牙的基本力學原理是下列何者？①換位 displacement ②槓桿 lever action ③軸向 axial action","options":["(A) 僅①","(B) 僅②③","(C) 僅①②","(D) ①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"關於阻生齒拔除，請依序回答下列 3 題。 下圖 X 光片之阻生齒屬於 Pell and Gregory 分類中之那一類？","options":["(A) Class 2 and A","(B) Class 2 and C","(C) Class 3 and A","(D) Class 3 and C"],"answer":1,"image":"ya4-111-2-12.jpeg","clinical_level":"一般"},{"id":"ya4-111-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"欲拔除此阻生齒，較合適之手術步驟為：①將牙齒分段 ②清創及縫合 ③去除覆蓋之骨頭 ④翻瓣 ⑤利 用牙挺將牙齒移除","options":["(A) ④→③→①→⑤→②","(B) ④→①→③→⑤→②","(C) ③→①→⑤","(D) ④→⑤→②"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-14","subject":"ya4","topic":"拔牙學與併發症","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"阻生齒拔除後，下列術後注意事項，何者錯誤？","options":["(A) 術後應咬緊紗布持續約 30 分鐘，若移除紗布後仍有流血現象，可再咬紗布持續 1 小時","(B) 術後 12 小時之內儘量避免吸菸、使用吸管喝飲料及激烈運動","(C) 術後 12 小時之內應請病人吃涼的軟質或流質食物","(D) 為避免術後疼痛及流血，建議病人術後 2 天不要刷牙"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-15","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"關於口腔念珠菌病（candidiasis）的敘述，下列何者錯誤？","options":["(A) 通常是由 candida albicans 所感染的","(B) 容易發生於 AIDS 或是接受化療的病人","(C) 其中 pseudomembranous type，因舌頭絲狀乳突（filiform papillae）喪失，形成裸露表面","(D) 口角炎（angular cheilitis），會在嘴角呈現白色斑狀，易發生在全口無牙患者"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"最典型用於骨髓炎（osteomyelitis）治療的手術術式為下列何者？","options":["(A) incision and drainage","(B) sequestrectomy and saucerization","(C) segmental resection","(D) osteotomy"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"有關齒源性感染，下列敘述何者正確？","options":["(A) 即使病人沒有發燒，但白血球超過正常值的上限時，就應該住院治療","(B) 糖尿病病人因為嚴重齒源性感染而會導致其血糖不易控制","(C) 病人可能因為齒源性感染而發燒，如果其尿液比重值小於 1.030 就表示身體缺水","(D) 年紀大的病人如果發生齒源性感染，為了安全起見應該住院觀察與治療"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"有關齒源性感染的擴散，下列敘述何者正確？","options":["(A) 齒源性感染的來源最多是來自於牙周囊袋的細菌","(B) 上顎骨齒源性感染常常穿透腭側皮質骨來擴散","(C) 下顎臼齒的感染其擴散部位與下顎舌骨肌（mylohyoid muscle）有關","(D) 來自於上顎骨臼齒的感染常常經由上顎粗隆（tuberosity）擴散到側咽間隙（lateral pharyngeal space）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-19","subject":"ya4","topic":"齒源性感染與藥物","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"引起齒源性感染之厭氧性革蘭陰性桿菌中，以下列何者最常見？","options":["(A) Fusobacterium spp.","(B) Actinobacillus spp.","(C) Clostridium spp.","(D) Prevotella及 Porphyromonas spp."],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-20","subject":"ya4","topic":"局部與全身麻醉","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"門診局部麻醉進行贋復前手術 mylohyoid ridge reduction 時，所需要麻醉的神經通常不包括下列那一條？","options":["(A) incisive nerve","(B) lingual nerve","(C) buccal nerve","(D) inferior alveolar nerve"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-21","subject":"ya4","topic":"植牙外科","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"關於植體（implant）與自然齒（nature tooth）周圍之結締組織（connective tissue）的敘述，下列何者正確？","options":["(A) 相較於自然齒，植體周圍之結締組織不易產生細菌引起之發炎破壞（bacterial-induced inflammatory breakdown）","(B) 植體周圍之結締組織相較自然齒而言，有較少的血液循環","(C) 自然齒周圍之結締組織連接至富含細胞之牙骨質（cellular cementum）","(D) 植體周圍之結締組織纖維垂直於植體表面"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-22","subject":"ya4","topic":"植牙外科","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"以夾式植骨法（interpositional bone graft）作齒槽增高，與覆蓋式植骨法（onlay bone graft）相比，其最大之優點 是：","options":["(A) 供骨區之傷口較小","(B) 手術較省時","(C) 不需作移植骨之固定","(D) 移植骨之吸收較少"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"廣泛性頸部淋巴廓清術（RND）一定要切除的組織為下列何者？","options":["(A) 上甲狀腺動脈","(B) 外頸靜脈","(C) 迷走神經","(D) 胸鎖乳突肌"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"陳先生是一位 40 歲的建築工人，因口腔癌接受了由口腔外科團隊所進行的廣泛性切除與頸部淋巴結廓清術， 在手術後尚須接受放射線照射治療（radiotherapy），下列何者是陳先生在放射線治療期間最可能遇到的問題？","options":["(A) 血小板缺少（thrombocytopenia）","(B) 放射線骨壞死（osteoradionecrosis）","(C) 口腔黏膜炎（mucositis）","(D) 深頸部感染（deep neck infection）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-25","subject":"ya4","topic":"植牙外科","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"植牙部位接受放射治療的患者，下列考量何者最適當？","options":["(A) 接受放射線劑量小於 4500 rad，植牙前接受高壓氧 10 次，植牙後接受高壓氧 10 次","(B) 接受放射線劑量小於 4500 rad，植牙前接受高壓氧 25 次，植牙後接受高壓氧 10 次","(C) 接受放射線劑量大於 4500 rad，植牙前接受高壓氧 10 次，植牙後接受高壓氧 10 次","(D) 接受放射線劑量大於 4500 rad，植牙前接受高壓氧 25 次，植牙後接受高壓氧 10 次"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-26","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"有關外科標本的處理，下列何者正確？","options":["(A) 標本應浸泡在 8％福馬林溶液內","(B) 標本應浸泡在 95％福馬林溶液內","(C) 福馬林溶液體積至少為標本體積的 20 倍","(D) 福馬林溶液體積至少為標本體積的 10 倍"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"最常見的顎骨的囊腫為下列何者？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 齒源性角化囊腫（odontogenic keratocyst）","(C) 鼻腭囊腫（nasopalatine cyst）","(D) 牙根尖囊腫（radicular cyst）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"罹患角化性囊腫的患者，同時罹患併指以及頭圍過大等全身性疾病，患者最可能罹患下列何種症候群？","options":["(A) 痣樣基底細胞癌症候群","(B) 克新氏症候群","(C) 米庫立資氏症候群","(D) 歐伯來氏症候群"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"下列何者不是以造袋術（marsupialization）治療含齒囊腫（dentigerous cyst）的適應症？","options":["(A) 囊腫沾黏下顎齒槽神經管","(B) 嚴重心血管疾病患者","(C) 懷疑為造釉細胞瘤","(D) 懷疑為病理性骨折"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-30","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"承上題，若是利用囊腫造袋術（cystic marsupialization）來治療下顎後齒區含齒囊腫，則下列敘述何者錯誤？","options":["(A) 容易造成病理性骨折","(B) 術後口腔傷口必須時時沖洗乾淨，照護較為困難","(C) 無法將囊腫病灶全部移除","(D) 比起剜除術，較不易造成下顎神經管的損傷"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-31","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"以正顎手術治療上顎骨之發育不足（maxillary deficiency），最常施行之術式為下列何者？","options":["(A) 上顎前段截骨術","(B) 口內雙側垂直下顎枝切開術","(C) 雙側矢向劈裂截骨術","(D) 勒福一型截骨術"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"下列何種術式最常用來改善病人下顎發育不足（mandibular deficiency）的顏面外觀？","options":["(A) 髁骨下截骨術（subcondylar osteotomy）","(B) 下顎枝矢向劈裂截骨術（sagittal split ramus osteotomy）","(C) 下顎枝垂直截骨術（vertical ramus osteotomy）","(D) 頦成形術（genioplasty）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"關於下顎發育異常的敘述，下列何者錯誤？","options":["(A) 過深的唇頦皺裂，下唇外翻，上唇位置異常","(B) 患有下顎骨過長（mandibular excess）之病人，常會有第一大臼齒及犬齒均為第三級咬合關係（Class III relationship）","(C) 頦成形術（genioplasty）可以矯正顏面的不對稱","(D) 患有下顎骨過長（mandibular excess）之病人，嚴重時會使嘴唇閉合困難"],"answer":[0,1,2,3],"image":"","clinical_level":"重點","explanation_pending":false},{"id":"ya4-111-2-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"關於顳部動脈炎（temporal arteritis）的敘述，下列何者錯誤？","options":["(A) 好發 40 歲以下","(B) 致病原因為 giant cell granulomatous reaction","(C) 常因咀嚼肌痛導致咀嚼功能不良（jaw claudication）症狀而就診","(D) 若病人因急性頭痛，臆斷是顳部動脈炎（temporal arteritis），接下來應抽血檢查紅血球沈降率（erythrocyte sedimentation rate）幫助鑑別診斷"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"有關神經痛（neuropathic pain）的敘述何者正確？","options":["(A) 神經痛為疼痛神經傳導系統受損或調控失衡導致","(B) 神經痛可能為外傷或醫源性傷害，而此種症狀多為感覺異常（paresthesia），該神經支配區域麻木，不會造成 完全的感覺喪失","(C) 若患者主訴臉部或口腔有燒灼、尖銳的電擊感時，應考慮口腔灼熱症候群，不可能為神經痛","(D) 幻肢痛（phantom pain）發生於四肢截肢後，不會發生在拔牙後"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"有關三叉神經痛（trigeminal neuralgia）的臨床表徵，下列何者正確？","options":["(A) 好發於 50 歲，男性較女性稍多","(B) 輕微的表面刺激可引發疼痛，持續數秒至一分鐘，有誘發區（trigger zone）","(C) 一般為單側疼痛，左側較多，侵犯三叉神經的單一分支","(D) 鑑別診斷齒源性疼痛的重要特徵為可使用局部麻醉劑止痛"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"下列何腦神經最常引發頭頸顏面疼痛？","options":["(A) 第七對","(B) 第八對","(C) 第九對","(D) 第十對"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"除了利用不同的 X 光片、超音波、電腦斷層、磁振造影及唾液腺攝影檢查外，對於診斷唾液腺相關的疾病， 臨床醫師通常可以選擇使用以下那些適合的項目來進行輔助檢查：①內視鏡 ②放射性同位素掃描 ③肌電 圖 ④抹片 ⑤細針抽吸及切片","options":["(A) ①②⑤","(B) ②④⑤","(C) ①③⑤","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"主唾液腺（管）結石依發生率高低順序為：","options":["(A) 顎下腺（管）＞舌下腺（管）＞腮腺（管）","(B) 顎下腺（管）＞腮腺（管）＞舌下腺（管）","(C) 腮腺（管）＞舌下腺（管）＞顎下腺（管）","(D) 腮腺（管）＞顎下腺（管）＞舌下腺（管）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-40","subject":"ya4","topic":"唾液腺疾病","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"下列何者為唾液腺最常見的腫瘤？","options":["(A) pleomorphic adenoma","(B) Warthin’s tumor","(C) mucoepidermoid carcinoma","(D) adenoid cystic carcinoma"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-41","subject":"ya4","topic":"唾液腺疾病","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"有關 ranula 的敘述，下列何者錯誤？","options":["(A) simple ranula 和 plunging ranula 的差異在後者有穿過 mylohyoid muscle","(B) simple ranula 的治療方法為 marsupialization 優先，如復發則摘除腺體","(C) simple ranula 的主要病源是由顎下腺所引起","(D) simple ranula 的形成有 mucous-retention cyst 和 mucous extravasation 兩種機轉"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"關於齒槽牙齒外傷的建議固定期間，下列敘述何者較不合理？","options":["(A) 牙齒鬆動（mobile tooth）固定約為 7～10 天","(B) 牙齒位移（tooth displacement）固定時間約為 2～3 周","(C) 牙根斷裂（root fracture）2～4 個月","(D) 牙根發育未完成的再植牙（replanted tooth with wide open apical foramen）約 7～10 天"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"關於成人顎部外傷的固定時程，下列何者錯誤？","options":["(A) 上顎門牙脫位，區域性固定 7～10 天","(B) 下顎齒槽骨完全骨折，單顎固定 1～2 周","(C) 髁狀突骨折，以閉合性處理（closed method），上下顎間固定 2～3 周","(D) 下顎骨聯合處骨折（symphyseal fracture），以閉合性處理，上下顎間固定 6 周"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"右側髁狀突頸部（condylar neck）骨折產生位移，於張口時下列何種情況最常見？","options":["(A) 髁頭（condylar head）往左前移位，頦部（chin）往左偏移","(B) 髁頭（condylar head）往左前移位，頦部（chin）往右偏移","(C) 髁頭（condylar head）往右前移位，頦部（chin）往左偏移","(D) 髁頭（condylar head）往右前移位，頦部（chin）往右偏移"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-45","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"關於骨折第一級癒合（primary healing）所需條件的敘述，下列何者錯誤？","options":["(A) 骨折兩端要直接接觸，不能有空隙","(B) 骨折兩端間沒有活動度（mobility）","(C) 骨折區沒有感染","(D) 骨折區有良好的血液供應"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"下列有關顏面骨折的敘述，何者正確？","options":["(A) 病人出現眼距過寬（traumatic telecanthus）時，是因為上顎骨 Le Fort I fracture 所造成","(B) 當病人的上下眼瞼無法閉合時，是因為第三對腦神經受損","(C) 兒童下顎骨骨折時，以 closed reduction 或 mono-cortical fixation 為主","(D) 骨折處的位移程度，與骨折斷面的方向無關"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"關於唇腭裂手術，下列敘述何者正確？","options":["(A) 唇裂的修復越早越好","(B) 硬腭的修復通常在軟腭修復之前","(C) 腭裂修復後的疤痕不會影響上顎發育","(D) 提早修復硬腭有助於後續的矯正治療"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"下列何者非唇腭裂患者常遇到的問題？","options":["(A) 常常伴隨牙齒缺失或是贅生齒的問題","(B) 咬合不正","(C) 反覆中耳炎","(D) 鼻子過敏"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-49","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"下列何種神經的主要作用是感覺疼痛及温度改變？①A alpha fiber ②A beta fiber ③A delta fiber ④C fiber","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-50","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"在進行口腔手術前時，發現病人的肚子痛、胡言亂語、十分疲勞、血壓降低、肌肉疼痛、嘔心、意識不淸、 虛弱，可能發生的疾病為何？","options":["(A) 急性腎上腺功能不足（acute adrenal insufficiency）","(B) 血糖過低（hypoglycemia）","(C) 急性甲狀腺風暴（acute thyroid storm）","(D) 癲癇（seizure）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-51","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"鬱血性心衰竭（congestive heart failure）的常見症狀，下列何者除外？","options":["(A) 胸部有沈重擠壓感覺","(B) 直立性呼吸（orthopnea）","(C) 陣發性夜間呼吸困難（paroxysmal nocturnal dyspnea）","(D) 足踝水腫（ankle edema）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-52","subject":"ya4","topic":"全身性疾病與急症","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"臨床上最常見導致腎上腺皮質功能不足（adrenocortical insufficiency）之原因是：","options":["(A) 艾迪生氏病（Addison's disease）","(B) 克新氏症候群（Cushing's syndrome）","(C) 長期糖尿病（diabetes mellitus）引起的缺血性病變導致腎上腺組織壞死","(D) 長期服用皮質類固醇（corticosteroid）引起的繼發性腎上腺皮質功能不足（secondary adrenocortical insufficiency）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-53","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"關於使用骨延長術用於治療下顎骨黏連所致之顎骨發育不足時，latency period 需要多少天？","options":["(A) 5～7 天","(B) 8～14 天","(C) 15～21 天","(D) 21～28 天"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"下顎骨髁頭骨折時，為了避免產生下列何種症狀，因此顎間固定不能太久？","options":["(A) 顳顎關節黏連","(B) 關節盤前置位移","(C) 關節盤穿孔","(D) 顳顎關節被膜發炎"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"關節盤在影像上已經發現破損穿孔，請問在 Wilkes 分類為何 stage？","options":["(A) I","(B) II","(C) IV","(D) V"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-56","subject":"ya4","topic":"口腔外科基礎","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"病患基於某種理由而拒絕接受 X 光攝影，使牙醫師無法進行診斷與治療時，牙醫師應優先考慮如何處理？","options":["(A) 轉介給其他牙醫師","(B) 拒絕治療患者","(C) 說服患者接受必要的 X 光攝影","(D) 強迫患者接受 X 光攝影"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"有關 X 光的產生，下列敘述何者錯誤？","options":["(A) 其係由高速電子在 X 光管中急遽減速而產生","(B) 會產生 bremsstrahlung photon","(C) 大部分會產生 characteristic radiation","(D) 會有 99%的能量耗損，僅有 1%成 X 光"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"根據 2007 年 International commission on Radiological Protection（ICRP）制定的規範，一般民眾每年 effective dose 的容忍度為多少 mSv？","options":["(A) 1.0","(B) 2.0","(C) 6.0","(D) 20.0"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"X 光束衰減（attenuation）包含以下那些作用？①離子化（ionization） ②吸收（absorption） ③反射 （reflection） ④散射（scattering）","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"下列何者為減少兒童暴露於牙科放射線的最佳做法？","options":["(A) 每次拍攝時都要穿鉛衣","(B) 改用數位攝影法","(C) 每次拍攝時都要使用頸圈","(D) 評估後有必要時才拍攝"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"改善 X 光片品質的方法，下列敘述何者正確？","options":["(A) 增加焦點（focal spot）大小","(B) 減短焦點到被照物體的距離","(C) 減短 X 光機射柱（cone）的長度","(D) 減短被照物體到底片的距離"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"拍攝上顎犬齒根尖片時，X 光射線要對準那一位置？","options":["(A) 嘴角","(B) 鼻翼","(C) 鼻頭","(D) 眼角"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-63","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"拍攝環口 X 光片時，要避免拍出靠近上顎區呈現明顯的放射線透過性（radiolucent）影像，下列敘述何者正 確？","options":["(A) 使病人正中腭縫平面垂直地面","(B) 告訴病人儘量站直","(C) 請病人將舌尖頂在口腔最上緣","(D) 請病人嘴唇分開成微笑狀"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-64","subject":"ya4","topic":"放射影像診斷","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"圖中箭頭所指之放射線不透過性線條 （radiopaque line）為下列何者？","options":["(A) 固有層（lamina propria）","(B) 透明層（lamina lucida）","(C) 齒槽骨板（lamina dura）","(D) 齒板（lamina dentalis）"],"answer":2,"image":"ya4-111-2-64.jpeg","clinical_level":"重點"},{"id":"ya4-111-2-65","subject":"ya4","topic":"放射影像診斷","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"有關根尖影像中頦孔（mental foramen）的敘述，下列何者錯誤？","options":["(A) 為下顎神經管的末端","(B) 大約 90%的影像可以被辨識","(C) 通常出現在下顎小臼齒的根尖區域","(D) 必須與根尖病變做區別"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-66","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"附圖根尖片中，黑色箭頭所指的病變，最可能為下列何者？","options":["(A) 葡萄狀齒源性囊腫（botryoid odontogenic cyst）","(B) 含齒囊腫（dentigerous cyst）","(C) 側位牙周囊腫（lateral periodontal cyst）","(D) 根尖囊腫（radicular cyst）"],"answer":3,"image":"ya4-111-2-66.jpeg","clinical_level":"一般"},{"id":"ya4-111-2-67","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"20 歲男性因右上顎側門齒牙根尖處腫脹疼痛而來求診，經 X 光檢查如圖所示，此病患側門齒可能有下列何種 疾病？","options":["(A) 齒外齒（dens evaginatus）","(B) 齒中齒（dens invaginatus）","(C) 第一型牙本質發育不良（dentin dysplasia type I）","(D) 第二型牙本質發育不良（dentin dysplasia type II）"],"answer":1,"image":"ya4-111-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-111-2-68","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"6 歲女孩因下顎兩側後方有無痛之腫脹，經 X 光檢查如圖所示，此病患最可能罹患下列何種疾病？","options":["(A) 天使症（cherubism）","(B) 麥克滾-阿爾布萊德氏症候群（McCune-Albright syndrome）","(C) 痣樣基底細胞癌症候群（nevoid basal cell carcinoma syndrome）","(D) 骨肉瘤（osteosarcoma）"],"answer":0,"image":"ya4-111-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-111-2-69","subject":"ya4","topic":"唾液腺疾病","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"下列何者最可能為自體免疫疾病患者之唾液腺攝影影像？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":0,"image":"ya4-111-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-111-2-70","subject":"ya4","topic":"放射影像診斷","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"以放射線影像偵測齲齒之敘述，下列敘述何者錯誤？","options":["(A) 應定期放射線影像檢查","(B) 咬合面牙釉質齲齒，以放射線檢查比臨床檢查更為準確","(C) 放射線影像檢查間隔時間可因病人不同而有差異","(D) 咬翼放射線檢查（bitewing radiography）適用於鄰接面齲齒偵測"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-71","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"下列何者不是臨床上用來偵測齲齒之工具或方法？","options":["(A) extracellular matrix measurement","(B) laser light fiberoptic transillumination","(C) quantitative light-induced fluorescence","(D) bitewing X-ray films"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-72","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"下列何者最不可能呈現牙冠周圍單室型放射線透過性病灶（pericoronal unilocular radiolucent lesion）？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 齒源性角化囊腫（odontogenic keratocyst）","(C) 側位牙周囊腫（lateral periodontal cyst）","(D) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-73","subject":"ya4","topic":"口腔病理基礎","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"根尖 X 光片中，何種發現最可以用來區分根尖牙骨質骨發育不良（periapical cemento-osseous dysplasia）及造牙骨 質細胞瘤（cementoblastoma）？","options":["(A) 病灶邊界是否清晰（well-demarcated）","(B) 完整牙周韌帶（periodontal ligamant）之有無","(C) 放射線不透性團塊旁是否有放射線透過性環帶（peripheral radiolucent rim）","(D) 牽涉之牙齒是否有齒槽嵴（alveolar crest）之破壞"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-74","subject":"ya4","topic":"放射影像診斷","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"圖中箭頭所指放射線不透過性病變最可能為下列何者？","options":["(A) 慢性鼻竇炎（chronic sinusitis）","(B) 鼻竇滯留偽囊腫（antral retention pseudocyst）","(C) 鼻竇石（antrolith）","(D) 鼻竇黏液囊腫（mucocele）"],"answer":2,"image":"ya4-111-2-74.jpeg","clinical_level":"一般"},{"id":"ya4-111-2-75","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"那一種影像能提供顏面骨折診斷最多的訊息？","options":["(A) Waters' view radiography","(B) computed tomography","(C) panoramic radiography","(D) posterior-anterior skull radiography"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-76","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"請依此 X 光影像圖，依序回答下列 3 題。 圖示 X 光影像是用何種拍攝法？","options":["(A) Waters' view radiography","(B) occlusal radiography","(C) panoramic radiography","(D) posterior-anterior skull radiography"],"answer":2,"image":"ya4-111-2-76.jpeg","clinical_level":"重點"},{"id":"ya4-111-2-77","subject":"ya4","topic":"放射影像診斷","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"X 光影像中白色箭頭所指的解剖構造名稱為何？","options":["(A) posterior border of ramus","(B) styloid ligament","(C) inferior border of ramus","(D) ascending ramus"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-78","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"X 光影像中白色箭頭所指病變最可能造成下列何種疾病？","options":["(A) 伊格爾氏症候群（Eagle syndrome）","(B) 顱顏面成骨不全症（Crouzon's syndrome）","(C) 艾伯氏症候群（Apert's syndrome）","(D) 副甲狀腺機能過旺（hyperparathyroidism）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-111-2-79","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"有關直接數位放射線影像（direct digital radiography），下列敘述何者正確？","options":["(A) PSP system 屬於這類數位放射線影像","(B) CMOS system 屬於這類數位放射線影像","(C) 感應片（receptor）較易摺損","(D) 口內數位放射線影像檔案大小約 20 kilobytes"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-111-2-80","subject":"ya4","topic":"放射線原理與技術","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"下列何者不是廣島及長崎原子彈爆炸後倖存者的晚期輻射生物效應？","options":["(A) 血癌","(B) 生長發育障礙","(C) 白內障","(D) 壽命減短"],"answer":[0,1,2,3],"image":"","clinical_level":"重點","explanation_pending":false},{"id":"ya4-112-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"處理傷口癒合方法中，三級癒合（tertiary intention）指的是採取何方法？","options":["(A) 傷口直接以組織移植物（tissue graft）覆蓋","(B) 直接將傷口縫密","(C) 傷口無法完全縫密，仍留下間隙（gap）","(D) 傷口以內外分二層縫合"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"下列那些因素會造成缺血（ischemia），且可能影響口腔傷口的癒合？①縫合不夠緊 ②傷口血腫 ③高血壓","options":["(A) ①","(B) 僅②","(C) 僅③","(D) ②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"周邊神經修復的速度，下列何者正確？","options":["(A) 0.01 mm／day","(B) 0.1 mm／day","(C) 1 mm／day","(D) 10 mm／day"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-4","subject":"ya4","topic":"口腔外科基礎","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"下列有關3-0黑絲縫線（3-0 black silk）的敘述，何者錯誤？","options":["(A) 在口腔中黑絲縫線容易辨認","(B) 多股線容易打結，不鬆脫","(C) 不會因吸收口水（wicking）而造成線頭膿腫（stitch abscess）","(D) 線頭柔軟不會刺激周圍的軟組織"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-5","subject":"ya4","topic":"局部與全身麻醉","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"健康成人接受下齒槽神經傳導麻醉後出現悸動性（throbbing）頭痛，最可能的原因為下列何者？","options":["(A) 過敏反應","(B) 血管收縮劑過量","(C) 血管內注射","(D) 麻藥局部擴散至顱底"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"承上題，下列何處理方式最適當？","options":["(A) 讓病人休息，安撫病人並持續觀察","(B) 病人姿勢改為頭低腳高","(C) 施打類固醇","(D) 施打鎮靜劑"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"下列四種牙科麻醉藥濃度組成配方，那一種在齒髓麻醉（pulpal anesthesia）時，作用時間可以超過90分，最符 合長效型（long duration）牙科麻藥配方？","options":["(A) bupivacaine HCl 0.5％＋epinephrine 1：200,000","(B) lidocaine HCl 2％＋epinephrine 1：200,000","(C) mepivacaine HCl 3％","(D) prilocaine HCl 4％"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-8","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"依發生阻生齒機率由高而低排列，下列順序何者正確？①maxillary canine ②mandibular premolar ③maxillary premolar ④second molars ⑤maxillary and mandibular 3rd molars","options":["(A) ⑤②③①④","(B) ⑤①③②④","(C) ⑤①②③④","(D) ⑤④①②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-9","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"有關多顆牙拔牙順序，下列何者較恰當？①mandibular canine ②maxillary canine ③mandibular posterior teeth ④maxillary posterior teeth ⑤mandibular anterior teeth，leaving the canine ⑥maxillary anterior teeth， leaving the canine","options":["(A) ③④①②⑤⑥","(B) ④③②①⑥⑤","(C) ③⑤①④⑥②","(D) ④⑥②③⑤①"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"關於阻生齒手術的類固醇使用，下列敘述何者正確？","options":["(A) 除了術前給予外，術後持續給予類固醇一至二天，能有效避免腫脹產生","(B) 短效且高劑量的類固醇可能造成嚴重副作用","(C) 類固醇的副作用包含誘發白血球的趨化反應（chemotaxis）","(D) 若有急性感染情形可以減量使用"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"關於拔除下顎阻生第三大臼齒優點的敘述，下列何者錯誤？","options":["(A) 避免齒源性囊腫的產生","(B) 避免下顎前牙排列擁擠","(C) 可以改變下顎臉型","(D) 避免鄰牙的齲齒"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"懷孕20週的孕婦因為反覆牙冠周圍炎要求拔除下顎阻生第三大臼齒，下列敘述何者正確？","options":["(A) 因為懷孕是拔牙的禁忌症，所以無法幫她拔牙","(B) 阿斯匹靈是術後止痛藥的首選","(C) 避免使用含有lidocaine的麻藥","(D) 若是沒有過敏病史，術後可以使用penicillin類抗生素"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-13","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"下列何者為最難拔除的下顎阻生齒？","options":["(A) distoangulation，class 2 ramus relationship，class B depth","(B) mesioangulation，class 2 ramus relationship，class C depth","(C) mesioangulation，class 3 ramus relationship，class B depth","(D) distoangulation，class 3 ramus relationship，class C depth"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-14","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"關於齒源性感染手術處置的敘述，下列何者錯誤？","options":["(A) 牙齒需要做牙髓病治療保留牙齒時，可切開引流把膿排出","(B) 需要拔除牙齒以終止感染源，可順便把膿排出","(C) 切開引流後放置引流管的目的是為了防止被切開的黏膜提早癒合及持續引流","(D) 當傷口無排出的膿性液體後，引流管必須等待一週才可抽出"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"關於口面放線菌病（orofacial actinomycosis）治療方式，下列敘述何者正確？","options":["(A) 給予長期抗生素治療","(B) 給予長期抗真菌劑治療","(C) 手術切除並給予長期抗生素治療","(D) 手術切除並給予長期抗真菌劑治療"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"下列何種致病菌種類在齒源性感染中扮演較重要的角色？","options":["(A) anaerobic gram-positive cocci","(B) anaerobic gram-negative cocci","(C) anaerobic gram-positive rods","(D) aerobic gram-negative rods"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"下列何者為顎骨骨髓炎臨床特徵？","options":["(A) 下顎骨的發生率較高，因為上顎骨的血液循環較佳","(B) 造成骨髓炎的原因是以皮質骨的微循環被破壞為主","(C) 化膿性骨髓炎通常在一星期內就會出現X光片的變化","(D) 周邊軟組織易有出血及增生等現象"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"有關齒源性感染的supportive treatment，下列何者錯誤？","options":["(A) 給與抗生素","(B) 給與足夠水分","(C) 改善營養","(D) 控制體溫"],"answer":[0,1,2,3],"image":"","clinical_level":"一般","explanation_pending":false},{"id":"ya4-112-1-19","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"因配戴活動假牙造成之輕度inflammatory fibrous hyperplasia（epulis fissurata），最適當的治療方式為下列何 者？","options":["(A) 以雷射切除表層的黏膜讓其再度生長","(B) 調整假牙，可合併使用soft liner","(C) 使用手術切除並以皮瓣修補","(D) 去除底層齒槽骨增加前庭深度"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-20","subject":"ya4","topic":"口腔外科基礎","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"關於中隔齒槽整形術（intraseptal alveoloplasty）的敘述，下列何者錯誤？","options":["(A) 又稱為Dean's technique","(B) 可保留剩餘齒槽骨高度","(C) 可保留剩餘齒槽骨寬度","(D) 剩餘齒槽骨血液供應較充足"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-21","subject":"ya4","topic":"口腔外科基礎","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"進行唇繫帶切除手術（labial frenectomy）時，下列何種術式不是以繼生性上皮形成（secondary epithelialization）的方式癒合？","options":["(A) simple excision technique","(B) Z-plasty technique","(C) localized vestibuloplasty with secondary epithelialization","(D) laser-assisted frenectomy"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-22","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"關於相同的腫瘤發生在不同的部位其預後的敘述，下列何者錯誤？","options":["(A) 發生在上顎的預後比下顎為佳","(B) 發生在下顎前區比後區為佳","(C) 接近重要組織器官者，預後較差","(D) 骨內腫瘤侵入軟組織者，預後較差"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-23","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"有關齒源性角化囊腫的臨床及病理特徵，下列何者正確？","options":["(A) 囊腫外壁厚，且分泌出大量角蛋白（keratin）","(B) 由於囊腫外壁厚，上皮細胞通常超過10層","(C) 上皮細胞呈現正角化（orthokeratinization）居多","(D) 屬於容易復發，基底層的細胞核染色呈現嗜鹼性"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"切除腫瘤時連同周圍軟組織、骨及淋巴結等一起切除，此種切除稱為下列何者？","options":["(A) 完全切除（total resection）","(B) 複合性切除（composite resection）","(C) 部分切除（partial resection）","(D) 邊緣切除（marginal resection）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-25","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"下列何者是化學治療的後遺症？①骨髓抑制血球下降 ②嘔吐食慾不佳 ③口腔微生物菌種改變 ④關節疼 痛","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"改良式廣泛性頸部淋巴廓清術（modified RND）可分三類，第一類（type I）是保留何構造？","options":["(A) 副神經","(B) 副神經及胸鎖乳突肌","(C) 副神經、胸鎖乳突肌及內頸靜脈","(D) 胸鎖乳突肌"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-27","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"下列何者不是非齒源性發育囊腫（non-odontogenic developmental cyst）？","options":["(A) 鼻腭管囊腫（nasopalatine duct cyst）","(B) 鼻唇囊腫（nasolabial cyst）","(C) 中腭囊腫（mid-palatal cyst）","(D) 原基性囊腫（primordial cyst）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-28","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"關於顎骨囊腫的病變，若選擇先施行造袋術（marsupialization）後再以剜出術（enucleation）來處理，下列敘 述何者錯誤？","options":["(A) 兩種方法先後合併使用，可減少發病率，並促進傷口的完全癒合","(B) 經造袋術後，囊腫壁可能逐漸變厚，後續的剜出術將較為容易操作","(C) 囊腫完全剜出後，可使用鄰近軟組織皮瓣，來關閉手術缺損的部位","(D) 先經造袋術之後所施行的剜出術與未先經造袋術的剜出術，其手術切開方式完全相同"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-29","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"關於齒源性角化囊腫（odontogenic keratocyst）的敘述，下列何者錯誤？","options":["(A) 2005年曾被WHO重新歸類為腫瘤類","(B) 又稱為 keratocystic odontogenic tumor","(C) 有高的復發率","(D) 其中之正角質化齒源性角化囊腫（orthokeratinized odontogenic keratocyst）預後比較不好"],"answer":3,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-112-1-30","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"下列何者是軟組織囊腫？","options":["(A) 史塔尼骨囊腫（Stafne's bone cyst）","(B) 球突上顎囊腫（globulomaxillary cyst）","(C) 鼻齒槽囊腫（nasoalveolar cyst）","(D) 戈林囊腫（Gorlin cyst）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-31","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"上顎骨發育不足的特徵，下列何者錯誤？","options":["(A) 側面觀呈現著突出（convex）的臉型","(B) 上唇內縮","(C) 鼻旁區（paranasal area）發育較為不足","(D) 相對於中顏面三分之一的部份，頦部（chin）是比較明顯的部份"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-32","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"睡眠時呼吸中止達多少秒時，即稱為呼吸中止症？","options":["(A) 3秒","(B) 5秒","(C) 10秒","(D) 30秒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"對合併上顎骨發育不足（maxillary deficiency），下顎骨過度發育（mandibular excess）之病例，正顎手術前 的矯正治療最常會產生下列何種變化？","options":["(A) 顏面外觀會產生改善","(B) 上下門牙反向水平距離（incisor reverse overjet）會增加","(C) 牙齒咬合關係會改善","(D) 鼻唇角（nasolabial angle）會減少"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-34","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"顳顎關節症候群（temporomandibular disorders）的最常見問題是下列何者？","options":["(A) internal derangement","(B) myofascial pain","(C) degenerative joint disease","(D) ankylosis"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"下列何者不是顳顎關節鏡手術（arthroscopic surgery）可能的副作用？","options":["(A) perforation of the glenoid fossa","(B) nerve injury risk：CN V","(C) rupture of tympanic membrane","(D) nerve injury risk：CN VI"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"顏面部帶狀疱疹後神經痛好發於何處？","options":["(A) 三叉神經第一支（V1）","(B) 三叉神經第二支（V2）","(C) 三叉神經第三支（V3）","(D) 顏面神經（facial nerve）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-37","subject":"ya4","topic":"唾液腺疾病","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"關於乳頭狀淋巴性囊狀腺瘤（papillary cystadenoma lymphomatosum）的敘述，下列何者正確？","options":["(A) 又稱為Warthin's tumor，好發於腮腺的尾部，約60歲的年紀","(B) 腫瘤多生長快速，導致病患顏面區域的疼痛及神經麻痺","(C) 亦常發生於腭部的小唾液腺中","(D) 若選擇以簡單的外科手術切除，腫瘤復發率較高"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-38","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"關於唾液腺相關疾病常使用平面影像（plain film）的放射線檢查，下列何者錯誤？","options":["(A) 主要可輔助診斷於唾液腺結石的發生部位、大小及形狀","(B) 為利用放射線在不同X光片所作的影像檢查，惟仍然約有15～20％的機率，結石型態具有放射通透性，無法 判讀結石的發生","(C) 常用的X光片包括環口攝影片、咬合片、根尖片等","(D) 環口攝影檢查對於位在口底處的舌下腺及腺管結石診斷最有幫助"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-39","subject":"ya4","topic":"唾液腺疾病","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"關於唾液腺感染（salivary gland infections）的敘述，下列何者正確？","options":["(A) 感染的腺體，因病菌刺激會導致唾液流量增加","(B) 急性化膿性腮腺炎，常與體液平衡改變有關，多發生在年輕族群","(C) 感染最常見的菌種為金黃色葡萄球菌（Staphylococcus aureus）","(D) 於急性或慢性的感染時，最常與舌下腺管道的阻塞有關"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-40","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"參考所附圖示，下列的敘述，何者較不合理？","options":["(A) 當發現病人有上述臨床表徵時，要考慮挫傷（contusion injury）","(B) 挫傷可能由鈍器碰撞皮下或黏膜下出血而造成","(C) 撞擊如此劇烈，範圍如此廣泛，挫傷必定伴隨顏面骨或齒槽骨骨折","(D) 若黏膜或皮膚表面完整，此患者發生感染的機會應該不大"],"answer":2,"image":"ya4-112-1-40.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-41","subject":"ya4","topic":"植牙外科","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"夾式植骨法（interpositional bone graft）的優點為下列何者？","options":["(A) 可以減少神經的受損害","(B) 可以維持顎骨上缘的型態","(C) 可以不必要使用自體骨","(D) 可以用在嚴重萎縮的顎骨"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"根據力學分析理論，下顎角（angle）骨折，若只以一片迷你固板（miniplate）固定，下列敘述何者正確？","options":["(A) 固定於骨角上緣，因為上緣是壓力帶（compression zone）","(B) 固定於骨角上緣，因為上緣是張力帶（tension zone）","(C) 固定於骨角下緣，因為下緣是壓力帶（compression zone）","(D) 固定於骨角下緣，因為下緣是張力帶（tension zone）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"顏面外傷患者在急診室求診，檢查時發現其下顎骨如附圖，下列何者為最合理的評估？","options":["(A) 是下顎骨horizontally favorable fracture","(B) 是下顎骨vertically favorable fracture","(C) 是下顎骨horizontally unfavorable fracture","(D) 是下顎骨vertically unfavorable fracture"],"answer":2,"image":"ya4-112-1-43.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"左側下顎角單純骨折，若僅用顎間固定術進行閉合式骨復位術，一般最常固定多久為宜？","options":["(A) 1～2周","(B) 3～4周","(C) 6～8周","(D) 10周以上"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"下列有關下顎骨骨聯合部位（symphysis）複雜性及開放性骨折的敘述，何者錯誤？","options":["(A) 通常代表該處有兩個以上的骨斷面","(B) 不可能發生上呼吸道阻塞窘迫的症狀","(C) 口底及下顎前庭黏膜可見到瘀青或血腫","(D) 該處的軟組織撕裂傷會深至見骨"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-46","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"以superior base pharyngeal flap來修復velopharyngeal insufficiency病人，下列何者是常見的long term手術併發 症？","options":["(A) 重鼻音","(B) 睡眠呼吸暫停","(C) 水腫","(D) 吞嚥困難"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"關於唇腭裂的敘述，下列何者正確？","options":["(A) 50％唇腭裂與症候群（syndromes）有關，僅15％為單純唇腭裂","(B) 與症候群（syndromes）無關之唇腭裂病人，僅20～30％者其致病因子可歸因於基因變異","(C) 目前可透過父母之基因檢測預測胎兒唇腭裂發生的機率","(D) 懷孕時減少使用藥物可以有效減少胎兒發生唇腭裂的機率"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-48","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"對於曾患心肌梗塞（myocardial infarction）病患，若要接受局部麻藥注射，血管收縮劑如腎上腺素 （epinephrine），一般安全劑量不宜超過：","options":["(A) 4 mg","(B) 0.4 mg","(C) 0.04 mg","(D) 0.004 mg"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-49","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"測量血壓時，關於選用血壓壓脈帶（blood pressure cuff）的大小（size），下列何者正確？","options":["(A) 過小的血壓壓脈帶，血壓數值偏低","(B) 過小的血壓壓脈帶，血壓數值偏高","(C) 過大的血壓壓脈帶，血壓數值偏高","(D) 過大的血壓壓脈帶，血壓數值不變"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-50","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"關於腎上腺功能不全（adrenal insufficiency）的病人，若要接受口腔外科大手術，下列何者為正確？","options":["(A) 若正持續服用皮質類固醇（corticosteroids）時，應在手術前、中、後三天內加倍劑量","(B) 若最近一年內沒有用皮質類固醇（corticosteroids）時，亦應在手術前、中、後三天內加倍劑量","(C) 若最近未服用但曾於一年內服用皮質類固醇（corticosteroids）20 mg超過兩週時，應在手術前、中、後三天 內加倍劑量","(D) 若最近一年內曾服用皮質類固醇（corticosteroids）20 mg超過兩週時，僅應在手術前加倍劑量"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-51","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"下列何者不是nonsteroidal anti-inflammatory drug（NSAID）的禁忌？","options":["(A) 上消化道潰瘍","(B) 腎功能低下","(C) 心血管疾病","(D) 孕婦"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-52","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"下列何者不是顳顎關節synovial發炎產生的疾病？","options":["(A) chondromatosis","(B) ankylosing spondylitis","(C) capsulitis","(D) polyarthritis"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"關於顳顎關節黏連所造成的孩童下顎骨直枝垂直高度不足，考慮顎骨發育尚未完全，下列手術治療何者最理 想？","options":["(A) 口內裝置之骨延長術（distraction osteogenesis ）","(B) 口外裝置之骨延長術（distraction osteogenesis）","(C) 口內進行肋軟骨骨移植（costochondral graft）","(D) 口外進行肋軟骨骨移植（costochondral graft）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-54","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"關於使用cone beam CT來看顳顎關節影像，下列何者錯誤？","options":["(A) 消除重疊影像，可以看清楚軟組織的影像","(B) 放射劑量較傳統的tomography低","(C) 可以看清楚下顎骨髁頭的解剖型態","(D) 可為一般牙科診所的設備（office-based scanner），提供三度立體空間的影像評估"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"關於autorepositioning splints咬合板治療顳顎關節疾病的敘述，下列何者錯誤？","options":["(A) 常配戴於上顎牙齒","(B) 可以使下顎骨髁頭達到稍為向後向上的位置","(C) 可以讓肌肉和關節都得到休息","(D) 不能去除顳顎關節疼痛"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-56","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"當病患為懷孕婦女時，下列何者是牙醫師最合適的作法？","options":["(A) 在放射線照射前，應告知她牙科X光片劑量低，不會有任何危險","(B) 應警告她有流產的可能性，所以最好不要拍攝牙科X光片","(C) 應告知她絕不可拍攝牙科X光片","(D) 視情況在適當的防護下可拍攝牙科X光片"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"在X光管中，電子束打在actual focal spot size 3 mm寬，傾斜角度20°陽極上，其effective focal spot size為多少？","options":["(A) 0.5 mm","(B) 1.0 mm","(C) 1.5 mm","(D) 2.0 mm"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"自然界中背景輻射（background radiation）最大的來源為那個元素？","options":["(A) 鎵（gallium）","(B) 氪（krypton）","(C) 氡（radon）","(D) 鎝（technetium）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"關於CCD（charge-coupled device）與CMOS（complementary metal oxide semiconductors）的敘述，下列何者錯 誤？","options":["(A) CMOS最先應用於數位X光影像存取","(B) CMOS成本比CCD低","(C) CMOS每個像素（pixel）就連結一個晶體管（transistor）","(D) CCD感應光的能力比感應X光更強"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-60","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"使用分角線法拍攝上顎門齒時，建議X光入射角與水平面的夾角為幾度？","options":["(A) +10或+15","(B) +20或+25","(C) +30或+35","(D) +40或+45"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"下列那一種牙科攝影法的影像變形量（distortion）最小？","options":["(A) 分角線法","(B) 環口攝影法","(C) 側顱分析法","(D) 平行法"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-62","subject":"ya4","topic":"唾液腺疾病","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"有關唾液腺造影術（sialography）之敘述，下列何者錯誤？","options":["(A) 可以診斷Sjogren's syndrome","(B) 可以診斷唾液腺結石","(C) 需要注射顯影劑","(D) 輻射劑量比錐束電腦斷層攝影的劑量高"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"為了補償curve of Monson，在照射臼齒區的咬翼片（bitewing）時，X光cone的垂直角度（vertical angulation） 為下列何者？","options":["(A) 向下15°～18°","(B) 向上15°～18°","(C) 向下5°～10°","(D) 向上5°～10°"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-64","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"Submentovertex radiography最合適用於診斷下列何解剖構造的斷折（fracture）？","options":["(A) maxillary periapical region","(B) maxillary molars","(C) orbital ring","(D) zygomatic arch"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-65","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"圖中箭頭所指之構造為下列何者？","options":["(A) 門齒孔（incisive foramen）","(B) 舌孔（lingual foramen）","(C) 頦孔（mental foramen）","(D) 頦窩（mental fossa）"],"answer":1,"image":"ya4-112-1-65.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-66","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"15歲男孩因上顎右側犬齒排列不整而來求診，經X光檢查如附圖所示，發現一放射線透過性影像如箭頭所示 之區域，相關牙齒之牙髓活性測試皆呈活性反應，在切片時發現此病變區呈現一空腔，病理鏡檢只看到少量 的纖維組織及骨小樑，並無上皮襯底（epithelial lining），此病變最可能為下列何者？","options":["(A) 動脈瘤性骨囊腫（aneurysmal bone cyst）","(B) 中心型巨細胞肉芽腫（central giant cell granuloma）","(C) 局部骨疏鬆性骨髓缺陷（focal osteoporotic marrow defect）","(D) 單純性骨囊腫（simple bone cyst）"],"answer":3,"image":"ya4-112-1-66.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-67","subject":"ya4","topic":"口腔病理基礎","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"48歲男性三個月前拔除右上顎第一大臼齒，之後有黃鼻涕的問題產生，在X光及錐狀射束電腦斷層掃描 （cone-beam computed tomography, CBCT）檢查如附圖所示，此病變最可能的診斷為下列何者？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) NK-T細胞淋巴瘤（NK-T cell lymphoma）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 殘根與鼻竇炎（retained root and sinusitis）"],"answer":3,"image":"ya4-112-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-68","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"下列何者臨床外觀與正常牙齒無異，僅能以X光檢查判定？","options":["(A) 爪形咬頭（talon cusp）","(B) 牙釉質發育不全（amelogenesis imperfecta）","(C) 牛型臼齒（taurodontism）","(D) 牙本質形成不良（dentinogenesis imperfecta）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-69","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"下圖為典型之頭頸部軟組織鈣化或骨化的部位示意圖，下列編號何者為靜脈石（phleboliths）好發部位？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":0,"image":"ya4-112-1-69.jpeg","clinical_level":"重點"},{"id":"ya4-112-1-70","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"發生於下顎骨的骨髓炎（osteomyelitis）與纖維性發育不良（fibrous dysplasia）在影像上的不同，下列敘述何 者正確？","options":["(A) fibrous dysplasia病灶界限邊緣清晰；osteomyelitis 則否","(B) fibrous dysplasia的new bone formation發生在下顎骨cortex內；osteomyelitis則發生於下顎骨cortex外","(C) mandibular canal可能會被osteomyelitis破壞；在fibrous dysplasia則不受影響，不破壞也不位移","(D) fibrous dysplasia經治療後顎骨會恢復原狀；osteomyelitis則否"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-71","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"有關利用bitewing and periapical radiographies評估牙周狀況之敘述，下列何者錯誤？","options":["(A) 主要是提供三度空間情況的二度空間影像","(B) 可顯示出軟組織與硬組織之間的相對關係，所以可從X光片上得知牙周囊袋的深度","(C) 所呈現出來的bone destruction大部分比實際來得輕微","(D) over-eruption或passive eruption的牙齒，因牙骨質牙釉質交界（CEJ）不易取得，而不易測量齒槽嵴的高度"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-72","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"下圖中左下顎骨角所顯示的放射線可透過影像（radiolucency），其最可能診斷為何？","options":["(A) 舌側下顎唾液腺凹陷（lingual mandibular bone depression）","(B) 單純性骨囊腫（simple bone cyst）","(C) 含齒囊腫（dentigerous cyst）","(D) 鈣化齒源囊腫（calcifying odontogenic cyst）"],"answer":0,"image":"ya4-112-1-72.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-73","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"牙周炎所造成之明顯牙周附連喪失（significant loss of attachment）至少需多久時間後，在放射線影像上才可 看到齒槽骨喪失（bone loss）？","options":["(A) 0.5至1個月","(B) 1.5至2個月","(C) 3至4個月","(D) 6至8個月"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-74","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"有關鎖顱骨成骨不全（cleidocranial dysostosis）的敘述，下列何者錯誤？","options":["(A) 全身先天性的膜性成骨骨化不全的罕見疾病，在流行病學統計上並沒有性別上的差異","(B) 主要影響鎖骨、頭顱骨和顏面骨，使得頭骨骨化慢，骨縫密合極慢","(C) 對於齒列的影響包括乳齒較不易脫落，恆齒較晚發育，有先天性多顆缺牙或是牙齒排列過於緊密情形","(D) lateral skull X ray film有時會看到 parietal bone under development的表現"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-75","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"圖中箭頭所指處之X光影像最可能為下列何種疾病？","options":["(A) 牙本質發育不良第一型（dentin dysplasia type I）","(B) 牙本質發育不良第二型（dentin dysplasia type II）","(C) 牙本質形成不良（dentinogenesis imperfecta）","(D) 局部牙齒發育不良（regional odontodysplasia）"],"answer":3,"image":"ya4-112-1-75.jpeg","clinical_level":"一般"},{"id":"ya4-112-1-76","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"請依此X光影像圖，依序回答下列3題。 圖示為下列何種X光影像？","options":["(A) Waters' view radiography","(B) occlusal radiography","(C) panoramic radiography","(D) posterior-anterior skull radiography"],"answer":1,"image":"ya4-112-1-76.jpeg","clinical_level":"重點"},{"id":"ya4-112-1-77","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"圖中黑色箭頭所指的解剖位置為何？","options":["(A) left maxilla","(B) right maxilla","(C) left mandible","(D) right mandible"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-78","subject":"ya4","topic":"放射影像診斷","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"圖中黑色箭頭所指的病變最可能為下列何者？","options":["(A) 殘餘囊腫（residual cyst）","(B) 側位牙周囊腫（lateral periodontal cyst）","(C) 根尖囊腫（radicular cyst）","(D) 含牙囊腫（dentigerous cyst）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-112-1-79","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"針對CT影像的Hounsfield Units（HU）之敘述，下列何者錯誤？","options":["(A) 骨頭在+400～+1,000","(B) 軟組織在+10～+30","(C) 水為0","(D) 脂肪在-60～-100"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"下列何者不是游離輻射造成的直接作用或傷害？","options":["(A) 自由基（free radicals）造成去氧核糖核酸（DNA）的破壞","(B) 點突變（point mutation）","(C) 細胞死亡","(D) 染色體複製異常"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"關於骨頭癒合的敘述，下列何者錯誤？","options":["(A) 當發生骨折時，骨折處固定後，在骨折斷裂處骨縫2mm時，是屬於一級癒合","(B) 骨痂（callus）是由於纖維母細胞與造骨母細胞產生很多纖維基質（fibrin matrix）超越骨折處，並將骨折處 兩端呈現環狀的包圍","(C) 當骨頭呈現不完全骨折時，也就是斷裂端並沒有分開，是屬於一級癒合","(D) 柳條狀骨折（greenstick fracture）是屬於一級癒合"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-2","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"關於拔牙後齒槽窩癒合的敘述，下列何者錯誤？","options":["(A) 拔牙後的第一週纖維母細胞與微血管，會朝向齒槽窩內生長","(B) 拔牙後的第一週破骨細胞（osteoclast）會沿著齒槽骨嵴而累積聚集","(C) 拔牙後的第一週類骨質細胞（osteoid）開始沿著齒槽骨堆積","(D) 齒槽窩的上皮化（epithelialization）通常在拔牙後第3到4週完成"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"阻礙傷口癒合的項目包括下列何者？①壞死組織 ②組織缺血 ③傷口張力過大 ④傷口敷料","options":["(A) ①②④","(B) ①②③","(C) ①③④","(D) ②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-4","subject":"ya4","topic":"口腔外科基礎","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"關於傷口癒合階段的敘述，下列何者錯誤？","options":["(A) 第一期是發炎期（inflammatory stage）","(B) 第二期是再塑期（remodeling stage）","(C) 發炎期又分成血管與細胞生成兩個層面","(D) 發炎期是組織受傷後就開始進行"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-5","subject":"ya4","topic":"口腔外科基礎","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"在皮膚移植過程中，皮膚與接受區何時可以達到穩定的結合？","options":["(A) 第一天","(B) 第三天","(C) 第九天","(D) 第十四天"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-6","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"服用metronidazole需要注意事項不包括下列何者？","options":["(A) 與抗凝血劑一起使用時","(B) 與酒精一起使用時","(C) 罹患慢性阻塞性肺臟疾病","(D) 懐孕"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"關於牙韌帶內注射，以下何種情況不適合使用？","options":["(A) 缺乏凝血因子7病人的牙齒","(B) 拔多顆乳牙時","(C) 拔上顎笫三大臼齒","(D) 疼痛的診斷"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-8","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"對控制不良或未控制之甲狀腺亢進患者（hyperthyroidism），下列何種藥物為絕對禁忌？","options":["(A) lidocaine","(B) bupivacaine","(C) epinephrine","(D) felypressin"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"小明拔完下顎大臼齒四天後，傷口突然非常疼痛且伴隨臭味，無發燒現象，最可能的診斷為下列何者？","options":["(A) 乾性齒槽炎（dry socket）","(B) 骨髓炎（osteomyelitis）","(C) 蜂窩性組織炎（cellulitis）","(D) 正常的拔牙術後變化"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"下顎第三大臼齒因阻生而確定要拔除時，下列時機何者較適當？","options":["(A) 牙根形成未達三分之一前","(B) 牙根已形成三分之一但未達三分之二前","(C) 牙根已形成三分之二但未達四分之三前","(D) 牙根完全形成後"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"關於在拔牙過程中，若造成口鼻竇相通（oroantral communication），則下列敘述何者正確？","options":["(A) 小於4mm以下的口鼻竇相通，通常不需特別處理","(B) 最容易發生於上顎第三大臼齒的拔牙","(C) 病患通常需合併服用的藥物包括抗生素（antibiotics）及抗組織胺（antihistamine）等","(D) 若要取出進入上顎竇的牙齒組織，可由腭側進行Caldwell-Luc approach而將其取出"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"曾接受過頭頸部放射線治療的病患，希望接受拔牙治療，下列敘述何者錯誤？","options":["(A) 放射線劑量累積達50Gy就不可拔牙","(B) 術前跟術後接受高壓氧治療有助於傷口修復","(C) 術後儘量將傷口縫合減少感染機會","(D) 系統性抗生素給予能減少顎骨壞死機會"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-13","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"關於拔牙時機的敘述，下列何者正確？","options":["(A) 阻生智齒產生嚴重牙冠周圍炎（pericoronitis）時須盡速拔除","(B) 口腔癌侵犯及包圍牙齒時需拔除以免癌細胞經牙周膜轉移入顎骨","(C) 一般而言，急性感染不是拔牙的禁忌症（contraindication）","(D) 所有服用抗凝血藥物的病人必須停藥後才可以拔牙"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-14","subject":"ya4","topic":"拔牙學與併發症","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"第三大臼齒拔除後，影響鄰接第二大臼齒牙周修復的主要因素為下列何者？","options":["(A) 手術時間","(B) 病患的年紀","(C) 第二大臼齒的牙根型態","(D) 是否接受術前抗生素"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"下列何者為齒源性感染中常見的厭氧菌種？①格蘭氏陽性球菌 ②格蘭氏陰性球菌 ③格蘭氏陽性桿菌 ④ 格蘭氏陰性桿菌","options":["(A) ①③","(B) ②③","(C) ①④","(D) ②④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-16","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"頭頸部感染的過程中，如果體溫上升不超過103°F（39.4℃）時，則可能對身體有益處的原因為下列何者？","options":["(A) 減少血液流至感染區","(B) 促進吞噬作用（phagocytosis）","(C) 體溫適度上升可使代謝率下降，減少細菌毒素的散播","(D) 增強抗體效能與體溫適度上升無關"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"有關蜂窩性組織炎與急性骨髓炎的比較，下列敘述何者正確？","options":["(A) 蜂窩性組織炎如果沒有控制好，就會轉變成急性骨髓炎","(B) 蜂窩性組織炎是由細菌局部擴散形成，急性骨髓炎多由於細菌經由血路擴散而成","(C) C-reactive protein（CRP）值在蜂窩性組織炎比較明顯增高","(D) 兩者之臨床特徵雷同"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-18","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"口腔癌病人在放射線治療結束三個月後，發現其嘴角處有水疱、潰爛現象，如下圖，比較可能是何種感染？","options":["(A) 蜂窩性組織炎","(B) 放射線性口腔黏膜炎","(C) 黴菌感染","(D) 續發性疱疹感染"],"answer":3,"image":"ya4-112-2-18.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-19","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"為預防感染性心內膜炎（infectious endocarditis），一些高危險病人在拔牙前須服用預防性抗生素 （prophylactic antibiotic），有關抗生素選擇的敘述，下列何者正確？","options":["(A) 優先使用amoxicillin，因為大多是由金黃葡萄球菌（staphylococcus aureus）引起","(B) 優先使用amoxicillin，因為大多是由草綠色鏈球菌（streptococcus viridans）引起","(C) 優先使用gentamicin，因為大多是由金黃葡萄球菌（staphylococcus aureus）引起","(D) 優先使用gentamicin，因為大多是由草綠色鏈球菌（streptococcus viridans）引起"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-20","subject":"ya4","topic":"植牙外科","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"在上顎竇側壁進行上顎竇增高術（sinus lift）時，最有可能遭遇到下列何種動脈的吻合枝？","options":["(A) 前上齒槽動脈與後上齒槽動脈","(B) 降腭動脈與眶下動脈","(C) 後上齒槽動脈與眶下動脈","(D) 大腭動脈"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-21","subject":"ya4","topic":"植牙外科","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"植牙手術時，最後鎖入植體時的扭力至少須達多少newton centimeters（Ncm）才能達到最佳的穩定性？","options":["(A) 20","(B) 25","(C) 30","(D) 35"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-22","subject":"ya4","topic":"植牙外科","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"在正常情況下，牙科植體距離頦孔（mental foramen）前緣至少需要多少mm？","options":["(A) 1","(B) 3","(C) 5","(D) 10"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-23","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"有關齒源性角化囊腫（odontogenic keratocyst）的敘述，下列何者正確？","options":["(A) 好發於下顎骨","(B) 好發於前牙區","(C) 手術後比其他囊腫的復發率低","(D) 發生在60歲以上的患者比較多"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-112-2-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"依AJCC第六版（2002），在口腔癌的分類TNM系統中，T除了代表腫瘤大小，還可表示下列何者？","options":["(A) 是否有近端的淋巴轉移","(B) 腫瘤生長速度","(C) 腫瘤侵犯的深度","(D) 腫瘤侵犯的不同組織或解剖間隙"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"關於口腔惡性腫瘤化學治療後的評估，下列何者錯誤？","options":["(A) complete response意指腫瘤完全消失","(B) partial response意指腫瘤比原來小至少50％","(C) stable disease 意指腫瘤大小不變","(D) progression意指腫瘤變大"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-26","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"關於痣樣基底細胞癌的敘述，下列何者正確？","options":["(A) 此類患者的ACTH腫瘤抑制基因發生突變","(B) 此類患者的基底細胞癌發生在全身皮膚部位的機率沒有差別","(C) 此類患者的齒源性角化囊腫也是採用大範圍切除，以避免復發","(D) 有不到三分之一的患者在手掌及腳掌有皮膚凹陷（pitting defects）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"有關口腔良性腫瘤的處理原則中，下列何者正確？","options":["(A) 造釉細胞瘤（ameloblastoma）復發率低，可以利用刮除術（curettage）來移除","(B) 顎骨的巨細胞肉芽腫（giant cell granuloma）復發率高，必須進行composite resection","(C) 造釉細胞纖維瘤（ameloblastic fibroma）復發率低，可以施行enucleation","(D) 齒源性黏液瘤odontogenic myxoma復發率低，術後不須密切追蹤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"關於牙周囊腫（paradental cyst）的敘述，下列何者錯誤？","options":["(A) 亦可稱為下顎感染性頰側囊腫（mandibular infected buccal cyst）","(B) 好發在下顎大臼齒","(C) 多數與牙冠周圍炎（pericoronitis）有關","(D) 好發在18歲左右的青春期"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"關於含齒囊腫（dentigerous cyst）的敘述，下列何者正確？","options":["(A) 有很高的復發率","(B) 在全口環狀X光片中會呈現單房性（unilocular）之放射線透過性病灶","(C) 若是病灶過大，壓迫下顎齒槽神經時，可以挖除術來治療","(D) 患者合併有其他全身症狀"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-112-2-30","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"關於顎骨發炎性囊腫（inflammatory cyst）的敘述，下列何者錯誤？","options":["(A) 殘餘囊腫（residual cyst）屬於發炎性囊腫","(B) 牙周囊腫（paradental cyst）屬於發炎性囊腫","(C) 根尖囊腫（radicular cyst）屬於發炎性囊腫","(D) 是由退化的牙釉質上皮（enamel epithelium）發育而來"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-31","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"關於顎骨內的囊腫及類囊腫良性病灶處理，下列何種手術方式最不適當？","options":["(A) 複合式切除（composite resection）","(B) 造袋術（marsupialization）","(C) 剜出術（enucleation）","(D) 造袋術之後剜出術（enucleation after marsupialization）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-32","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"40歲男性患者來醫院求診，主訴於例行的牙科X光檢查時，發現右側後下顎區有一放射線透過性的病灶（如 圖一所示），經門診切片檢查，病理報告顯示為含齒囊腫（dentigerous cyst）；安排患者接受電腦斷層檢查 後，以3D技術列印出完整的下顎模型（如圖二所示）。關於病患下顎此一巨大囊腫的處理方式，下列敘述何 者正確？ 圖一 圖二","options":["(A) 手術前不需考慮術後的重建問題，因為含齒囊腫較不可能導致下顎骨骨折及下齒槽神經的侵犯","(B) 為避免囊腫病變造成下顎骨更大範圍的破壞或術後的復發，處理的方式可優先選擇剜出術（enucleation）及 合併下顎骨局部切除術","(C) 可單獨使用造袋術（marsupialization）來處理，將可獲得最佳的結果","(D) 造袋術通常不需使用預防性的抗生素，除非患者的健康狀況不佳"],"answer":3,"image":"ya4-112-2-32.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"下列何者是下顎骨前突症（mandibular prognathism）明顯的特徵？","options":["(A) 側面觀呈現著中顏面三分之一的部分明顯的突出","(B) 唇頦皺摺（labiomental fold）會增加","(C) 是屬於Class II異常咬合（malocclusion）","(D) 側面觀呈現著下顏面三分之一的部分明顯的突出"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"利用正顎手術來治療下顎骨前突症（mandibular prognathism）時，下列何種術式最少單獨使用？","options":["(A) 髁骨下截骨術（subcondylar osteotomy）","(B) 下顎枝矢向劈裂截骨術（sagittal split ramus osteotomy）","(C) 下顎枝垂直截骨術（vertical ramus osteotomy）","(D) 頦成形術（genioplasty）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-35","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"對於上顎骨發育不足（maxillary deficiency）的病例，下列敘述何者正確？","options":["(A) 最主要的手術方式為上顎前段截骨術（upper anterior segmental osteotomy）","(B) 常會合併鼻側（paranasal）及眼眶下區（infraorbital rim）發育不足","(C) 微笑時牙齒會過度暴露","(D) 發育不足僅會發生在前後徑（anteroposterior）及左右徑（transverse）方向，不會發生在上下徑方向 （vertical）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"關於三叉神經痛的敘述，下列何者正確？","options":["(A) chlorzoxazone最常被用來治療三叉神經痛","(B) 發作時間會超過十分鐘，疼痛是尖銳的","(C) 好發於20～30歲的年齡層","(D) 引發區（trigger zone），在口腔內任何部位都有可能發生"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"有關去傳導後牙痛（odontalgia resulting from deafferentation）的敘述，下列何者錯誤？","options":["(A) 局部麻醉可以緩解症狀","(B) 引發的疼痛，有時是非常劇烈的","(C) 在牙齒及齒槽骨附近找不到病因","(D) 常發生在拔牙後，但不發生於根管治療後"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-38","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"當帶狀疱疹發生於三叉神經時，下列何者正確？","options":["(A) 最常發生於第一個分支","(B) 最常發生於第二個分支","(C) 最常發生於第三個分支","(D) 三個分支的機率差別不大"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"關於多形性腺瘤（pleomorphic adenoma）的敘述，下列何者正確？","options":["(A) 約有5％的比例，可能會轉變為惡性","(B) 主唾液腺中最好發於顎下腺","(C) 小唾液腺中最好發於下唇","(D) 為第二常見的唾液腺良性腫瘤"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-40","subject":"ya4","topic":"唾液腺疾病","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"以下是人體中可能發生三種不同型態的唾液腺惡性腫瘤：①多形性低度腺癌（polymorphous low-grade adenocarcinoma） ②腺樣囊狀癌（adenoid cystic carcinoma） ③黏液表皮樣瘤（mucoepidermoid carcinoma） 依腫瘤發生頻率的高低，其正確的順序為？","options":["(A) ②③①","(B) ①③②","(C) ③①②","(D) ③②①"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-41","subject":"ya4","topic":"唾液腺疾病","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"關於黏液囊腫（mucocele）的敘述，下列何者正確？","options":["(A) 常見的原因為小唾液腺結石，導致管道阻塞所引起","(B) 手術切除時不需切除其相關的小唾液腺，以避免嚴重的疤痕收縮，影響美觀","(C) 手術切除此類假性囊腫後，檢體不須送組織病理檢查","(D) 術後復發率為15～30％"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"下列幾種臨床情況，何者不需以開放性骨復位術加以治療？","options":["(A) 下顎骨骨角處骨折，病人無法忍受顎間固定，明確要求縮短顎間固定術的時間","(B) 使用閉合式骨復位術，但無法完成復位改善咬合","(C) 右側髁（condylar）單純骨折，咬合關係正常，張口不受限且略為偏向患側","(D) 上下顎骨多處骨折，骨折錯位嚴重複雜"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"關於中臉顏面骨骨折產生位移時，下列敘述何者錯誤？","options":["(A) 勒福氏第一級（Le Fort I）骨折，不會有腦脊髓液滲漏","(B) 勒福氏第二級（Le Fort II）骨折，不會出現中臉扁平","(C) 勒福氏第三級（Le Fort III）骨折，不會出現咬合改變","(D) 勒福氏第一級、第二級或第三級骨折不會造成下顎偏移"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"典型顴骨（zygoma）骨折的位移方向，下列何者正確？","options":["(A) 顴骨骨體往前，顴骨弓往外","(B) 顴骨骨體往後，顴骨弓往內","(C) 顴骨骨體往前，顴骨弓往內","(D) 顴骨骨體往後，顴骨弓往外"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"下列何種骨折不會造成咬合改變？","options":["(A) 勒福氏第一級（Le Fort I）骨折","(B) 勒福氏第二級（Le Fort II）骨折","(C) 勒福氏第三級（Le Fort III）骨折","(D) 顴骨（zygoma）骨折"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"關於頭部合併顏面外傷的患者，下列處理原則何者最不合理？","options":["(A) 首先要確定呼吸道暢通及心血管功能系統穩定","(B) 由於影像評估很重要，只要病人有呼吸心跳，應直接安排電腦斷層攝影，盡快確定骨折的部位及傷勢","(C) 對於潛在的威脅，如明顯的出血，要盡快加以止血，以維持生命徵象穩定","(D) 神經學的評估應在生命徵象維持穩定及排除潛在威脅後再實施"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"有關唇腭裂的治療時機，下列敘述何者不屬於rule of 10's？","options":["(A) 病童年齡10週後","(B) 幼童之血色素（hemoglobin）至少要10 mg／dL","(C) 幼童之體重至少要10磅","(D) 幼童之血小板要10萬／mm3"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-48","subject":"ya4","topic":"植牙外科","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"下列供應區，何者可以提供最多顆粒性髓質骨？","options":["(A) 腸骨（ilium）","(B) 顱頂骨（calvarium）","(C) 下顎聯合處（symphysis）","(D) 肋骨（rib）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"對於曾患心肌梗塞（myocardial infarction）病患，若要接受預先安排的重大手術（elective major surgery）時， 一般應該在病發後多久？","options":["(A) 4週","(B) 6週","(C) 8週","(D) 24週"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-50","subject":"ya4","topic":"局部與全身麻醉","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"根據美國麻醉醫師學會（ASA）發展的生理狀態分級系統評估病人，下列何者屬於 ASA III？","options":["(A) 有失能性的系統性疾病，且已持續威脅到生命","(B) 病患有輕度受控制的系統性疾病，而這疾病沒有影響到正常活動","(C) 有嚴重的系統性疾病，活動已受限制","(D) 垂死的病患，不論是否接受手術都不被預期會存活過24小時"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-51","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"關於哮喘（asthma）的用藥，下列何者錯誤？","options":["(A) cromolyn可用於防止哮喘發生，但對已發生的支氣管痙攣則無效","(B) 若發生哮喘聲（wheezing）時可自行使用epinephrine 或 metaproterenol 噴霧劑","(C) 牙科手術中禁用氧化亞氮（nitrous oxide），因可能引起哮喘","(D) 嚴重哮喘可用茶鹼（theophylline）或皮質類固醇（corticosteroids）治療"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-52","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"嚴重的慢性阻塞性肺部疾病（chronic obstructive pulmonary disease）需接受口腔手術時，下列何者正確？","options":["(A) 若正在服用皮質類固醇（corticosteroids），應考慮於術前增加劑量","(B) 因焦慮（anxiety）而激發慢性阻塞性肺部疾病，使用鎮靜劑（sedatives）、安眠藥（hypnotics）或麻醉藥 （narcotics）以減低症狀","(C) 病人在牙科治療椅上，應採平躺姿勢（supine position）","(D) 手術中供給高流量（flow rate）的純氧"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"病人敘述耳前的疼痛，在顳顎關節疾病中，發生率最高的為？","options":["(A) myofascial pain and dysfunction","(B) internal derangements","(C) degenerative joint disease","(D) systemic arthritic conditions"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"顳顎關節關節腔沖洗（arthrocentesis）下列敘述何者正確？","options":["(A) 沖洗上關節腔，50mL","(B) 沖洗下關節腔，50mL","(C) 沖洗上關節腔，200mL","(D) 沖洗下關節腔，200mL"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"一位24歲病人來求診，嘴巴張不開，咬合為二級異常咬合，下巴頦部非常小， 側方運動和前突運動也無法 做，臉有明顯不對稱，最常見的診斷是下列何者？","options":["(A) 顳顎關節類風濕性關節炎（rheumatoid arthritis of TMJ ）","(B) 可復位之關節盤前置位移（anterior disk displacement with reduction）","(C) 顳顎關節內黏連（intracapsular ankylosis）","(D) 顳顎關節外黏連（extracapsular ankylosis）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-56","subject":"ya4","topic":"口腔外科基礎","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"下列何醫療行為可以不需要簽署知情同意書？","options":["(A) 門診手術","(B) 檢驗愛滋病","(C) 處方開藥","(D) 局部麻醉"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"下列何者為X光管中之散熱裝置？①銅塊 ②銀塊 ③金塊 ④油 ⑤水","options":["(A) ①⑤","(B) ②④","(C) ①④","(D) ③⑤"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"下列何者不能減少病人X光放射線劑量？","options":["(A) 鉛衣","(B) 低速底片","(C) 瞄準儀（collimator）","(D) 數位化攝影"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-59","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"下列何者在放射線影像中不會有蛋殼效應（eggshell effect）？①齒槽骨板（lamina dura） ②上顎竇邊緣 （border of maxillary sinus） ③鼻子（nose） ④舌頭（tongue）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"下列何種口外片拍攝方式，病人需低頭且視線朝下？","options":["(A) cephalometric projection","(B) submentovertex projection","(C) Waters projection","(D) reverse Towne projection"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-61","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"下列那種拍攝方式，其condyle neck的影像最不清楚？","options":["(A) submentovertex projection","(B) posteroanterior cephalometric projection","(C) reverse Towne projection","(D) panoramic projection"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-62","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"下列那種拍攝方式，其眼眶（orbit）的影像最不清楚？","options":["(A) lateral cephalometric projection","(B) Waters projection","(C) posteroanterior cephalometric projection","(D) reverse Towne projection"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-63","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"關於側顱放射線攝影（lateral cephalometric projection）的敘述，下列何者錯誤？","options":["(A) 標準為病人面對接受屏向左，水平參考基準線為法蘭克福平面（F-H plane）","(B) X光管頭前方有楔形濾光片（wedge filter）會吸收部分放射線，以利顯示臉部軟組織影像","(C) 盡可能使左右兩側重疊，離midsagittal plane越遠越容易重疊，變形越小","(D) 判讀依序為顱骨、上中顏面、下顏面、頸部評估、齒槽骨及牙齒，最後才進入測顱分析"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-64","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"附圖中黑色箭頭所指的構造為何？","options":["(A) 耳咽管咽皺襞（salpingopharyngeal fold）","(B) 蝶鞍（sella turcica）","(C) 蝶竇（sphenoid sinus）","(D) 軟腭（soft palate）"],"answer":1,"image":"ya4-112-2-64.jpeg","clinical_level":"重點"},{"id":"ya4-112-2-65","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"附圖中箭頭所指影像之解剖構造為何？","options":["(A) 上顎竇（maxillary sinus）","(B) 喙狀突（coronoid process）","(C) 粗隆（tuberosity）","(D) 顴骨（zygoma）"],"answer":3,"image":"ya4-112-2-65.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-66","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"附圖根尖X光片中，白色箭頭所指為何種構造？","options":["(A) mental foramen","(B) lingual foramen","(C) incisive foramen","(D) mental fossa"],"answer":1,"image":"ya4-112-2-66.jpeg","clinical_level":"重點"},{"id":"ya4-112-2-67","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"附圖X光片中，黑色箭頭所指的牙齒異常為何？","options":["(A) 融合齒（fusion of teeth）","(B) 雙生齒（gemination）","(C) 連合齒（concrescence）","(D) 巨齒症（macrodontia）"],"answer":0,"image":"ya4-112-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-68","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"病人的左臉上有長期的青春痘，其咬翼片影像紅色圈內左臉軟組織中的鈣化物，最可能的診斷為何？","options":["(A) osteoma cutis","(B) phleboliths","(C) sialoliths","(D) tonsilloliths"],"answer":0,"image":"ya4-112-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-69","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"45歲男性因右下臉腫脹前來就診，其環口X光片影像如圖所示，下列何者為最不可能的臨床診斷？","options":["(A) dentigerous cyst","(B) residual cyst","(C) odontogenic keratocyst","(D) ameloblastoma"],"answer":1,"image":"ya4-112-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-70","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"67歲女性因車禍前來急診，病人抱怨受傷後牙齒咬合狀況改變，在電腦斷層檢查後，發現有單一處顏面骨折 如圖所示。在進行病人口內檢查時，最可能看到下列何種狀況？","options":["(A) right side premature contact","(B) left side premature contact","(C) bilateral open bite","(D) right side open bite"],"answer":0,"image":"ya4-112-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-71","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"40歲女性病人因長期顳顎關節疾病困擾就醫，在進行核磁共振造影（MRI）檢查後得出T1-weighted影像如 左、右二圖。左圖為閉口時所代表之矢狀面（sagittal view）影像，右圖為最大張口時之矢狀面（sagittal view）影像。由左右二圖對於顳顎關節盤診斷，下列何者正確？","options":["(A) right disc displacement with reduction","(B) right disc displacement without reduction","(C) left disc displacement with reduction","(D) left disc displacement without reduction"],"answer":3,"image":"ya4-112-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-72","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"關於鎖骨顱骨發育不全（cleidocranial dysplasia）的敘述，下列何者錯誤？","options":["(A) 顱骨發育過小","(B) 上顎發育過小","(C) 乳牙延遲脫落","(D) 常會出現多生牙"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-112-2-73","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"附圖為那種X光影像？","options":["(A) submentovertex projection","(B) Waters projection","(C) reverse Towne projection","(D) oblique lateral projection"],"answer":0,"image":"ya4-112-2-73.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-74","subject":"ya4","topic":"放射影像診斷","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"承上題，這個影像，最不易看到下列何者？","options":["(A) 額竇（frontal sinus）","(B) 卵圓孔（foramen ovale）","(C) 蝶竇（sphenoid sinus）","(D) 顴骨弓（zygomatic arch）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-75","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"關於齲齒的影像學檢查，下列何者正確？①從一張影像品質良好的根尖片上，可以判定齲齒的狀態為已停止 或進行中 ②3號片易造成影像重疊，一般不建議用來作為咬翼片檢查鄰接面齲齒之用 ③絶大多數的鄰接面 齲齒起源於接觸點（contact point）和游離牙齦（free gingival）之間而非牙齦下，由此可和cervical burnout區 別 ④侷限於enamel範圍內的齲齒，若脫鈣程度達20%，即可藉由例行的X光片檢查出來","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-76","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"下列何種疾病的X光影像常呈現如洋蔥皮樣外形（onion-skin appearance），且病變區域牙齒常為非活性牙 （non-vital teeth）？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 加勒氏骨髓炎（Garre's osteomyelitis）","(C) 複合性牙瘤（compound odontoma）","(D) 骨之柏哲德氏病（Paget disease of bone）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-77","subject":"ya4","topic":"口腔病理基礎","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"下列何種疾病，最可能呈現毛玻璃狀放射線不透過性病灶（ground glass radiopacity）？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 牙骨質骨發育不良（cemento-osseous dysplasia）","(C) 柏哲德氏病（Paget disease）","(D) 嘉德耐氏症候群（Gardner's syndrome）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-78","subject":"ya4","topic":"全身性疾病與急症","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"下列何種疾病最可能造成圖中X光影像之變化？","options":["(A) 血友病（hemophilia）","(B) 週期性嗜中性白血球減少症（cyclic neutropenia）","(C) 地中海型貧血（thalassemia）","(D) 惡性貧血（pernicious anemia）"],"answer":2,"image":"ya4-112-2-78.jpeg","clinical_level":"一般"},{"id":"ya4-112-2-79","subject":"ya4","topic":"放射線原理與技術","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"區分細微物體影像的能力最容易受下列何者所影響？","options":["(A) 對比解析（contrast resolution）","(B) 空間解析（spatial resolution）","(C) 平面解析（flat resolution）","(D) 矢狀解析（sagittal resolution）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-112-2-80","subject":"ya4","topic":"口腔外科基礎","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"有關減少放射線性骨壞死（osteoradionecrosis）的作法，下列何者不建議使用？","options":["(A) 將所有照射範圍內之牙齒拔除，可減少放射線性骨壞死","(B) 放射線治療後，儘量避免拔牙","(C) 放射線治療後6個月內，應儘量避免於照射部位實施X光攝影","(D) 如須利用外科手術來處置時，應儘量應用無外傷性（atraumatic）之手術技術"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-1","subject":"ya4","topic":"齒源性感染與藥物","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"哺乳的病人，罹患牙冠周圍炎，應使用下列何種抗生素比較安全？","options":["(A) ampicillin","(B) cephalexin","(C) tetracycline","(D) metronidazole"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-2","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"一般下顎第一大臼齒，拔除後拔牙窩傷口之癒合形態屬於下列何者？","options":["(A) primary intention","(B) secondary intention","(C) tertiary intention","(D) fourth intention"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-3","subject":"ya4","topic":"植牙外科","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"植體置放時壓迫到下齒槽神經，但未造成神經 axon 或 endoneurium 連續性喪失，此時所造成的神經傷害稱為 下列何者？","options":["(A) neurapraxia","(B) axonotmesis","(C) neurotmesis","(D) neuralgia"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-4","subject":"ya4","topic":"口腔外科基礎","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"關於發炎期（inflammatory stage）的敘述，下列何者錯誤？","options":["(A) 傷口處在發炎期，組織中的嗜中性白血球比例升高","(B) 會有紅腫熱痛的現象","(C) 可能會有導致部分組織功能受限或喪失的現象","(D) 會產生水腫（edema）現象"],"answer":[0,1,2,3],"image":"","clinical_level":"重點","explanation_pending":false},{"id":"ya4-113-1-5","subject":"ya4","topic":"口腔外科基礎","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"為防止皮瓣壞死，有關口內皮瓣（flap）之設計，下列何者正確？","options":["(A) 若皮瓣底部（base）有主要血管供應（axial blood supply），則皮瓣尖端（tip）可容許較底部為寬","(B) 皮瓣長度最多不應超過底部寬度 1.5 倍","(C) 不建議皮瓣底部寬度大於皮瓣長度，以避免皮瓣翻轉不易","(D) 不建議皮瓣帶有主要血管供應（axial blood supply），以免皮瓣翻轉時血管阻塞，甚至容易造成出血"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"下列有關考慮使用血管收縮素的敘述何者最不適當？","options":["(A) 牙科治療程序需較長時間者，要考慮配合有加血管收縮素的麻藥","(B) 若治療過程中須局部止血可以加入含有 norepinephrine 的麻藥，效果最佳","(C) felypressin 具有較低的心血管刺激作用並且較少引起心律不整；可用於 ASA III 和 IV 心血管風險患者","(D) 以 lidocaine 為主要麻醉成分的局部麻醉藥中，無論加入 1：50,000，1：100,000，1：200,000 的腎上腺 素，均可以使麻藥作用時間延長到近一個小時"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"後上齒槽神經阻斷（posterior superior alveolar nerve block）不一定可以麻醉上顎第一大臼齒之那一牙 根？","options":["(A) 腭側根","(B) 遠心頰側根","(C) 近心頰側根","(D) 近心及遠心頰側根"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"施行上顎牙齒局部麻醉時，最容易引起顏面神經麻痺的部位是？","options":["(A) 門齒","(B) 犬齒","(C) 小臼齒","(D) 大臼齒"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-9","subject":"ya4","topic":"口腔外科基礎","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"下列有關 role of the opposite hand 的敘述何者正確？","options":["(A) 指手術者的慣用手","(B) 具穩定病人下顎的功能","(C) 易遮住照明口腔的光線","(D) 可在同一時間執行所有功能"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"下列何者是拔智齒的禁忌症？ ①老年人 ②身體不健康 ③位於惡性腫瘤內 ④牙冠周圍炎","options":["(A) 僅①","(B) 僅②③","(C) ②④","(D) ①②③（一律給分）"],"answer":[0,1,2,3],"image":"","clinical_level":"一般","explanation_pending":false},{"id":"ya4-113-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"下列那個因素會增加阻生齒拔除的困難度？","options":["(A) 牙根尚未發育完成","(B) 較寬的牙周韌帶","(C) 較薄的牙囊（dental follicle）","(D) 融合的牙根"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-12","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"當阻生齒牙冠周圍的濾胞空間（follicular space）至少大於多少毫米時，可合理診斷有含齒囊腫之存在？","options":["(A) 1","(B) 3","(C) 5","(D) 8"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-13","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"手術拔除下顎第三大臼齒阻生齒，可能因舌側骨板斷裂，造成牙齒被推入到何組織間隙？ ①頦下間隙（submental space） ②顳下間隙（infratemporal space） ③顎下間隙（submandibular space） ④翼下顎間隙（pterygomandibular space）","options":["(A) 僅①②","(B) 僅③④","(C) ①②③","(D) ②③④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-14","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"使用拔牙鉗五個主要動作的先後順序為何？ ①頰側施力 ②舌側施力 ③牽引（tractional force） ④根尖方向施壓 ⑤旋轉","options":["(A) ①②③④⑤","(B) ④①②③⑤","(C) ④②①⑤③","(D) ④①②⑤③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-15","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"有關複雜性拔牙結束縫合時之敘述，下列何者錯誤？ ①在齒槽窩上方縫合可維持血塊的穩定 ②為了達到止血效果，應將傷口緊緊縫合 ③如使用袋狀瓣（envelope flap），縫合時只需縫 papillae 處即可 ④縫合時應先由皮瓣活動端進針 ⑤進針點應離傷口邊緣小於 1 mm，以免傷害過多的軟組織 ⑥結（knot）應打在切線兩側，以免施予過大壓力於切線上","options":["(A) ①②③④⑤⑥","(B) 僅②③⑥","(C) 僅②⑤","(D) 僅①②③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-16","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"以手術切開引流治療感染區域時，下列何種檢查對於引流部位與路徑的參考價值最高？","options":["(A) 側顱攝影","(B) 根尖攝影","(C) 全顎攝影","(D) 頭頸部電腦斷層"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-17","subject":"ya4","topic":"齒源性感染與藥物","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"可自行合成 ß-lactamase 的細菌會對下列何者產生抗藥性？","options":["(A) vancomycin","(B) erythromycin","(C) penicillin","(D) clindamycin"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-18","subject":"ya4","topic":"齒源性感染與藥物","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"下顎智齒感染，穿通舌側皮質板（lingual cortical plate perforation）並侷限在下顎舌骨肌（mylohyoid muscle）以上，將引起下列何間隙（space）之感染？","options":["(A) 下顎舌骨間隙（mylohyoid space）","(B) 下顎下間隙（submandibular space）","(C) 舌下間隙（sublingual space）","(D) 側咽間隙（lateral pharyngeal space）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-19","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"一位住院齒源性感染患者，接受靜脈抗生素治療 2～3 天後感染情形惡化，此時進行患者再次評估時，下列何 者應最優先評估？","options":["(A) 患者 airway 是否通暢， 是否受腫脹壓迫","(B) 評估治療感染源牙齒，甚至提早拔除","(C) 儘早使用氧氣面罩於呼吸道完全受感染阻塞的病患","(D) 使用全顎攝影（panoramic view）來評估頸部腫脹部分"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-20","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"下列何者最不易導致顎骨骨髓炎？","options":["(A) 纖維性發育異常（fibrous dysplasia）","(B) 糖尿病","(C) 罹患癌症","(D) 自體免疫疾病"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-21","subject":"ya4","topic":"植牙外科","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"可支持上顎全顎固定式贋復物的植體數目最少需要多少顆？","options":["(A) 2","(B) 4","(C) 6","(D) 8"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-22","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"拔完牙後將骨移植（bone graft）置入齒槽（socket），做為齒槽嵴保存術（alveolar ridge preservation），應放入多少數量的移植骨較為適合？","options":["(A) 齒槽嵴深度的四分之三","(B) 齒槽嵴深度的一半","(C) 超過齒槽嵴 5mm","(D) 與齒槽嵴等高"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-23","subject":"ya4","topic":"口腔外科基礎","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"關於進行腭隆突（torus palatinus）骨去除術時的敘述，下列何者錯誤？","options":["(A) 須注意避免鼻黏膜穿孔","(B) 當腭隆突大小不影響到假牙製作時，可不予處理","(C) 須注意升腭動脈（ascending palatine artery）血管的走向","(D) 手術後戴上暫時性的假牙或手術固定裝置（splint）可以減少血腫的發生"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-24","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"對於多房性造釉細胞瘤（multilocular ameloblastoma），下列手術治療中，何者最不容易復發？","options":["(A) 顎骨塊狀切除術（block resection of jaw bone）","(B) 剜出術（enucleation）加上刮除術（curettage）","(C) 刮除術（curettage）","(D) 造袋術（marsupialization）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-25","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"有關 fibrous dysplasia 的敘述，下列何者錯誤？","options":["(A) 病灶影響顎骨時，通常會造成顎骨疼痛合併部分腫脹","(B) 在臨床上，被認定為不明病因的 developmental hamartomatous fibro-osseous disease","(C) 其中一種類型的 fibrous dysplasia 稱為 McCune-Albright syndrome ，此時病灶合併多處部位包括 hyperpigmentation and endocrine disturbances","(D) X 光的典型表現為 ground-glass opacity without clearly defined borders"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"病人於切片檢查後，病理報告顯示為舌部鱗狀細胞癌時，下列何者非癌症分期必須檢查之項目？","options":["(A) 頭頸部之電腦斷層或磁共振","(B) 胸部 X 光","(C) 腹部超音波","(D) 吞嚥功能"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-27","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"舌癌的病人，檢查結果顯示患者之腫瘤大小為 6×5 公分，侵犯 hyoglossus、genioglossus，且頸部淋巴結於 同側疑似有兩顆淋巴結轉移，但其餘器官並未發現有癌細胞侵犯，此時癌症分期為下列何者？","options":["(A) cT3N2bM0","(B) cT4aN2bM0","(C) pT3N2bM0","(D) pT4aN2bM0"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-28","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"舌部鱗狀細胞癌合併頸部淋巴轉移的病人，醫師告知患者可能之手術風險時，下列何者不屬之？","options":["(A) 頸動脈及頸靜脈破裂引發大出血。","(B) 術後乳糜管滲漏","(C) 食道撕裂（laceration）","(D) 左手手臂無法順利上舉"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-29","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"關於不完全角化齒源性角化囊腫（parakeratinized odontogenic keratocyst）的敘述，下列何者正確？","options":["(A) 佔齒源性角化囊腫（odontogenic keratocyst）的大多數，較為常見","(B) 在全口環狀攝影 X 光片下，大多是呈現單房性（unilocular）的放射性透光病灶","(C) 鱗狀上皮較薄且光滑，約有 2 到 3 個細胞厚度","(D) 復發率極低"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-113-1-30","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"下列何者不屬於發炎性齒源性囊腫（inflammatory odontogenic cyst）？","options":["(A) 頰側分叉囊腫（buccal bifurcation cyst）","(B) 萌牙囊腫（eruption cyst）","(C) 根尖囊腫（radicular cyst）","(D) 殘餘囊腫（residual periapical cyst）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-31","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"下列何種手術治療齒源性角化囊腫（odotogenic keratocyst）最為適當？","options":["(A) 減壓術（decompression）","(B) 剜除術（enucleation）","(C) 剜除術合併刮除術（enucleation and curettage）","(D) 骨塊狀切除術（block resection）"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-113-1-32","subject":"ya4","topic":"口腔病理基礎","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"某患者因右側後下顎囊腫，實施造袋術，並記錄他的口腔內照片（如圖一）及 X 光檢查（如圖二），下列敘 述何者正確？ 圖一 圖二","options":["(A) 造袋術的適應症，通常也是剜出術的優點","(B) 造袋術的缺點，包括操作處理較複雜，可能對重要結構造成損傷","(C) 若囊腫內襯夠厚且條件允許的話，可沿著開口周圍將囊腫縫至口腔黏膜，或是可於傷口處放置填塞紗布約兩 週的時間","(D) 患者必須每天使用針筒沖洗囊腫腔數次，持續數週待傷口完成初級癒合後，即完成治療"],"answer":2,"image":"ya4-113-1-32.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"關於阻塞型睡眠呼吸中止症（obstructive sleep apnea）的敘述，下列何者錯誤？","options":["(A) 病人睡覺時產生嚴重的缺氧","(B) 潛在地引發病人的心肺功能的異常","(C) 常見於下顎骨發育過多（mandibular excess）","(D) 可利用下顎骨移動手術來增加呼吸道的空間"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"上顎骨垂直過度生長（vertical maxillary excess）常會伴隨下列何種顏面特徵？","options":["(A) 前牙開咬（open bite）","(B) 下 1／3 顏面變短（shortening of lower third of face）","(C) 鼻翼變寬（widening of nose alar base）","(D) 嘴唇過度閉合（lip overclosure）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-35","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"正常人由側面將臉部長度等分為數個部分，則從下唇頂點到下巴最下一點之間的距離佔側臉長度的幾分之 幾？","options":["(A) 2／3","(B) 2／6","(C) 2／9","(D) 2／12"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"關於頭痛的敘述，下列何者正確？","options":["(A) 偏頭痛（migraine）多半在青少年期就已發病，約 40%患者在發作時有前兆（aura），症狀持續四至七十二 小時，可能由顳顎關節症候群引發","(B) 緊張型頭痛（tension-type headache）是最常見的頭痛，男性居多，一個月至少發作十五天以上，可能由 肌筋膜疼痛引發","(C) 叢發性頭痛（cluster headache）症狀持續十五至一百八十分鐘，一天可能發作數次，無規律性，喝酒及抽 菸可能引發","(D) 巨細胞動脈炎（giant cell arteritis）表現為鈍痛或顳部疼痛，與類風濕性關節炎有關，可能引發咀嚼障 礙（jaw claudication）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"關於叢發性頭痛（cluster headache），下列何者正確？","options":["(A) 為單側頭痛，以眼睛及顳部為中心，症狀持續十五至一百八十分鐘，一天可能發作數次，具規律性","(B) 患者以男性較多，一般二十多歲就發病，不論何時喝酒都會誘發頭痛","(C) 常伴有副交感神經症狀，如流淚、眼瞼下垂、瞳孔放大、流鼻水","(D) 常會造成上顎後牙區的疼痛，但因容易鑑別，不會造成不必要的牙科治療"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-38","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"對一位病人用棉花去輕碰某一部位，就引起痛感，但相同方式碰觸其他地方則不會痛，此種情形稱為：","options":["(A) 異質痛覺（allodynia）","(B) 感覺不良（dysesthesia）","(C) 痛覺過敏（hyperalgesia）","(D) 神經痛（neuralgia）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-39","subject":"ya4","topic":"唾液腺疾病","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"關於人體口腔小唾液腺的敘述，下列何者正確？","options":["(A) 新生兒時，小唾液腺已發育完全，具有分泌唾液的功能","(B) 小唾液腺的腺泡細胞，主要分泌為漿液","(C) 口腔包含有數萬個小唾液腺體，分泌的唾液大約佔所有唾液量的 5%","(D) 整個舌背面、硬腭區及附連牙齦等處的口腔黏膜，並不含有小唾液腺的分佈"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-40","subject":"ya4","topic":"唾液腺疾病","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"人體中由顎下腺所分泌的唾液，佔所有唾液量的百分比為多少？","options":["(A) 90％","(B) 70％","(C) 50％","(D) 30％"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-41","subject":"ya4","topic":"唾液腺疾病","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"給予患者顯影劑後，進行唾液腺攝影（sialography）檢查，主要可獲得三個不同階段的影像：①腺泡期（acinar phase） ②管道期（ductal phase） ③排空期（evacuation phase） 其依時間進行所出現影像的順序為：","options":["(A) ②①③","(B) ①②③","(C) ③①②","(D) ③②①"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"Le Fort I 骨折可能出現的症狀，下列何者錯誤？","options":["(A) epiphora","(B) auriculotemporal syndrome","(C) anterior open bite","(D) nonunion"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"參考所附圖，下面的敘述，何者最不合理？","options":["(A) 可能因為皮膚與撞擊物表面的摩擦 ，導致以上所見傷勢 以免導致皮膚缺損擴大","(B) 傷口不可以太徹底的清潔，以免導致皮膚缺損擴大 可考慮以敷料覆蓋保護","(C) 表淺的傷口，可考慮以敷料覆蓋保護 可能要照會口腔顎面外科醫師以移植方式治療","(D) 較深的傷口，可能要照會口腔顎面外科醫師以移植方式治療"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"關於骨折的敘述，下列何者錯誤？","options":["(A) 骨折通過已萌出牙齒的牙周膜為開放性骨折（open fracture）","(B) 骨折感染引起骨髓炎是一種病理性骨折（pathologic fracture）","(C) 多處骨折並相連的骨折是碎裂性骨折（comminuted fracture）","(D) 柳條狀骨折（greenstick fracture）是不完全骨折（incomplete fracture）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"六歲兒童下顎前牙區骨折時，優先選擇的處理方法為下列何者？","options":["(A) 上下顎間固定","(B) 壓克力板及環繞下顎式鋼絲固定（ （circum-mandibular wiring） 及鋼絲固定","(C) 開放性復位（open reduction）及鋼絲固定","(D) 開放性復位（open reduction）及迷你骨板 及迷你骨板（miniplate）固定"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"關於骨折第二級癒合（secondary healing）的敘述，下列何者正確？","options":["(A) 開放性骨折（open fracture）的癒合為第二級癒合","(B) 骨折超過二週以上才進行復位及固定，其癒合為第二級癒合","(C) 產生骨痂（callus）再骨化的癒合為第二級癒合","(D) 以纖維組織為主癒合的骨折為第二級癒合"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"有關唇腭裂相關障礙的敘述下列何者正確？","options":["(A) 在腭裂旁之多生齒須儘速拔除以利正常牙齒萌發","(B) 唇腭裂者 Class III malocclusion 大部分為 pseudoprognathism","(C) 唇腭裂者會因腭裂而造成吸吮及吞嚥反射功能喪失","(D) 唇腭裂者會因軟腭裂口而有利歐氏管開啟並減少中耳炎發生"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"下列有關腭裂手術之敘述，何者正確？","options":["(A) 如採兩階段手術，應先做硬腭，再做軟腭","(B) 硬腭手術，應合併骨移植","(C) 軟腭手術的閉合，需做三層縫合，即鼻腔黏膜層、肌肉層、口腔黏膜層","(D) W-Y 以及 U-shaped push back 兩種方法，目的在增加軟腭的寬度"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-1-49","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"一位以躺姿正接受牙科治療的病患，突發換氣過度症候群（hyperventilation syndrome），下列何種處理方 法最合理？","options":["(A) 維持平躺姿勢","(B) 給予 100% 氧氣","(C) 使用病患能夠聽懂的語言以安定情緒（reassurance）","(D) 立即使用紙袋呼吸法，直接送至急診室"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-50","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"一位正接受牙科治療的病患，呈現噁心、頻繁的吞嚥動作、感到焦慮、冒汗，下列何者可能即將發生？","options":["(A) 過敏性休克（anaphylactic shock）","(B) 換氣過度症候群（hyperventilation）","(C) 嘔吐（vomiting）","(D) 心肌缺血或梗塞（myocardial ischemia or infarction）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-51","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"一位長期酗酒的病人來診所要拔牙，需要注意事項之敘述，下列何者錯誤？","options":["(A) 拔牙前應先檢查病人肝功能","(B) 拔牙前應先檢查病人凝血功能","(C) 應給予較多的局部麻醉藥物","(D) 術後應避免開立 acetaminophen"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-52","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"當一位曾有狹心症（angina pectoris）病史 65 歲男性病患至門診，需要拔牙時，則下列注意事項中，何者 錯誤？","options":["(A) 應事先照會其心臟內科醫師，詢問詳情","(B) 要確定病人有隨身攜帶 nitroglycerin","(C) 必要時可以給予氧氣緩和胸悶症狀","(D) 使用的局部麻醉劑，不應該含有血管收縮劑（epinephrine）的成分"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-53","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"幼時跌倒，左側下顎骨髁頭骨折後，嘴巴漸漸張不開，則長大後咬合通常產生下列何種問題？","options":["(A) Class I occlusion","(B) Class II occlusion","(C) Class III occlusion","(D) Scissor bite"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"反復性的顳顎關節脫臼，病人復位後，需要限制張口多久？","options":["(A) 2～4 天","(B) 7～10 天","(C) 2～4 週","(D) 2～4 月"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"有關顳顎關節肌筋膜疼痛之治療，不包括下列何者？","options":["(A) 肌肉痛點直接注射（muscle injection of trigger points）","(B) 經皮式電刺激療法（transcutaneous electrical nerve stimulation）","(C) 顳顎關節鏡手術（arthroscopy）","(D) 超音波治療（ultrasonic therapy）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-56","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"關於愛滋病病人的隱私權敘述，下列何者正確？","options":["(A) 病人可以不告知醫護人員他的病情","(B) 醫護人員應將他的病情告知受轉介醫護人員","(C) 病人可以不揭露他的感染來源","(D) 病人要求隱匿病情（包括其配偶），醫師應予配合"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"下列何種電磁輻射（electromagnetic radiation）的波長（wavelength）最長？","options":["(A) γ-ray","(B) X-ray","(C) UV","(D) microwave"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"於牙科診所服務之非輻射工作人員，其年劑量最高不得超過多少 mSv 有效等效劑量？","options":["(A) 1","(B) 2","(C) 5","(D) 20"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"下列何種中心射線（central ray）的位置偏差是造成附圖中牙冠重疊現象最可能的原因？","options":["(A) 距離過近","(B) 距離過遠","(C) 水平方向","(D) 垂直方向"],"answer":2,"image":"ya4-113-1-59.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-60","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"下列何種病變，使用水平咬翼片（horizontal bite-wing film）拍攝不到？","options":["(A) 齲齒（caries）","(B) 齒間骨喪失（interdental bone loss）","(C) 齒外齒（dens evaginatus）","(D) 大臼齒牙根尖外吸收（external resorption）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"下列那種拍攝方式，其下顎前區（anterior mandible）的影像最不清楚？","options":["(A) lateral cephalometric projection","(B) submentovertex projection","(C) Waters projection","(D) posteroanterior cephalometric projection"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"關於放射線同位素攝影（radioisotope imaging）優點的敘述，下列何者錯誤？","options":["(A) 可偵測目標組織的功能狀態","(B) 所有類似的目標組織可一次檢查","(C) 解析度佳","(D) 可使用電腦分析及強化結果"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"下列何者不是對使用口腔攜帶式 X 光機器拍攝者的保護措施？","options":["(A) 較短的曝光時間（exposure time）","(B) 較長的 X 光源到皮膚的距離（spot-to-skin distance）","(C) 內部屏蔽裝置（internal shieldings）","(D) 瞄準器（aiming cylinder）屏蔽裝置"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-64","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"下圖中黑色箭頭所指的構造最可能為何？","options":["(A) 下顎管（mandibular canal）","(B) 下顎舌骨嵴（mylohyoid ridge）","(C) 外斜嵴（external oblique ridge）","(D) 下顎小舌（lingula mandibulae）"],"answer":2,"image":"ya4-113-1-64.jpeg","clinical_level":"重點"},{"id":"ya4-113-1-65","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"下圖環口 X 光影像中，箭頭所指之放射線不透過性影像為何？","options":["(A) 第三節頸椎（C3）","(B) 舌骨（hyoid bone）","(C) 甲狀軟骨（thyroid cartilage）","(D) 涎石（sialolith）"],"answer":1,"image":"ya4-113-1-65.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-66","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"在上顎正中門齒的根尖影像中，當門齒孔（incisive foramen）直徑大於多少 mm 時，須懷疑可能是囊腫？","options":["(A) 1","(B) 3","(C) 5","(D) 10"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-67","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"下圖中，箭頭所標示的牙周炎齒槽突（alveolar process）變化，分別為何？","options":["(A) a：齒間陷口（interdental crater），b：水平骨缺損（horizontal bone loss）","(B) a：垂直骨缺損（vertical bone loss），b：齒間陷口（interdental crater）","(C) a：水平骨缺損（horizontal bone loss），b：垂直骨缺損（vertical bone loss）","(D) a：水平骨缺損（horizontal bone loss），b：齒間陷口（interdental crater）"],"answer":3,"image":"ya4-113-1-67.jpeg","clinical_level":"重點"},{"id":"ya4-113-1-68","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"口內 X 光最容易觀察到下列那種牙周組織的破壞？","options":["(A) 發炎的牙齦","(B) 舌側皮質骨的高度","(C) 近心側的垂直骨缺損","(D) 上顎大臼齒的頰側根叉"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-69","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"圖中 白色箭頭與 黑色箭頭所標示的變化最可能為何？","options":["(A) 根尖肉芽腫（periapical granuloma）； 硬化性骨炎（sclerosing osteitis）","(B) 根尖肉芽腫（periapical granuloma）； 內生贅骨（enostosis）","(C) 早期根尖牙骨質骨發育不良（cemento-osseous dysplasia）； 內生贅骨（enostosis）","(D) 與 標示的變化都屬於根尖牙骨質骨發育不良（cemento-osseous dysplasia）病灶的一部分"],"answer":0,"image":"ya4-113-1-69.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-70","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"年幼的小孩（young child）接受單次輻射劑量超過多少 Gy 時，會造成不可逆的生長遲滯及身材矮小？","options":["(A) 1","(B) 4","(C) 10","(D) 20"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-71","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"附圖 X 光影像中箭頭所指之病灶，下列何者為最可能的診斷？","options":["(A) calcified atherosclerotic plaques","(B) calcified lymph nodes","(C) phleboliths","(D) sialoliths"],"answer":2,"image":"ya4-113-1-71.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-72","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"圖中之 X 光影像為何種拍攝方式？","options":["(A) posteroanterior projection","(B) Waters projection","(C) reverse Towne projection","(D) oblique lateral projection"],"answer":2,"image":"ya4-113-1-72.jpeg","clinical_level":"重點"},{"id":"ya4-113-1-73","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"承上題，下列何種狀況最適合採用此拍攝方式評估？","options":["(A) 慢性鼻竇炎","(B) 下顎骨髁頭骨折","(C) 眼眶骨骨折","(D) 顴骨骨折"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-74","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"病人的顱骨 X 光如圖所示，最可能是那一種疾病？","options":["(A) 鎖骨顱骨發育不全（cleidocranial dysplasia）","(B) 骨質石化病（osteopetrosis）","(C) 畸形性骨炎（osteitis deformans）","(D) 骨性纖維發育不良（fibrous dysplasia of bone）"],"answer":1,"image":"ya4-113-1-74.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-75","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"承上題，下列敘述何者與這個疾病有關？","options":["(A) 又稱為大理石骨病（marble bone disease）","(B) 病人血清鹼性磷酸酶（alkaline phosphatase）數值可能極高","(C) 常會出現多生牙","(D) 皮膚出現咖啡牛奶（café-au-lait）斑"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-76","subject":"ya4","topic":"放射影像診斷","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"附圖 X 光片所呈現的影像，其臨床診斷最可能為下列何者？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 囊腫（cyst）","(C) 顳顎關節脫位（TMJ dislocation）","(D) 造釉細胞瘤（ameloblastoma）"],"answer":2,"image":"ya4-113-1-76.jpeg","clinical_level":"重點"},{"id":"ya4-113-1-77","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"25 歲女性因矯正接受側顱 X 光檢查如附圖所示，發現其頭顱邊緣有毛髮狀（hair-on-end）影像，白框中區 域放大如右下圖所示，此病人最可能罹患下列何種疾病？","options":["(A) 貧血（anemia）","(B) 週期性嗜中性白血球減少症（cyclic neutropenia）","(C) 血友病（hemophilia）","(D) 白血病（leukemia）"],"answer":0,"image":"ya4-113-1-77.jpeg","clinical_level":"一般"},{"id":"ya4-113-1-78","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"洋蔥皮狀放射線不透性（onion-skin radiopacity）較不會出現在下列那個疾病？","options":["(A) 位於長骨（long bone）之愛溫氏肉瘤（Ewing sarcoma）","(B) 增殖性骨膜炎（proliferative periostitis）","(C) 加勒氏骨髓炎（Garre's osteomyelitis）","(D) 纖維性發育不良（fibrous dysplasia）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-79","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"與傳統影像相比，下列何者不是數位影像的特點？","options":["(A) 完全依賴電腦與網路","(B) 病人的輻射暴露量低","(C) 完全沒有造成環境污染","(D) 影像可以事後校正"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"有關等效劑量（equivalent dose）與有效劑量（effective dose）之敘述，下列何者錯誤？","options":["(A) 等效劑量與放射線的性質有關，X 光的 radiation weighting factor 為 1","(B) 有效劑量主要是用於輻射防護，而且是用來表示對生物的效應","(C) 一般而言，有效劑量常比等效劑量大","(D) α射線之等效劑量是一般輻射線中最強，其 radiation weighting factor 為 20"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-1","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"下列關於笑氣鎮靜的敘述，何者適當？①在21℃環境中，笑氣在鋼瓶壓力下呈現液態，而氧氣在鋼瓶壓力下 呈現氣態 ②妊娠前三個月孕婦不宜使用笑氣 ③笑氣安全性高，只需術前測量一次生命徵象後，便可使用","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"下列對於死腔的敘述，何者正確？","options":["(A) 死腔是傷口經二級癒合後所形成，通常充滿肉芽組織及可能的致病菌","(B) 對於包含多層組織的傷口，先將表皮層緊密縫合，即可有效減少死腔的形成","(C) 若無法將組織縫合在一起，可填塞含抗生素的敷料，以減少死腔感染的機會","(D) Penrose引流管為常用的抽吸式引流裝置"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-3","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"下列關於預防性抗生素的敘述，何者正確？","options":["(A) 裝置心律調節器病人，於簡單拔牙手術前須使用預防性抗生素","(B) 術前使用抗生素預防感染性心內膜炎者，術後必須追加一次劑量","(C) 為預防感染性心內膜炎，低度侵犯性牙科處置發生非預期性出血，可於事發後4小時內補投預防性抗生素","(D) 2016年美國骨科學會建議置換人工關節之病人，拔牙前均須使用預防性抗生素"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-4","subject":"ya4","topic":"口腔外科基礎","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"下列有關牙床皮瓣設計的說明，何者正確？","options":["(A) 為使牙齦獲得較多血液供給，皮瓣牙齦端的寬度要比基部大","(B) 皮瓣切線位於上顎犬齒區隆突較佳，使皮瓣較易被完整剝離","(C) 皮瓣切線最適合使用11號刀片配3號刀柄進行切割","(D) 皮瓣切線下方必須有健康骨骼，以提高皮瓣存活率"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-5","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"2％ lidocaine 1.8 mL含有多少mg的lidocaine成分？","options":["(A) 18 mg","(B) 36 mg","(C) 180 mg","(D) 360 mg"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"根據美國麻醉醫學會（ASA）對病人身體狀況的分類，下列敘述何者錯誤？","options":["(A) ASAⅠ為健康的求診者","(B) ASAⅡ為帶有輕度系統性疾病的病人，病人治療期間需小心使用儀器監測","(C) ASAⅤ為腦死，器官準備捐出為移植所用的病人","(D) 若ASA分類在Ⅲ或以上的病人，需手術治療時，可考慮轉診至醫院"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"下列有關神經阻斷注射後，麻醉範圍的敘述，何者正確？","options":["(A) 大腭神經：硬腭後部及覆蓋的軟組織，前側範圍可至第一小臼齒，內側則至中線處","(B) 鼻腭神經：硬腭前部、中間部位及覆蓋的軟組織，向後可至雙側第一大臼齒的近心側範圍","(C) 中上齒槽神經：上顎第一與第二小臼齒、完整上顎第一大臼齒的牙髓，及上述牙齒的頰側牙周組織與骨組 織","(D) 後上齒槽神經：上顎第二與第三大臼齒的牙髓，及上述牙齒的頰側牙周組織與骨組織"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-8","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"下列有關智齒拔除術後的處置，何者最不適當？","options":["(A) 可以在權衡效益與風險後，給與口服或靜脈注射類固醇消腫","(B) 術後立即熱敷對於消腫極為有效","(C) 視病患拔牙前狀況，術後不一定要開立抗生素","(D) 可以告知病人術後腫約於一週後消退"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"埋伏第三大臼齒拔除最理想的時機為何？","options":["(A) 牙根形成小於1/3","(B) 牙根形成1/3～2/3","(C) 牙根形成接近完全，但根尖尚未閉合","(D) 牙根完全形成且根尖閉合"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"關於拔牙工具的使用，下列敘述何者錯誤？","options":["(A) 先以牙周刀（periotome）切斷牙周韌帶，有助於保留齒槽形態","(B) 拔牙挺前端的凸面是作用在頂住牙根表面","(C) 三角形的拔牙挺有區分左右兩種方向","(D) 可考慮先使用拔牙挺頂鬆牙齒後再使用拔牙鉗（forceps）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"關於下顎阻生第三大臼齒分類的敘述，下列何者正確？","options":["(A) 依照與下顎枝（ramus）前緣的關係分為Pell and Gregory type A、B、C","(B) 垂直阻生齒（vertical impaction）是最常見的阻生情形","(C) 近心阻生齒（mesioangular impaction）是最罕見的阻生情形","(D) 遠心阻生齒（distoangular impaction）被認為是最難處理的阻生齒"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"關於拔除阻生齒後造成乾性齒槽（dry socket），下列敘述何者錯誤？","options":["(A) 拔牙傷口以大量生理食鹽水沖洗，有助於降低發生率","(B) 良好的無菌技術及無創傷性（atraumatic）操作，有助於預防其發生","(C) 局部沖洗及施放鎮痛藥物可舒緩其症狀","(D) 局部使用eugenol會惡化傷口"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-13","subject":"ya4","topic":"齒源性感染與藥物","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"75歲女性，主訴右臉紅腫，併張口受限。詢問病史表示2個月前至診所拔牙，口內檢查發現拔牙傷口未癒 合，伴隨化膿。環口放射線攝影發現拔牙區呈現不規則放射線透射，有蟲蛀（moth eaten）徵象。依上述資 料，回答下列三題。 這位病人最可能是下列何種診斷？","options":["(A) suppurative osteomyelitis","(B) acute alveolitis","(C) osteomyelitis with proliferative periostitis","(D) sclerosing osteomyelitis"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-14","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"進一步追問，病人家屬才想起病人有乳癌病史，曾經接受放射線以及雙磷酸鹽類藥物治療。下列何者為此病 人最可能的原發性疾病？","options":["(A) osteoradionecrosis","(B) medication related osteonecrosis of jaws","(C) actinomycosis","(D) Garre osteomyelitis"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-15","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"下列何者不是上述疾病之處置方法？","options":["(A) 移除感染源","(B) 採取檢體進行細菌抗生素敏感性測試","(C) 靜脈注射ketoconazole 4週","(D) 手術清創移除壞死骨頭"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-16","subject":"ya4","topic":"口腔外科基礎","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"關於補綴前手術，下列敘述何者錯誤？","options":["(A) 創造合適的支持結構，並保存最大量的軟硬組織","(B) 修整不規則的齒槽骨及軟組織","(C) 需考慮上下顎間的咬合關係","(D) 活動義齒及植牙重建，兩者治療模式所需的齒槽嵴條件相同"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-17","subject":"ya4","topic":"植牙外科","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"有關於後上顎部位植入人工牙根的敘述，何者錯誤？①後上顎之骨質通常較下顎骨為佳，預期完成骨整合的 時間較短 ②若曾接受頭頸部放射線治療，植牙失敗率極高，是絕對禁忌症 ③若骨嵴高度嚴重不足，可先 施行上顎竇增高術合併骨移植，並建議於6週後再植入人工牙根","options":["(A) 僅①②","(B) 僅①③","(C) ①②③","(D) 僅②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-18","subject":"ya4","topic":"植牙外科","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"關於人工植牙和自然牙周圍軟組織的敘述，下列何者正確？①軟組織由被上皮覆蓋的結締組織組成 ②骨嵴 上（supracrestal）的結締組織纖維方向兩者相同 ③植牙周圍軟組織具有緻密結締組織帶 ④自然牙具有 牙周韌帶，而植牙則直接與齒槽骨接觸","options":["(A) 僅①②③","(B) 僅②④","(C) ①②③④","(D) 僅①③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-19","subject":"ya4","topic":"植牙外科","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"關於齒槽骨重建使用xenograft的敘述，下列何者正確？","options":["(A) 移植材料不易取得","(B) 移植物具有骨誘導性（osteoinductive）","(C) 指移植體來自不同物種","(D) 手術必須在全身麻醉下進行"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-20","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"根據美國2020年的一項研究報告，口腔扁平苔癬病灶區發生鱗狀細胞癌時，下列敘述何者正確？","options":["(A) 與吸菸習慣呈正相關","(B) 易發生淋巴轉移","(C) 易復發","(D) 存活率較低"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-21","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"下列那一種齒源性腫瘤（odontogenic tumors）採取enucleation and/or curettage，復發率最低？","options":["(A) 造釉細胞瘤（ameloblastoma）","(B) 鈣化上皮齒源瘤（calcifying epithelial odontogenic tumor）","(C) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(D) 齒源性黏液瘤（odontogenic myxoma）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-22","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"下列關於口腔及口咽鱗狀細胞癌危險因子之敘述，何者錯誤？","options":["(A) HPV與口咽鱗狀細胞癌之預後有關聯性","(B) 同時有飲酒與抽菸之習性，會加乘罹患口腔癌的風險","(C) HSV-1與口腔鱗狀細胞癌之預後有關聯性","(D) 飲用烈酒與酒精攝取量大者，其罹患口腔癌之風險較高"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"關於口腔癌放射線治療，下列敘述何者正確？","options":["(A) 腫瘤位於舌腹或口底，較易淋巴轉移，因此術後均須接受放射線治療","(B) 為確保術後不復發，手術前必須接受放射線治療","(C) 腫瘤過大無法切除或術後無法保留說話與吞嚥功能時，可選擇放射線治療","(D) 頸部淋巴實施放射線治療，通常劑量為500 cGy分25次進行"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-24","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"下列關於oral potentially malignant disorders（OPMDs）的敘述，何者錯誤？","options":["(A) 扁平苔癬屬於OPMDs","(B) 組織形態改變且較正常部位容易產生癌症者，稱之為癌前病變","(C) 白斑合併有上皮發育異常（dysplasia）時，此白斑才能稱之為癌前病變","(D) 均質性白斑之惡性轉變風險較非均質性白斑低"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"2001年美國頭頸醫學會將頸部分為6個區域，下列那個術式並不會移除第1區到第5區所有的淋巴結 （levelⅠtoⅤnodes）？","options":["(A) 選擇性頸部廓清術（selective neck dissection）","(B) 改良式根治性頸部廓清術（modified radical neck dissection）","(C) 根治性頸部廓清術（radical neck dissection）","(D) 延伸式頸部廓清術（extended neck dissection）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-26","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"有關cemento-osseous dysplasia的敘述，下列何者錯誤？","options":["(A) 好發於tooth-bearing 區域","(B) 是常見的fibro-osseous disease，但因通常沒有臨床症狀，不一定需要手術治療","(C) 好發於男性及亞洲人族群","(D) 大部分病灶不會造成顎骨膨大"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"對於進行囊腫造袋術（marsupialization）的步驟，下列敘述何者正確？","options":["(A) 含齒囊腫的牙齒正常萌發後，仍需第二階段手術","(B) 只需部分切除軟組織送病理檢查，第二階段手術的必要性很低","(C) 若囊腫侵犯到鼻腔或鼻竇，可從鼻側開口","(D) 若手術檢視到囊腫上皮有潰瘍或增厚，可等到囊腫縮小再進行切片檢查"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"有關齒源性角化囊腫（odontogenic keratocyst）的敘述，下列何者錯誤？","options":["(A) 可能是不完全角化（parakeratinized）或完全角化（orthokeratinized）的上皮","(B) 影像檢查可能是單囊性或多囊性","(C) 大型的病灶可以先行造袋術（marsupialization），但通常需要追加剜除術（enucleation）及刮除術 （curettage）","(D) 比含齒囊腫有較高的復發率"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-113-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"關於鈣化齒源性囊腫（calcifying odontogenic cyst）之敘述，下列何者正確？","options":["(A) 標準治療為剜除術（enucleation）與刮除術（curettage）","(B) 又稱為Gardner's cyst","(C) 手術需合併使用硝酸銀移除鈣化上皮","(D) 多發生在周邊組織（peripheral），少發生在骨內（intraosseous）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-30","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"原基性囊腫（primordial cyst），病理切片後最常被確認為下列何者？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 側位牙周囊腫（lateral periodontal cyst）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 戈林囊腫（Gorlin's cyst）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-31","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"關於訂定顎骨囊腫病灶治療計畫的敘述，下列何者最不適當？","options":["(A) 病人的年紀非治療計畫的主要考量","(B) 病人的系統性疾病與健康狀況會影響治療計畫","(C) 囊腫的位置與大小對於治療計畫會產生重要影響","(D) 如果術前有做切片檢查，可以提供很好的手術參考"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"關於下顎枝垂直截骨術（vertical ramus osteotomy）的敘述，下列何者錯誤？","options":["(A) 骨切線是自乙狀切迹（sigmoid notch）至下顎緣（mandibular border）","(B) 為了維持近端骨塊（proximal segment）血液循環，骨塊上的骨膜及肌肉組織應儘量不要剝離","(C) 截骨路徑應在下顎小舌（lingula of mandible）之前","(D) 可用於下顎前突（mandibular prognathism）或顏面不對稱之病人"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"評估顎顏面畸形病人的敘述，下列何者正確？①應由齒顎矯正醫師與口腔外科醫師共同評估 ②應評估病人 的認知與對治療結果的期待 ③評估病人的身體與心理健康狀態","options":["(A) 僅①②","(B) 僅①③","(C) ①②③","(D) 僅②③"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"施行勒福一型（Le Fort Ⅰ）正顎手術，下列敘述何者錯誤？","options":["(A) 若做大幅度移動，下置（inferior reposition）術後穩定性最差","(B) 手術切口採上顎前庭切線，切線位於黏膜牙齦交界（mucogingival junction）","(C) 必須將上顎與翼板（pterygoid plate）分離","(D) 游離之上顎骨塊其血液供應主要來自升腭動脈（ascending palatine artery）及升咽動脈（ascending pharyngeal artery）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"關於口腔灼感症候群的敘述，下列何者正確？","options":["(A) 好發於停經後婦女，使用荷爾蒙替代療法通常可以改善症狀","(B) 大多數患者需要積極治療，否則無法改善症狀","(C) 已證明使用抗癲癇藥或抗憂鬱藥來治療，可產生良好的治療效果","(D) 最好發的位置為舌頭"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"下列步驟何者有助於評估非齒源性顎顏面部疼痛？①詳細詢問病史 ②使用局部麻醉抑制疼痛測試 ③頭頸 部理學檢查 ④顎骨影像學檢查 ⑤腦神經的神經學檢查","options":["(A) 僅①②④⑤","(B) 僅①③⑤","(C) 僅②③④","(D) ①②③④⑤"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"關於口腔顏面疼痛（orofacial pain）分類的敘述，下列何者錯誤？","options":["(A) 顳顎關節的疼痛是屬於somatic pain","(B) 唾液腺的疼痛是屬於visceral pain","(C) neuropathic pain常因外傷或手術造成周邊神經的損傷而引起","(D) 口腔顏面疼痛最常由精神相關疾病引發"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"有關唾液腺結石（sialolithiasis）之敘述，下列何者錯誤？","options":["(A) 顎下腺發生機會較腮腺高","(B) 若顎下腺結石位於下顎舌骨肌（mylohyoid muscle）後緣之後，有可能會需要切除腺體","(C) 若腮腺結石位於頰肌內側，可經由口內切除","(D) 舌下腺結石亦常見，其臨床表現與顎下腺結石類似"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"關於唾液腺疾病，下列敘述何者錯誤？","options":["(A) 多形性腺瘤（pleomorphic adenoma）組織特徵為導管上皮與肌上皮細胞增生","(B) benign mixed tumor也被稱為papillary cystadenoma lymphomatosum","(C) 口腔黏液囊腫（mucocele）可能因黏液外滲或黏液儲留囊腫兩種現象引起","(D) 蛤蟆腫（ranula）是舌下腺的黏液外滲囊腫，是口腔底部黏液囊腫的一種"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-113-2-40","subject":"ya4","topic":"唾液腺疾病","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"腮腺管（Stensen's duct）結石位於何處時，較難以手術從口內取出？","options":["(A) 咬肌前緣的後方","(B) 咬肌前緣與頰肌之間","(C) 頰肌中","(D) 頰肌內緣"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"有關顏面骨折的功能性穩定固定（functionally stable fixation），下列敘述何者正確？","options":["(A) 是一種剛性固定（rigid fixation）","(B) 以此原則固定骨折後，在受力時不會有斷骨間的移動（interfragmentary mobility）存在","(C) 骨癒合過程不會產生骨痂（callus）","(D) 在下顎骨角骨折的張力側打上一片迷你骨板，即是達到功能性穩定固定的例子"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"圖示之下顎骨骨折，單純使用骨內固定時的考量，下列敘述何者錯誤？","options":["(A) 必須考慮以load bearing osteosynthesis的概念來進行固定","(B) 可以使用數片2.0 mm的迷你骨板進行骨塊的復位及固定","(C) 進行骨塊固定前需先確認咬合","(D) 在骨體中間及靠牙齒區域不合適使用雙皮質骨釘（bicortical screws）進行固定"],"answer":1,"image":"ya4-113-2-42.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"下列何種骨折適合單用閉合式復位（closed reduction）來處理？①下顎髁頭囊內骨折（intracapsular condylar fracture） ②斷裂下顎髁頭顱內移位（displacement into the middle cranial fossa） ③ 兒童之下顎髁頭骨折（condylar fracture） ④下顎髁下柳條狀骨折（greenstick subcondylar fracture）","options":["(A) ①②③","(B) ①③④","(C) ②③④","(D) ①②④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"下列關於上下顎間固定（intermaxillary fixation, IMF）的敘述，何者錯誤？","options":["(A) 對於全口無牙的顎骨骨折病人，可以利用病人原有的活動假牙，搭配arch bar進行上下顎間固定","(B) 使用IMF骨釘進行上下顎間固定，其優點為減少被金屬線刺傷的風險","(C) 當顎骨骨折導致咬合錯位，必須使用上下顎間固定恢復咬合","(D) 與成人骨折病人相比較，建議縮短兒童病人的上下顎間固定時間"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"對於附圖的骨折說明，何者最適當？①compound fracture ②complex fracture ③simple fracture","options":["(A) 僅①","(B) ①②","(C) ①③","(D) ②③"],"answer":1,"image":"ya4-113-2-45.jpeg","clinical_level":"重點"},{"id":"ya4-113-2-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"門牙因外傷脫落，在指導病人到達診所之前，將脫落的完整門牙保存，下列何者最不適當？","options":["(A) 先用牛奶沖洗牙齒，再將牙齒放回齒槽骨內","(B) 先用生理食鹽水沖洗牙齒，再將牙齒放回齒槽骨內","(C) 將牙齒放回齒槽骨內時，要避免傷及牙根部位","(D) 先用開水刷洗牙根，再將牙齒含在下顎前庭"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"施行腭裂修復手術後產生瘻管，下列敘述何者錯誤？","options":["(A) 最常發生在前腭（anterior palate）處","(B) 瘻管若小於4 mm，且沒有功能性的影響，治療上沒有急迫性","(C) 齒列矯正的擴弓（arch expansion）治療，不一定與瘻管的產生相關","(D) 殘留的瘻管可以用von Langenbeck術式進行修復"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"關於腭裂病人的補綴說話輔助裝置（prosthetic speech aid appliances），下列敘述何者錯誤？","options":["(A) 可以填補缺牙區","(B) 可以減少說話的鼻音","(C) 可以將軟腭下推輔助吞嚥","(D) 可以封閉口鼻瘻管"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"根據美國心臟學會（2021年）建議，接受過人工心臟瓣膜置換的成年病人進行牙科手術前，給與預防性抗生 素的原則，下列何者錯誤？","options":["(A) 對penicillin類的藥物沒有過敏現象，可在術前1小時給與口服amoxicillin 2 g","(B) 對penicillin過敏，可在術前1小時給與口服clindamycin 2 g","(C) 對penicillin類的藥物有過敏現象，可在術前1小時給與口服azithromycin 500 mg","(D) 對penicillin類的藥物沒有過敏現象，可在術前1小時給與針劑注射ampicillin 2 g"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-50","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"對於急性過敏反應出現呼吸道阻塞症狀時，下列處置何者最不適當？","options":["(A) 立刻停止目前正在給與的藥物","(B) 合併發紺（cyanosis）情況時，立即給與抗組織胺治療","(C) 聽到喘鳴聲（wheezing）時，可先給與吸入性支氣管擴張劑","(D) 如果嚴重的喉痙攣（laryngospasm）無法緩解，可考慮緊急環甲切開術（cricothyrotomy）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-51","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"心血管系統風險評估是一項重要的手術前準備，下列何種條件最不適合進行非急迫性手術（elective surgery）？","options":["(A) 依1999年版Goldman心臟風險指標（revised Goldman cardiac risk index）評估為0分","(B) 依美國心臟病學學院和美國心臟協會於2014年做出的指引，病人無法進行整體代謝當量（total metabolic equivalents, METs）大於4分的活動","(C) 距離前次心肌梗塞時間3個月","(D) 經皮冠狀動脈氣球成形術（balloon angioplasty）後10日"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-52","subject":"ya4","topic":"全身性疾病與急症","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"治療有氣喘病史的病人，下列敘述何者最不適當？","options":["(A) 為避免病人緊張與焦慮導致氣喘發作，可以適當給與nitrous oxide","(B) 緩解氣喘發作，應以注射藥物為主","(C) 如果病人長期服用類固醇，應於術前會診評估是否調升劑量","(D) 儘量避免非類固醇抗發炎藥物（NSAIDs）的使用"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"關於外傷性顳顎關節炎（traumatic TMJ arthritis）的敘述，下列何者錯誤？","options":["(A) 晚期影像學的表現類似退化性關節炎","(B) 早期的影像學可觀察到glenoid fossa頂部至condylar surface距離變小","(C) 可能演變成顳顎關節的黏連（ankylosis）","(D) 發生在孩童時可能會導致咬合不正"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"下列何者為最常見的顳顎關節疾病？","options":["(A) degenerative osteoarthritis","(B) inflammatory arthritis","(C) infectious arthritis","(D) traumatic arthritis"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"有關顳顎關節及咀嚼肌神經血管供應之敘述，下列何者錯誤？","options":["(A) 關節囊是由耳顳神經、深顳神經及咬肌神經所支配","(B) 翼肌、顳肌及咬肌之神經支配主要來自三叉神經","(C) 關節囊與關節盤之血液供應主要來自顳動脈之分枝","(D) 顳顎關節之血流供應，部分來自淺顳動脈"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-56","subject":"ya4","topic":"口腔外科基礎","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"關於我國在醫療糾紛或醫療爭議現況的敘述，下列何者錯誤？","options":["(A) 病人或家屬以口頭或書面方式向醫事人員本人或醫院提出抱怨投訴，也算是醫療糾紛","(B) 未得病人的同意而進行處置或病患認為醫院收費太貴都可能造成醫療糾紛的產生","(C) 醫療糾紛之訴訟案件，大部分是病人勝訴","(D) 根據「醫療事故預防及爭議處理法」，可以利用庭外和解，迅速合理的解決醫療糾紛"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"下列何者為目前使用之放射線吸收劑量單位？","options":["(A) sievert","(B) roentgen","(C) gray","(D) rem"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"背景輻射最主要的來源為下列何者？","options":["(A) 食物","(B) 飲水","(C) 氡","(D) 核電廠"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"X光片上物體影像之對比（contrast）與下列何者最有關？","options":["(A) kVp","(B) kVp與mA","(C) mA","(D) kVp、mA與曝光時間"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"咬合片攝影（occlusal radiography）對下列何者能提供的資訊較少？","options":["(A) 阻生齒（impacted teeth）的定位","(B) 口底的異物（foreign bodies）","(C) 顱底（skull base）的骨折","(D) 正中腭骨縫（midpalatal suture）於矯正治療中的變化"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"下列何者不屬於咬翼片（bite-wing film）所使用之接受器裝置（receptor-holding device）？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":0,"image":"ya4-113-2-61.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"在kVp 中的「p」 代表下列何者？","options":["(A) percentage","(B) pair","(C) peak","(D) pressure"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-63","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"下列何種X光攝影，最適合用來診斷顴骨弓骨折（zygomatic arch fracture）？","options":["(A) transcranial projection","(B) reverse Towne's view","(C) Zimmer's view","(D) submentovertex projection"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-64","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"附圖CT影像中，何者為鼻淚管（nasolacrimal duct）？","options":["(A) 1","(B) 2","(C) 8","(D) 22"],"answer":1,"image":"ya4-113-2-64.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-65","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"附圖X光影像中，星號所指之放射線透過性區域為何？","options":["(A) 顎下窩（submandibular fossa）","(B) 創傷性骨囊腫（traumatic bone cyst）","(C) 單純性骨囊腫（simple bone cyst）","(D) 骨質疏鬆症（osteoporosis）"],"answer":0,"image":"ya4-113-2-65.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-66","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"所附電腦斷層影像中，白色箭頭所指為下列何者？","options":["(A) 篩竇（ethmoid sinus）","(B) 蝶竇（sphenoid sinus）","(C) 上顎竇（maxillary sinus）","(D) 乳突氣房（mastoid air cells/mastoid process）"],"answer":3,"image":"ya4-113-2-66.jpeg","clinical_level":"重點"},{"id":"ya4-113-2-67","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"病人左下第二小臼齒處腫脹疼痛，X光檢查結果如圖，其左下第二小臼齒有何形態異常？","options":["(A) 第一型牙本質發育不良（dentin dysplasia type I）","(B) 雙生齒（gemination）","(C) 齒中齒（dens invaginatus）","(D) 齒外齒（dens evaginatus）"],"answer":3,"image":"ya4-113-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-68","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"附圖X光片中，左下門齒有何形態異常？","options":["(A) 雙生齒（gemination）","(B) 融合齒（fusion of teeth）","(C) 連合齒（concrescence）","(D) 巨齒症（macrodontia）"],"answer":1,"image":"ya4-113-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-69","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"病人被診斷有牙周病，故每日清潔牙齒5次，每次皆用牙線清潔10分鐘。因牙齒對冷熱水敏感，就診時拍攝 根尖X光片如下，其齒頸部異常為何？","options":["(A) 磨耗（abrasion）","(B) 咬耗（attrition）","(C) 齒腐蝕（erosion）","(D) 內吸收（internal resorption）"],"answer":0,"image":"ya4-113-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-70","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"病患因右邊牙齒對冷熱食物刺激有疼痛感而來檢查，臨床檢查發現牙齒顏色變化，根尖X光片如附圖，標示1 與2處最可能的診斷為何？","options":["(A) 1為齲齒（dental caries）；2為內吸收（internal resorption）","(B) 1為內吸收（internal resorption）；2為齲齒（dental caries）","(C) 1、2皆為齲齒（dental caries）","(D) 1、2皆為內吸收（internal resorption）"],"answer":0,"image":"ya4-113-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-71","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"附圖之錐束電腦斷層掃描（cone beam computed tomography）片中，黑色箭頭所指牙齒異常為何？","options":["(A) 咬耗（attrition）","(B) 磨耗（abrasion）","(C) 齲齒（dental caries）","(D) 內吸收（internal resorption）"],"answer":2,"image":"ya4-113-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-72","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"左下側門齒為活性牙且無臨床症狀，經過長時間追蹤的影像如附圖，其最可能的診斷為何？","options":["(A) sclerosing osteitis","(B) periapical cemento-osseous dysplasia","(C) fibrous dysplasia","(D) dense bone island"],"answer":1,"image":"ya4-113-2-72.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-73","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"在核磁共振造影（MRI）檢查中，對於含水豐富的組織（high free water tissues），如腦脊髓液 （CSF）、囊腫（cysts），在T1-weighted與T2-weighted image的訊號強度（signal intensity）分別為下 列何者？","options":["(A) T1-weighted：high，T2-weighted：high","(B) T1-weighted：high，T2-weighted：low","(C) T1-weighted：low，T2-weighted：high","(D) T1-weighted：low，T2-weighted：low"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-74","subject":"ya4","topic":"口腔病理基礎","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"一位中年女性因前頸部出現不痛的腫塊而就醫，該腫塊的電腦斷層影像如白色箭頭所指，下列何者為最可能 之臨床診斷？","options":["(A) branchial cleft cyst","(B) lymphoepithelial cyst","(C) thyroid goiter","(D) thyroglossal duct cyst"],"answer":3,"image":"ya4-113-2-74.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-75","subject":"ya4","topic":"唾液腺疾病","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"附圖為唾液腺疾病於使用顯影劑的電腦斷層影像，下列何者為最可能之診斷？","options":["(A) obstructive sialodochitis","(B) chronic sialadenitis","(C) autoimmune sialadenitis","(D) tumor displacement of salivary gland"],"answer":0,"image":"ya4-113-2-75.jpeg","clinical_level":"一般"},{"id":"ya4-113-2-76","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"下列何種解剖構造於勒福一型（Le Fort I）與勒福二型（Le Fort II）骨折中，最可能皆呈現骨折？","options":["(A) 眶下堤（infraorbital rim）","(B) 鼻底（nasal floor）","(C) 上顎齒槽骨（maxillary alveolar bone）","(D) 翼板（pterygoid plate）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-77","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"下列何種疾病，其疾病後期顎骨X光影像較常呈現羊毛棉花狀（cotton wool appearance），且較好犯於老 年男性病人的上顎骨？","options":["(A) 增生性骨膜炎（proliferative periostitis）","(B) 纖維性發育不良（fibrous dysplasia）","(C) 骨之柏哲德氏病（Paget disease of bone）","(D) 齒瘤（odontoma）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-78","subject":"ya4","topic":"放射影像診斷","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"附圖兩張X光片所呈現的影像，其臨床診斷最可能是下列何者？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 淋巴結（lymph node）","(C) 造釉細胞瘤（ameloblastoma）","(D) 涎石病（sialolithiasis）"],"answer":3,"image":"ya4-113-2-78.jpeg","clinical_level":"重點"},{"id":"ya4-113-2-79","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"數位放射線影像攝影之訊號單位（picture element）為何？","options":["(A) charge-coupled device","(B) digitizer","(C) pixel","(D) sensor"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-113-2-80","subject":"ya4","topic":"放射線原理與技術","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"下列之血液成分中，何者對放射線最敏感？","options":["(A) 顆粒球","(B) 血小板","(C) 紅血球","(D) 淋巴球"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"下列術後用藥的注意事項，何者最適當？","options":["(A) acetaminophen 的缺點是干擾血小板功能，明顯增加術後出血風險","(B) ibuprofen 不會干擾血小板功能，適用於有血小板缺陷並且有出血風險的病患","(C) 鴉片類鎮痛劑很少單獨在牙科處方中使用","(D) 可待因成癮性低，所有人均具備使可待因有效作用的必要酶"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"下列對於手術傷口切開基本原則的敘述，何者正確？","options":["(A) 切線位於附連牙齦上，為不良的翻瓣設計","(B) 傷口採重複及較小力道的切開方式，可以減少組織傷害的範圍，傷口癒合較佳","(C) 切開時手術刀片與上皮表面角度應形成銳角，有利於縫合並減少死腔的形成","(D) 切開骨膜及韌帶組織的阻力大，刀片容易變鈍，應視需要更換刀片"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"有關滅菌處理技術的敘述，何者正確？","options":["(A) 乾熱法可使細胞蛋白質變性，完成殺菌所需時間較溼熱法短，且更為有效","(B) 溼熱法可氧化細胞蛋白質，費用較乾熱法便宜，且不易損傷器械","(C) 器械經過熱滅菌處理一年後，微生物進入滅菌袋的可能性開始明顯增加","(D) 使用氧化乙烯（ethylene oxide）的氣體滅菌法，於 50℃時，在 3 小時內能有效殺死所有的微生物，包括 孢子"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-4","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"下列何項處置不是減少死腔（dead space）的方法？","options":["(A) 由內而外一層一層的縫合傷口","(B) 拔牙傷口塞入止血棉且不移除而後再縫合","(C) 置入引流管","(D) 使用敷料加壓"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-5","subject":"ya4","topic":"局部與全身麻醉","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"關於局部麻醉藥的藥物代謝動力學，下列敘述何者正確？","options":["(A) cocaine 是唯一持續產生血管舒張作用的局部麻醉藥","(B) 局部麻醉藥經黏膜吸收速率，其順序是食道快於咽部，咽部快於氣管","(C) tetracaine、chloroprocaine 和 propoxycaine 具有不同程度的血管舒張特性，效果皆強過 procaine","(D) 酯類（ester）局部麻醉藥在血漿中被偽膽鹼酶（pseudocholinesterase）水解"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"下列何者於使用含有血管收縮藥物的局部麻醉劑時，要特別衡量其益處及風險？①甲狀腺功能障礙 ②對亞硫 酸鹽（sulfite）過敏 ③使用三環類抗憂鬱藥 ④心血管疾病處於 ASA 3 級和 4 級","options":["(A) 僅①③","(B) 僅②③④","(C) 僅①②④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-7","subject":"ya4","topic":"局部與全身麻醉","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"關於局部麻醉藥劑中的 epinephrine，下列敘述何者最不適當？","options":["(A) 在高劑量時，會產生血管收縮的效果","(B) 主要作用在血管，不會增加耗氧量","(C) 在正常劑量下，對中樞神經系統不會有強烈刺激作用","(D) 須注意術後血管擴張導致反彈性出血的可能性"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-8","subject":"ya4","topic":"局部與全身麻醉","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"圖示 X 光片，顯示何種手術併發症？","options":["(A) 拔牙傷口流血不止","(B) 魯特維氏咽峽炎（Ludwig's angina）","(C) 局部麻醉藥注射針頭斷裂殘留","(D) 下顎骨骨折"],"answer":2,"image":"ya4-114-1-8.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-9","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"預防阻生智齒牙冠周圍炎再發，下列何者為最有效的方法？","options":["(A) 定期使用抗生素","(B) 執行齦蓋切除術（operculectomy）","(C) 定期清洗牙結石","(D) 拔除已產生牙冠周圍炎的智齒"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"依 Pell and Gregory classification，下顎第三大臼齒咬合面位於前方第二大臼齒齒頸部以下，此為何種 分類？","options":["(A) class A","(B) class B","(C) class C","(D) class D"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-11","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"拔除下列牙齒的拔牙鉗，何者有區分左右？","options":["(A) 上顎小臼齒","(B) 下顎第一、二大臼齒","(C) 下顎小臼齒","(D) 上顎第一、二大臼齒"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"關於乾性齒槽（dry socket），下列敘述何者正確？","options":["(A) 通常發生在拔牙術後隔天，伴隨劇烈疼痛","(B) 最好發於下顎小臼齒區","(C) 致病機轉是傷口血塊過慢分解導致","(D) 拔牙後以大量生理食鹽水沖洗傷口能降低其發生率"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-13","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"咽後間隙（retropharyngeal space）緊鄰下列那些筋膜？ ①superficial cervical fascia ②alar fascia ③prevertebral fascia ④investing fascia","options":["(A) ①②③","(B) ①③④","(C) 僅③④","(D) 僅②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-14","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"下列菌種何者最可能為引發下顎化膿性骨髓炎的菌種？","options":["(A) Lactobacillus spp.","(B) Streptococcus spp.","(C) Haemophilus spp.","(D) Klebsiella spp."],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-15","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"頭頸部放射治療後之病人，在適當條件下，仍可接受下列何種治療？①拔牙 ②人工植牙 ③活動義齒","options":["(A) 僅①","(B) 僅①②","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-16","subject":"ya4","topic":"植牙外科","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"顴骨植體（zygomatic implant）的長度通常為多少 mm？","options":["(A) 20～30","(B) 35～55","(C) 60～70","(D) 75～95"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-17","subject":"ya4","topic":"植牙外科","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"齒槽骨嵴牽引術的初始潛伏期（initial latency period）通常建議為多久？","options":["(A) 3～4 天","(B) 5～7 天","(C) 10～14 天","(D) 14 天以上"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-18","subject":"ya4","topic":"植牙外科","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"右側下顎第一大臼齒接受植牙治療，於牙冠黏著固定 3 個月後，追蹤檢查無咬合異常，但植牙區明顯有牙齦 出血及流膿，檢測囊袋深度＞5 mm，根尖 X 光片如圖所示。造成其植體周圍炎最可能的原因為何？","options":["(A) 不當咬合力","(B) 假牙邊緣不密合","(C) 黏著劑殘留","(D) 後牙向前傾斜分力"],"answer":2,"image":"ya4-114-1-18.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-19","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"有關 intraseptal alveoloplasty 的敘述，何者正確？","options":["(A) 藉由去除齒槽內的間隔骨板，可重置腭側的皮質骨","(B) 於修整齒槽骨板時，會有損傷大腭神經的可能併發症","(C) 手術鄰近部位的肌肉附著點，通常不會被影響到","(D) 可增加術後齒槽嵴的厚度，有助於後續植體的穩定性"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-20","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"口腔癌病人在接受放射線治療後的副作用，下列何者正確？①味覺喪失且無法恢復 ②味覺喪失但會逐漸恢 復 ③刺激唾液腺分泌，導致唾液變黏稠 ④唾液腺萎縮，且不易完全恢復","options":["(A) ②③","(B) ①④","(C) ①③","(D) ②④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-21","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"有關造釉細胞瘤的組織特性，下列何者正確？","options":["(A) 最常見的型態為濾泡型（follicular type）及角質型（keratosis type）","(B) 可見柱狀（columnar）及立方形（cuboidal）的外層上皮細胞（outer epithelial cell）排列在結締組織 邊緣","(C) 外層上皮細胞（outer epithelial cell）的細胞核偏向基底膜（basement membrane）","(D) 內層上皮細胞（inner epithelial cell）常會出現 dysplasia 現象"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-22","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"口腔鱗狀細胞癌目前最主要之治療方法為何？","options":["(A) 手術切除","(B) 放射線治療","(C) 化學治療","(D) 免疫治療"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-23","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"對於口腔黏膜白斑（leukoplakia），下列敘述何者正確？","options":["(A) 自體螢光影像（autofluorescence imaging）明顯比在白熾光光源（incandescent light）下的目測法有較 佳的口腔癌診斷率","(B) 化學預防法（chemoprevention）比手術切除對於白斑症惡性轉變有較高的防治率","(C) 手術切除有助於診斷白斑病灶內是否有上皮發育不良（dysplasia）","(D) 均質性（homogeneous）白斑與非均質性（non-homogeneous）白斑都有一樣的惡性轉變率"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"下列何者不是蘭格罕細胞組織球增生症（Langerhans cell histiocytosis）重要的預後因子？","options":["(A) 發病年紀小於 2 歲","(B) 肺臟、肝臟、脾臟發現腫瘤細胞","(C) 侵犯到皮膚","(D) 首次化療後的腫瘤反應（response to initial chemotherapy）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"有關口腔內色斑病灶（pigmented lesion），若是出現下列何種徵象，必須強烈懷疑黑色素瘤（melanoma） 的可能？①外觀呈現非對稱性（asymmetry） ②在同一病灶有多重顏色（color）表現 ③邊緣（border） 不規則","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"關於齒源性腫瘤（odontogenic tumors）的敘述，下列何者錯誤？","options":["(A) 轉移性造釉細胞瘤（metastasizing ameloblastoma）最常轉移的部位是肺","(B) 造釉細胞癌（ameloblastic carcinoma）不一定會合併遠端轉移的病灶","(C) 亮細胞齒源性癌（clear cell odontogenic carcinoma）好發於成年女性","(D) 亮細胞齒源性癌（clear cell odontogenic carcinoma）較好發於上顎骨"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-27","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"源自胚胎發育時期多能幹細胞或上皮組織被包埋在下顎舌骨肌（mylohyoid muscle）附近，其囊腫上皮為複 層鱗狀上皮（stratified squamous epithelium），最可能是下列何者？","options":["(A) 皮樣囊腫（dermoid cyst）","(B) 甲狀舌管囊腫（thyroglossal duct cyst）","(C) 鰓裂囊腫（branchial cleft cyst）","(D) 胸腺囊腫（thymic cyst）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-28","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"被診斷出基底細胞痣症候群（basal cell nevus syndrome）的孩童患者，其顎骨區發現多個大型齒源性角化 囊腫（odontogenic keratocyst）病灶，下列何者是優先考慮的治療方式？","options":["(A) 刮除術（curettage）後再追加剜除術（enucleation）","(B) 剜除術（enucleation）後再追加減壓術（decompression）","(C) 整塊切除手術（en bloc resection）","(D) 減壓術（decompression）後再視情況追加剜除術（enucleation）及刮除術（curettage）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-29","subject":"ya4","topic":"唾液腺疾病","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"腮腺的淋巴表皮囊腫（lymphoepithelial cyst）與下列何者最有相關性？","options":["(A) 後天免疫缺乏症候群（acquired immunodeficiency syndrome, AIDS）","(B) 全身性紅斑性狼瘡（systemic lupus erythematosus, SLE）","(C) 傳染性單核球增多症（infectious mononucleosis）","(D) 腮腺炎（mumps）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-30","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"關於鈣化齒源性囊腫（calcifying odontogenic cyst）的敘述，下列何者正確？","options":["(A) 好發於上顎","(B) 若伴生齒瘤（odontoma），多發生於年輕人","(C) 好發於臼齒區，尤其是阻生齒","(D) 一般需以骨切除手術（resection）治療"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-31","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"下列各區域中，何者為含齒囊腫較好發區域？","options":["(A) 上顎犬齒區","(B) 下顎犬齒區","(C) 下顎第一大臼齒區","(D) 上顎側門牙區"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"關於上顎垂直向生長過多（vertical maxillary excess）的特徵，下列敘述何者錯誤？","options":["(A) 顏面的下三分之一明顯過長","(B) 通常鼻翼較寬","(C) 上顎前牙牙齦暴露（gingival exposure）較多","(D) 病人的齒列可能是異常咬合 Class Ⅰ、Class Ⅱ、Class Ⅲ"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"病人顏面不對稱，且有咬合面傾斜，可能須接受何部位之正顎手術？①上顎骨 ②下顎骨 ③頦部","options":["(A) 僅①","(B) 僅②","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"相對於口內下顎枝垂直截骨術（intraoral vertical ramus osteotomy），施行兩側矢向分裂截骨術 （bilateral sagittal split osteotomy）有下列那項缺點？","options":["(A) 術後之穩定性較差","(B) 較易傷及下齒槽神經，導致下唇感覺異常","(C) 較易造成術後感染","(D) 術後必須施行 6～8 週之顎間固定（intermaxillary fixation）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"下列何者為肌筋膜疼痛及功能障礙（myofascial pain and dysfunction）病人常見的症狀？①咀嚼時會產生 疼痛 ②顳顎關節運動範圍受限 ③情緒壓力增加時疼痛加劇","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"55 歲病人，主訴右臉頰陣發性疼痛，具電擊刺痛感，每次發作時間約持續幾秒鐘至 1 分鐘，特別在吃東西碰 到右下第一大臼齒前庭區時。其診斷最可能是下列何者？","options":["(A) 叢發性頭痛","(B) 肌筋膜疼痛","(C) 非典型顏面痛","(D) 三叉神經痛"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"關於顱神經痛（cranial neuralgias）的敘述，下列何者錯誤？","options":["(A) 最常見的是舌下神經痛","(B) 迷走神經痛可能會引發咽喉附近的疼痛而轉移至下顎枝","(C) 常用抗癲癇藥物治療","(D) 部分病患需顱內手術治療"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-38","subject":"ya4","topic":"唾液腺疾病","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"關於唾液腺之分泌，下列敘述何者錯誤？","options":["(A) 腮腺所分泌的唾液較舌下腺黏稠","(B) 顎下腺的唾液分泌占整體唾液量的比例最高","(C) 調控舌下腺的副交感神經是來自顏面神經","(D) 顎下腺之唾液成分中鈣離子濃度較其他唾液腺高，且較呈鹼性"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-39","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"下列涎管放射攝影檢查（sialogram）影像，何者較可能是謝格連氏症候群（Sjögren's syndrome）所致？","options":["(A) [見附圖]","(B) [見附圖]","(C) [見附圖]","(D) [見附圖]"],"answer":2,"image":"ya4-114-1-39.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-40","subject":"ya4","topic":"唾液腺疾病","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"顎下腺導管可大致以下顎那一顆牙為界，分成前區及後區，協助判斷是否容易經口內手術處理顎下腺結石？","options":["(A) 第一小臼齒","(B) 第二小臼齒","(C) 第一大臼齒","(D) 第二大臼齒"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"對於全層之下唇撕裂傷（full-thickness lower lip laceration），下列縫合順序何者最為適當？①口腔黏 膜（oral mucosa） ②口輪匝肌（orbicularis oris） ③唇紅緣邊緣 ④顏面皮膚（facial skin）","options":["(A) ④③②①","(B) ③④②①","(C) ①②③④","(D) ③②①④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"針對上顎骨骨折（maxillary fracture）之治療，下列敘述何者錯誤？","options":["(A) 對於勒福一式上顎骨骨折（Le Fort Ⅰ maxillary fracture），可將鼻上顎支柱（nasomaxillary buttress）及顴上顎支柱（zygomaticomaxillary buttress）加以復位固定","(B) 對於勒福二式上顎骨骨折（Le Fort Ⅱ maxillary fracture），可將額顴骨縫（frontozygomatic suture）及顴上顎骨縫（zygomaticomaxillary suture）加以復位固定","(C) 如骨折處不易移動進行復位，可以考慮進行截骨術（osteotomy）來幫助復位","(D) 若合併腭部骨折（palatal fracture），製作手術咬合板（surgical splint）可幫助維持上顎寬徑"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"鈍性創傷（blunt trauma）所造成之皮下腫脹瘀血稱之為：","options":["(A) 挫傷（contusion）","(B) 撕裂傷（laceration）","(C) 擦傷（abrasion）","(D) 撕脫傷（avulsion）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"關於撕裂傷（laceration wound）的敘述，下列何者錯誤？","options":["(A) 是指上皮（epithelial）與上皮下（subepithelial）組織的撕裂","(B) 若伴隨牙齒齒槽外傷，應先縫合軟組織，減少傷口出血，再處理硬組織","(C) 處理時應包括清潔、清創、止血、縫合等四個步驟","(D) 處理下唇穿通性撕裂傷，需要縫合肌肉層"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"關於上下顎間固定（maxillomandibular fixation）的敘述，下列何者錯誤？","options":["(A) 只用上下顎間固定來治療骨折，稱為閉合式復位術（closed reduction）","(B) 有多種方式可以施行上下顎間固定，例如 arch bar、Ivy loop","(C) 全口無牙的病人，無法施行上下顎間固定","(D) 使用開放式復位術（open reduction）來治療骨折，可以合併施行上下顎間固定"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-46","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"將脫落的成熟恆牙再植回，下列何者對癒合的成功率最沒有幫助？","options":["(A) 植入後將牙齒固定 7～10 天","(B) 若脫落時間小於 20 分鐘，應以生理食鹽水輕微沖洗牙齒後立即植回","(C) 先將齒槽窩用優碘溶液沖洗","(D) 若脫落時間超過 20 分鐘，植入前牙齒要先泡在 Hanks 溶液 30 分鐘，然後以四環黴素溶液泡 5 分鐘"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"關於唇腭裂手術時機，下列敘述何者正確？","options":["(A) 位於上顎骨及齒槽骨的骨缺損，接受骨移植手術的時機在出生 6 至 9 個月時","(B) 唇腭裂患者的鼻整形（rhinoplasty）較適當的時機在正顎手術之後","(C) 腭裂修復時機在出生後 10 週","(D) 相較於一般人，唇腭裂患者接受正顎手術的年齡需要延遲"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"下列何種皮瓣無法用來修復口鼻瘻管？","options":["(A) 腭瓣（palatal flap）","(B) 頰瓣（buccal flap）","(C) 顳肌瓣（temporalis flap）","(D) 頦下瓣（submental flap）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-49","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"65 歲的陳先生患有第一型糖尿病，並規律注射胰島素，血糖控制在正常範圍內。因右上第一小臼齒牙根斷 裂，須在局部麻醉下拔除斷齒，下列敘述何者正確？","options":["(A) 本次拔牙手術前不能進食，以免血糖太高","(B) 拔牙前一天應開始停止胰島素注射","(C) 若接受手術時，發生焦慮、臉色發白、盗汗、心跳加速且全身無力的狀況，很可能是血糖太高造成的現象","(D) 發生低血糖的現象時，應先停止牙科治療，給患者喝一杯果汁或是吃糖果"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-50","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"對於有心肌梗塞病史的病人，減少焦慮是牙科治療過程重要的一環，下列何種處置對於降低病人焦慮最沒有 幫助？","options":["(A) 治療中儘量不要跟病人說話","(B) 治療時給與足夠的局部麻醉劑量","(C) 靜脈注射抗焦慮藥物（anxiolytics）","(D) 治療器械遠離病人視野"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-51","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"哺乳中的母親（lactating mothers）使用下列何種藥物，會對受哺育的嬰兒最不安全？","options":["(A) acetaminophen","(B) lidocaine","(C) tetracyclines","(D) cephalexin"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-52","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"下列何種檢查，可以幫助評估血友病病人的凝血功能？","options":["(A) 血小板數","(B) 流血時間（bleeding time）","(C) prothrombin time","(D) partial thromboplastin time"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"關於類風濕性顳顎關節炎的敘述，下列何者錯誤？","options":["(A) 滑膜組織異常增生（pannus formation）","(B) 發生年齡可能比退化性關節炎早","(C) 通常侵犯單側","(D) 可能會造成髁頭－上行枝高度（condylar-ramus height）喪失"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"關於顳顎關節 osteoarthritis 的影像學變化，下列敘述何者錯誤？","options":["(A) 早期可能出現 joint space 縮小","(B) 早期可能出現 subchondral bone resorption","(C) 隨著疾病的進展，articular eminence 可能變平","(D) 晚期可能出現 condylar head 皮質骨侵蝕"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"關於關節穿刺術（arthrocentesis）之敘述，下列何者錯誤？","options":["(A) 其作用在沖洗出關節內之發炎物質，達到症狀緩解之目的","(B) 通常施行在下關節腔","(C) 沖洗液建議至少 100 毫升","(D) 第一穿刺點約在關節窩後緣，即在耳珠－眼眥線下方 2 mm，耳珠前 10 mm 之位置"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-56","subject":"ya4","topic":"口腔外科基礎","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"生命倫理學建構於共有道德理論基礎之上。其有四個原則做為道德判斷的起點。下列何者不屬於生命倫理學 的四個原則？","options":["(A) 尊重自主原則","(B) 不傷害原則","(C) 利己原則","(D) 正義原則"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"關於 X 光機的敘述，下列何者錯誤？","options":["(A) 在 X 光管中，電子束來源為陰極（cathode）","(B) 超過 99%的電子束動能，轉換為熱能，僅少數轉換為 X 光","(C) X 光的能量單位是 mAs，強度單位為 kVp","(D) X 光的影像對比主要由能量決定；影像亮度與劑量主要由強度決定"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-58","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"典型或常見的頭頸部放射治療所導致的併發症中，下列何者通常最早恢復？","options":["(A) 味覺異常或喪失","(B) 口腔黏膜炎","(C) 唾液減少","(D) 放射線齲齒"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"目前牙科 X 光攝影使用的有線數位 CCD（charge-coupled device）感應片，其接受到 X 光至傳送訊號到電腦 後，以灰階方式呈現。目前最常見的灰階數為多少？","options":["(A) 256","(B) 512","(C) 1024","(D) 2048"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-60","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"關於以分角線法（bisecting-angle technique）進行牙根尖放射線攝影（periapical radiography）的缺 點，下列敘述何者錯誤？","options":["(A) 影像中的牙冠常會變形","(B) 不容易準確判斷齒槽骨高度","(C) 顴骨弓（zygomatic arch）的影像疊加（superimpose）常干擾上顎大臼齒牙根的觀察","(D) 以影像測量上顎大臼齒的頰側牙根長度，可能比實際長"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"下列何種拍攝方式，其 coronoid process 的影像最不清楚？","options":["(A) lateral cephalometric projection","(B) Waters projection","(C) posteroanterior cephalometric projection","(D) panoramic projection"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"關於正子攝影的敘述，下列何者錯誤？","options":["(A) 最常使用的顯影劑為 2-[18F] fluoro-2-deoxy-D-glucose（FDG），配合細胞的高糖解活性（glycolytic activity）","(B) 正子掃描需配合核磁共振攝影，將兩者重疊而得最後影像","(C) 可用於評估骨代謝疾病、原發或復發之惡性腫瘤、骨髓炎","(D) 一次檢查可同時獲得形態及功能性資訊"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"下列何者不是口腔咬翼放射線攝影法（bitewing radiography）主要的適應症（main indication）？","options":["(A) 偵測鄰接面齲齒","(B) 評估牙周狀況","(C) 評估復形物狀況","(D) 監測牙根尖病變的進展"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-64","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"關於附圖影像箭頭處所指構造，下列敘述何者錯誤？","options":["(A) 放射線影像學名稱為篩狀板","(B) 其外觀會受放射線行進方向與皮質骨厚度之相對關係影響","(C) 其外觀會受放射線行進方向與牙根之相對角度影響","(D) 此一構造之厚度與牙齒承受之咬合力有關"],"answer":0,"image":"ya4-114-1-64.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-65","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"附圖影像中箭頭所指之處，為下列何種構造？","options":["(A) 鼻腭管（nasopalatine duct）","(B) 前鼻棘（anterior nasal spine）","(C) 上顎間縫（intermaxillary suture）","(D) 營養管（nutrient canal）"],"answer":2,"image":"ya4-114-1-65.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-66","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"附圖中紅色箭頭所指放射線透過性線條（radiolucent lines）為下列何者？","options":["(A) mandibular canals","(B) nutrient canals","(C) lamina dura","(D) lingual foramen"],"answer":1,"image":"ya4-114-1-66.jpeg","clinical_level":"重點"},{"id":"ya4-114-1-67","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"附圖中紅色箭頭所指者為何種牙齒異常？","options":["(A) fusion","(B) concrescence","(C) gemination","(D) taurodontism"],"answer":0,"image":"ya4-114-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-68","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"附圖 X 光片中大臼齒有何種牙齒異常？","options":["(A) fusion","(B) concrescence","(C) gemination","(D) taurodontism"],"answer":3,"image":"ya4-114-1-68.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-69","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"附圖 X 光片中，無齒頸部或牙根齲齒的牙位為何？","options":["(A) 44","(B) 45","(C) 46","(D) 47"],"answer":3,"image":"ya4-114-1-69.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-70","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"附圖 X 光片中，左下第一大臼齒遠心側（distal side）的牙周破壞影像描述為何？","options":["(A) horizontal bone loss","(B) vertical bone defects","(C) interdental craters","(D) buccal or lingual cortical plate loss"],"answer":1,"image":"ya4-114-1-70.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-71","subject":"ya4","topic":"放射影像診斷","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"頭頸部 X 光影像常見軟組織鈣化的典型分布圖中，何者為涎石（sialoliths）最常出現的區域？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":1,"image":"ya4-114-1-71.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-72","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"下列那一種檢查，其原理是利用傳統核醫追蹤劑（radiotracer）及 gamma camera 以一定的角度，環繞病人 之標的器官，得到一系列的平面影像，再以電腦影像重組技術得到另一系列的影像，且可用於檢查口腔癌病 人是否有遠端轉移？","options":["(A) computed tomography","(B) magnetic resonance imaging","(C) ultrasonography","(D) single photon emission computed tomography"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-73","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"附圖 X 光片影像，在何種疾病中最易觀察到？","options":["(A) 戈林症狀群（Gorlin syndrome）","(B) 柏哲德氏病（Paget disease）","(C) 骨化纖維瘤（ossifying fibroma）","(D) 顱顏面骨發育不全（craniofacial dysostosis）"],"answer":1,"image":"ya4-114-1-73.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-74","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"附圖 X 光片影像，最可能是下列何種疾病？","options":["(A) 骨化纖維瘤（ossifying fibroma）","(B) 纖維發育不良（fibrous dysplasia）","(C) 牙骨質－骨質發育不良（cemento-osseous dysplasia）","(D) 成纖維性纖維瘤（desmoplastic fibroma）"],"answer":1,"image":"ya4-114-1-74.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-75","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"下顎骨前部外傷時，最常造成下列何部位之間接骨折？","options":["(A) 下顎角（mandibular angle）","(B) 下顎枝（mandibular ramus）","(C) 下顎喙狀突（coronoid process）","(D) 下顎髁頸（condylar neck）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-76","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"附圖影像為下列何種疾病之特徵？","options":["(A) 皮耶－羅賓氏症候群（Pierre Robin syndrome）","(B) 亞伯氏症候群（Apert syndrome）","(C) 戈林氏症候群（Gorlin syndrome）","(D) 崔屈－寇林氏症候群（Treacher Collins syndrome）"],"answer":1,"image":"ya4-114-1-76.jpeg","clinical_level":"一般"},{"id":"ya4-114-1-77","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"顎骨中神經鞘瘤（neurilemoma）之 X 光影像，最可能為下列何者？","options":["(A) 周圍界線清楚之放射線透過性病變（well-defined radiolucent lesion）","(B) 周圍界線不清楚之放射線透過性病變（ill-defined radiolucent lesion）","(C) 周圍界線清楚之放射線透過性及不透過性混合病變（well-defined radiolucent and radiopaque mixed lesion）","(D) 周圍界線清楚之放射線不透過性病變（well-defined radiopaque lesion）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-78","subject":"ya4","topic":"口腔病理基礎","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"下列何種顎骨疾病，其 X 光影像較常呈現放射線透過性病變（radiolucent lesion），沿著牙根邊緣呈波浪 狀，且好犯於 10 至 20 歲病人下顎骨？","options":["(A) 史塔尼氏囊腫（Stafne cyst）","(B) 單純性骨囊腫（simple bone cyst）","(C) 動脈瘤性骨囊腫（aneurysmal bone cyst）","(D) 裂隙囊腫（fissural cyst）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-1-79","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"超音波（ultrasound）應用在頭頸部診斷時，所用的頻率為下列何者？","options":["(A) 1～20 MHz","(B) 30～50 MHz","(C) 60～80 MHz","(D) 90～120 MHz"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"下列何者不是游離輻射造成的生物效應？","options":["(A) 畸胎","(B) 致癌","(C) 中毒","(D) 骨壞死"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"下列那一個敘述符合口內皮瓣設計的原理？①皮瓣的高度最好是底部寬度的兩倍 ②最好能夠包含中軸血液供 應（axial blood supply） ③皮瓣根部最好不要扭曲","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"有關神經損傷及修復的敘述，何者正確？","options":["(A) neurotmesis，為損傷造成神經部分切斷，通常自發性復原機會極高，預後較好","(B) axonotmesis，為最嚴重的神經損傷，通常神經功能將持續異常，預後最差","(C) neuropraxia，為神經髓鞘及軸索的損傷，功能修復可在 3～6 個月內復原","(D) Wallerian degeneration，為神經在損傷後，髓鞘及軸突的近心端會進行變性，遠心端會進行分解"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-3","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"下列對於 penicillins 抗生素的敘述，何者正確？","options":["(A) penicillins 會抑制細菌細胞壁的合成，對 staphylococci 特別具有療效","(B) 6％的人對此藥會有過敏反應，首選的替代用藥為 metronidazole","(C) penicillin V 通常為口服，penicillin G 則為注射使用","(D) amoxicillin 在血清的半衰期比 ampicillin 短，不適合作為細菌性心內膜炎的預防用藥"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-4","subject":"ya4","topic":"口腔外科基礎","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"下列有關傷口止血的敘述，何者正確？","options":["(A) 可用局部塗敷凝血酶（thrombin）止血","(B) 大血管出血需使用可吸收線材綑綁，以免造成異物反應","(C) 不可使用 epinephrine 止血","(D) 使用電刀止血必須保留出血點上及周圍之血液與液體，以利形成血栓"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-5","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"45 歲的男性病人，1 個月內曾有心肌梗塞發作的病史，因局部牙齦發炎及腫痛來院求診，經醫師診斷為蜂窩性 組織炎合併有下顎囊腫及阻生智齒。下列對此病人的處置，何者正確？","options":["(A) 欲安排進行較大型的手術與重建治療，應延後至病人心肌梗塞發作後滿 3 個月再施行","(B) 病人看診前半小時，需常規使用硝化甘油（nitroglycerin）做預防性治療較安全","(C) 施行口腔局部治療時，需給與足夠的局部麻醉劑，腎上腺素的用量不要超過 0.004 mg","(D) 看診應減輕病人焦慮，治療時可給與笑氣"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"下列有關麻醉藥注射針斷針之敘述，何者錯誤？","options":["(A) 麻醉藥注射前不要折彎注射針，以免增加斷針機會","(B) 注射後上齒槽神經（posterior superior alveolar nerve）較下齒槽神經（inferior alveolar nerve）， 易發生斷針","(C) 病人無預期的轉頭，易增加斷針機會","(D) 注射針用力碰撞骨骼，易增加斷針機會"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"在使用局部麻醉劑前，下列何種狀況應特別考量添加血管收縮劑的必要性及風險？①甲狀腺機能亢進 ② sulfite 過敏 ③長期服用 tricyclic antidepressants","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-8","subject":"ya4","topic":"口腔外科基礎","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"下列有關牙齒拔除後傷口癒合的敘述，何者錯誤？","options":["(A) 第二週的特徵，為齒槽內充滿了肉芽組織，並且類骨質（osteoid）沉積其內","(B) 第一週為發炎期，纖維組織開始增生","(C) 完整上皮覆蓋（epithelialization）通常完成於第二週","(D) 拔牙 6 個月後，由 X 光影像上，可看到原來清晰易辨的齒槽骨板（lamina dura）消失"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"有關多生牙，下列敘述何者錯誤？","options":["(A) 阻生正中贅齒妨礙恆門齒萌發時，可於恆門齒牙根形成至 2/3 時拔除","(B) 阻生多生牙無妨礙正常恆齒萌發時，可以暫時追蹤觀察","(C) 多生牙仍有可能萌發至口腔中","(D) 阻生多生牙不可能併發含牙囊腫"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"下列有關翻瓣拔牙後傷口縫合處理之敘述，何者正確？","options":["(A) 使用 8 字結（figure-of-eight）可使出血中之傷口完全止血","(B) 皮瓣覆蓋齒槽骨可以避免骨質壞死","(C) 傷口縫合越緊越好，以利止血","(D) 縫合線結必須置於切線上，以利皮瓣兩邊張力平衡"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"Triangular elevator 拔牙所使用的原理為下列何者？","options":["(A) wheel-and-axle","(B) wedge","(C) third-class lever","(D) second-class lever"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"上顎阻生第三大臼齒最常出現的角度是：","options":["(A) mesioangular","(B) vertical","(C) distoangular","(D) horizontal"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-13","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"關於壞死性筋膜炎，下列何者最有療效？","options":["(A) 單次膿液抽吸，送細菌學檢查","(B) 切開引流手術（incision and drainage），繼續抗生素治療","(C) 反覆膿液抽吸，送細菌學檢查","(D) 筋膜切開術（fasciotomy）合併清創（debridement），繼續抗生素治療"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-14","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"下列何種抗生素，較不易造成偽膜性腸炎（pseudomembranous colitis）腹瀉之副作用？","options":["(A) amoxicillin","(B) clindamycin","(C) metronidazole","(D) cephalexin"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"頭頸部感染的病人，下列何種情形最不需要住院治療？","options":["(A) 發高燒，體溫到攝氏 40 度","(B) 頰間隙（buccal space）感染","(C) 吞嚥困難，呼吸急促","(D) 有脫水現象"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-16","subject":"ya4","topic":"口腔外科基礎","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"下列手術何者又稱為唇轉位（Lip switch）？","options":["(A) Dean technique","(B) transpositional flap vestibuloplasty","(C) submucosal vestibuloplasty","(D) Clark vestibuloplasty"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-17","subject":"ya4","topic":"植牙外科","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"以同種異體骨移植（allografts）來重建齒槽骨的優點，不包括下列何者？","options":["(A) 避免額外的供體部位（donor site）","(B) 較容易取得","(C) 病人在門診即可接受此類手術","(D) 具有幹細胞"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-18","subject":"ya4","topic":"植牙外科","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"有關顴骨植體（zygomatic implants）的敘述，下列何者錯誤？","options":["(A) 當上顎骨嚴重萎縮或缺損時，所採取的特殊植牙方式","(B) 顴骨植體長度可由 35～55 mm，是一般植體的 4～5 倍長","(C) 手術置入植體可能穿越上顎竇，到達顴骨體處","(D) 植體通常由上顎犬齒區露出，結合後上顎的植體，成為固定的贋復體"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-19","subject":"ya4","topic":"植牙外科","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"有關上顎竇增高術的敘述，下列何者錯誤？","options":["(A) 出現多個頰－腭方向的中隔時，即無法採用側方開窗術","(B) 側方開窗術通常適用於上顎竇底部的齒槽嵴不足 4 mm 時","(C) 以 transcrestal approach 所進行的手術，通常增高超過 4 mm 時，會增加上顎竇黏膜穿孔的風險","(D) 若遭遇小於 5 mm 的上顎竇黏膜穿孔時，可使用吸收性的生物膜修補"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-20","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"下列何者不是施行冷凍切片（frozen section）的適應症？","options":["(A) 鑑別診斷大型單囊性顎骨病灶（large unilocular jaw lesion）","(B) 鑑別診斷多室型放射線透射病灶（multilocular radiolucent lesion）","(C) 診斷口腔黏膜的類天皰瘡（pemphigoid）病灶","(D) 骨膜（periosteum）切片檢查以判斷腫瘤是否有髓質侵犯（medullary invasion）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-21","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"關於痣樣基底細胞癌症候群（nevoid basal cell carcinoma syndrome）病人的頭部特徵，下列何者錯誤？","options":["(A) 前額隆起（frontal bossing）","(B) 眼距過寬（hypertelorism）","(C) 大腦鐮鈣化（calcified falx cerebri）","(D) 上顎前突（maxillary protrusion）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-22","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"造釉細胞瘤（ameloblastoma）的組織型態分類，包括下列何者？","options":["(A) 非角化型（non-keratinizing type）","(B) 濾泡型（follicular type）","(C) 多形性型（pleomorphic type）","(D) 黏液型（mucous type）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"發生在舌前 2/3 之鱗狀細胞癌，其同側頸部淋巴轉移的機會，下列分區中何者最高？","options":["(A) level Ⅴ","(B) level Ⅱ","(C) level Ⅲ","(D) level Ⅳ"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-24","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"下列藥品中，何者與誘發口瘡性口腔炎（aphthous stomatitis）最有關？","options":["(A) Cox-2 inhibitors","(B) acyclovir","(C) nystatin","(D) denosumab"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"關於顎骨肉瘤（sarcoma of jaw）的敘述，下列何者正確？","options":["(A) 對於骨肉瘤（osteosarcoma）的手術治療，雖然臨床及影像學檢查未發現淋巴轉移，仍應進行選擇性頸部淋 巴廓清術（elective neck dissection）","(B) 低度惡性纖維肉瘤（low-grade fibrosarcoma）應以廣泛性切除手術搭配輔助性放射治療（adjuvant radiotherapy），以求好的疾病控制","(C) 對於手術治療後發現高度惡性脂肪肉瘤（liposarcoma），則應加入輔助性放射治療（adjuvant radiotherapy）","(D) 細胞型態對於橫紋肌肉瘤（rhabdomyosarcoma）是一個重要的預後指標，在 10 歲以上兒童族群，以胚胎型 橫紋肌肉瘤（embryonal rhabdomyosarcoma）最為常見"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"頸部淋巴群介於二腹肌（digastric muscle）之前後二腹間，屬於下列何者？","options":["(A) level ⅠA","(B) level ⅠB","(C) level Ⅱ","(D) level Ⅲ"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"下列何者在手術時或術後的病理檢查，最可能發現 epithelial lining？","options":["(A) traumatic bone cyst","(B) median mandibular cyst","(C) aneurysmal bone cyst","(D) Stafne's bone cyst"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"齒源性角化囊腫（odontogenic keratocyst）與下列何基因突變最相關？","options":["(A) SMO","(B) PTCH","(C) BCL","(D) SHH"],"answer":1,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-114-2-29","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"以環口放射線影像診斷顎骨囊腫時，通常可發現下列何種特性？","options":["(A) 經常出現牙根吸收現象","(B) 周邊骨質常出現緻密反應，可與正常骨質有明顯區別","(C) 絕大多數是多房性","(D) 囊腫中心通常呈現毛玻璃樣（ground glass）影像"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-30","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"顎骨囊腫的治療，下列敘述何者正確？","options":["(A) 單房性（unilocular）囊腫不可使用剜除術為治療術式","(B) 多房性（multilocular）囊腫，手術前建議先進行切片檢查確定診斷","(C) 如囊腫過大或鄰近重要神經組織，應先使用剜除術後再使用造袋術","(D) 含齒囊腫剜除時，通常會將阻生齒保留"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-31","subject":"ya4","topic":"口腔病理基礎","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"下列顎骨囊腫中，若囊腫大小皆為類似，且未造成任何組織與器官的沾黏，更無造成病理性骨折的疑慮，何 者最需要剜除術（enucleation）合併刮除術（curettage）？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 齒源性角化囊腫（odontogenic keratocyst）","(C) 鼻腭囊腫（nasopalatine cyst）","(D) 根尖囊腫（radicular cyst）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"關於下顎枝垂直截骨術（vertical ramus osteotomy）的敘述，下列何者錯誤？","options":["(A) 可以從顎下（submandibular）切線暴露出下顎枝","(B) 可以從口內切線暴露出下顎枝","(C) 遠心段（distal segment）是指包含髁（condyle）的骨段","(D) 可以使用顎間固定（IMF），也可以用鋼線、骨板或骨釘作內固定"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"有關正顎手術的併發症，下列何者錯誤？","options":["(A) 施行下顎枝垂直截骨術，術中可能造成上顎動脈（maxillary artery）或咬肌動脈（masseteric artery） 出血","(B) 施行矢向分裂截骨術，可能會造成下齒槽神經、舌神經或顏面神經的損傷","(C) 矢向分裂截骨術後，可能發生顳顎關節障礙的併發症","(D) 矢向分裂截骨術，骨段接觸面積大且有內固定，術後不會有復發（relapse）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"關於口內下顎枝垂直截骨術（intraoral vertical ramus osteotomy）的敘述，下列何者錯誤？","options":["(A) Bauer retractor 是要用來避免手術中傷害到下齒槽神經","(B) antilingular eminence 可作為下顎孔（mandibular foramen）位置的參考標記之一","(C) 骨切線可距離下顎骨後緣 6～7 mm","(D) 與矢向分裂截骨術（sagittal split osteotomy）相比，對於神經的傷害較少"],"answer":0,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-114-2-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"下列因素何者可能導致牙齒拔除後的疼痛持續存在？①傳入性神經（afferent nerve）損傷導致局部神經過 度活躍 ②中樞神經系統的過度活躍 ③交感神經系統活性異常","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"Ramsay Hunt 綜合症主要影響那一條腦神經？","options":["(A) 三叉神經","(B) 舌咽神經","(C) 顏面神經","(D) 迷走神經"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"關於偏頭痛（migraine）的敘述，下列何者錯誤？","options":["(A) 患者以女性為多，通常單側頭痛，部分患者在發作前會有前兆（aura）","(B) 一般症狀持續 4～72 小時，大多數患者發作時會噁心、畏光","(C) 誘發因子包括生理期、壓力、影響血管作用的食物或藥物、肌肉骨骼障礙造成三叉神經區域的疼痛","(D) 預防勝於治療，平日應以曲坦類（triptans）藥物控制"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"有關唾液腺惡性腫瘤，下列敘述何者錯誤？","options":["(A) 常見包含 mucoepidermoid carcinoma、adenoid cystic carcinoma、adenocarcinoma","(B) 主唾液腺中 parotid gland 最常發生","(C) mucoepidermoid carcinoma 是主唾液腺中最常見的惡性腫瘤","(D) adenoid cystic carcinoma 最常發生在 submandibular gland"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"腮腺的副交感神經支配源自於何處？","options":["(A) 上唾液核（superior salivatory nucleus）","(B) 舌咽神經的鼓室分支（tympanic branch of the glossopharyngeal nerve）","(C) 鼓索神經（chorda tympani）","(D) 顏面神經（facial nerve）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-40","subject":"ya4","topic":"唾液腺疾病","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"下列何者不適用於腮腺腫瘤的處置？","options":["(A) enucleation","(B) superficial parotidectomy","(C) total parotidectomy","(D) modified Blair incision"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"下列 facial buttress 何者不是用來提供垂直方向的支撐（vertical support）？","options":["(A) nasomaxillary buttress","(B) zygomatic buttress","(C) pterygomaxillary buttress","(D) frontal buttress"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"附圖中箭頭所指的骨折屬於下列何者？","options":["(A) condylar neck","(B) diacapitular","(C) subcondylar","(D) sigmoid notch"],"answer":2,"image":"ya4-114-2-42.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"對於外傷脫落開放根尖的牙齒，下列處理何者錯誤？","options":["(A) 脫落時間小於 2 小時，應該儘速做根管永久性充填","(B) 可以保存在牛奶或是 Hanks 溶液","(C) 重新植入後，需固定（splinting）7～10 天","(D) 必要時可用氫氧化鈣幫助根尖成形（apexification）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"下列情況中，何者最容易造成前牙開咬？","options":["(A) 勒福一型骨折（Le Fort Ⅰ fracture）","(B) 顴骨骨折","(C) 下顎骨喙狀突（coronoid process）骨折","(D) 鼻骨骨折"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"關於下顎骨骨折的敘述，下列何者錯誤？","options":["(A) 柳條狀骨折（greenstick fracture）是指未完全骨折，或是骨折只影響到單側皮質骨","(B) 雙側下顎骨角骨折，不會造成前牙開咬，也不會影響呼吸道","(C) 下顎骨開放性骨折是指經由皮膚、黏膜或牙周組織等與外界相通的骨折","(D) 下顎骨骨折可依照部位、生物力學、骨折型態來分類"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"關於牙齒側向脫位（lateral luxation），下列敘述何者最不合理？","options":["(A) 一般而言，要儘快予以復位固定","(B) 牙齒復位後應固定 4 週","(C) 脫位嚴重伴隨齒槽骨斷裂時，可能合併牙齦軟組織外傷，硬組織復位固定後需縫合牙齦組織","(D) 一般而言，側向脫位的牙齒通常不需要根管治療處理，因為牙髓組織壞死的機率很低"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"關於唇腭裂手術後殘留腭瘻管的敘述，下列何者正確？","options":["(A) 原本腭裂越嚴重，術後發生腭瘻管的比例越高","(B) 腭瘻管最常發生在門齒孔之前的硬腭區","(C) 腭瘻管第二常見發生在軟硬腭交界處","(D) 通常都是在施行正顎手術時做殘留腭瘻管修補"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"有關唇腭裂修補手術，下列敘述何者正確？","options":["(A) Von Langenbeck operation 是一種唇縫合手術（cheilorrhaphy）","(B) 硬腭裂手術關閉需包括軟組織及硬組織修補","(C) Vomer flap 可用於軟腭裂修補","(D) 軟腭裂修補需包含鼻黏膜、肌肉及口腔黏膜"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"在牙科治療過程中，對於發生過度換氣（hyperventilation）的敘述，下列何者最不適當？","options":["(A) 可能會發生在對治療感到焦慮的病人，會有呼吸急促並自覺難以呼吸","(B) 應暫停牙科治療，使病人採取坐姿","(C) 因為有呼吸困難的現象，應使用張口器使其維持呼吸道暢通","(D) 若經由基本處置後（包括吸入二氧化碳比例高的空氣），症狀仍然持續，可給與 diazepam"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-50","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"關於牙科治療異物吞入的敘述，下列何者最不適當？","options":["(A) 發生異物吞入應拍攝胸部 X 光及腹部 X 光進行確認","(B) 使用橡皮障（rubber dam）能減少異物吞入的發生","(C) 平躺（supine）的姿勢較容易發生異物吞入","(D) 進入氣管的異物一定會引起強烈的咳嗽"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-51","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"下列何者不屬於牙科診間急救箱中的常備藥物？","options":["(A) 抗生素","(B) 類固醇","(C) 抗組織胺","(D) 抗痙攣藥"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-52","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"病人聲稱近來有顫抖、心跳過速、體重減輕、血壓升高、易怒、不耐熱及眼球突出，最可能原因為何？","options":["(A) 甲狀腺功能亢進症（hyperthyroidism）","(B) 後天免疫缺乏症候群（acquired immunodeficiency syndrome）","(C) 糖尿病（diabetes mellitus）","(D) 腎上腺功能不足（adrenal insufficiency）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"當右側不可復位顳顎關節盤前移合併左側可復位顳顎關節盤前移時，最不可能出現下列何者？","options":["(A) 右側顳顎關節沒有彈響聲（clicking sound）","(B) 側方運動時，下顎往右側比往左側受限","(C) 左側顳顎關節彈響聲（clicking sound）","(D) 張口度最大時下顎向右側偏移"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"醫師請病人於患側對側犬齒處咬壓舌板，藉此觀察患側的顳顎關節處是否有明顯痛感，關於此臨床檢查的敘 述，下列何者錯誤？","options":["(A) 此臨床檢查名稱為 Mahan's sign","(B) 若感覺疼痛，則表示患側的顳顎關節可能有病變","(C) 若感覺疼痛，可診斷病人之患側關節於 Wilkes 分級常為Ⅱ、Ⅲ、Ⅳ","(D) 若病人不感覺到疼痛，則可以診斷此關節 Wilkes 分級為Ⅰ"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"關於顳顎關節全置換，視野最佳的手術切線（surgical approach）為下列何者？","options":["(A) 僅耳前切線即可（preauricular incision alone）","(B) 耳前切線加下顎後切線（preauricular incision + retromandibular incision）","(C) 僅需要顎下切線（submandibular incision alone）","(D) 僅需要冠狀切線（coronal incision alone）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-56","subject":"ya4","topic":"全身性疾病與急症","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"有關人類免疫缺陷病毒（human immunodeficiency virus, HIV）陽性病患接受牙科治療，下列敘述何者錯 誤？","options":["(A) 治療時依照感控標準程序做預防處理","(B) 病患沒有主動告知醫師其已感染 HIV 的義務","(C) 病患提供其感染事實後，醫師不得拒絕提供治療","(D) HIV 病患可以接受拔牙等侵入性治療"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"β射線之 LET（linear energy transfer）比α射線小，因此它的組織穿透力與α射線的比較結果為何？","options":["(A) 較大","(B) 較小","(C) 一樣","(D) 不一定，因不同組織而異"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"牙科 X 光檢查，除了要提高管電壓，增加濾片厚度以外，常使用長方形的瞄準儀（collimator），其主要的 目的是為了減少病人的：","options":["(A) 不適感","(B) 暴露時間","(C) 暴露面積","(D) 移動"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"下列何者不是傳統 X 光底片中鉛薄片（thin lead foil）的主要功能？","options":["(A) 防止後向散射（backscatter radiation）","(B) 減少病人的輻射暴露","(C) 發現拍攝時底片的方向錯誤","(D) 降低影像的對比（contrast）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"下列口外片的拍攝方法，何者的底片匣最靠近頭頂？","options":["(A) submentovertex projection","(B) Waters projection","(C) cephalometric projection","(D) reverse Towne projection"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"關於拍攝根尖片（periapical film）的步驟，下列何者為正確排序？①調整 X 光機的拍攝條件 ②請病人進 行拍攝前準備並坐上位置 ③完成拍攝 ④開啟 X 光機並準備設備 ⑤將接受器（receptor）放入病人口中","options":["(A) ④①②⑤③","(B) ④②①⑤③","(C) ④②⑤①③","(D) ④⑤①②③"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-62","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"下列何種 2D 影像攝影較適合用於檢查病人的顱底腫瘤或顴骨弓骨折？","options":["(A) lateral cephalometric projection","(B) posteroanetrior cephalometric projection","(C) submentovertex projection","(D) reverse Towne projection"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-63","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"照 X 光時使用之鉛裙，其鉛的厚度至少為幾 mm？","options":["(A) 0.10","(B) 0.15","(C) 0.20","(D) 0.25"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-64","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"側顱 X 光片可用於評估呼吸道的狀況，下列何者最有可能是附圖中黑色箭頭所指的部位？","options":["(A) 鼻腔（nasal cavity）","(B) 鼻咽（nasopharynx）","(C) 口咽（oropharynx）","(D) 下咽腔（hypopharynx）"],"answer":2,"image":"ya4-114-2-64.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-65","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"附圖 X 光影像中，星號所標示的解剖構造為何？","options":["(A) 鼻腭管（nasopalatine canal）","(B) 鼻淚管（nasolacrimal canal）","(C) 鼻腭囊腫（nasopalatine cyst）","(D) 根尖囊腫（radicular cyst）"],"answer":0,"image":"ya4-114-2-65.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-66","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"上顎門齒區之根尖 X 光片中，下列何者最不常見？","options":["(A) 門齒孔（incisive foramen）","(B) 前鼻棘（anterior nasal spine）","(C) 上顎間縫（intermaxillary suture）","(D) 鼻唇皺摺（nasolabial fold）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-67","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"附圖 X 光片中，右上側門齒的牙根異常為何？","options":["(A) 牙根內吸收（internal root resorption）","(B) 牙根外吸收（external root resorption）","(C) 牙根齲齒（root caries）","(D) 牙根斷裂（root fracture）"],"answer":0,"image":"ya4-114-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-68","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"關於圖中 36、37 齒間牙周炎破壞區域的 X 光攝影特徵，下列敘述何者錯誤？","options":["(A) 有垂直骨缺損（vertical bone defect）","(B) 有齒間陷口（interdental crater）","(C) 有牙結石","(D) 有反應性骨硬化（reactive bone sclerosis）"],"answer":0,"image":"ya4-114-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-69","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"38 歲女性，主訴右側牙齦持續腫脹、咬痛數週，口檢時發現右下第二小臼齒頰側黏膜牙齦連接 （mucogingival junction）附近有膿腫（abscess），電髓試驗結果 10/10。環口放射線攝影（panoramic radiography）與牙根尖放射線攝影（periapical radiography）結果如附圖。有關箭頭所標示的放射線透過 性（radiolucent）區域，下列敘述何者正確？","options":["(A) a 是根尖炎性疾病（periapical inflammatory disease）造成的；b 是頦孔（mental foramen）","(B) a 與 b 都是根尖炎性疾病（periapical inflammatory disease）造成的","(C) a 是頦孔（mental foramen）；b 是根尖炎性疾病（periapical inflammatory disease）造成的","(D) a 與 b 都是頦孔（mental foramen）"],"answer":1,"image":"ya4-114-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-70","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"依據附圖 X 光片，最不可能的診斷為何？","options":["(A) osteoporosis","(B) osteomyelitis","(C) osteoradionecrosis","(D) medication-related osteonecrosis（MRONJ）"],"answer":0,"image":"ya4-114-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-71","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"環口 X 光影像中靠近第 3、4 節頸椎處，箭頭所指軟組織中的鈣化物，最可能的診斷為下列何者？","options":["(A) calcified atherosclerotic plaque","(B) osteophytes of cervical spine","(C) sialoliths","(D) tonsilloliths"],"answer":0,"image":"ya4-114-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-72","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"關於下顎骨骨折的評估，下列敘述何者最不適當？","options":["(A) 懷疑下顎骨角骨折，可以拍攝咬合片評估","(B) 懷疑下顎骨骨體骨折，可以拍攝 oblique lateral 評估","(C) 懷疑下顎骨髁頭骨折，可以拍攝環口片評估","(D) 懷疑下顎骨聯合骨折，可以拍攝咬合片評估"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-73","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"附圖所示之 X 光影像是由何種拍攝方式所產生？","options":["(A) posteroanterior projection","(B) Waters projection","(C) reverse Towne projection","(D) oblique lateral projection"],"answer":1,"image":"ya4-114-2-73.jpeg","clinical_level":"重點"},{"id":"ya4-114-2-74","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"承上題，這種影像，最不適合評估下列何者？","options":["(A) 慢性鼻竇炎","(B) 下顎骨髁頭骨折","(C) 眼眶骨骨折","(D) 顴骨骨折"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-75","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"下列疾病何者不具有如圖之影像學特徵？","options":["(A) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(B) 平伯氏腫瘤（Pindborg tumor）","(C) 齒源性角化囊腫（odontogenic keratocyst）","(D) 戈林氏囊腫（Gorlin cyst）"],"answer":2,"image":"ya4-114-2-75.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-76","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"下列何種疾病最可能導致顎骨整體性骨密度偏低（generalized rarefactions of the jaw bones），類似骨 質疏鬆（osteoporosis）的影像特徵？","options":["(A) 克新氏症候群（Cushing's syndrome）","(B) 戈林氏症候群（Gorlin syndrome）","(C) 阿爾培可欣堡病（Albers-Schonberg disease）","(D) 嘉德耐氏症候群（Gardner's syndrome）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-77","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"附圖箭頭所指之牙齒影像被稱為下列何者？","options":["(A) 殼狀牙齒（shell teeth）","(B) 影子牙齒（ghost teeth）","(C) 鏟形牙齒（shovel teeth）","(D) 牙中牙（dens in dente）"],"answer":1,"image":"ya4-114-2-77.jpeg","clinical_level":"一般"},{"id":"ya4-114-2-78","subject":"ya4","topic":"放射影像診斷","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"下列何者最不會呈現多發性放射線透過性病變（multifocal radiolucencies）？","options":["(A) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）","(B) 天使病（cherubism）","(C) 蘭格罕氏細胞組織細胞增多症（Langerhans cell histiocytosis）","(D) 甲狀腺機能亢進（hyperthyroidism）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-114-2-79","subject":"ya4","topic":"放射線原理與技術","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"關於牙科數位 X 光影像與傳統 X 光影像之敘述，下列何者正確？","options":["(A) 數位 X 光影像所需之初期建置成本較低","(B) 數位 X 光影像較容易被複製與傳遞","(C) 傳統 X 光影像輻射劑量暴露較少","(D) 傳統 X 光影像需使用 photostimulable phosphor（PSP）technology"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-114-2-80","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"關於頭頸部癌症放射線療法副作用之敘述，下列何者錯誤？","options":["(A) 可造成急性黏膜炎及皮膚炎","(B) 黏液性唾液腺較漿液性唾液腺更具放射線敏感性","(C) 下顎骨發生放射線性骨壞死的機率較上顎骨為高","(D) 治療開始前三週以上完成牙科治療，可大幅降低發生放射線性骨壞死之機會"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-1","subject":"ya4","topic":"口腔外科基礎","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"進行口內軟組織手術時，下列敘述何者最為適當？","options":["(A) 以手臂而非手腕運行手術刀，較能夠精準地切開軟組織","(B) 刀片應與黏膜表面呈 45 度角切入，方可避免損及傷口邊緣的血液供應","(C) 最好避免在犬齒隆突等突出處進行切開","(D) 術中以擦拭（wiping）傷口的方式止血最為有效"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-2","subject":"ya4","topic":"口腔外科基礎","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"有關手術後組織水腫的形成與處置，下列敘述何者最適當？","options":["(A) 水腫主因是血管的損傷及纖維蛋白阻塞淋巴，體液滲漏並積蓄在組織間隙內","(B) 損傷區域內疏鬆結締組織愈少，水腫反應愈明顯，冰敷效果則極佳","(C) 局部注射皮質類固醇，可有效減少發炎反應與體液滲漏","(D) 以皮質類固醇降低組織水腫，在術後的第一天給與效果最佳"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-3","subject":"ya4","topic":"口腔外科基礎","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"下列何者不屬於直接造成組織受傷的化學性原因？","options":["(A) 蛋白酶（proteases）","(B) 輻射線（irradiation）","(C) 血管收縮劑（vasoconstrictors）","(D) 使血栓形成的物質（thrombogenic agent）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-4","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"骨折癒合過程中的造骨細胞（osteoblast）不會來自下列何者？","options":["(A) periosteum","(B) endosteum","(C) circulating pluripotential mesenchymal cells","(D) monocyte precursor cells"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-5","subject":"ya4","topic":"局部與全身麻醉","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"在含有適當血管收縮劑濃度下，下列何種局部麻醉劑的作用時間最長？","options":["(A) articaine","(B) bupivacaine","(C) lidocaine","(D) mepivacaine"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-6","subject":"ya4","topic":"局部與全身麻醉","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"有一位因為關節炎導致張口受限，最大張口度 5 mm 的患者，需拔除下顎第一及第二大臼齒殘根，下列何種神 經阻斷術最適用？","options":["(A) 傳統的下齒槽神經阻斷術及頰神經阻斷術","(B) Gow-Gates technique","(C) Vazirani-Akinosi technique 及頰神經阻斷術","(D) 門齒神經阻斷術"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-7","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"病患於接受下齒槽神經阻斷（inferior alveolar nerve block）幾天後，抱怨仍有下唇麻木及自發性銳痛， 但輕觸及針刺不覺疼痛，此情況屬於下列何者？","options":["(A) allodynia","(B) hyperalgesia","(C) dysesthesia","(D) hyperesthesia"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-8","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"有關拔牙手術與併發症，下列何者關聯性最低？","options":["(A) 上顎大臼齒拔除，有牙根斷片掉入上顎竇","(B) 下顎第三大臼齒拔除，有牙根斷片掉入舌下間隙","(C) 下顎犬齒拔除術後感染，引起海綿竇栓塞（cavernous sinus thrombosis）","(D) 下顎第一小臼齒殘根移除，發生頦神經（mental nerve）傷害"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-9","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"圖中所顯示的阻生齒，是屬於 Pell and Gregory 的那一種分類？","options":["(A) class 2 B","(B) class 2 C","(C) class 3 B","(D) class 3 C"],"answer":0,"image":"ya4-115-1-9.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-10","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"圖示之拔牙鉗，適合用於拔除那一種有牙根分叉牙齒？","options":["(A) 上顎大臼齒","(B) 上顎小臼齒","(C) 下顎大臼齒","(D) 下顎小臼齒"],"answer":0,"image":"ya4-115-1-10.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-11","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"下列四種情況的患者，欲進行相同難度的拔牙處置，何者風險較低？","options":["(A) 血壓在 140～159 mmHg／90～94 mmHg 之間的成年患者","(B) 患有症狀性甲狀腺功能亢進或低下的患者","(C) 控制不穩的癲癇患者（每年發作數次）","(D) 胰島素依賴性糖尿病（IDDM）控制不好的患者"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-12","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"有關下顎水平智齒嚴重牙冠周圍炎之敘述，下列何者正確？","options":["(A) 宜儘速拔除，以減少拔牙後的併發症","(B) 若同側上顎智齒有咬到牙冠周圍炎腫脹之組織，可考慮先予拔除","(C) 牙冠周圍炎不論嚴重程度，均須先使用抗生素治療","(D) 若造成嚴重的張口困難時，應立即拔除"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-13","subject":"ya4","topic":"齒源性感染與藥物","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"關於齒源性感染的處置，下列敘述何者最不適當？","options":["(A) 必要時需採取措施維持呼吸道暢通","(B) 對於嚴重的感染，應儘早進行細菌培養和敏感性測試","(C) 靜脈注射抗生素治療可作為控制、侷限感染的一種手段","(D) 沖洗引流傷口會造成細菌、膿液擴散至更深的解剖間隙"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-14","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"關於口腔黴菌感染，下列敘述何者最不適當？","options":["(A) 白色念珠菌是最常見的口腔黴菌感染，為伺機性感染","(B) 口腔念珠菌與口腔黏膜發育異常（dysplasia）的進展未必呈正相關","(C) 口腔念珠菌可用 nystatin，但不可以局部施於病灶處","(D) 從口腔白斑病變中分離出的念珠菌可能產生致癌物"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"若未適當處置，下列何者為盧德威氏口峽炎（Ludwig's angina）最常見的併發症？","options":["(A) 海綿竇栓塞","(B) 肺栓塞","(C) 呼吸道阻塞","(D) 廣泛性血管栓塞"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-16","subject":"ya4","topic":"植牙外科","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"關於齒槽嵴牽引（alveolar ridge distraction），下列敘述何者錯誤？","options":["(A) 潛伏期（latency period）大約 5～7 天","(B) 以每天約 1 毫米的速度逐漸牽引","(C) 鞏固期（consolidation period）約 3～4 個星期","(D) 可以做垂直或水平方向牽引"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-17","subject":"ya4","topic":"植牙外科","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"下列何者為人工牙根種植前，進行下顎補骨手術所欲達成的治療效果？①使有足夠長度的植體可以植入 ② 使有足夠寬度的植體可以植入 ③降低術後骨折的風險 ④降低後續重建時神經損傷的風險","options":["(A) 僅②④","(B) 僅①③④","(C) 僅①②③","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-18","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"影像檢查中，下列何者可以精確測量出齒槽嵴（alveolar ridge）寬度？","options":["(A) 牙根尖片","(B) 側顱 X 光片","(C) 核磁共振","(D) 錐狀射束電腦斷層攝影（cone-beam CT）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-19","subject":"ya4","topic":"植牙外科","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"若每顆缺失牙齒都以一支人工牙根重建，下列那一區域在植入位置選擇上會最困難？","options":["(A) 下顎門牙區","(B) 上顎門牙區","(C) 上顎小臼齒區","(D) 下顎小臼齒區"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-20","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"齒源性黏液瘤（odontogenic myxoma）為良性齒源性腫瘤，下列敘述何者錯誤？","options":["(A) 腫瘤的周邊沒有膜包圍（non-encapsulated）","(B) 放射影像具特異性，可憑之得到正確診斷","(C) 腫瘤組織會浸潤入（infiltrate）周圍的骨組織","(D) 腫瘤切除時需有適當的邊緣距離（margin），防止復發"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-21","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"有關齒瘤（odontoma）的好發部位，下列敘述何者正確？","options":["(A) complex odontoma 好發於上顎前牙區","(B) compound odontoma 好發於上顎後牙區","(C) complex odontoma 好發於下顎前牙區","(D) compound odontoma 好發於上顎前牙區"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-22","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"下列何者以剜除術（enucleation）處置，復發率最低？","options":["(A) 鱗狀齒源性瘤（squamous odontogenic tumor）","(B) 造牙骨質細胞瘤（cementoblastoma）","(C) 齒源性黏液瘤（odontogenic myxoma）","(D) 造釉細胞齒瘤（ameloblastic odontoma）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-23","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"根據 American Joint Committee on Cancer（AJCC）第八版對於口腔癌分期的定義，下列分期何者正確？","options":["(A) 最大徑為 2.5 cm，侵犯深度為 12 mm 之舌癌為 T2","(B) 最大徑為 2.5 cm，侵犯深度為 4 mm 並且造成皮質骨表面侵蝕之下顎牙齦癌為 T4a","(C) 最大徑為 3.5 cm，侵犯深度為 12 mm 之頰黏膜癌為 T3","(D) 同側兩顆淋巴結發生轉移，且未有淋巴結外侵犯（extranodal extension）為 N2a"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-24","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"下列何者與齒源性角化囊腫（odontogenic keratocyst）的高復發率有關？","options":["(A) 病灶會穿透皮質骨（cortical perforation）","(B) 病灶位於下顎骨角（mandible angle）","(C) 手術時未摘除周邊之衛星囊腫（satellite cysts）","(D) 其上皮細胞通常較厚且有乳突狀突起"],"answer":2,"image":"","clinical_level":"重點(深度)"},{"id":"ya4-115-1-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"放射治療（radiotherapy）對於口腔顎顏面組織的影響，下列敘述何者錯誤？","options":["(A) 一般來說，第二週後開始會造成口腔黏膜潰瘍與疼痛","(B) 由於唾液腺上皮代謝速率快，有高度放射線敏感度（radiosensitive），故常呈現唾液腺萎縮，造成口乾症","(C) 會導致照射區域的肌肉慢性發炎進而纖維化，導致病人張口受限","(D) 會造成口腔微生物菌叢改變，故在口腔衛生不良病人身上可見口腔念珠菌感染（oral candidiasis）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"Supraomohyoid neck dissection 為口腔癌手術中常使用的頸部淋巴廓清術，下列何者為該術式所清除的淋 巴層？①Level Ⅰ ②Level Ⅱ ③Level Ⅲ ④Level Ⅳ","options":["(A) 僅①②","(B) ①②③","(C) ②③④","(D) ①④"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-27","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"關於含齒囊腫（dentigerous cyst）的臨床特徵，下列敘述何者錯誤？","options":["(A) 為 X 光透射單室性（unilocular radiolucency）病灶","(B) 會與一顆未萌發牙齒相關連，會造成病灶區齒槽骨膨脹","(C) X 光影像常會有硬化邊緣（sclerotic border）","(D) 當 pericoronal radiolucency 介於 0.5～1 cm，可判斷為變大的齒濾泡（dental follicle）而非囊腫"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-28","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"下列那一個病變最可能與齒瘤（odontoma）、腺體樣齒源性腫瘤（adenomatoid odontogenic tumor）或造釉 細胞瘤（ameloblastoma）等併存？","options":["(A) 含齒囊腫（dentigerous cyst）","(B) 齒源性角化囊腫（odontogenic keratocyst）","(C) 腺狀齒源性囊腫（glandular odontogenic cyst）","(D) 鈣化齒源性囊腫（calcifying odontogenic cyst）"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-29","subject":"ya4","topic":"口腔外科基礎","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"關於顎骨囊腫剜除術（enucleation），下列敘述何者正確？","options":["(A) 可以保留伴有含齒囊腫的阻生齒","(B) 手術時不可以拔除牙齒，以免妨害囊腫根除","(C) 剜除術施行時應儘量將囊腫完整一體移除，以減少殘留囊腫組織及復發之機會","(D) 與造袋術相比，可降低病理性骨折的風險"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-30","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"下列何者屬於發育性齒源性囊腫？①濾泡囊腫（follicular cyst） ②齒源性角化囊腫（odontogenic keratocyst） ③根尖囊腫（radicular cyst） ④鼻腭管囊腫（nasopalatine duct cyst）","options":["(A) ①②","(B) ①③","(C) ②④","(D) ②③"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-31","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"齒源性角化囊腫的患者同時合併發生基底細胞癌，如果患者為女性，則最可能患下列何種婦女病？","options":["(A) 子宮頸癌","(B) 子宮肌腺症","(C) 卵巢纖維瘤","(D) 乳癌"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"關於下顎枝垂直截骨術（vertical ramus osteotomy）的敘述，何者錯誤？","options":["(A) 可以從口外皮膚切開，也可以從口內黏膜切開，暴露出下顎枝","(B) 口外切線唯一的缺點是會在皮膚上留下疤痕","(C) 口外切線視野比較清楚，但較少被採用","(D) 口內下顎枝垂直截骨術，可使用有角度的擺動鋸（oscillating saw）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"關於咬合平面（occlusal plane）的敘述，下列何者錯誤？","options":["(A) 咬合平面和法蘭克福平面（Frankfort horizontal plane）的夾角，正常範圍為 30 度±2 度","(B) 通常手術增加咬合平面角度（occlusal plane angle），也會增加下顎平面角度（mandibular plane angle）","(C) 高咬合平面顏面形態（high occlusal plane angle facial morphology）的病人較常合併有顳顎關節病變","(D) 當上下顎複合體（maxillomandibular complex）以上門牙切端（incisor edge）做逆時針方向旋轉時，後 顏面高度（posterior facial height）將會增加"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"下列何者是造成齒顏面畸形（dentofacial deformity）的可能原因？①遺傳 ②生長過程中的全身性疾病 ③外傷 ④環境","options":["(A) 僅①④","(B) 僅①②③","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"關於帶狀疱疹後神經痛（postherpetic neuralgia, PHN）的敘述，下列何者正確？","options":["(A) 帶狀疱疹病毒第二次再活化（reactivated）發生率大於 10％","(B) 疼痛通常發生在出現皮疹之前","(C) PHN 的治療通常使用抗生素","(D) PHN 病例中，三叉神經侵犯的情況比胸神經侵犯更常見"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"病人主述吞嚥時產生尖銳的電擊般疼痛，並感覺下顎區疼痛，最可能為下列那一神經出現問題？","options":["(A) 動眼神經","(B) 顏面神經","(C) 舌咽神經","(D) 副脊神經"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"病人求診主訴右上後牙區尖銳疼痛，並伴隨同側流鼻涕、流淚和顳部疼痛，最可能是下列何種病症？","options":["(A) 顳部動脈炎（temporal arteritis）","(B) 偏頭痛（migraine）","(C) 叢發性頭痛（cluster headache）","(D) 緊張性頭痛（tension headache）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-38","subject":"ya4","topic":"唾液腺疾病","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"60 歲男性，有抽菸習慣，因右臉頰腫脹將近 10 年，期間並無明顯疼痛及大小改變的現象，臨床懷疑為右側 腮腺瓦新氏腫瘤（Warthin's tumor），下列有關診斷之敘述，何者錯誤？","options":["(A) 瓦新氏腫瘤觸診之感覺較軟，像麵團（doughy）一般","(B) 若想進一步進行病理學檢驗，可考慮進行針刺切片檢查（needle biopsy）","(C) 瓦新氏腫瘤在氟化去氧葡萄糖正子攝影檢查（FDG positron emission tomography）呈現高代謝活性（high metabolic activity）","(D) 瓦新氏腫瘤鎝 99m 閃爍檢查（Technetium-99m scintigraphy）信號呈現常為「冷病灶（cold lesion）」"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-39","subject":"ya4","topic":"唾液腺疾病","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"有關唾液腺結石的敘述，下列何者錯誤？","options":["(A) 大部分是單一結石","(B) 唾液腺結石成分包含磷酸鈣","(C) 腮腺管是較容易發生結石的位置，其原因在於唾液成分偏鹼性","(D) 併發症包括急性化膿性唾液腺炎、唾液管擴張或慢性纖維化狹窄"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-40","subject":"ya4","topic":"唾液腺疾病","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"有關 Sjögren syndrome 之敘述，下列何者錯誤？","options":["(A) 是一種自體免疫疾病，通常會侵犯淚腺和唾液腺","(B) 女性的發病率遠高於男性","(C) 可區分為原發性和繼發性兩種","(D) 大唾液腺切片是診斷的主要依據"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"對於顏面軟組織外傷，下列敘述何者錯誤？","options":["(A) 顏面組織因血液循環好，縫合時效性上較無所謂黃金時間（golden period）的考量","(B) 臉頰外傷位置在外眼眥垂線（vertical line from lateral canthus）前方時，可以不需進行顏面神經吻合 修補","(C) 為了傷口清潔及去除異物，建議以雙氧水進行沖洗及消毒","(D) 顏面軟組織恢復快，但雖經過適當修補，其組織強度即使 1 年也無法完全恢復至受傷前之強度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"依據附圖，關於病人的臨床症狀或治療考量，下列何者最不可能？","options":["(A) 張口時下顎會往左邊偏移","(B) 左側後牙咬合會有過早接觸（premature contact）現象","(C) 會有左下嘴唇麻木（lip numbness）現象","(D) 可經下顎後路徑（retromandibular approach）來進行復位及固定"],"answer":2,"image":"ya4-115-1-42.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-43","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"病人發生車禍後，有下唇穿刺傷及左下正中門齒牙冠斷裂，若懷疑下唇傷口中存有斷裂的牙冠碎片時，使用 下列何種放射線檢查來協助診斷最適當？","options":["(A) Waters view","(B) 骨掃描檢查（bone scan）","(C) 口底放一張咬合片，從頦下（submental）的方向拍攝","(D) 下唇內側放一張根尖片，以平時拍攝牙齒根尖片的 1/2～1/3 放射線劑量拍攝"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"圖中箭頭所指的骨折，下列何者正確？①favorable fracture ②unfavorable fracture ③容易錯位 ④ 不容易錯位","options":["(A) ②④","(B) ①③","(C) ①④","(D) ②③"],"answer":2,"image":"ya4-115-1-44.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"下列何者不是 naso-orbitoethmoid（NOE）fracture 常見的後遺症？","options":["(A) 淚溢（epiphora）","(B) 眼距變寬（telecanthus）","(C) 咬合不正（malocclusion）","(D) 馬鞍鼻（saddle nose）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"下列何者為 compound fracture？","options":["(A) 骨折只影響到皮質骨、不完全斷裂、沒有位移","(B) 多處骨折但未與外界相通","(C) 骨折碎裂成多塊","(D) 骨折處經由皮膚、黏膜或牙周組織與外界相通"],"answer":3,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"關於腭裂修補手術，下列敘述何者正確？①重建吞嚥及發音功能 ②應儘量降低對上顎生長的干擾 ③改善 咽帆功能（velopharyngeal functions）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-48","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"唇腭裂病患施予上顎前移手術以改善不足之中臉部時，下列敘述何者錯誤？","options":["(A) 上顎手術後若導致鼻音更嚴重，可再考慮以其他術式改善","(B) 改善鼻音的手術，建議在上顎手術 6 個月後再進行","(C) 咽部皮瓣（pharyngeal flap）為改善鼻音常用的術式","(D) 上顎手術後，大部分病人需要用其他術式改善鼻音"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-49","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"許多患者對於牙科治療會感到焦慮，下列何種急症較不可能被焦慮引發？","options":["(A) angina pectoris","(B) pulmonary edema","(C) hyperventilation","(D) severe hypertension"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-50","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"關於牙科處置時發生異物吸入（foreign body aspiration）產生呼吸道阻塞，下列敘述何者錯誤？","options":["(A) 若仍有正常的嘔吐反射且異物為部分阻塞的程度，可以鼓勵患者先嘗試自行咳出","(B) 已造成呼吸道完全阻塞（complete obstruction），而且成年病人已意識喪失，此時可用哈姆立克法 （Heimlich maneuver ) 嘗試排出異物","(C) 若異物無法自行咳出，也無法經由哈姆立克法使其排出，則可使用喉頭鏡（laryngoscopy）輔助夾出或是氣 管鏡（bronchoscopy）取出","(D) 若異物持續無法取出，且無法呼吸，持續呈現缺氧狀態，則可進行緊急環甲切開術（cricothyrotomy）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-51","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"下列血漿中的 plasma factors 何者不會影響 prothrombin time？","options":["(A) Ⅱ","(B) Ⅴ","(C) Ⅸ","(D) Ⅹ"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-52","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"下列那些藥物可能會誘發氣喘病人的發作？①aspirin ②ibuprofen ③acetaminophen ④corticosteroid ⑤theophylline ⑥epinephrine","options":["(A) ①②③","(B) ④⑤⑥","(C) 僅①②","(D) ③④"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"嚴重顳顎關節病理性破壞造成之症狀，不包含下列何者？","options":["(A) 嚴重張口受限","(B) 髁頭或下顎枝垂直高度改變","(C) 咬合不正","(D) 開閉口活動時關節內彈響聲"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"關於單側不可復位關節盤前移（anterior disk displacement without reduction），下列何者錯誤？","options":["(A) 開口時下顎偏向非患側","(B) 開口受到限制","(C) 開口時不會發生彈響聲（clicking sound）","(D) 關節盤無法滑動（sliding）"],"answer":0,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"下列何者不是手術治療顳顎關節黏連常發生之併發症？","options":["(A) 復發性之關節黏連（recurrent ankylosis）","(B) 味覺異常（parageusia）","(C) 神經損傷（nerve injury）","(D) 咬合不正（malocclusion）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-56","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"關於 DNR（do not resuscitate），下列何者錯誤？","options":["(A) 國內的 DNR 法律文件包括有病人自己簽署的「預立安寧緩和醫療暨維生醫療抉擇意願書」和病人無法表達意 見時由家屬代為簽署的「不施行心肺復甦術同意書」","(B) 安寧緩和醫療意願書和不施行心肺復甦術同意書的執行條件，都只有在病人已經被兩位相關專科醫師診斷為 「末期病人」，即罹患嚴重傷病不可治癒，且近期內病程會進行至死亡者","(C) 成年且具有完全行為能力的人，得預立選擇安寧緩和醫療意願書，可親自簽名或蓋章者，不需在場見證人簽 名即可完成","(D) DNR（do not resuscitate）是「不施行心肺復甦術」的英語縮寫，指的是當末期病人臨終時，不以電擊、 強心劑、心臟按壓、呼吸道插管等措施恢復或維持病人的呼吸心跳"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-57","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"關於輻射線（radiation）的敘述，下列何者錯誤？","options":["(A) X 光射線（X-ray）和珈瑪射線（γ-ray）皆屬電磁輻射","(B) 電磁輻射之能量與波長成反比","(C) 高速β-微粒於組織中之穿透深度最大可達 5 公分","(D) 微粒輻射之線性能量轉換（linear energy transfer）與微粒之質量、速度以及電荷有關"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-58","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"如果沒有理想的輻射防護下，放射師拍攝 X 光片時，應該要距離多少公尺？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-59","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"附圖中所示之感應片（sensor plate）上的阿拉伯數字「2」及「4」其意義為何？","options":["(A) 表示口內感應片之種類","(B) 為產品的序列代號","(C) 表示能重複使用的次數","(D) 表示產品的生產代數（generation number）"],"answer":0,"image":"ya4-115-1-59.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-60","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"下列 X 光影像中，a 與 b 標示分別為何？","options":["(A) a：顴突（zygomatic process），b：上顎竇（maxillary antrum）底部","(B) a：顴突（zygomatic process），b：齒槽嵴尖（alveolar crest）","(C) a：上顎竇（maxillary antrum）底部，b：齒槽嵴尖（alveolar crest）","(D) a：上顎竇（maxillary antrum）底部，b：顴突（zygomatic process）"],"answer":0,"image":"ya4-115-1-60.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-61","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"關於 2-D 牙科放射線攝影的基本原則的敘述，下列何者錯誤？","options":["(A) X 光機陽極的焦點（focal spot）愈小愈好","(B) 放射源（X-ray source）與接受器（receptor）距離愈短愈好","(C) 拍攝物體（object）與接受器（receptor）距離愈短愈好","(D) 接受器（receptor）與拍攝物體（object）的長軸應儘量平行"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-62","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"關於電腦斷層（computed tomography）的敘述，下列何者錯誤？","options":["(A) 照射時 X 光管頭以 slip-ring 方式繞病人持續旋轉，可減少檢查時間及最多 75%的輻射劑量","(B) 依據組織密度不同，有不同的 X 光吸收量，呈現不同程度的灰階，稱為 Hounsfield unit","(C) 拍攝時得到 axial 及 coronal section，再由電腦重組出 sagittal section 及 3-D 影像","(D) 可藉由調整 window level 及 window width 改變特定組織的識別度"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-63","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"關於核磁共振攝影的敘述，下列何者正確？","options":["(A) T1 加權（T1-weighted）影像用於描述病理性改變，如發炎及腫瘤","(B) T2 加權（T2-weighted）影像通常用於顯示解剖構造","(C) 不同波序（pulse sequence）可加強或抑制特定的組織在影像上的表現","(D) 優點為具多重切面技術（multi-plane）、極佳的軟組織表現、掃描快速、檢查時間短"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-64","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"下列 X 光影像，是以基線眥耳線（canthomeatal line）與 X 光片（film）呈現多少角度拍攝而得？","options":["(A) 平行","(B) 負 30 度","(C) 10 度","(D) 37 度"],"answer":3,"image":"ya4-115-1-64.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-65","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"附圖中白色箭頭所指部位為下列何者之影像？","options":["(A) 上嘴唇","(B) 鼻頭","(C) X 光片刮痕","(D) 上顎前牙牙齦"],"answer":1,"image":"ya4-115-1-65.jpeg","clinical_level":"重點"},{"id":"ya4-115-1-66","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"圖中箭頭所指的放射線不透過性白線（radiopaque line）為下列何者？","options":["(A) 門齒孔（incisive foramen）","(B) 上顎間縫（intermaxillary suture）","(C) 鼻中隔（nasal septum）","(D) 鼻腭管側壁（lateral walls of nasopalatine canal）"],"answer":3,"image":"ya4-115-1-66.jpeg","clinical_level":"重點"},{"id":"ya4-115-1-67","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"病人主訴牙齒容易移位及脫落，其局部根尖片顯示如圖，此病人最可能罹患何種疾病？","options":["(A) 局部牙齒發育不良（regional odontodysplasia）","(B) 第一型牙本質發育不良（dentin dysplasia type I）","(C) 第二型牙本質發育不良（dentin dysplasia type II）","(D) 牙本質形成不良（dentinogenesis imperfecta）"],"answer":1,"image":"ya4-115-1-67.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-68","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"附圖 X 光片中 47 近心側齒槽骨流失的比例，應如何計算？ （a：近心邊緣嵴，b：牙骨質－牙釉質交界，c：牙骨質－牙釉質交界往牙根 2 mm 處，d：齒槽嵴尖，e：牙 根尖）","options":["(A) （b 至 d 距離）÷（a 至 e 距離）× 100%","(B) （b 至 d 距離）÷（b 至 e 距離）× 100%","(C) （c 至 d 距離）÷（c 至 e 距離）× 100%","(D) （c 至 d 距離）÷（b 至 e 距離）× 100%"],"answer":2,"image":"ya4-115-1-68.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-69","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"附圖中，所標示的牙周炎齒槽突（alveolar process）變化，最可能為何？","options":["(A) 頰側或舌側皮質板喪失（buccal or lingual cortical plate loss）","(B) 根叉侵犯（furcation involvement）","(C) 齒間陷口（interdental crater）","(D) 水平骨缺損（horizontal bone loss）"],"answer":0,"image":"ya4-115-1-69.jpeg","clinical_level":"重點"},{"id":"ya4-115-1-70","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"14 歲病人，其 X 光影像由箭頭所標示的病灶被判斷是內生贅骨（enostosis），而不是硬化性骨炎 （sclerosing osteitis）。下列判斷依據，何者最不適合？","options":["(A) 牙齒沒有齲齒","(B) 牙周韌帶空間（periodontal ligament space）寬度一致","(C) 開放型根尖（open apex）","(D) 放射線不透過性（radiopaque）區域與周圍正常骨質的交界清楚"],"answer":2,"image":"ya4-115-1-70.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-71","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"下列 X 光影像中，何者最符合 hypophosphatasia 的特徵？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"ya4-115-1-71.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-72","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"下列何種病變，其發生位置和 X 光影像，與根尖囊腫（radicular cyst）最為相似？","options":["(A) 硬化性骨炎（condensing osteitis）","(B) 骨化纖維瘤（ossifying fibroma）","(C) 早期牙根尖牙骨質-骨質發育不良（early-stage periapical cemento-osseous dysplasia）","(D) 中期牙根尖牙骨質-骨質發育不良（middle-stage periapical cemento-osseous dysplasia）"],"answer":2,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-73","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"附圖之下顎後牙區之根尖片影像，最可能之牙齒變異（tooth anomaly）為何？","options":["(A) 缺牙（missing tooth）","(B) 牛型臼齒（taurodontism）","(C) 牙本質發育不全（dentinogenesis imperfecta）","(D) 牙釉質發育不全（amelogenesis imperfecta）"],"answer":1,"image":"ya4-115-1-73.jpeg","clinical_level":"重點"},{"id":"ya4-115-1-74","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"顎骨中愛溫氏肉瘤（Ewing sarcoma）之放射線影像，最常呈現為下列何者？","options":["(A) 界線清楚之放射線透過性病變（well-defined radiolucent lesion）","(B) 界線不清楚之放射線透過性病變（ill-defined radiolucent lesion）","(C) 混合放射線透過性和不透過性病變（mixed radiolucent and radiopaque lesion）","(D) 放射線不透過性病變（radiopaque lesion）"],"answer":1,"image":"","clinical_level":"重點"},{"id":"ya4-115-1-75","subject":"ya4","topic":"口腔病理基礎","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"28 歲男性因左下顎有一無疼痛的腫脹，經影像檢查如附圖（一）所示，切片後病理鏡檢如附圖（二），結合 影像的發現，此病人最可能罹患下列何種疾病？ 圖（一） 圖（二）","options":["(A) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）","(B) 造釉細胞瘤（ameloblastoma）","(C) 鈣化上皮齒源性瘤（calcifying epithelial odontogenic tumor）","(D) 齒源性角化囊腫（odontogenic keratocyst）"],"answer":1,"image":"ya4-115-1-75.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-76","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"43 歲女性因右下顎缺牙想要植牙，經 X 光檢查如附圖所示，此病人最可能罹患下列何種疾病？","options":["(A) 麥克滾－阿爾布萊德氏症候群（McCune-Albright syndrome）","(B) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）","(C) 變形性骨炎（Paget disease of bone）","(D) 家族性巨大畸形牙骨質瘤（familial gigantiform cementoma）"],"answer":1,"image":"ya4-115-1-76.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-77","subject":"ya4","topic":"放射影像診斷","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"附圖為典型之頭頸部軟組織鈣化或骨化的部位示意圖，其中那一編號為扁桃腺結石（tonsilloliths）好發部 位？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":3,"image":"ya4-115-1-77.jpeg","clinical_level":"重點"},{"id":"ya4-115-1-78","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"如圖 X 光影像所示，下列敘述何者錯誤？","options":["(A) 此 X 光影像所顯示疾病最可能是 Treacher Collins syndrome","(B) 左側中央，短而細的箭頭指的是 wormian bones in the occipital region","(C) 此 X 光影像所顯示疾病最可能是 cleidocranial dysplasia","(D) 右側中上，長而粗的箭頭指的是 open fontanel"],"answer":0,"image":"ya4-115-1-78.jpeg","clinical_level":"一般"},{"id":"ya4-115-1-79","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"下列何者為數位影像壓縮（digital image compression）最主要的目的？","options":["(A) 保留最佳品質","(B) 降低數位影像檔案的大小","(C) 符合醫院評鑑的需求","(D) 降低成本以減少病人負擔"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-1-80","subject":"ya4","topic":"放射線原理與技術","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"下列何者不屬於游離輻射造成的 deterministic effect？","options":["(A) 皮膚灼傷（skin burns）","(B) 放射線骨壞死（osteoradionecorsis）","(C) 輻射引發的白內障","(D) 遺傳效應（hereditary effects）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-1","subject":"ya4","topic":"口腔外科基礎","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"下列何種設計會增加手術皮瓣發生壞死的機會？","options":["(A) 皮瓣長度不大於皮瓣底部寬度","(B) 軸心供應血管（axial blood supply）保留在皮瓣內","(C) 皮瓣末端寬度小於皮瓣底部寬度","(D) 皮瓣底部扭轉"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-2","subject":"ya4","topic":"口腔外科基礎","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"關於手術後產生的水腫（edema），下列敘述何者正確？①與血管內液體滲出有關 ②與淋巴回流阻塞有關 ③高峰期為術後5～7天","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-3","subject":"ya4","topic":"口腔外科基礎","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"關於手術傷口止血，下列敘述何者錯誤？","options":["(A) 止血不佳形成血腫（hematoma），會增加感染機會","(B) 使用加壓止血法，對於較大的血管可能需時數分鐘","(C) 手術中使用紗布清除手術區域積血，要用擦拭（wipe）而不是輕壓（blot）","(D) 可用3號或4號絲線結紮血管"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-4","subject":"ya4","topic":"口腔外科基礎","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"有關基本縫合技術，下列敘述何者錯誤？","options":["(A) 縫針必須以持針器夾住於距針尖1/3至1/2全長處","(B) 將游離的軟組織與較為穩定的軟組織縫合時，應先讓縫線穿過前者然後縫向後者","(C) 縫合黏膜時，縫針應以直角穿入黏膜表面","(D) 縫合後傷口的邊緣應略呈外翻（eversion）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-5","subject":"ya4","topic":"局部與全身麻醉","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"有關惡性高熱症（malignant hyperthermia）的敘述，何者正確？","options":["(A) 一般多發生於給與特定局部麻醉劑後，引發病人體溫超過40℃的急性病症","(B) 通常在成年人的發生機率較孩童為高，其症狀與遺傳因子較無相關","(C) 除體溫過高及肌肉僵直外，其它可能出現的症狀包括代謝性鹼中毒、心搏過慢等","(D) Dantrolene可作為預防及治療惡性高熱症的藥物"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-6","subject":"ya4","topic":"局部與全身麻醉","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"下列有關局部麻醉劑的敘述，何者錯誤？","options":["(A) articaine對於孕婦屬於A級藥物","(B) lidocaine對於nursing infants屬於安全藥物","(C) 局部麻醉過量容易發生在體重低於30公斤者","(D) 一管局部麻醉藥於15秒內誤注入兒童血管中，有可能產生seizure"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-7","subject":"ya4","topic":"局部與全身麻醉","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"一支1.8 mL 2％ lidocaine麻醉藥筒，lidocaine含量多少？","options":["(A) 9 mg","(B) 90 mg","(C) 3.6 mg","(D) 36 mg"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-8","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"拔除下顎第三大臼齒造成神經傷害，下列何者預後最差？","options":["(A) neurotmesis","(B) axopraxia","(C) neurapraxia","(D) axonotmesis"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-9","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"圖中所示的拔牙鉗，最適合拔除下列那一牙位的牙齒？","options":["(A) 上顎右側大臼齒","(B) 下顎大臼齒","(C) 上顎左側大臼齒","(D) 下顎小臼齒"],"answer":0,"image":"ya4-115-2-9.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-10","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"下列有關拔牙的機械原理，何者最不合理？","options":["(A) 拔牙鉗的尖端喙緣（beak）深入牙齒與骨頭的間隙時，是利用楔狀（wedge）原理，當鉗子的尖端向根部施加壓力時，幫助將牙齒從牙槽中推出","(B) 拔牙挺的使用涉及槓桿原理，係將較小力量透過長槓臂（long lever arm）和短作用臂（short effector arm）之機械優勢，使小範圍的運動能對抗牙齒移動時較大的阻力","(C) 將小型直式拔牙挺插入牙齒周圍，令其根部向咬合面推移，從而將牙齒從齒槽中推出，亦為槓桿原理的應用","(D) 當牙齒的多根中有一根留在齒槽中時，以三角形拔牙挺（如：Cryer或Winter's elevator）放入齒槽中並轉動將牙齒拔除，是輪軸原理的應用"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-11","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"下列何種角度的下顎阻生第三大臼齒最常見？","options":["(A) mesioangular","(B) horizontal","(C) vertical","(D) distoangular"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-12","subject":"ya4","topic":"拔牙學與併發症","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"血小板功能低下之病人，拔牙後服用下列何種止痛藥較佳？","options":["(A) mefenamic acid","(B) ibuprofen","(C) naproxen","(D) acetaminophen"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-13","subject":"ya4","topic":"齒源性感染與藥物","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"關於抗生素使用原則，下列敘述何者錯誤？","options":["(A) 儘量選擇窄效型抗生素，較不易改變病人身體的微生物生態","(B) 抗生素可以預防術後感染，因此一般口腔手術前一定要先給與抗生素","(C) 複雜的齒源性感染，包括腫脹範圍大、先前治療失敗或者免疫力低下的病人，可考慮使用比較廣效的抗生素","(D) 廣效型抗生素包含：添加clavulanic acid的amoxicillin、azithromycin和moxifloxacin"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-14","subject":"ya4","topic":"齒源性感染與藥物","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"關於齒源性感染的敘述，下列何者正確？","options":["(A) 大部分齒源性上顎竇炎都是由犬齒感染引起","(B) 上顎犬齒感染位置若在提口角肌（levator anguli oris）的下方時，可造成眼眶下間隙（infraorbital space）的感染","(C) 上顎臼齒感染，若感染源比頰肌的附著處高，可能發展成頰間隙（buccal space）的感染","(D) 下顎第二大臼齒的感染不易擴展至顎下間隙（submandibular space）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-15","subject":"ya4","topic":"齒源性感染與藥物","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"頭頸部感染的病人，出現下列何種情況最需要轉介至口腔顎面外科專科醫師處理？","options":["(A) 疼痛不適已達10天","(B) 年紀超過60歲","(C) 在5年前曾有胃潰瘍病史","(D) 吞嚥困難"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-16","subject":"ya4","topic":"植牙外科","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"有關以骨牽引術增高齒槽骨的敘述，下列何者錯誤？","options":["(A) 通常每天以2 mm的牽引速度最適合骨生成與骨化","(B) 後續骨質堅實化的時間約需2至3個月","(C) 優點為同時可增長局部軟組織","(D) 缺點為有骨壞死的風險"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-17","subject":"ya4","topic":"植牙外科","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"下列那些方法可用於嚴重上顎齒槽骨吸收病例的人工植牙重建？①自體骨塊覆蓋移植（onlay graft） ②鼻竇升高術（sinus lift） ③齒槽嵴牽引術（alveolar ridge distraction）","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-18","subject":"ya4","topic":"植牙外科","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"在骨移植手術中，下列何者為使用骨成形蛋白（bone morphogenetic proteins）的優勢？①與其他移植材料相比價格較低 ②無須使用其他補骨或支撐材料 ③增強重建區骨生成能力","options":["(A) ①②","(B) ②③","(C) ①③","(D) 僅③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-19","subject":"ya4","topic":"植牙外科","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"軟組織狀況的評估，對於贋復前手術計劃的擬定是很重要的，下列何項評估是錯誤的？","options":["(A) 義齒配戴區角化黏膜的質與量","(B) 任何可疑的病變區，應做切片檢查","(C) 評估下顎舌骨肌（mylohyoid muscle）在頰側前庭區附著情況","(D) 評估病人舌頭的運動位置"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-20","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"下列何者屬於口腔癌前期病灶（oral premalignant lesion）中的白斑（leukoplakia）？","options":["(A) 慢性頰咬傷（morsicatio buccarum）引起的角質化","(B) 抽菸病人的舌側角化過度（hyperkeratosis）","(C) 腭黏膜的尼古丁口腔炎（nicotinic stomatitis）","(D) 下唇日曬性唇炎（actinic cheilitis）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-21","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"下列何種放射線治療的方式，對於降低非腫瘤區域的吸收劑量效果最差？","options":["(A) 使用高分次治療（hyperfractionation）","(B) 提高射源能量為兆伏（megavoltage）","(C) 使用屏蔽（shielding）","(D) 使用強度調控放射線治療（intensity modulated radiotherapy）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-22","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"有關鈣化上皮齒源瘤（calcifying epithelial odontogenic tumor）的敘述，下列何者最適當？","options":["(A) 經常會造成疼痛","(B) 較常發生於下顎骨","(C) 以剜除術（enucleation）為標準手術方式，也可以搭配刮除術（curettage）","(D) 手術時可以發現明顯的包膜"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-23","subject":"ya4","topic":"骨骼代謝與發育疾病","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"下列何者不是牙骨質－骨質發育不良（cemento-osseous dysplasia）之特徵？","options":["(A) 為最常見的纖維骨病變（fibro-osseous disease）","(B) 臨床上可區分根尖型（periapical）、局部型（focal）及廣泛型（florid）三種亞型","(C) 在疾病的發展初期會造成疼痛，之後會逐漸緩解","(D) 通常不需要手術介入"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-24","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"判斷下顎牙齦鱗狀細胞癌有無骨髓腔（marrow space）侵犯時，下列何種檢查方式敏感度最高？","options":["(A) 臨床觀察","(B) 齒顎全景放射線攝影","(C) 電腦斷層攝影","(D) 磁振造影"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-25","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"依據National Comprehensive Cancer Network（NCCN）指引，對於口腔癌，下列何種情況會建議進行手術後的放射線治療？①頸部淋巴結發生兩顆以上轉移 ②發生頸部淋巴結外侵犯 ③T4的原發腫瘤","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-26","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"下列何者為舌癌患者腫瘤切除合併頸部廓清手術後一週內，需特別注意之狀況？①引流液之顏色及量 ②頸部是否有鼓起 ③呼吸狀況 ④敷料是否發生異味","options":["(A) 僅①②③","(B) 僅①③④","(C) 僅②③④","(D) ①②③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-27","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"下列何者不是囊腫進行造袋術（marsupialization）治療的優點與適應症？","options":["(A) 可降低鄰近感覺神經受傷的風險","(B) 可降低顎骨病理性骨折的風險","(C) 可幫助未萌發的牙齒萌發","(D) 有助於完整病理檢查"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-28","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"下列何者最不適合以剜除術（enucleation）或刮除術（curettage）治療？","options":["(A) 動脈瘤樣骨囊腫（aneurysmal bone cyst）","(B) 造釉細胞纖維齒瘤（ameloblastic fibro-odontoma）","(C) 鱗狀上皮齒源性瘤（squamous odontogenic tumor）","(D) 鈣化齒源性囊腫（calcifying odontogenic cyst）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-29","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"關於含齒囊腫（dentigerous cyst）依發生機率由高至低排列，下列順序何者正確？①上顎犬齒 ②第三大臼齒 ③下顎小臼齒 ④上顎小臼齒","options":["(A) ①②③④","(B) ②④③①","(C) ②③④①","(D) ②①③④"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-30","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"痣樣基底細胞癌症候群（nevoid basal cell carcinoma syndrome）除了多發齒源性角化囊腫外，合併有許多臨床表徵，下列何者較常出現？","options":["(A) meningioma","(B) epidermal cysts of the skin","(C) cleft lip or palate","(D) mental retardation"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-31","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"50歲男性，左側上顎區域腫痛約兩個月餘，牙科X光檢查發現透射線病灶並導致鄰近牙齒吸收（如附圖所示）。下列何者為最不可能的初步診斷？","options":["(A) 鼻唇囊腫（nasolabial cyst）","(B) 造釉細胞瘤（ameloblastoma）","(C) 骨肉瘤（osteosarcoma）","(D) 顎骨炎性病變"],"answer":0,"image":"ya4-115-2-31.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-32","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"有關勒福一型截骨術（Le Fort Ⅰ osteotomy）的敘述，何者錯誤？","options":["(A) 可以用在改善上顎發育不足或發育過度","(B) 可以將上顎作三度空間的調整","(C) 將上顎往上移動，會比往下移動有較好的穩定度","(D) 施行時，不能結紮兩側descending palatine arteries，否則骨段會壞死"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-33","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"對骨性咬合不正的病人而言，先矯正再正顎手術治療的好處不包含下列何者？","options":["(A) 手術移動骨頭較為準確","(B) 若已符合病人的期待就毋須手術","(C) 有些牙齒的移動是必須先於手術的","(D) 可早期達到外觀及功能的改善"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-34","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"有關雙側矢向分裂截骨術（bilateral sagittal split osteotomy）與下顎枝垂直截骨術（vertical ramus osteotomy）用於治療下顎前突症，下列敘述何者錯誤？","options":["(A) 兩者之骨接合處皆是鬆質骨（cancellous bone）對鬆質骨之骨癒合","(B) 前者較後者容易傷到下齒槽神經","(C) 前者較後者容易內固定（internal fixation）","(D) 有顳顎關節病之患者較適合使用後者"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-35","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"關於傳入神經阻滯所引發牙齒疼痛（odontalgia resulting from deafferentation）的敘述，下列何者錯誤？","options":["(A) 多為持續性的悶痛或燒灼痛（aching or burning pain），也可能會有尖銳的陣發性疼痛（sharp paroxysms）","(B) 因周邊神經過度活躍（peripheral hyperactivity）引起疼痛時，無法以阻斷麻醉止痛","(C) 症狀常持續4～6個月以上","(D) 通常有手術或外傷的病史"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-36","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"三叉神經分為三個分支，簡寫為第一支（V1），第二支（V2）及第三支（V3），有關三叉神經痛發生機率之敘述，下列何者正確？","options":["(A) V1＞V2＞V3","(B) V2＞V3＞V1","(C) V3＞V2＞V1","(D) V2＞V1＞V3"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-37","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"傳導痛覺的感覺神經纖維屬於下列何者？","options":["(A) Aα和Aβ","(B) Aδ和C","(C) Aγ和B","(D) Aβ和B"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-38","subject":"ya4","topic":"唾液腺疾病","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"唾液腺黏液囊腫（mucocele）最常發生於下唇，次常發生的部位為下列何者？","options":["(A) 頰黏膜","(B) 口底","(C) 舌背","(D) 舌腹"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-39","subject":"ya4","topic":"唾液腺疾病","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"關於單形性腺瘤（monomorphic adenoma）的敘述，下列何者正確？","options":["(A) 為最常見的唾液腺良性腫瘤","(B) 常發生在腮腺及上唇的小唾液腺","(C) 手術切除後復發率高","(D) 有很高比例會轉變為惡性"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-40","subject":"ya4","topic":"唾液腺疾病","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"關於人類顎下腺的敘述，下列何者錯誤？","options":["(A) 包含大約相等數目的黏液及漿液腺泡細胞","(B) 分泌量約占唾液總量的70％","(C) 為唾液腺結石發生率最高的腺體","(D) 為良性唾液腺腫瘤發生率最高的腺體"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-41","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"關於眼心反射（oculocardiac reflex），下列敘述何者錯誤？","options":["(A) 可能會出現在兒童活板門眼眶骨折（pediatric trapdoor orbital trauma）","(B) 會造成心搏過速（tachycardia）","(C) 其反射輸入支（afferent limb）是經由三叉神經（trigeminal nerve）","(D) 其反射輸出支（efferent limb）是經由迷走神經（vagus nerve）"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-42","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"對於全顏面骨折（panfacial fracture）並有明顯的眼距過寬（telecanthus）的病人，需進行氣道維持時，下列何種方式最不合適？","options":["(A) 氣管造口術（tracheostomy）","(B) 經口氣管插管（orotracheal intubation）","(C) 經鼻氣管插管（nasotracheal intubation）","(D) 頦下插管（submental intubation）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-43","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"關於下顎骨骨折的敘述，下列何者錯誤？","options":["(A) 根據斷裂的解剖部位，可分為mandibular condyle、angle、body、ramus、symphyseal、alveolar、coronoid process fractures","(B) 根據骨頭斷裂的型態，可分為greenstick、simple、comminuted、compound fractures","(C) 根據骨折斷裂的方向與肌肉拉扯的位置與方向，可分為tension及compression fractures","(D) 槍傷及穿刺傷經常會造成comminuted fracture"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-44","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"病人因撞擊造成右上正中門齒脫出，當下已將牙齒撿回，並且泡在Hanks balanced salt solution中，於20分鐘內抵達診間，經口內檢查無合併齒槽骨斷裂。要將脫落牙齒重新植入前，下列處置何者正確？","options":["(A) 將牙根刮乾淨，並且用優碘沖洗消毒","(B) 將牙根刮乾淨，齒槽窩清創之後，用clindamycin溶液沖洗消毒","(C) 將牙根及齒槽窩用雙氧水消毒","(D) 小心保護牙根，將牙根及齒槽窩輕輕用生理食鹽水沖洗"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-45","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"下列何者最適合診斷顴骨弓（zygomatic arch）骨折？","options":["(A) Waters view","(B) panoramic view","(C) submental vertex view","(D) Towne view"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-46","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"有關顏面軟組織外傷，下列敘述何者正確？","options":["(A) 磨擦傷會造成患者疼痛","(B) 磨擦傷是表皮淺層受傷，因此沒有處理的必要","(C) eschar是軟組織受傷後壞死的組織","(D) eschar是上皮修復後留下的疤痕形成"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-47","subject":"ya4","topic":"唇顎裂與正顎手術","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"下列有關唇腭裂病因及發生率之敘述，何者正確?","options":["(A) 唇腭裂是因單一基因MSX變異所造成的疾病","(B) 唇裂發生在男性的比率高於女性","(C) 唇裂發生在右邊的比率高於左邊","(D) 雙側唇裂發生比率高於單側"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-48","subject":"ya4","topic":"口腔外科基礎","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"根據Sunderland神經受損的分類，在沒有異物的情況下，第幾級開始就有可能需要手術來介入治療？","options":["(A) 第一級","(B) 第二級","(C) 第三級","(D) 第四級"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-49","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"手術之前要評估糖尿病患者的血糖控制狀況，可以參考下列那一項血液檢驗數值？","options":["(A) WBC","(B) Hemoglobin（Hb）","(C) Hematocrit（Hct）","(D) Hemoglobin A1c（HbA1c）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-50","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"牙科治療時，孕婦應避免使用下列那些藥物？①tetracycline ②morphine ③aspirin ④ corticosteroids ⑤phenobarbital","options":["(A) 僅②③⑤","(B) 僅①②④","(C) 僅①③④⑤","(D) ①②③④⑤"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-51","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"雙腳踝部明顯浮腫，平躺時表示呼吸困難，要求立即坐起，病人最可能是患有下列何種疾病？","options":["(A) 鬱血性心衰竭（congestive heart failure）","(B) 慢性阻塞性肺病（chronic obstructive pulmonary disease）","(C) 急性心肌梗塞（acute myocardial infarction）","(D) 哮喘（asthma）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-52","subject":"ya4","topic":"全身性疾病與急症","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"下列何種情況，最不適合接受非迫切性拔牙？","options":["(A) 不穩定型狹心症（angina pectoris）已持續半年","(B) 一年前曾接受頭頸部放射治療","(C) 二年前曾接受冠狀動脈繞道手術","(D) 有心肌梗塞（myocardial infarction）病史，超過二年未再發作"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-53","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"對顴骨弓（zygomatic arch）進行垂直截骨，使其往關節隆突（articular eminence）前下方位移來阻止髁突（condyle）移動，以治療慢性復發顳顎關節脫臼，此為下列何種手術方法？","options":["(A) Dean procedure","(B) Lipswitch procedure","(C) LeClerc procedure","(D) Le Fort procedure"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-54","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"下列何者最不可能使用顳顎關節鏡執行手術？","options":["(A) release of joint fibrosis and adhesions","(B) disk repositioning surgery","(C) disk repair or removal","(D) release of bony ankylosis"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-55","subject":"ya4","topic":"顳顎關節與顏面疼痛","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"使用肋軟骨移植來治療顳顎關節黏連時，最適合用第幾根肋骨？","options":["(A) 1","(B) 3","(C) 6","(D) 12"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-56","subject":"ya4","topic":"口腔外科基礎","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"關於醫療的權利與責任關係，下列何者錯誤？","options":["(A) 若違反本國制訂的「醫療法」，醫者必須接受國家的懲罰與制裁","(B) 世界醫學會制訂的「赫爾辛基宣言」，違反者必須接受國家的懲罰與制裁","(C) 世界醫學會制訂的「病人權利宣言」，不遵守者並不觸犯法律","(D) 「醫師法」屬於法律權"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-57","subject":"ya4","topic":"放射線原理與技術","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"關於X光的光電效應（photoelectric effect），下列敘述何者錯誤？","options":["(A) 為X光光子（photon）與組織中原子（atom）之內殼電子（inner-shell electron）的交互作用","(B) 其結果是造成X光的光子自組織中散射（scatter）","(C) 低kV值的X光機器較高kV值的X光機器更容易產生光電效應","(D) 骨組織較軟組織更容易出現光電效應"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-58","subject":"ya4","topic":"放射線原理與技術","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"有關X光機中瞄準儀（collimator）形狀，下列何者能產生最佳的輻射防護結果？","options":["(A) 三角形","(B) 正方形","(C) 圓形","(D) 長方形"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-59","subject":"ya4","topic":"放射線原理與技術","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"依輻射線的生物效應，下列何者不屬於隨機效應（stochastic effects）？","options":["(A) 短時暴露造成之皮膚紅斑（short-time exposure-induced skin erythema）","(B) 癌症誘發（cancer induction）","(C) 遺傳性／基因性效應（heritable/genetic effects）","(D) 對未出生胎兒的效應（effects on the unborn child）"],"answer":0,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-60","subject":"ya4","topic":"放射線原理與技術","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"下列何者不屬於口內放射線攝影？","options":["(A) 咬翼片放射線攝影（bite-wing radiography）","(B) 咬合片放射線攝影（occlusal radiography）","(C) 環口放射線攝影（panoramic radiography）","(D) 牙根尖片放射線攝影（periapical radiography）"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-61","subject":"ya4","topic":"放射線原理與技術","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"若要拍攝成年病人口底是否有唾液腺結石，則應選用下列何種大小的X光片？","options":["(A) size 0","(B) size 1","(C) size 2","(D) size 4"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-62","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"數位影像的檢出器（detector），其對比解析度（contrast resolution）最容易被下列何者所影響？","options":["(A) 影像讀取的時間","(B) 影像讀取的速度","(C) 被照物的密度","(D) 被照物的形狀"],"answer":2,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-63","subject":"ya4","topic":"口腔腫瘤與癌症","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"有關放射線治療引起口腔病變的敘述，下列何者錯誤？","options":["(A) 唾液分泌減少","(B) 放射線是造成齲齒的直接原因","(C) 口內酸鹼值（pH）降低","(D) 齲齒常見於齒頸部，且常有牙冠變黑之症狀"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-64","subject":"ya4","topic":"放射線原理與技術","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"環口放射線影像（panoramic radiograph）的下顎前牙影像不清楚，且牙齒尺寸變大，可能的原因為何？","options":["(A) 病人下顎置放得太前","(B) 病人下顎置放得太後","(C) 病人下顎向右傾斜","(D) 病人下顎向左傾斜"],"answer":1,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-65","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"關於錐狀束電腦斷層攝影拍攝發育中齒列的適應症，下列何者錯誤？","options":["(A) 局部評估阻生齒","(B) 評估牙根外吸收與未萌發牙齒間關係","(C) 計畫顎顏面骨性異常的手術處理","(D) 矯正治療時計畫置放暫時錨定裝置"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-66","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"附圖X光影像中黑色箭頭所指的構造為何？","options":["(A) 上顎竇上緣","(B) 硬腭","(C) 軟腭","(D) 舌頭"],"answer":1,"image":"ya4-115-2-66.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-67","subject":"ya4","topic":"錐狀束 CT 與電腦影像","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"有關下顎電腦斷層示意圖對應的解剖結構，下列敘述何者正確？","options":["(A) 1是mylohyoid ridge，2是lingual foramen","(B) 3是mandibular foramen，4是mandibular canal","(C) 1是internal oblique ridge，3是mental foramen","(D) 2是lingual foramen，5是submandibular fossa"],"answer":3,"image":"ya4-115-2-67.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-68","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"附圖影像中箭頭所指之處，為下列何種構造？","options":["(A) 頦結節（genial tubercle）","(B) 頦棘（mental spine）","(C) 外斜嵴（external oblique ridge）","(D) 下顎舌骨嵴（mylohyoid ridge）"],"answer":3,"image":"ya4-115-2-68.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-69","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"附圖環口X光片中，所有牙齒的形態異常為何？","options":["(A) 牙釉質發育不全（hypoplastic amelogenesis imperfecta）","(B) 牙本質形成不良（dentinogenesis imperfecta）","(C) 局部牙齒發育不良（regional odontodysplasia）","(D) 第二型牙本質發育不良（dentin dysplasia type II）"],"answer":0,"image":"ya4-115-2-69.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-70","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"附圖X光片中，可發現那一顆牙齒有齲齒？","options":["(A) 左上顎第一大臼齒","(B) 左上顎第二大臼齒","(C) 左下顎第一大臼齒","(D) 左下顎第二大臼齒"],"answer":2,"image":"ya4-115-2-70.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-71","subject":"ya4","topic":"顎顏面外傷與骨折","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"一名外傷病人的X光影像如附圖，其最可能的診斷為何？","options":["(A) zygomatic fracture","(B) horizontal fracture","(C) pyramidal fracture","(D) craniofacial disjunction"],"answer":2,"image":"ya4-115-2-71.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-72","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"頭頸部X光影像常見軟組織鈣化的典型分布圖中，何者為靜脈結石（phleboliths）最常出現的區域？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"ya4-115-2-72.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-73","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"下列環口X光片中，此病患有幾顆多生牙（supernumerary teeth）？","options":["(A) 0","(B) 1","(C) 2","(D) 3"],"answer":0,"image":"ya4-115-2-73.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-74","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"附圖中白色箭頭所指的倒三角形為何種解剖構造？","options":["(A) zygomatic process of maxilla","(B) pterygomaxillary fissure","(C) maxillary tuberosity","(D) floor of the orbit"],"answer":1,"image":"ya4-115-2-74.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-75","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"附圖X光影像中箭頭所指之處，為下列何種疾病之特徵？","options":["(A) 柏哲德氏病（Paget disease）","(B) 梅爾科森－羅森索症候群（Melkersson-Rosenthal syndrome）","(C) 崔屈－寇林氏症候群（Treacher Collins syndrome）","(D) 史特吉－韋柏氏症候群（Sturge-Weber syndrome）"],"answer":3,"image":"ya4-115-2-75.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-76","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"附圖X光片影像，最可能出現於下列何種疾病之病人？","options":["(A) 腦下垂體功能過旺","(B) 腦下垂體功能不足","(C) 副甲狀腺功能過旺","(D) 副甲狀腺功能不足"],"answer":2,"image":"ya4-115-2-76.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-77","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"附圖X光片影像，最可能是下列那個診斷？","options":["(A) 纖維發育不良（fibrous dysplasia）","(B) 牙骨質－骨質發育不良（cemento-osseous dysplasia）","(C) 浦茲－詹賀症候群（Peutz-Jeghers syndrome）","(D) 嘉德耐氏症候群（Gardner's syndrome）"],"answer":1,"image":"ya4-115-2-77.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-78","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"下列何種囊腫，位於上顎兩正中門齒牙根之間或牙根尖區域（periapical area），且其X光影像為單房、放射線透過性病變（unilocular radiolucent lesion），形狀可能為圓形、卵圓形、倒梨形（inverted pear shape）或心臟形（heart shape）？","options":["(A) 鰓裂囊腫（branchial cleft cyst）","(B) 甲狀腺舌管囊腫（thyroglossal duct cyst）","(C) 鼻唇囊腫（nasolabial cyst）","(D) 鼻腭管囊腫（nasopalatine duct cyst）"],"answer":3,"image":"","clinical_level":"一般"},{"id":"ya4-115-2-79","subject":"ya4","topic":"口腔病理基礎","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"病人在其skull bone影像上發現\"punched out lesion\"，且於下顎骨X光片中出現如圖之\"scooped out image\"，則此病人最可能罹患下列何種病變？","options":["(A) 纖維性發育不良（fibrous dysplasia）","(B) 蘭格罕氏細胞組織細胞增多症（Langerhans cell histiocytosis）","(C) 動脈瘤性骨囊腫（aneurysmal bone cyst）","(D) 繁盛性牙骨質骨發育不良（florid cemento-osseous dysplasia）"],"answer":1,"image":"ya4-115-2-79.jpeg","clinical_level":"一般"},{"id":"ya4-115-2-80","subject":"ya4","topic":"放射影像診斷","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"附圖中箭頭所指病變之最可能診斷為何？","options":["(A) 根尖囊腫（periapical cyst）","(B) 齒源性角化囊腫（odontogenic keratocyst）","(C) 齒源性黏液瘤（odontogenic myxoma）","(D) 腺瘤樣齒源性瘤（adenomatoid odontogenic tumor）"],"answer":3,"image":"ya4-115-2-80.jpeg","clinical_level":"一般"}];
